import assert from 'node:assert/strict'
import { mkdir, writeFile } from 'node:fs/promises'
import { launchExtensionContext, extensionWorker } from '../tests/e2e/support/browser.mjs'
import { distDir, testResultsDir, resultPath } from '../tests/e2e/support/paths.mjs'

// 只读账号模板；选择和编辑只发生在隔离浏览器内，不保存模板、不查询或下载业务文件。
assert.equal(process.env.PATMAIL_LIVE_READONLY, '1')
assert(process.env.PATMAIL_AUDIT_USER && process.env.PATMAIL_AUDIT_PASSWORD)
const origin = 'http://183.36.43.66:88'
const context = await launchExtensionContext(distDir, { viewport: { width: 1600, height: 1000 } })
try {
  const site = await context.newPage()
  await site.goto(origin, { waitUntil: 'domcontentloaded' })
  await site.locator('#chk_password').uncheck()
  await site.locator('#txtUser').fill(process.env.PATMAIL_AUDIT_USER)
  await site.locator('#txtPwd').fill(process.env.PATMAIL_AUDIT_PASSWORD)
  await site.locator('#btnLogin').click()
  const worker = await extensionWorker(context)
  const app = await context.newPage()
  await app.goto(`chrome-extension://${new URL(worker.url()).host}/app.html#/files`)
  await app.waitForFunction(async () => {
    const loaded = await chrome.runtime.sendMessage({ type: 'WORKSPACE', payload: { action: 'load' } })
    return Boolean(loaded.payload?.connection?.operatorId)
  }, undefined, { polling: 500, timeout: 45000 })
  const selected = await site.evaluate(async () => {
    const result = await fetch('/AjaxServers/BaseInfo.ashx', { method: 'POST', credentials: 'include',
      body: new URLSearchParams({ Call: 'GetFileTempNameList', log_pagename: 'FileSearch.aspx' }) }).then(response => response.json())
    const templates = result.TempNameList ?? []
    const row = templates.find(item => item.temp_name === '华峰官文') ?? templates.find(item => item.new_filename === 'app_no;-;case_name;-;file_desc')
    return row ? { label: row.temp_name, filename: row.new_filename, types: row.file_name_type } : null
  })
  assert(selected, '账号应存在截图对应的五段模板')
  const row = app.locator('.download-name-row')
  await row.locator('.download-template-select [role="combobox"]').click()
  const option = app.getByRole('option', { name: selected.label, exact: true })
  await option.waitFor({ timeout: 45000 })
  await option.click()
  const parts = row.locator('.download-name-part')
  await app.waitForFunction(expected => document.querySelectorAll('.download-name-part').length === expected, selected.types.split(';').length)
  const shown = await parts.locator('.theme-select-label').allTextContents()
  const fixed = await row.locator('.download-part-text').evaluateAll(inputs => inputs.map(input => input.value))
  assert.equal(shown.length, selected.types.split(';').length)
  assert.deepEqual(fixed, selected.filename.split(';').filter((_, index) => selected.types.split(';')[index] === 'txt'))
  await row.locator('.download-part-text').first().fill('_')
  await app.getByRole('button', { name: '添加名称段', exact: true }).click()
  assert.equal(await parts.count(), shown.length + 1)
  await app.getByRole('button', { name: `删除第${shown.length + 1}段`, exact: true }).click()
  assert.equal(await parts.count(), shown.length)
  // 重选模板应恢复原配方。
  await row.locator('.download-template-select [role="combobox"]').click()
  await app.getByRole('option', { name: '不限', exact: true }).click()
  assert.equal(await parts.count(), 1)
  await row.locator('.download-template-select [role="combobox"]').click()
  await app.getByRole('option', { name: selected.label, exact: true }).click()
  await row.scrollIntoViewIfNeeded()
  await mkdir(testResultsDir, { recursive: true })
  await row.screenshot({ path: resultPath('download-editor-live.png') })
  const report = { passed: true, version: await app.evaluate(() => chrome.runtime.getManifest().version),
    parts: shown.length, labels: shown, fixedText: fixed, addRemoveAndReset: true, queryOrDownload: false, templateWrite: false }
  await writeFile(resultPath('download-editor-live.json'), JSON.stringify(report, null, 2))
  console.log(JSON.stringify(report))
} finally { await context.close() }

import assert from 'node:assert/strict'
import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { launchExtensionContext, extensionWorker } from '../tests/e2e/support/browser.mjs'
import { distDir, testResultsDir, resultPath } from '../tests/e2e/support/paths.mjs'

// 仅显式运行。凭据只从当前进程环境读取，报告不保留凭据、Cookie、筛选值或文件正文。
assert.equal(process.env.PATMAIL_LIVE_READONLY, '1', 'Set PATMAIL_LIVE_READONLY=1 for an explicit live read-only audit')
assert(process.env.PATMAIL_AUDIT_USER && process.env.PATMAIL_AUDIT_PASSWORD && process.env.PATMAIL_AUDIT_HAR)
const origin = 'http://183.36.43.66:88'
const expectedVersion = JSON.parse(await readFile(new URL('../package.json', import.meta.url), 'utf8')).version
const queryOnly = process.env.PATMAIL_AUDIT_QUERY_ONLY === '1'
const har = JSON.parse(await readFile(process.env.PATMAIL_AUDIT_HAR, 'utf8'))
const entry = har.log.entries.find(item => new URLSearchParams(item.request.postData?.text ?? '').get('Call') === 'GetSearchFiles')
assert(entry)
const original = new URLSearchParams(entry.request.postData.text)
const fields = Object.fromEntries([...original].filter(([key]) => ![
  'Call', 'pageIndex', 'pageSize', 'IsFirst', 'is_pat', 'colsel', '_t', 'log_pagename', '_doneCallback'
].includes(key)))
const context = await launchExtensionContext(distDir)
const report = { version: '', queryOnly, formBefore: {}, formAfter: {}, starts: [], ends: [], initialMs: 0, allMs: 0, total: 0, selected: [], notices: [], peak: 0, error: '' }
let ticker
try {
  const site = await context.newPage()
  await site.goto(`${origin}/`, { waitUntil: 'domcontentloaded' })
  await site.locator('#chk_password').uncheck()
  await site.locator('#txtUser').fill(process.env.PATMAIL_AUDIT_USER)
  await site.locator('#txtPwd').fill(process.env.PATMAIL_AUDIT_PASSWORD)
  await site.locator('#btnLogin').click()
  const worker = await extensionWorker(context)
  const app = await context.newPage()
  await app.goto(`chrome-extension://${new URL(worker.url()).host}/app.html#/files`)
  await app.waitForFunction(async () => {
    const loaded = await chrome.runtime.sendMessage({ type: 'WORKSPACE', payload: { action: 'load' } })
    const connection = loaded.payload?.connection
    return Boolean(connection?.operatorId && connection.easyTabId != null)
  }, undefined, { timeout: 45000, polling: 500 })
  const saved = await app.evaluate(async fields => {
    const loaded = await chrome.runtime.sendMessage({ type: 'WORKSPACE', payload: { action: 'load' } })
    const c = loaded.payload.connection
    const now = new Date().toISOString()
    const result = await chrome.runtime.sendMessage({ type: 'WORKSPACE', payload: {
      action: 'saveQueryTemplate', expectedVersion: null,
      expectedScope: { easyOrigin: c.easyOrigin, operatorId: c.operatorId, easyTabId: c.easyTabId, connectionVersion: c.connectionVersion },
      template: { id: 'local-performance-audit', name: '本次性能验收', source: 'local', queryType: 'FileSearch', fields, version: 1, createdAt: now, updatedAt: now }
    } })
    return { version: chrome.runtime.getManifest().version, saved: result.payload?.ok }
  }, fields)
  report.version = saved.version
  assert.equal(saved.saved, true)
  assert.equal(saved.version, expectedVersion)
  await app.reload({ waitUntil: 'domcontentloaded' })
  await app.getByRole('button', { name: /本次性能验收/ }).click()
  const formState = async () => {
    const state = {}
    for (const label of ['文件描述', '文件来源', '附件名称', '设置下载文件名称']) {
      const node = app.getByText(label, { exact: true })
      state[label] = await node.count() > 0 && await node.first().isVisible()
    }
    return state
  }
  report.formBefore = await formState()
  const cdp = await context.newCDPSession(site)
  await cdp.send('Network.enable')
  const ids = new Set()
  cdp.on('Network.requestWillBeSent', event => {
    const params = new URLSearchParams(event.request.postData ?? '')
    if (params.get('Call') === 'GetSearchFiles' && params.get('case_volume') === original.get('case_volume')) {
      ids.add(event.requestId)
      report.starts.push({ id: event.requestId, page: Number(params.get('pageIndex')), size: Number(params.get('pageSize')), at: event.timestamp })
    }
  })
  cdp.on('Network.loadingFinished', event => { if (ids.has(event.requestId)) report.ends.push({ id: event.requestId, at: event.timestamp }) })
  const initialStart = Date.now()
  await app.getByRole('button', { name: '查询文件', exact: true }).click()
  const totalLabel = app.getByText(/^共 \d+ 个文件$/, { exact: true })
  await totalLabel.waitFor({ timeout: 120000 })
  report.initialMs = Date.now() - initialStart
  report.total = Number(/\d+/.exec(await totalLabel.innerText())[0])
  if (queryOnly) {
    await app.getByRole('button', { name: '校对最新字段', exact: true }).click()
    await app.getByText(/^已打开原网站的文件查询页/).waitFor({ timeout: 45000 })
    report.explicitFormCheck = true
  }
  report.formAfter = await formState()
  if (queryOnly) {
    assert(Object.values(report.formAfter).every(Boolean), '查询后必须仍展示文件条件')
    console.log(JSON.stringify({ completed: true, queryOnly, total: report.total, initialMs: report.initialMs, formBefore: report.formBefore, formAfter: report.formAfter }))
  } else {
  const allStart = Date.now()
  await app.getByRole('button', { name: '全选所有', exact: true }).click()
  ticker = setInterval(() => console.log(JSON.stringify({ phase: 'selecting', sent: report.starts.length, received: report.ends.length, elapsedMs: Date.now() - allStart })), 15000)
  await app.getByText(`已全选 ${report.total} 个文件。`, { exact: true }).waitFor({ timeout: 240000 })
  report.allMs = Date.now() - allStart
  report.selected = await app.getByText(/^已选 \d+ 个文件/).allTextContents()
  report.notices = await app.getByText(/^已全选 /).allTextContents()
  assert(report.selected.some(text => text.startsWith(`已选 ${report.total} 个文件`)))
  assert.equal(report.starts.length, Math.ceil(report.total / 100))
  assert(report.starts.every(request => request.size === 100))
  console.log(JSON.stringify({ completed: true, total: report.total, initialMs: report.initialMs, allMs: report.allMs, requests: report.starts.length, notices: report.notices }))
  }
} catch (error) {
  report.error = error instanceof Error ? error.message : String(error)
  throw error
} finally {
  clearInterval(ticker)
  report.peak = report.starts.length ? Math.max(...report.starts.map(start => report.starts.filter(item => item.at <= start.at && !report.ends.some(end => end.id === item.id && end.at <= start.at)).length)) : 0
  await mkdir(testResultsDir, { recursive: true })
  await writeFile(resultPath(queryOnly ? 'file-form-live.json' : 'file-pagination-live-optimized.json'), JSON.stringify(report, null, 2))
  await context.close()
}

import assert from 'node:assert/strict'
import { readFile, readdir, mkdir, writeFile, open, unlink } from 'node:fs/promises'
import { execFile } from 'node:child_process'
import { promisify } from 'node:util'
import { createHash } from 'node:crypto'
import { chromium } from 'playwright'
import { testResultsDir, resultPath } from '../tests/e2e/support/paths.mjs'
import { launchExtensionContext, extensionWorker } from '../tests/e2e/support/browser.mjs'
import { distDir } from '../tests/e2e/support/paths.mjs'

// 研究原站既有下载协议。报告只保留时序、字节数和格式，不保留凭据、Cookie、文件名、编号、GUID或文件正文。
const origin = 'http://183.36.43.66:88'
const report = { offline: [], source: [], live: [], checkedAt: new Date().toISOString() }
if (process.env.PATMAIL_AUDIT_APPEND_REPORT === '1') {
  try { report.live.push(...JSON.parse(await readFile(resultPath('download-streaming-research.json'), 'utf8')).live) } catch {}
}
const harFolder = new URL('../../HAR/', import.meta.url)
const inputs = (await readdir(harFolder)).map(name => new URL(name, harFolder))
if (process.env.PATMAIL_AUDIT_HAR) inputs.push(process.env.PATMAIL_AUDIT_HAR)
for (const path of inputs) {
  let har
  try { har = JSON.parse(await readFile(path, 'utf8')) } catch { continue }
  for (const entry of har.log?.entries ?? []) {
    const params = entry.request.postData?.text ? new URLSearchParams(entry.request.postData.text)
      : new URLSearchParams((entry.request.postData?.params ?? []).map(item => [item.name, item.value]))
    const call = params.get('Call')
    const url = new URL(entry.request.url)
    if (!['DownLoad', 'DownLoadFiles', 'DownLoadZip'].includes(call) && !/FileHandler(New)?\.ashx/i.test(url.pathname)) continue
    const headers = Object.fromEntries((entry.response.headers ?? []).map(item => [item.name.toLowerCase(), item.value]))
    let json
    try { json = JSON.parse(entry.response.content?.text ?? '') } catch {}
    const finding = { source: String(path).split(/[\\/]/).at(-1), handler: url.pathname.split('/').at(-1), call,
      count: params.get('file_no')?.split(';').filter(Boolean).length ?? null,
      elapsedMs: entry.time, timings: entry.timings, status: entry.response.status,
      contentType: headers['content-type'], contentLength: headers['content-length'], transferEncoding: headers['transfer-encoding'],
      bodySize: entry.response.bodySize, capturedSize: entry.response.content?.size,
      returnedGuid: Boolean(json?.file_guid), reportedFileSize: json?.file_size ?? null }
    report.offline.push(finding)
  }
}
if (process.env.PATMAIL_LIVE_DOWNLOAD_RESEARCH !== '1') {
  await mkdir(testResultsDir, { recursive: true })
  await writeFile(resultPath('download-streaming-research.json'), JSON.stringify(report, null, 2))
  console.log(JSON.stringify(report, null, 2))
  process.exit(0)
}
assert(process.env.PATMAIL_AUDIT_USER && process.env.PATMAIL_AUDIT_PASSWORD && process.env.PATMAIL_AUDIT_REQUEST)
const pasted = await readFile(process.env.PATMAIL_AUDIT_REQUEST, 'utf8')
const lines = pasted.split(/\r?\n/)
const values = {}
for (let index = 0; index < lines.length; index++) {
  const key = /^\d+\.\s*(\w+)\s*$/.exec(lines[index])?.[1]
  if (key) values[key] = lines[index + 1]?.trim() ?? ''
}
assert.equal(values.Call, 'DownLoad')
const ids = values.file_no.split(';')
const names = values.file_name.split(';')
assert.equal(ids.length, names.length)
const extensionMode = process.env.PATMAIL_AUDIT_EXTENSION === '1'
const browser = extensionMode ? null : await chromium.launch({ headless: true })
const context = extensionMode ? await launchExtensionContext(distDir) : await browser.newContext()
const page = await context.newPage()
try {
  await page.goto(origin, { waitUntil: 'domcontentloaded' })
  await page.locator('#chk_password').uncheck()
  await page.locator('#txtUser').fill(process.env.PATMAIL_AUDIT_USER)
  await page.locator('#txtPwd').fill(process.env.PATMAIL_AUDIT_PASSWORD)
  await page.locator('#btnLogin').click()
  await page.waitForFunction(async () => {
    try {
      const data = await fetch('/AjaxServers/Login.ashx', { method: 'POST', body: new URLSearchParams({ Call: 'GetUserModel' }) }).then(response => response.json())
      return data.ClientInfo?.IsLogin === true && Boolean(data.UserModel?.user_id)
    } catch { return false }
  }, undefined, { timeout: 45000, polling: 1000 })
  console.log(JSON.stringify({ stage: 'authenticated', sampleCount: ids.length }))
  const formUrl = `${origin}/Forms/Patent/FileSearch.aspx`
  const html = await context.request.get(formUrl).then(response => response.text())
  const scripts = [...html.matchAll(/<script[^>]+src\s*=\s*["']([^"']+)["']/gi)]
    .map(match => new URL(match[1], formUrl)).filter(url => url.origin === origin && /FileSearch|public\.js/i.test(url.pathname))
  for (const url of scripts) {
    const code = await context.request.get(url.href).then(response => response.text())
    report.source.push({ file: url.pathname.split('/').at(-1), sha256: createHash('sha256').update(code).digest('hex'),
      bytes: Buffer.byteLength(code), downloadCalls: [...new Set([...code.matchAll(/Call\s*:\s*['"](\w*[Dd]own\w*)['"]/g)].map(match => match[1]))],
      handlers: [...new Set([...code.matchAll(/FileHandler\w*\.ashx/g)].map(match => match[0]))] })
    await writeFile(resultPath(`research-${url.pathname.split('/').at(-1)}`), code)
  }
  await page.exposeFunction('__reportStreamingResearch', packet => console.log(JSON.stringify(packet)))
  const counts = (process.env.PATMAIL_AUDIT_COUNTS ?? '1,20').split(',').map(Number)
  for (const count of counts) {
    assert(Number.isInteger(count) && count > 0 && count <= 100)
    const params = new URLSearchParams({ Call: 'DownLoad', file_no: ids.slice(0, count).join(';'), file_name: names.slice(0, count).join(';'),
      zip_name: '', zip_pwd: '', down_type: '', model: 'FILE', childpath: '', log_pagename: 'FileSearch.aspx' })
    console.log(JSON.stringify({ stage: 'packing-start', count }))
    const result = await page.evaluate(async ({ body, count }) => {
      const started = performance.now()
      const controller = new AbortController()
      const stop = setTimeout(() => controller.abort(), 240000)
      const heartbeat = setInterval(() => void window.__reportStreamingResearch({ stage: 'packing-wait', count, elapsedMs: Math.round(performance.now() - started) }), 15000)
      const metrics = { count, headersMs: null, firstBytesMs: null, firstGuidMs: null, completeMs: null, bytes: 0, chunks: [], status: null, headers: {}, leadingWhitespaceBytes: 0 }
      try {
        const response = await fetch('/AjaxServers/BaseInfo.ashx', { method: 'POST', body: new URLSearchParams(body), credentials: 'include', signal: controller.signal })
        metrics.headersMs = Math.round(performance.now() - started)
        metrics.status = response.status
        for (const key of ['content-type', 'content-length', 'transfer-encoding', 'content-encoding']) metrics.headers[key] = response.headers.get(key)
        const reader = response.body.getReader()
        const decoder = new TextDecoder()
        let text = ''
        for (;;) {
          const chunk = await reader.read()
          if (chunk.done) break
          metrics.bytes += chunk.value.byteLength
          const elapsedMs = Math.round(performance.now() - started)
          metrics.firstBytesMs ??= elapsedMs
          text += decoder.decode(chunk.value, { stream: true })
          if (metrics.firstGuidMs === null && /"file_guid"\s*:\s*"[0-9a-f-]{36}"/i.test(text)) metrics.firstGuidMs = elapsedMs
          const item = { elapsedMs, bytes: chunk.value.byteLength, totalBytes: metrics.bytes }
          metrics.chunks.push(item)
          void window.__reportStreamingResearch({ stage: 'packing-chunk', count, ...item })
          if (metrics.bytes > 2 * 1024 * 1024) throw new Error('Unexpected large preparation response')
        }
        text += decoder.decode()
        metrics.completeMs = Math.round(performance.now() - started)
        metrics.leadingWhitespaceBytes = new TextEncoder().encode(/^\s*/.exec(text)?.[0] ?? '').length
        const data = JSON.parse(text.trim())
        return { metrics, guid: typeof data.file_guid === 'string' ? data.file_guid : null, fileSize: data.file_size ?? null,
          login: data.ClientInfo?.IsLogin, failedCount: /共(\d+)个文件下载失败/.exec(data.error_message ?? '')?.[1] ?? null }
      } catch (error) {
        return { metrics, error: error instanceof Error ? error.message : String(error) }
      } finally { clearTimeout(stop); clearInterval(heartbeat) }
    }, { body: params.toString(), count })
    const { guid, ...summary } = result
    if (guid && /^[0-9a-f-]{36}$/i.test(guid)) {
      // 只读新建临时包：请求尾部64KB，检验ZIP结束目录是否已经可用。服务器忽略Range时限制读取量。
      summary.archive = await page.evaluate(async guid => {
        const started = performance.now()
        const controller = new AbortController()
        const timer = setTimeout(() => controller.abort(), 60000)
        const result = { status: null, headers: {}, headersMs: null, firstBytesMs: null, elapsedMs: null, received: 0, ended: false, eocdPresent: false, entryCount: null, zipPrefix: null }
        try {
          const response = await fetch(`/AjaxServers/FileHandler.ashx?guid=${encodeURIComponent(guid)}`, { headers: { Range: 'bytes=-65536' }, signal: controller.signal, credentials: 'include' })
          result.status = response.status
          result.headersMs = Math.round(performance.now() - started)
          for (const key of ['content-type', 'content-length', 'content-range', 'accept-ranges', 'transfer-encoding', 'last-modified']) result.headers[key] = response.headers.get(key)
          const max = Number(response.headers.get('content-length')) > 8 * 1024 * 1024 ? 131072 : 8 * 1024 * 1024
          const reader = response.body.getReader()
          const chunks = []
          for (;;) {
            const chunk = await reader.read()
            if (chunk.done) { result.ended = true; break }
            result.firstBytesMs ??= Math.round(performance.now() - started)
            result.received += chunk.value.byteLength
            chunks.push(chunk.value)
            if (result.received > max) { await reader.cancel(); break }
          }
          const bytes = new Uint8Array(result.received)
          let offset = 0
          for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length }
          result.zipPrefix = [...bytes.slice(0, 4)].map(value => value.toString(16).padStart(2, '0')).join('')
          for (let index = bytes.length - 22; index >= Math.max(0, bytes.length - 65558); index--) {
            if (bytes[index] === 0x50 && bytes[index + 1] === 0x4b && bytes[index + 2] === 5 && bytes[index + 3] === 6 &&
              index + 22 + bytes[index + 20] + 256 * bytes[index + 21] === bytes.length && result.ended) {
              result.eocdPresent = true
              result.entryCount = bytes[index + 10] + 256 * bytes[index + 11]
              break
            }
          }
        } catch (error) { result.error = error instanceof Error ? error.message : String(error) }
        finally { clearTimeout(timer); result.elapsedMs = Math.round(performance.now() - started) }
        return result
      }, guid)
      if (count <= 2) {
        const alternativeGuid = await page.evaluate(async body => {
          const data = await fetch('/AjaxServers/BaseInfo.ashx', { method: 'POST', body: new URLSearchParams(body), credentials: 'include' }).then(response => response.json())
          return data.file_guid
        }, params.toString())
        summary.alternativeHandler = await page.evaluate(async guid => {
        const started = performance.now()
        const controller = new AbortController()
        const timer = setTimeout(() => controller.abort(), 30000)
        try {
          const response = await fetch(`/AjaxServers/FileHandlerNew.ashx?guid=${encodeURIComponent(guid)}`, { signal: controller.signal, credentials: 'include' })
          const headers = {}
          for (const key of ['content-type', 'content-length', 'transfer-encoding', 'accept-ranges']) headers[key] = response.headers.get(key)
          const reader = response.body.getReader()
          const chunk = await reader.read()
          await reader.cancel()
          return { freshHandle: true, status: response.status, headers, firstBytesMs: Math.round(performance.now() - started),
            prefix: [...(chunk.value ?? []).slice(0, 4)].map(value => value.toString(16).padStart(2, '0')).join('') }
        } catch (error) { return { error: error instanceof Error ? error.message : String(error) } }
        finally { clearTimeout(timer) }
        }, alternativeGuid)
      }
      if (extensionMode) {
        // 取包句柄可能只能用一次，跨扩展上下文能力测试必须使用新句柄。
        const freshGuid = await page.evaluate(async body => {
          const data = await fetch('/AjaxServers/BaseInfo.ashx', { method: 'POST', body: new URLSearchParams(body), credentials: 'include' }).then(response => response.json())
          return data.file_guid
        }, params.toString())
        const worker = await extensionWorker(context)
        const app = await context.newPage()
        await app.goto(`chrome-extension://${new URL(worker.url()).host}/app.html#/files`)
        summary.extensionStreaming = await app.evaluate(async ({ guid, origin }) => {
          const capabilities = { secureContext: isSecureContext, filePicker: typeof showSaveFilePicker === 'function', readableStream: typeof ReadableStream === 'function' }
          let login = null
          try {
