            if (!response.ok || !response.body) throw new Error('Original-file stream unavailable')
            events.push({ stage: 'producer-ready', index, elapsedMs: Math.round(performance.now() - started) })
            return response.body
          })
          try {
            for (let index = 0; index < jobs.length; index++) {
              const name = encoder.encode(`sample-${index + 1}.pdf`)
              const offset = written
              const [header, view] = part(30 + name.length)
              view.setUint32(0, 0x04034b50, true); view.setUint16(4, 20, true); view.setUint16(6, 0x0808, true)
              view.setUint16(12, 33, true); view.setUint16(26, name.length, true); header.set(name, 30)
              await write(header)
              const dataOffset = written
              const stream = await jobs[index]
              const reader = stream.getReader()
              let crc = 0xffffffff
              let size = 0
              try {
                for (;;) {
                  const chunk = await reader.read()
                  if (chunk.done) break
                  maxChunkBytes = Math.max(maxChunkBytes, chunk.value.byteLength)
                  crc = updateCrc(crc, chunk.value)
                  size += chunk.value.byteLength
                  await write(chunk.value)
                  firstPayloadWriteMs ??= Math.round(performance.now() - started)
                }
              } finally { reader.releaseLock() }
              crc = (crc ^ 0xffffffff) >>> 0
              const [descriptor, desc] = part(16)
              desc.setUint32(0, 0x08074b50, true); desc.setUint32(4, crc, true); desc.setUint32(8, size, true); desc.setUint32(12, size, true)
              await write(descriptor)
              records.push({ name, offset, dataOffset, size, crc })
              events.push({ stage: 'entry-written', index, bytes: written, elapsedMs: Math.round(performance.now() - started) })
            }
            const centralOffset = written
            for (const record of records) {
              const [header, view] = part(46 + record.name.length)
              view.setUint32(0, 0x02014b50, true); view.setUint16(4, 20, true); view.setUint16(6, 20, true); view.setUint16(8, 0x0808, true)
              view.setUint16(14, 33, true); view.setUint32(16, record.crc, true); view.setUint32(20, record.size, true); view.setUint32(24, record.size, true)
              view.setUint16(28, record.name.length, true); view.setUint32(42, record.offset, true); header.set(record.name, 46)
              await write(header)
            }
            const centralSize = written - centralOffset
            const [end, view] = part(22)
            view.setUint32(0, 0x06054b50, true); view.setUint16(8, records.length, true); view.setUint16(10, records.length, true)
            view.setUint32(12, centralSize, true); view.setUint32(16, centralOffset, true)
            await write(end)
            await output.close()
            const file = await fileHandle.getFile()
