              entries: records.length, archiveBytes: written, payloadBytes: records.map(record => record.size), crcVerified: verified,
              maxChunkBytes, firstPayloadWriteMs, elapsedMs: Math.round(performance.now() - started), events,
              blobAssembly: false, storage: 'isolated browser OPFS temporary file', productionFeature: false }
          } catch (error) { await output.abort().catch(() => {}); throw error }
          finally { await root.removeEntry('streaming-research.zip').catch(() => {}) }
          }, { origin, files: ids.slice(0, 2) })
          await validationFile.close()
          const python = process.env.PATMAIL_RESEARCH_PYTHON ?? 'python'
          const code = 'import zipfile,json,sys\nwith zipfile.ZipFile(sys.argv[1]) as archive:\n assert len(archive.infolist()) == 2\n assert archive.testzip() is None\n print(json.dumps({"passed":True,"entries":len(archive.infolist()),"methods":[item.compress_type for item in archive.infolist()],"uncompressedBytes":sum(item.file_size for item in archive.infolist())}))'
          const { stdout } = await promisify(execFile)(python, ['-c', code, validationPath], { windowsHide: true })
          summary.localZipPrototype.independentPythonValidation = JSON.parse(stdout)
          } finally { await validationFile.close().catch(() => {}); await unlink(validationPath).catch(() => {}) }
        }
        await app.close()
      }
    }
    report.live.push(summary)
    console.log(JSON.stringify({ stage: 'sample-complete', ...summary }))
    await mkdir(testResultsDir, { recursive: true })
    await writeFile(resultPath('download-streaming-research.json'), JSON.stringify(report, null, 2))
    if (result.error || result.login === false) break
  }
} finally {
  await mkdir(testResultsDir, { recursive: true })
  await writeFile(resultPath('download-streaming-research.json'), JSON.stringify(report, null, 2))
  await context.close()
  await browser?.close()
