import assert from 'node:assert/strict'
import { mkdir, writeFile, readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { chromium } from 'playwright'
import { testResultsDir, resultPath } from '../tests/e2e/support/paths.mjs'

// 完全离线的独立扩展夹具；不使用业务账号，不修改生产扩展。
const fixture = join(testResultsDir, 'native-stream-fixture')
await mkdir(fixture, { recursive: true })
await writeFile(join(fixture, 'manifest.json'), JSON.stringify({ manifest_version: 3, name: 'Local streaming research', version: '0.0.1',
  permissions: ['downloads'], background: { service_worker: 'worker.js' },
  web_accessible_resources: [{ resources: ['generated-stream.bin'], matches: ['<all_urls>'] }] }))
await writeFile(join(fixture, 'app.html'), '<!doctype html><title>Local streaming research</title>')
await writeFile(join(fixture, 'generated-stream.bin'), 'static-control')
await writeFile(join(fixture, 'worker.js'), `
globalThis.streamEvents = [];
self.addEventListener('fetch', event => {
  if (!event.request.url.includes('/generated-stream.bin')) return;
  streamEvents.push({url:event.request.url, at:Date.now()});
  let index = 0;
  const stream = new ReadableStream({async pull(controller) {
    await new Promise(resolve => setTimeout(resolve, 200));
    if (index === 8) { controller.close(); return; }
    controller.enqueue(new Uint8Array(65536).fill(index++));
  }});
  event.respondWith(new Response(stream, {headers:{'Content-Type':'application/octet-stream','Content-Disposition':'attachment; filename=generated-stream.bin'}}));
});
chrome.runtime.onMessage.addListener((_message,_sender,respond) => respond({ready:true}));
`)
const context = await chromium.launchPersistentContext('', { channel: 'chromium', headless: true, acceptDownloads: true, downloadsPath: testResultsDir,
  args: [`--disable-extensions-except=${fixture}`, `--load-extension=${fixture}`] })
const report = { fetch: null, native: null, events: [], observations: [] }
try {
  const worker = context.serviceWorkers()[0] ?? await context.waitForEvent('serviceworker')
  const origin = new URL(worker.url()).origin === 'null' ? worker.url().replace(/\/worker\.js$/, '') : new URL(worker.url()).origin
  const app = await context.newPage()
  await app.goto(`${origin}/app.html`)
  report.fetch = await app.evaluate(async () => {
    try { const response = await fetch(chrome.runtime.getURL('generated-stream.bin?mode=fetch')); const data = await response.arrayBuffer(); return { status: response.status, bytes: data.byteLength } }
    catch(error) { return { error: error.message } }
  })
  try {
    const id = await worker.evaluate(() => chrome.downloads.download({url:chrome.runtime.getURL('generated-stream.bin?mode=native'),filename:'native-stream-research.bin',saveAs:false}))
    for (let index = 0; index < 40; index++) {
      const item = await worker.evaluate(id => chrome.downloads.search({id}).then(items => items.map(({state,error,bytesReceived,totalBytes,filename}) => ({state,error,bytesReceived,totalBytes,filename}))[0]), id)
      report.observations.push(item)
      if (item?.state === 'complete' || item?.state === 'interrupted') { report.native = item; break }
      await new Promise(resolve => setTimeout(resolve, 100))
    }
    if (report.native?.state === 'complete') report.verifiedDiskBytes = (await readFile(report.native.filename)).byteLength
  } catch(error) { report.native = { error: error.message } }
  report.events = await worker.evaluate(() => globalThis.streamEvents)
} finally {
  await writeFile(resultPath('native-stream-research.json'), JSON.stringify(report, null, 2))
  console.log(JSON.stringify(report, null, 2))
  await context.close()
}

/** 仓库 API/ 下的接口记录。构建时打进后台，问句走混合检索图，不整库塞进每一轮。 */

import { renderRagHits, runHybridRag } from './rag-graph'

export interface ApiDocSection {
  file: string
  heading: string
  body: string
}

const rawFiles = import.meta.glob('../../../API/*.md', {
  query: '?raw',
  import: 'default',
  eager: true
}) as Record<string, string>

function fileName(path: string): string {
  const parts = path.split(/[/\\]/)
  return parts[parts.length - 1] || path
}

/** 按二级标题切开。一级标题当作这篇文档的名字。 */
export function sectionsFromMarkdown(file: string, markdown: string): ApiDocSection[] {
  const lines = markdown.split(/\r?\n/)
  let title = file.replace(/\.md$/i, '')
  let heading = ''
  let buf: string[] = []
  const sections: ApiDocSection[] = []
  const push = (): void => {
    const body = buf.join('\n').trim()
    buf = []
    if (!body) return
    sections.push({ file, heading: heading ? `${title} / ${heading}` : title, body })
  }
  for (const line of lines) {
    if (line.startsWith('# ')) {
      title = line.slice(2).trim() || title
      continue
    }
    if (line.startsWith('## ')) {
      push()
      heading = line.slice(3).trim()
      continue
    }
    buf.push(line)
  }
  push()
  return sections
}

let cached: ApiDocSection[] | null = null

export function apiDocSections(): ApiDocSection[] {
  if (cached) return cached
  cached = Object.entries(rawFiles).flatMap(([path, text]) => sectionsFromMarkdown(fileName(path), text))
  return cached
}

export function apiDocFiles(): string[] {
  return [...new Set(apiDocSections().map(section => section.file))].sort()
}

/** 文档浮窗用：按文件名取整篇原文。文件名对不上时给空串。 */
export function apiDocRawText(file: string): string {
  const hit = Object.entries(rawFiles).find(([path]) => fileName(path) === file)
  return hit?.[1] ?? ''
}

function readmeText(): string {
  const hit = Object.entries(rawFiles).find(([path]) => fileName(path) === 'README.md')
  return hit?.[1] ?? ''
}

function entryCounts(text: string): Array<{ name: string; count: number }> {
  const start = text.indexOf('## 入口一览')
  if (start < 0) return []
  const end = text.indexOf('## 全部接口', start)
  const block = text.slice(start, end > start ? end : undefined)
  const rows: Array<{ name: string; count: number }> = []
  for (const line of block.split(/\r?\n/)) {
    const matched = /^\|\s*(?:\[([^\]]+)\]\([^)]+\)|([^|]+?))\s*\|\s*(\d+)\s*\|/.exec(line)
    if (!matched) continue
    const name = (matched[1] || matched[2] || '').trim()
    if (!name || name === '入口') continue
    rows.push({ name, count: Number(matched[3]) })
  }
  return rows
}

function callRowCount(text: string): number {
  const start = text.indexOf('## 全部接口')
  if (start < 0) return 0
  return text.slice(start).split(/\r?\n/).filter(line => /^\|\s*`[^`]+`\s*\|/.test(line)).length
}

/** 问「一共有多少接口」时用。个数来自索引表，不把文档篇数当成接口数。 */
export function apiCatalogBrief(): string {
  const text = readmeText()
  const entries = entryCounts(text)
  const listed = entries.filter(item => item.name !== '合计')
  const declared = entries.find(item => item.name === '合计')?.count ?? 0
  const summed = listed.reduce((total, item) => total + item.count, 0)
  const calls = callRowCount(text)
  if (listed.length === 0 || calls === 0) return '索引里没有数出接口个数。不要凭文档篇数估计。'
  const lines = listed.map(item => `${item.name} ${item.count}`)
  const agree = declared === summed && summed === calls
  return [
    `按入口和 Call 去重，一共 ${calls} 个接口。`,
    agree ? '入口表的合计、各入口相加、索引里的 Call 行，三个数一致。' : `入口表合计 ${declared}，各入口相加 ${summed}，Call 行 ${calls}。这三个数不一致，回答时要把三个数都说出来，不要另编一个。`,
    '这是接口个数，不是文档篇数。',
    ...lines,
    '回答只报这个数，可以带上入口分布。不要把 md 文件篇数说成接口数，也不要再写一段接口涵盖哪些方面。'
  ].join('\n')
}

function asksForCatalog(query: string): boolean {
  const text = query.trim()
  return /多少|几个|一共|总数|数量|清单|有哪些入口|入口一览/.test(text) && /接口|Call|入口/.test(text)
}

/** 用 Call 名、ashx 入口或中文主题找最相关的几段。问句不必和原文一致。 */
export function searchApiSections(sections: ApiDocSection[], query: string, limit = 4): string {
  const state = runHybridRag(sections, query, limit)
  if (state.tokens.length === 0 && state.dense.length === 0) return '请给出 Call 名、ashx 入口或中文主题。'
  return renderRagHits(sections, query, state.hits)
}

export function searchApiDocs(query: string): string {
  if (asksForCatalog(query)) return apiCatalogBrief()
  return searchApiSections(apiDocSections(), query)
}

/** Agent（LLM）接入配置。与写开关一样存在本机 chrome.storage.local，不上传。 */
export const AGENT_CONFIG_KEY = 'patmail.agent.config.v1'

export interface AgentConfig {
  /** OpenAI 兼容接口根地址，含版本段，例如 http://host:8588/v1。 */
  baseUrl: string
  /** 同时放在 Authorization: Bearer 和 x-api-key 两个请求头里。 */
  apiKey: string
  model: string
  /** 单次回复上限。思考和正文共用这一额度；0 表示不传，由服务端默认。 */
  maxTokens: number
  /** 思考型模型的思考链开关。关掉可以省 token、直接出正文。 */
  thinking: boolean
}

export const AGENT_CONFIG_DEFAULT: AgentConfig = {
  baseUrl: 'http://43.138.138.200:8588/v1',
  // 内网模型服务的密钥同样只放本机 .env，构建时注入，源码里不留明文。
  apiKey: import.meta.env.VITE_AGENT_DEFAULT_KEY ?? '',
  model: 'Qwen3.6-35B-A3B-oQ4-fp16-mtp',
  maxTokens: 8192,
  thinking: false
}

/** 主模型连不上时用的小米 MiMo。地址和密钥不进设置页。 */
export const AGENT_FALLBACK: Pick<AgentConfig, 'baseUrl' | 'apiKey' | 'model'> = {
  baseUrl: 'https://api.xiaomimimo.com/v1',
  // 密钥只放本机 .env（已被 .gitignore 忽略），构建时注入，源码里不留。
  // 注意：打包后的 JS 里仍是明文，拿到 dist 就能读出来；这一步只保证仓库干净。
  apiKey: import.meta.env.VITE_AGENT_FALLBACK_KEY ?? '',
  model: 'mimo-v2.6-pro'
}

export function endpointOrigin(baseUrl: string): string {
  return baseUrl.trim().replace(/\/+$/, '')
}

export function usesFallbackEndpoint(config: Pick<AgentConfig, 'baseUrl'>): boolean {
  return endpointOrigin(config.baseUrl) === endpointOrigin(AGENT_FALLBACK.baseUrl)
}

/** 保留这一轮的思考开关和长度上限，只换备用地址、密钥和模型。 */
export function fallbackAgentConfig(primary: AgentConfig): AgentConfig {
  return { ...primary, ...AGENT_FALLBACK }
}

/** 配置由后台自己读取，不信任页面消息里的地址和密钥。 */
export function isAgentConfig(value: unknown): value is AgentConfig {
  if (typeof value !== 'object' || value === null) return false
  const config = value as Record<string, unknown>
  return typeof config.baseUrl === 'string' && /^https?:\/\/[^\s]+$/i.test(config.baseUrl) && config.baseUrl.length <= 300 &&
    typeof config.apiKey === 'string' && config.apiKey.length <= 200 &&
    typeof config.model === 'string' && config.model.trim().length > 0 && config.model.length <= 200 &&
    typeof config.maxTokens === 'number' && Number.isSafeInteger(config.maxTokens) && config.maxTokens >= 0 && config.maxTokens <= 1_048_576 &&
    typeof config.thinking === 'boolean'
}

/** 旧默认 1024 会把思考和正文一起截断。后来抬到 1048576 又会把整段窗口占满。这两个数都收回到现在的默认。 */
function storedMaxTokens(value: unknown): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0 || value > 1_048_576) return 0
  return value === 1024 || value === 1_048_576 ? AGENT_CONFIG_DEFAULT.maxTokens : value
}

export function normalizeAgentConfig(value: unknown): AgentConfig {
  if (typeof value !== 'object' || value === null) return AGENT_CONFIG_DEFAULT
  const record = value as Record<string, unknown>
  const next: AgentConfig = {
    baseUrl: typeof record.baseUrl === 'string' ? record.baseUrl.trim().replace(/\/+$/, '') : '',
    apiKey: typeof record.apiKey === 'string' ? record.apiKey : '',
    model: typeof record.model === 'string' ? record.model.trim() : '',
    maxTokens: storedMaxTokens(record.maxTokens),
    thinking: typeof record.thinking === 'boolean' ? record.thinking : false
  }
  return isAgentConfig(next) ? next : AGENT_CONFIG_DEFAULT
}

export interface ConfigStorage {
  get(key: string): Promise<Record<string, unknown>>
  set(items: Record<string, unknown>): Promise<void>
}

export async function loadAgentConfig(area?: ConfigStorage): Promise<AgentConfig> {
  const storage = area ?? (typeof chrome !== 'undefined' ? chrome.storage?.local : undefined)
  if (!storage) return AGENT_CONFIG_DEFAULT
  try {
    return normalizeAgentConfig((await storage.get(AGENT_CONFIG_KEY))[AGENT_CONFIG_KEY])
  } catch {
    return AGENT_CONFIG_DEFAULT
  }
}

export async function saveAgentConfig(area: ConfigStorage, config: AgentConfig): Promise<AgentConfig> {
  const next = normalizeAgentConfig(config)
  await area.set({ [AGENT_CONFIG_KEY]: next })
  return next
}

import { fallbackAgentConfig, usesFallbackEndpoint, type AgentConfig } from './config'

/** OpenAI 兼容的对话消息。tool 相关字段供后续 agent 循环使用，本次接入先走纯文本。 */
export interface ChatMessage {
  role: 'system' | 'user' | 'assistant' | 'tool'
  content: string
  toolCallId?: string
  toolCalls?: AssistantToolCall[]
}

export interface AssistantToolCall {
  id: string
  type: 'function'
  function: { name: string; arguments: string }
}

export interface ToolSchema {
  type: 'function'
  function: { name: string; description: string; parameters: Record<string, unknown> }
}

export interface ChatChoice {
  content: string
  /** 思考链。只有设置里打开思考模式时才展示。 */
  reasoning: string
  finishReason: string
  toolCalls: AssistantToolCall[]
}

export interface ChatUsage {
  promptTokens: number
  completionTokens: number
}

export interface ChatOutcome {
  choices: ChatChoice[]
  usage: ChatUsage | null
  raw: unknown
}

/** 服务端回传的 model 优先。没有这一栏时，用这次实际发出去的模型名。 */
export function servedModel(outcome: ChatOutcome, requested: string): string {
  const raw = outcome.raw
  if (typeof raw === 'object' && raw !== null) {
    const name = (raw as Record<string, unknown>).model
    if (typeof name === 'string' && name.trim()) return name.trim().slice(0, 200)
  }
  return requested.trim().slice(0, 200)
}

export type LlmFailureKind = 'rate_limit' | 'upstream' | 'transient' | 'auth' | 'overflow' | 'timeout' | 'other'

export class LlmError extends Error {
  readonly code: 'NETWORK_ERROR' | 'REQUEST_TIMEOUT' | 'HTTP_ERROR' | 'INVALID_RESPONSE'
  readonly status?: number

  constructor(code: LlmError['code'], message: string, status?: number) {
    super(message)
    this.code = code
    this.status = status
  }
}

/** 502 一类网关失败可以再试，认证失败不试。连不上时由备用模型接手，不在这里换。 */
export function llmFailureKind(error: LlmError): LlmFailureKind {
  if (error.code === 'REQUEST_TIMEOUT') return 'timeout'
  if (error.status === 429) return 'rate_limit'
  if (error.status === 502 || error.status === 503 || error.status === 504) return 'upstream'
  if (error.code === 'NETWORK_ERROR') return 'transient'
  if (error.status === 401 || error.status === 403) return 'auth'
  if (error.status === 413 || /context length|maximum context|too many tokens|context_length_exceeded/i.test(error.message)) return 'overflow'
  return 'other'
}

/** 主模型没接上、超时、被限流或没返回有效内容时换备用。认证失败、上下文过长和用户停下不换。 */
export function shouldFallbackModel(error: LlmError): boolean {
  if (error.message === '已停下。') return false
  const kind = llmFailureKind(error)
  if (kind === 'timeout' || kind === 'transient' || kind === 'upstream' || kind === 'rate_limit') return true
  if (error.status !== undefined && error.status >= 500) return true
  return error.code === 'INVALID_RESPONSE'
}

/** 小米 MiMo 用 thinking / api-key；本地 Qwen 用 chat_template_kwargs。 */
export function modelDialect(config: AgentConfig): 'qwen' | 'mimo' {
  try {
    if (new URL(config.baseUrl).hostname.endsWith('xiaomimimo.com')) return 'mimo'
  } catch {
    // 地址不合法时仍按主模型的请求格式发。
  }
  return 'qwen'
}

export interface ChatDelta {
  reasoning: string
  content: string
}

export interface ChatOptions {
  messages: ChatMessage[]
  tools?: ToolSchema[]
  temperature?: number
  timeoutMs?: number
  fetcher?: typeof fetch
  signal?: AbortSignal
  /** 有这个回调时走流式响应，思考链会边生成边送回来。 */
  onDelta?: (partial: ChatDelta) => void
}

function endpointOf(baseUrl: string): string {
  const trimmed = baseUrl.trim().replace(/\/+$/, '')
  return `${trimmed}/chat/completions`
}

function requestHeaders(config: AgentConfig): Record<string, string> {
  return {
    'Content-Type': 'application/json',
    // 本地端点用 x-api-key；小米端点用 api-key。Bearer 两边都带。
    'x-api-key': config.apiKey,
    ...(modelDialect(config) === 'mimo' ? { 'api-key': config.apiKey } : {}),
    Authorization: `Bearer ${config.apiKey}`,
    Accept: 'text/event-stream, application/json'
  }
}

function completionLimit(config: AgentConfig): Record<string, unknown> {
  if (config.maxTokens <= 0) return {}
  return modelDialect(config) === 'mimo'
    ? { max_completion_tokens: config.maxTokens }
    : { max_tokens: config.maxTokens }
}

function thinkingBody(config: AgentConfig): Record<string, unknown> {
  if (modelDialect(config) === 'mimo') return { thinking: { type: config.thinking ? 'enabled' : 'disabled' } }
  // Qwen3 系用这个字段开关思考链。关掉时必须显式传 false，只省略字段时服务端仍可能在想。
  return { chat_template_kwargs: { enable_thinking: config.thinking } }
}

interface ToolDraft { id: string; name: string; arguments: string }

function draftsToCalls(tools: ToolDraft[]): AssistantToolCall[] {
  return tools.filter(tool => tool.id && tool.name).map(tool => ({
    id: tool.id,
    type: 'function' as const,
    function: { name: tool.name, arguments: tool.arguments }
  }))
}

function absorbToolDelta(tools: ToolDraft[], raw: unknown): void {
  if (!Array.isArray(raw)) return
  for (const item of raw) {
    if (typeof item !== 'object' || item === null) continue
    const record = item as Record<string, unknown>
    const index = typeof record.index === 'number' ? record.index : tools.length
    const current = tools[index] ?? { id: '', name: '', arguments: '' }
    if (typeof record.id === 'string' && record.id) current.id = record.id
    const fn = record.function
    if (typeof fn === 'object' && fn !== null) {
      const call = fn as Record<string, unknown>
      if (typeof call.name === 'string') current.name += call.name
      if (typeof call.arguments === 'string') current.arguments += call.arguments
    }
    tools[index] = current
  }
}

function choiceFromPayload(parsed: unknown): ChatChoice {
  const record = parsed as Record<string, unknown>
  if (!Array.isArray(record.choices) || record.choices.length === 0) {
    throw new LlmError('INVALID_RESPONSE', '模型服务响应里没有 choices。')
  }
  const first = record.choices[0]
  const choice = (typeof first === 'object' && first !== null ? first : {}) as Record<string, unknown>
  const message = (typeof choice.message === 'object' && choice.message !== null ? choice.message : {}) as Record<string, unknown>
  return {
    content: typeof message.content === 'string' ? message.content : '',
    reasoning: typeof message.reasoning_content === 'string' ? message.reasoning_content : '',
    finishReason: typeof choice.finish_reason === 'string' ? choice.finish_reason : '',
    toolCalls: parseToolCalls(message.tool_calls)
  }
}

/** 读 OpenAI 兼容的 SSE。服务端如果仍回整段 JSON，也按整段解析。 */
async function readChatStream(response: Response, onDelta: (partial: ChatDelta) => void): Promise<ChatChoice> {
  const reader = response.body?.getReader()
  if (!reader) return choiceFromPayload(JSON.parse(await response.text()))
  const decoder = new TextDecoder()
  let buffer = ''
  let sawEvent = false
  const choice: ChatChoice = { content: '', reasoning: '', finishReason: '', toolCalls: [] }
  const tools: ToolDraft[] = []
  const emit = (): void => onDelta({ reasoning: choice.reasoning, content: choice.content })
  const applyEvent = (data: string): void => {
    if (!data || data === '[DONE]') return
    const parsed = JSON.parse(data) as Record<string, unknown>
    const first = Array.isArray(parsed.choices) ? parsed.choices[0] : undefined
    const row = (typeof first === 'object' && first !== null ? first : {}) as Record<string, unknown>
    const delta = (typeof row.delta === 'object' && row.delta !== null ? row.delta : {}) as Record<string, unknown>
    if (typeof delta.reasoning_content === 'string') choice.reasoning += delta.reasoning_content
    else if (typeof delta.reasoning === 'string') choice.reasoning += delta.reasoning
    if (typeof delta.content === 'string') choice.content += delta.content
    if (typeof row.finish_reason === 'string' && row.finish_reason) choice.finishReason = row.finish_reason
    absorbToolDelta(tools, delta.tool_calls)
    emit()
  }
  const takeLine = (line: string): void => {
    const trimmed = line.trim()
    if (!trimmed.startsWith('data:')) return
    sawEvent = true
    applyEvent(trimmed.slice(5).trim())
  }
  while (true) {
    const step = await reader.read()
    if (step.done) break
    buffer += decoder.decode(step.value, { stream: true })
    if (!sawEvent && buffer.trimStart().startsWith('{')) {
      while (true) {
        const rest = await reader.read()
        if (rest.done) break
        buffer += decoder.decode(rest.value, { stream: true })
      }
      const whole = choiceFromPayload(JSON.parse(buffer))
      onDelta({ reasoning: whole.reasoning, content: whole.content })
      return whole
    }
    const lines = buffer.split('\n')
    buffer = lines.pop() ?? ''
    for (const line of lines) takeLine(line)
  }
  if (buffer.trim()) takeLine(buffer)
  if (!sawEvent && buffer.trim().startsWith('{')) {
    const whole = choiceFromPayload(JSON.parse(buffer))
    onDelta({ reasoning: whole.reasoning, content: whole.content })
    return whole
  }
  choice.toolCalls = draftsToCalls(tools)
  return choice
}

function parseToolCalls(raw: unknown): AssistantToolCall[] {
  if (!Array.isArray(raw)) return []
  const calls: AssistantToolCall[] = []
  for (const item of raw) {
    if (typeof item !== 'object' || item === null) continue
    const record = item as Record<string, unknown>
    const functionPart = record.function
    if (typeof record.id !== 'string' || typeof functionPart !== 'object' || functionPart === null) continue
    const fn = functionPart as Record<string, unknown>
    if (typeof fn.name !== 'string' || typeof fn.arguments !== 'string') continue
    calls.push({ id: record.id, type: 'function', function: { name: fn.name, arguments: fn.arguments } })
  }
  return calls
}

/** 单次（非流式）chat/completions 调用。地址与密钥只来自后台读取的配置。 */
export async function chatCompletion(config: AgentConfig, options: ChatOptions): Promise<ChatOutcome> {
  const fetcher = options.fetcher ?? globalThis.fetch.bind(globalThis)
  const controller = new AbortController()
  let timedOut = false
  const onExternalAbort = () => controller.abort()
  options.signal?.addEventListener('abort', onExternalAbort, { once: true })
  const timer = setTimeout(() => {
    timedOut = true
    controller.abort()
  }, options.timeoutMs ?? 120_000)
  try {
    const response = await fetcher(endpointOf(config.baseUrl), {
      method: 'POST',
      headers: requestHeaders(config),
      body: JSON.stringify({
        model: config.model,
        messages: options.messages.map(message => ({
          role: message.role,
          content: message.content,
          ...(message.toolCallId === undefined ? {} : { tool_call_id: message.toolCallId }),
          ...(message.toolCalls === undefined || message.toolCalls.length === 0 ? {} : {
            tool_calls: message.toolCalls.map(call => ({ id: call.id, type: call.type, function: call.function }))
          })
        })),
        ...(options.tools === undefined || options.tools.length === 0 ? {} : { tools: options.tools }),
        ...(options.temperature === undefined ? {} : { temperature: options.temperature }),
        ...completionLimit(config),
        ...thinkingBody(config),
        ...(options.onDelta ? { stream: true } : {})
      }),
      signal: controller.signal
    })
    if (!response.ok) {
      const body = await response.text().catch(() => '')
      const brief = body.slice(0, 300).replace(/\s+/g, ' ').trim()
      throw new LlmError('HTTP_ERROR', `模型服务返回 HTTP ${response.status}${brief ? `：${brief}` : '。'}`, response.status)
    }
    if (options.onDelta && response.body) {
      const choice = await readChatStream(response, options.onDelta)
      return { choices: [choice], usage: null, raw: null }
    }
    const body = await response.text()
    let parsed: unknown
    try {
      parsed = JSON.parse(body)
    } catch {
      throw new LlmError('INVALID_RESPONSE', '模型服务响应不是有效 JSON。')
    }
    const record = parsed as Record<string, unknown>
    if (!Array.isArray(record.choices) || record.choices.length === 0) {
      throw new LlmError('INVALID_RESPONSE', '模型服务响应里没有 choices。')
    }
    const usageRaw = record.usage
    const usage = typeof usageRaw === 'object' && usageRaw !== null &&
      typeof (usageRaw as Record<string, unknown>).prompt_tokens === 'number' &&
      typeof (usageRaw as Record<string, unknown>).completion_tokens === 'number'
      ? { promptTokens: (usageRaw as Record<string, number>).prompt_tokens, completionTokens: (usageRaw as Record<string, number>).completion_tokens }
      : null
    const choices = (record.choices as unknown[]).map((item): ChatChoice => {
      const choice = (typeof item === 'object' && item !== null ? item : {}) as Record<string, unknown>
      const message = (typeof choice.message === 'object' && choice.message !== null ? choice.message : {}) as Record<string, unknown>
      const content = typeof message.content === 'string' ? message.content : ''
      const reasoning = typeof message.reasoning_content === 'string' ? message.reasoning_content : ''
      return {
        content,
        reasoning,
        finishReason: typeof choice.finish_reason === 'string' ? choice.finish_reason : '',
        toolCalls: parseToolCalls(message.tool_calls)
      }
    })
    return { choices, usage, raw: parsed }
  } catch (error) {
    if (error instanceof LlmError) throw error
    if (options.signal?.aborted && !timedOut) throw new LlmError('REQUEST_TIMEOUT', '已停下。')
    if (timedOut) throw new LlmError('REQUEST_TIMEOUT', '模型服务请求超时。')
    if (controller.signal.aborted) throw new LlmError('REQUEST_TIMEOUT', '模型服务请求已取消。')
    throw new LlmError('NETWORK_ERROR', '无法连接模型服务，请检查地址、密钥和网络。')
  } finally {
    clearTimeout(timer)
    options.signal?.removeEventListener('abort', onExternalAbort)
  }
}

/**
 * 这一轮先打主模型。主模型不通就换备用，并在本轮后续请求里继续用备用。
 * 下一轮要重新 bind，好让主模型恢复后还能先试主模型。
 * 已经开始吐字的请求不改接备用，避免两段回答粘在一起。
 */
export function bindModelFallback(hooks?: { onSwitch?: () => void }): (config: AgentConfig, options: ChatOptions) => Promise<ChatOutcome> {
  let sticky = false
  let told = false
  return async (config, options) => {
    if (sticky) return chatCompletion(fallbackAgentConfig(config), options)
    if (usesFallbackEndpoint(config)) return chatCompletion(config, options)
    let streamed = false
    const watched: ChatOptions = options.onDelta
      ? { ...options, onDelta: partial => { streamed = true; options.onDelta?.(partial) } }
      : options
    try {
      return await chatCompletion(config, watched)
    } catch (error) {
      if (streamed || !(error instanceof LlmError) || !shouldFallbackModel(error)) throw error
      sticky = true
      if (!told) {
        told = true
        hooks?.onSwitch?.()
      }
      return chatCompletion(fallbackAgentConfig(config), options)
    }
  }
}

/** 单次调用的备用。对话一轮用 bindModelFallback，避免每一步都先撞主模型。 */
export function chatCompletionWithFallback(config: AgentConfig, options: ChatOptions): Promise<ChatOutcome> {
  return bindModelFallback()(config, options)
}

