export interface AgentTurnResult {
  reply: string
  steps: number
  memory: AgentMemoryState
  history: Array<{ role: 'user' | 'assistant'; content: string }>
}

export type Complete = typeof chatCompletion

function wait(ms: number): Promise<void> {
  return new Promise(resolve => { setTimeout(resolve, ms) })
}

function messageOf(turn: { role: string; content: string; guidance?: string }): string {
  if (turn.role === 'assistant') {
    const split = splitAgentReply(turn.content)
    return omitVerdict(split.thought ? split.answer : turn.content)
  }
  if (turn.role === 'user' && turn.guidance) return `${turn.content}\n\n${turn.guidance}`
  return turn.content
}

/** 裁决行不送回模型。页面上仍保留原文，下一句普通提问不会照着抄。 */
function omitVerdict(text: string): string {
  const lines = text.split('\n')
  const kept: string[] = []
  let dropped = 0
  for (const line of lines) {
    if (line.trim() && readArbitrationDecisions(line).length > 0) {
      dropped += 1
      continue
    }
    kept.push(line)
  }
  if (!dropped) return text
  const rest = kept.join('\n').trim()
  const note = `上一轮收件人裁决共 ${dropped} 行，原文已略去，不要照抄。`
  return rest ? `${note}\n${rest}` : note
}

function isArbitrationAsk(text: string): boolean {
  return text.includes('请仲裁收件人和抄送')
}

function repeatsPrevious(state: AgentMemoryState, reply: string): boolean {
  const answer = (splitAgentReply(reply).answer || reply).replace(/\s+/g, '')
  if (!answer) return false
  const visible = state.turns.filter(turn => !turn.hidden && (turn.role === 'user' || turn.role === 'assistant'))
  for (let index = visible.length - 1; index >= 0; index -= 1) {
    const turn = visible[index]
    if (!turn || turn.role !== 'assistant') continue
    const prior = modelAnswer(turn.content).replace(/\s+/g, '')
    return prior.length > 0 && prior === answer
  }
  return false
}

/** 仲裁只看这一批材料。更早的闲聊留在记忆里，但不送给模型，避免它顺着上一轮的英文接着写。续写时仍带上这一轮刚加的隐藏提示。 */
function plainTurns(turns: AgentMemoryState['turns']): AgentMemoryState['turns'] {
  let start = turns.length - 1
  while (start > 0 && turns[start]?.hidden) start -= 1
  return turns.slice(Math.max(0, start))
}

/** 系统提示保持不变。摘录和长期记忆挂在这一轮的用户消息上，不改已经发出的历史。 */
function toChat(state: AgentMemoryState, system = SYSTEM_PROMPT): ChatMessage[] {
  const asked = [...state.turns].reverse().find(turn => turn.role === 'user' && !turn.hidden)?.content ?? ''
  const facts = factsForPrompt(state, asked).map(fact => `- ${fact.text}`).join('\n')
  const visibleUsers = state.turns.flatMap((turn, index) => turn.role === 'user' && !turn.hidden ? [index] : [])
  const firstUser = visibleUsers[0]
  const lastUser = visibleUsers[visibleUsers.length - 1]
  return [
    { role: 'system', content: system },
    ...state.turns.map((turn, index): ChatMessage => ({
      role: turn.role,
      content: outgoingContent(turn, index, firstUser, lastUser, state.summary, facts),
      ...(turn.toolCallId ? { toolCallId: turn.toolCallId } : {}),
      ...(turn.toolCalls ? { toolCalls: turn.toolCalls } : {})
    }))
  ]
}

function outgoingContent(turn: MemoryTurn, index: number, firstUser: number | undefined, lastUser: number | undefined, summary: string, facts: string): string {
  let text = messageOf(turn)
  if (turn.role === 'tool' && lastUser !== undefined && index < lastUser) return projectOldToolText(text)
  if (turn.role !== 'user' || turn.hidden) return text
  if (index !== lastUser && isArbitrationAsk(text)) return '上一轮已经仲裁过收件人。材料不重复附上，不要照抄裁决行。'
  if (index === firstUser && summary) text = `更早对话的原文摘录：\n${summary}\n\n${text}`
  if (index === lastUser && facts) text = `${text}\n\n本轮可以参考的长期记忆：\n${facts}`
  return text
}

function withTool(state: AgentMemoryState, id: string, text: string): AgentMemoryState {
  return { ...state, turns: [...state.turns, { role: 'tool', content: text, toolCallId: id }] }
}

function sealSkipped(state: AgentMemoryState, calls: AssistantToolCall[]): AgentMemoryState {
  return calls.reduce((current, call) => withTool(current, call.id, skippedToolText()), state)
}

/** 先把超长工具结果收成头尾，再摘更早的原话。摘录连续三次没变短就停。 */
async function compress(_config: AgentConfig, state: AgentMemoryState, _complete: Complete): Promise<AgentMemoryState> {
  const trimmed = trimToolResults(state)
  if ((trimmed.digestMisses ?? 0) >= DIGEST_MISS_LIMIT) return trimmed
  if (!needsCompression(trimmed)) return trimmed
  const { older } = splitForCompression(trimmed)
  if (older.length === 0) return { ...trimmed, digestMisses: Math.min(DIGEST_MISS_LIMIT, (trimmed.digestMisses ?? 0) + 1) }
  const next = applySummary(trimmed, foldDigest(trimmed.summary, older))
  if (!next.summary || contextChars(next) >= contextChars(trimmed)) {
    return { ...trimmed, digestMisses: Math.min(DIGEST_MISS_LIMIT, (trimmed.digestMisses ?? 0) + 1) }
  }
  return { ...next, digestMisses: 0 }
}

/** 手动收摘录。最近一大段原话照留，缓存还没超出这段时不动。 */
export async function compactAgentMemory(_config: AgentConfig, memory: AgentMemoryState, _complete: Complete = chatCompletion): Promise<{ memory: AgentMemoryState; reply: string }> {
  const trimmed = trimToolResults(memory)
  const { older } = splitForCompression(trimmed)
  if (older.length === 0) return { memory: trimmed, reply: '这段对话还没到要收的长度，先不用压。' }
  const next = applySummary(trimmed, foldDigest(trimmed.summary, older))
  return { memory: { ...next, digestMisses: 0 }, reply: '更早的对话已收成原文摘录，最近一大段原话还在。' }
}

const SAVED_STEPS = new Set<string>([...Object.values(TOOL_ACTIVITY), '正在办理', '已拆成计划', '连着失败已停下', '重复查询已停下'])

interface JournalEntry { kind: 'thought' | 'step'; text: string; detail: string }

function appendThought(items: JournalEntry[], text: string): void {
  const cleaned = text.trim()
  if (!cleaned) return
  const last = items.at(-1)
  if (last?.kind === 'thought') {
    if (cleaned === last.text || cleaned.startsWith(last.text)) {
      last.text = cleaned
      return
    }
    if (last.text.startsWith(cleaned)) return
  }
  items.push({ kind: 'thought', text: cleaned, detail: '' })
}

function appendStep(items: JournalEntry[], label: string, detail?: string): void {
  if (!SAVED_STEPS.has(label)) return
  if (detail) {
    const open = [...items].reverse().find(item => item.kind === 'step' && item.text === label && !item.detail)
    if (open) {
      open.detail = detail
      return
    }
    items.push({ kind: 'step', text: label, detail })
    return
  }
  const last = items.at(-1)
  if (last?.kind === 'step' && last.text === label && !last.detail) return
  items.push({ kind: 'step', text: label, detail: '' })
}

function renderJournal(items: readonly JournalEntry[]): string {
  const blocks: string[] = []
  let steps: string[] = []
  const flush = (): void => {
    if (steps.length === 0) return
    blocks.push(steps.join('\n'))
    steps = []
  }
  for (const item of items) {
    if (item.kind === 'step') {
      steps.push(item.detail ? `- ${item.text}：${item.detail}` : `- ${item.text}`)
      continue
    }
    flush()
    if (item.text.trim()) blocks.push(item.text.trim())
  }
  flush()
  return blocks.join('\n\n')
}

function isStepBlock(block: string): boolean {
  const lines = block.split('\n').map(line => line.trim()).filter(Boolean)
  return lines.length > 0 && lines.every(line => line.startsWith('- '))
}

/** 超长时先丢掉前面的思考，步骤留下。否则结束后折叠里就只剩思考。 */
function clipJournal(body: string): string {
  if (body.length <= 12_000) return body
  const blocks = body.split(/\n{2,}/).map(block => block.trim()).filter(Boolean)
  const chosen: string[] = []
  let used = 0
  for (let index = blocks.length - 1; index >= 0; index -= 1) {
    const block = blocks[index] ?? ''
    const next = used + block.length + 2
    if (next > 12_000 && (!isStepBlock(block) || used > 0)) continue
    chosen.push(block)
    used = next
  }
  return chosen.reverse().join('\n\n')
}

/** 思考和步骤按发生顺序收成一段。展开后先看到先发生的那一件。 */
export function packJournal(reply: string, journal: readonly JournalEntry[]): string {
  const split = splitAgentReply(reply)
  const answer = (split.answer || reply).trim()
  const items = journal.map(item => ({ ...item }))
  if (split.thought.trim() && split.thought.trim() !== answer) appendThought(items, split.thought)
  const body = renderJournal(items)
  if (!body) return answer
  return `${THOUGHT_MARK}thought${THOUGHT_MARK}${clipJournal(body)}${THOUGHT_MARK}${answer}`
}

/** 思考模式打开时，把思考链放在正文前面。正文还没写出来时不把思考当成回复。 */
function replyText(choice: { content: string; reasoning?: string }, thinking: boolean): string {
  const answer = choice.content.trim()
  const thought = thinking ? (choice.reasoning ?? '').trim() : ''
  if (!answer || !thought || thought === answer) return answer
  return `${THOUGHT_MARK}thought${THOUGHT_MARK}${thought}${THOUGHT_MARK}${answer}`
}

/** 模型把推理写进了正文。这种半截独白不能当给用户的回复。 */
function isSelfTalk(text: string): boolean {
  return (text.match(/我应该|让我|规则说|不符合规则|再仔细看/g) ?? []).length >= 3
}

function hitLength(reason: string): boolean {
  return reason === 'length' || reason === 'max_tokens'
}

function thinkLeftOpen(text: string): boolean {
  return /^<think>/i.test(text) && !/<\/think>/i.test(text)
}

function shouldResume(choice: { content: string; reasoning?: string; finishReason: string; toolCalls: unknown[] }, thinking: boolean): boolean {
  if (choice.toolCalls.length > 0) return false
  if (thinkLeftOpen(choice.content) || isSelfTalk(choice.content)) return true
  if (hitLength(choice.finishReason)) return true
  return thinking && !choice.content.trim() && Boolean(choice.reasoning?.trim())
}

/** 半截正文留下来接着写。推理独白不送回去，避免模型顺着独白继续。 */
function resumePartial(choice: { content: string }): string {
  if (!choice.content.trim() || isSelfTalk(choice.content) || thinkLeftOpen(choice.content)) return ''
  return choice.content.trim()
}

function mergeCut(partial: string, next: string): string {
  const head = partial.trim()
  const tail = next.trim()
  if (!head) return tail
  if (!tail) return head
  if (tail.startsWith(head)) return tail
  return /[。！？]$/.test(head) ? `${head}\n${tail}` : `${head}${tail}`
}

function groundSources(state: AgentMemoryState, traces: ToolTrace[], userText: string): string[] {
  const said = state.turns.filter(turn => turn.role === 'user' && !turn.hidden).map(turn => turn.content)
  // Memory acknowledgements and recalls are not independent evidence for new facts.
  const found = traces.filter(trace => trace.ok && trace.name !== 'remember' && trace.name !== 'recall').map(trace => trace.text)
  return [userText, ...said, ...found]
}

interface ToolBatch {
  state: AgentMemoryState
  traces: ToolTrace[]
  unknownStreak: number
  halt: boolean
}

/** 并行查到的文件和期限各留各的，后写上的那一边不要把另一边盖掉。 */
function absorbWork(current: AgentMemoryState, returned: AgentMemoryState, name: string): AgentMemoryState {
  const previous = current.work
  const patch = returned.work
  if ((name !== 'search_cases' && name !== 'search_deadlines') || !patch) {
    return previous ? { ...returned, work: previous } : returned
  }
  const work: AgentWork = {
    files: name === 'search_cases' ? patch.files : (previous?.files ?? []),
    deadlines: name === 'search_deadlines' ? patch.deadlines : (previous?.deadlines ?? []),
    ...(name === 'search_cases'
      ? (patch.fileQuery ? { fileQuery: patch.fileQuery } : {})
      : (previous?.fileQuery ? { fileQuery: previous.fileQuery } : {})),
    ...(name === 'search_deadlines'
      ? (patch.deadlineQuery ? { deadlineQuery: patch.deadlineQuery } : {})
      : (previous?.deadlineQuery ? { deadlineQuery: previous.deadlineQuery } : {}))
  }
  return { ...returned, work }
}

/** 每个工具调用都回一条结果。只读查询同一波一起跑，写操作仍按顺序。重复查询和无此工具在这里停。 */
async function runToolBatch(state: AgentMemoryState, calls: AssistantToolCall[], traces: ToolTrace[], unknownStreak: number, ctx: ToolContext, userText: string, onActivity?: (label: string, thought?: string, detail?: string) => void, compacted = false): Promise<ToolBatch> {
  let next = state
  const seen = traces.map(trace => ({ ...trace }))
  let unknown = unknownStreak
  let halt = false
  const groups = groupToolCalls(calls.map(call => call.function.name))
  for (const group of groups) {
    if (halt) break
    const ready: AssistantToolCall[] = []
    for (const index of group) {
      const call = calls[index]
      if (!call) continue
      const args = canonicalArgs(call.function.arguments)
      if (shouldStopFailures(seen, call.function.name, args)) {
        onActivity?.('连着失败已停下', undefined, activityDetail(failedQueryText(call.function.name)))
        const text = failedQueryText(call.function.name)
        next = withTool(next, call.id, text)
        seen.push({ name: call.function.name, args, text, ok: false })
        next = sealSkipped(next, calls.slice(index + 1))
        halt = true
        break
      }
      if (shouldStopRepeat(seen, call.function.name, args)) {
        onActivity?.('重复查询已停下', undefined, activityDetail(stuckQueryText(call.function.name, args)))
        const text = stuckQueryText(call.function.name, args)
        next = withTool(next, call.id, text)
        seen.push({ name: call.function.name, args, text, ok: false })
        next = sealSkipped(next, calls.slice(index + 1))
        halt = true
        break
      }
      ready.push(call)
    }
    if (ready.length === 0) break
    for (const call of ready) onActivity?.(toolActivity(call.function.name))
    const base = next
    const fresh: AssistantToolCall[] = []
    const reused = new Map<string, ToolTrace>()
    for (const call of ready) {
      const prior = previousTrace(seen, call.function.name, canonicalArgs(call.function.arguments))
      if (prior) reused.set(call.id, prior)
      else fresh.push(call)
    }
    const executed = new Map<string, { text: string; memory: AgentMemoryState; ok: boolean }>()
    if (fresh.length > 0) {
      const batch = await Promise.all(fresh.map(async call => {
        if (ctx.signal?.aborted) throw new LlmError('REQUEST_TIMEOUT', '已停下。')
        let verifiedArgs = call.function.arguments
        if (call.function.name === 'remember') {
          let requested: Record<string, unknown> | undefined
          try {
            const parsed: unknown = JSON.parse(verifiedArgs)
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) requested = parsed as Record<string, unknown>
          } catch { /* Let the tool report malformed JSON in its usual way. */ }
          if (requested) {
            const original = groundedMemoryText(requested.text, requested.source, groundSources(base, seen, userText))
            if (!original) return [call.id, {
              text: '没有写入长期记忆：未能核对到原话。请在source中逐字复制用户消息或本次成功工具结果中的原句，不能提供改写；只允许纠正一次。',
              memory: base, ok: false
            }] as const
            verifiedArgs = JSON.stringify({ text: original })
          }
        }
        const result = await executeAgentTool(call.function.name, verifiedArgs, ctx, base)
        return [call.id, result] as const
      }))
      for (const [id, result] of batch) executed.set(id, result)
    }
    for (const call of ready) {
      const args = canonicalArgs(call.function.arguments)
      const prior = reused.get(call.id)
      const result = prior ? { text: prior.text, memory: base, ok: prior.ok } : executed.get(call.id)
      if (!result) continue
      const text = result.text
      const memory = prior ? next : absorbWork(next, result.memory, call.function.name)
      const ok = result.ok
      const note = isUnknownTool(text) ? '' : repeatNote(seen, call.function.name, args, text)
      if (isUnknownTool(text)) unknown += 1
      else unknown = 0
      const stopUnknown = unknown >= UNKNOWN_STOP_AT
      const again = compacted && sameResultAgain(seen, call.function.name, args, text)
      const stored = `${text}${note}${again ? '\n整理过更早对话之后，同一结果又出现了一次，不再重复查。' : ''}${stopUnknown ? unknownStopNote() : ''}`
      seen.push({ name: call.function.name, args, text, ok })
      onActivity?.(toolActivity(call.function.name), undefined, activityDetail(stored))
      next = { ...memory, turns: [...next.turns, { role: 'tool', content: stored, toolCallId: call.id }] }
      if (call.function.name === 'remember' && shouldStopFailures(seen, 'remember', args)) {
        onActivity?.('记忆写入已停下', undefined, activityDetail(failedQueryText('remember')))
        next = sealSkipped(next, calls.slice(calls.indexOf(call) + 1))
        halt = true
        break
      }
      if (again) {
        const lastIndex = calls.indexOf(call)
        next = sealSkipped(next, calls.slice(lastIndex + 1))
        halt = true
        break
      }
      if (stopUnknown) {
        const lastIndex = calls.indexOf(call)
        next = sealSkipped(next, calls.slice(lastIndex + 1))
        halt = true
        break
      }
    }
  }
  return { state: next, traces: seen, unknownStreak: unknown, halt }
}

/** 一轮用户请求：先裁工具结果，再按工具调用循环。正文要过闸门，步数用尽时再要一次不带工具的收尾。 */
export async function runAgentTurn(config: AgentConfig, memory: AgentMemoryState, userText: string, ctx: ToolContext, complete: Complete = chatCompletion, onMemory?: (state: AgentMemoryState) => Promise<void>, onActivity?: (label: string, thought?: string, detail?: string) => void, plain = false): Promise<AgentTurnResult> {
  const resolved = resolveSlash(userText)
  if (resolved.kind === 'local' || resolved.kind === 'unknown') {
    return { reply: resolved.message, steps: 0, memory, history: visibleHistory(memory) }
  }
  const content = resolved.kind === 'skill' ? resolved.display : userText
  const guidance = resolved.kind === 'skill' ? resolved.guidance : undefined
  const required = requiredTools(content)
  const submitAsked = asksToSubmit(content)
  const factsAtStart = memory.facts
  let state: AgentMemoryState = {
    ...memory,
    turns: [...memory.turns, { role: 'user', content, ...(guidance ? { guidance } : {}) }]
  }
  if (needsCompression(state)) onActivity?.('正在整理更早的对话')
  const summaryBefore = state.summary
  state = trimToolResults(state)
  state = await compress(config, state, complete)
  const compacted = Boolean(state.summary) && state.summary !== summaryBefore
  const persistTranscript = async (): Promise<void> => {
    if (ctx.signal?.aborted) return
    await onMemory?.({ ...state, facts: factsAtStart })
  }
  let plan: WorkStep[] = []
  const journal: JournalEntry[] = []
  const watch = (label: string, thought?: string, detail?: string): void => {
    onActivity?.(label, thought, detail)
    appendStep(journal, label, detail)
  }
  const finish = async (reply: string, steps: number): Promise<AgentTurnResult> => {
    const packed = packJournal(reply, journal)
    state = { ...state, turns: [...state.turns.filter(turn => !turn.hidden), { role: 'assistant', content: packed }] }
    if (ctx.signal?.aborted) throw new LlmError('REQUEST_TIMEOUT', '已停下。')
    await onMemory?.(state)
    return { reply: packed, steps, memory: state, history: visibleHistory(state) }
  }
  const ask = async (withTools: boolean, override?: AgentConfig): Promise<ChatOutcome> => {
    const active = override ?? config
    const send = (current: AgentMemoryState): Promise<ChatOutcome> => {
      let thought = ''
      let draft = ''
      let shownThought = ''
      let shownDraft = ''
      let last = 0
      let timer: ReturnType<typeof setTimeout> | undefined
      const pushLive = (force = false): void => {
        const nextThought = thought.trim()
        const nextDraft = draft.trim()
        if ((nextThought === shownThought && nextDraft === shownDraft) || (!nextThought && !nextDraft)) return
        const now = Date.now()
        if (!force && last !== 0 && now - last < 80) {
          if (timer === undefined) timer = setTimeout(() => { timer = undefined; pushLive(true) }, 80)
          return
        }
        if (timer !== undefined) { clearTimeout(timer); timer = undefined }
        last = now
        if (nextThought && nextThought !== shownThought) {
          shownThought = nextThought
          onActivity?.('正在思考', shownThought)
        }
        if (nextDraft && nextDraft !== shownDraft) {
          shownDraft = nextDraft
          onActivity?.('正在写', shownDraft)
        }
      }
      const chatState = plain ? { ...current, summary: '', turns: plainTurns(current.turns) } : current
      return complete(active, {
        messages: toChat(chatState, plain ? ARBITRATION_SYSTEM : SYSTEM_PROMPT),
        ...(withTools && !plain ? { tools: agentToolSchemas([
          ...state.turns.filter(turn => turn.role === 'user').map(turn => [turn.content, turn.guidance].filter(Boolean).join('\n')),
          ...plan.map(step => [step.tool, step.args].filter(Boolean).join(' ')),
          ...traces.filter(trace => trace.ok).map(trace => trace.text)
        ]) } : {}),
        temperature: plain ? 0 : 0.2,
        onDelta: partial => {
          thought = partial.reasoning.trim()
          draft = partial.content.trim()
          pushLive()
        }
      }).finally(() => pushLive(true))
    }
    let upstreamTries = 0
    let transientTries = 0
    let overflowTries = 0
    let rateTries = 0
    let timeoutTries = 0
    for (;;) {
      try {
        return await send(state)
      } catch (error) {
        if (!(error instanceof LlmError)) throw error
        if (error.message === '已停下。') throw error
        const kind = llmFailureKind(error)
        if (kind === 'rate_limit' && rateTries < 2) {
          rateTries += 1
          onActivity?.('模型忙，稍等再试')
          await wait(RATE_LIMIT_BACKOFF_MS * rateTries)
          continue
        }
        if (kind === 'timeout' && timeoutTries < 1) {
          timeoutTries += 1
          onActivity?.('模型响应超时，再试一次')
          await wait(RATE_LIMIT_BACKOFF_MS)
          continue
        }
        if (kind === 'transient' && transientTries < 1) {
          transientTries += 1
          onActivity?.('网络不稳，再试一次')
          await wait(RATE_LIMIT_BACKOFF_MS)
          continue
        }
        if (kind === 'upstream' && upstreamTries < 2) {
          upstreamTries += 1
          onActivity?.('模型暂时没接上，再试一次')
          await wait(RATE_LIMIT_BACKOFF_MS)
          continue
        }
        if (kind === 'overflow' && overflowTries < 2) {
          overflowTries += 1
          let next = overflowTries === 1 ? trimToolResults(state, OVERFLOW_RETRY_CHARS) : dropOldTurns(state)
          if (contextChars(next) >= contextChars(state) && overflowTries === 1) {
            overflowTries = 2
            next = dropOldTurns(state)
          }
          if (contextChars(next) < contextChars(state)) {
            onActivity?.(overflowTries === 1 ? '正在缩短查询结果' : '正在整理更早的对话')
            state = next
            continue
          }
        }
        throw error
      }
    }
  }

  const askOrKeep = async (withTools: boolean, override?: AgentConfig): Promise<ChatOutcome> => {
    try {
      return await ask(withTools, override)
    } catch (error) {
      if (!(error instanceof LlmError) || error.message !== '已停下。') await onMemory?.(state)
      throw error
    }
  }

  const cutShort = '这轮回答写到一半被长度截断了，结论没有写完。再说一次我接着办。'
  const resumeCut = async (choice: ChatChoice): Promise<ChatChoice> => {
    if (!shouldResume(choice, config.thinking)) return choice
    onActivity?.('正在把剩下的写完')
    const partial = resumePartial(choice)
    const note = partial
      ? '上一句被输出长度截断了。从断句接着写完，不要重头再说，不要写思考过程。'
      : '思考已经够了。用简体中文直接给出结论，不要写思考过程。'
    const bookmark = state
    state = {
      ...state,
      turns: [
        ...state.turns,
        ...(partial ? [{ role: 'assistant' as const, content: partial, hidden: true }] : []),
        { role: 'user', content: note, hidden: true }
      ]
    }
    const fallback = (): ChatChoice => (
      partial
        ? { ...choice, content: partial, reasoning: '', finishReason: 'stop' }
        : { ...choice, content: cutShort, reasoning: '', finishReason: 'stop' }
    )
    try {
      const more = await askOrKeep(false, { ...config, thinking: false, maxTokens: Math.max(config.maxTokens, 4096) })
      const next = more.choices[0]
      state = bookmark
      if (!next || next.toolCalls.length > 0 || !next.content.trim() || isSelfTalk(next.content) || thinkLeftOpen(next.content)) return fallback()
      return { ...next, content: partial ? mergeCut(partial, next.content) : next.content.trim(), reasoning: '', finishReason: 'stop' }
    } catch (error) {
      state = bookmark
      if (error instanceof LlmError && error.message === '已停下。') throw error
      return fallback()
    }
  }

  const traces: ToolTrace[] = []
  if (plain) {
    onActivity?.('正在仲裁收件人和抄送')
    const outcome = await askOrKeep(false)
    const choice = outcome.choices[0]
    if (!choice || choice.toolCalls.length > 0) return finish(choice?.content.trim() || '这批没有裁出收件人。', 1)
    const settled = await resumeCut(choice)
    return finish(replyText(settled, config.thinking) || '这批没有裁出收件人。', 1)
  }
  let unknownStreak = 0
  let candidate = ''
  let nudges = 0
  let steps = 0
  let halt = false
  const toolNames = new Set(agentToolSchemas().map(tool => tool.function.name))
  while (steps < stepLimit(plan.length) && !halt) {
    steps += 1
    onActivity?.(config.thinking ? '正在思考' : '正在组织回答')
    const outcome = await askOrKeep(true)
    const choice = outcome.choices[0]
    if (!choice) { halt = true; break }
    if (choice.toolCalls.length > 0) {
      if (config.thinking) appendThought(journal, choice.reasoning ?? '')
      state = { ...state, turns: [...state.turns, { role: 'assistant', content: choice.content, toolCalls: choice.toolCalls }] }
      const expected = plan[0]
      const batch = await runToolBatch(state, choice.toolCalls, traces, unknownStreak, ctx, content, watch, compacted)
      state = batch.state
      traces.splice(0, traces.length, ...batch.traces)
      unknownStreak = batch.unknownStreak
      halt = batch.halt
      const written = planFromCalls(choice.toolCalls, traces, toolNames)
      if (written) {
        plan = written
        watch('已拆成计划', undefined, written.map((step, index) => `${index + 1}.${step.title}`).join(' '))
      } else if (expected && !choice.toolCalls.some(call => call.function.name === expected.tool && (!expected.args || expected.args === canonicalArgs(call.function.arguments)))) {
        const argsNote = expected.args ? `，参数 ${expected.args}` : ''
        state = {
          ...state,
          turns: [...state.turns, { role: 'user', content: `计划的下一步是「${expected.title}」，要调用 ${expected.tool}${argsNote}。刚才做的不是这一步。`, hidden: true }]
        }
      }
      await persistTranscript()
      if (halt && traces.at(-1)?.name === 'remember' && !traces.at(-1)?.ok) return finish(failedQueryText('remember'), steps)
      if (halt) break
      continue
    }
    const settled = await resumeCut(choice)
    const reply = replyText(settled, config.thinking)
    if (!reply) { halt = true; break }
    if (!plain && repeatsPrevious(state, reply)) {
      if (nudges < MAX_NUDGES) {
        nudges += 1
        state = {
          ...state,
          turns: [
            ...state.turns,
            { role: 'assistant', content: reply, hidden: true },
            { role: 'user', content: '这和上一轮回复相同。直接回答用户这一句，不要照抄上一轮裁决或上一轮回复。', hidden: true }
          ]
        }
        continue
      }
      return finish('这次回复和上一轮一样，没有采用。请换个说法再问。', steps)
    }
    const planLeft = remainingWork(plan, traces).map(step => step.title)
    const gate = reviewReply({ answer: splitAgentReply(reply).answer || reply, required, traces, submitAsked, planLeft })
    if (gate.action === 'nudge' && nudges < MAX_NUDGES) {
      candidate = reply
      nudges += 1
      state = {
        ...state,
        turns: [
          ...state.turns,
          { role: 'assistant', content: reply, hidden: true },
          { role: 'user', content: gate.note, hidden: true }
        ]
      }
      continue
    }
    if (gate.action === 'nudge') {
      candidate = reply
      break
    }
    return finish(reply, steps)
  }
  if (candidate) return finish(candidate, steps)
  onActivity?.('正在整理这轮结果')
  const unfinished = remainingWork(plan, traces).map(step => step.title)
  const wrap = unfinished.length ? `${WRAP_NOTE}\n还没做完：${unfinished.join('、')}。` : WRAP_NOTE
  state = { ...state, turns: [...state.turns, { role: 'user', content: wrap, hidden: true }] }
  try {
    const outcome = await askOrKeep(false)
    const choice = outcome.choices[0]
    const settled = choice && choice.toolCalls.length === 0 ? await resumeCut(choice) : null
    const reply = settled ? replyText(settled, config.thinking) : ''
    if (reply && (plain || !repeatsPrevious(state, reply))) return finish(reply, steps)
  } catch (error) {
    if (error instanceof LlmError && error.message === '已停下。') throw error
  }
  const stuck = unfinished.length ? `${STEP_LIMIT_REPLY}\n还没做完：${unfinished.join('、')}。` : STEP_LIMIT_REPLY
  return finish(stuck, steps)
}

import type { AssistantToolCall } from './llm'
import type { SelectedPatentFile } from '../mail/types'

export const AGENT_MEMORY_KEY = 'patmail.agent.memory.v1'

/** 一轮原话上限。默认 8192 token 的回复，加上思考，会超过 2 万字。 */
export const AGENT_TURN_CHARS = 100_000
/** 一次结果里带回的可见对话。更早的仍留在记忆里。 */
export const AGENT_HISTORY_LIMIT = 120

/** 近期原话。超长后旧的几轮收成原文摘录，不整段丢掉。 */
export interface MemoryTurn {
  role: 'user' | 'assistant' | 'tool'
  content: string
  /** 点名技能时附给模型的做法。页面上只显示 content。 */
  guidance?: string
  toolCallId?: string
  toolCalls?: AssistantToolCall[]
  /** 闸门追加的说明。模型要看见，页面上不显示。 */
  hidden?: boolean
}

/** 跨会话还在的事实：偏好、常用客户、没做完的交代。 */
export interface MemoryFact {
  id: string
  text: string
  at: string
}

/** 这一段对话里查到、下一句还能接着用的文件和期限。跟对话走，不跟长期记忆走。 */
export interface AgentDeadlineRef {
  procId: string
  caseId: string
  caseVolume: string
}

export interface AgentWork {
  files: SelectedPatentFile[]
  deadlines: AgentDeadlineRef[]
  fileQuery?: string
  deadlineQuery?: string
}

/** 和文件查询页最大的一页一样。 */
export const AGENT_FILE_KEEP = 100
/** 期限页一次收集时每页 100，这里留两页。 */
export const AGENT_DEADLINE_KEEP = 200

export interface AgentMemoryState {
  summary: string
  turns: MemoryTurn[]
  facts: MemoryFact[]
  /** 原文摘录连续没变短的次数。到 3 次就停，避免同一段反复摘。 */
  digestMisses?: number
  /** 当前这段对话查到的文件和期限。换一段对话就换一份。 */
  work?: AgentWork
}

export const EMPTY_MEMORY: AgentMemoryState = { summary: '', turns: [], facts: [] }

/** Qwen3.6-35B-A3B 原生窗口。按字符估算，中文大约一字一 token，用来提前留出余量。 */
const CONTEXT_WINDOW_CHARS = 262_144
/**
 * 存下来的对话超过这个长度才收摘录。取窗口的四分之三，
 * 给系统提示、工具说明和这一轮回复留位置。Codex 也是快到窗口上限才压。
 */
export const COMPRESS_AT_CHARS = Math.floor(CONTEXT_WINDOW_CHARS * 0.75)
/** 压完后仍把最近这段原话交给模型。Codex 保留大约 6.4 万 token 的最近消息。 */
export const KEEP_RECENT_CHARS = 64_000
/** 极端情况下的存储上限，避免坏数据撑满浏览器缓存。正常在压缩阈值就会收掉。 */
const STORAGE_TURN_CHARS = 240_000
/** 单条工具结果的上限。超出留头尾，诊断经常在末尾。 */
export const TOOL_RESULT_CHARS = 2_400
const TOOL_OMISSION = '\n…中间已省略…\n'

/** 上一轮已经有多行的工具原文，发给模型时只留第一行。头尾裁过的结果保持原样。 */
export function projectOldToolText(text: string): string {
  if (text.includes('中间已省略')) return text
  const lines = text.split('\n').map(item => item.trim()).filter(Boolean)
  const first = lines[0]
  if (!first || lines.length < 2) return text
  return `${first.slice(0, 180)}\n较早的工具原文已收成一行。`
}

export function clipToolResult(text: string, max = TOOL_RESULT_CHARS): string {
  if (text.length <= max) return text
  const tail = Math.min(600, Math.floor(max / 4))
  const head = max - tail - TOOL_OMISSION.length
  if (head < 1) return text.slice(0, max)
  return `${text.slice(0, head)}${TOOL_OMISSION}${text.slice(-tail)}`
}

/** 上下文仍超长时再压一档。已经到这一档还超，就不再重试。 */
export const OVERFLOW_RETRY_CHARS = 800

export function trimToolResults(state: AgentMemoryState, max = TOOL_RESULT_CHARS): AgentMemoryState {
  let changed = false
  const turns = state.turns.map(turn => {
    if (turn.role !== 'tool') return turn
    const content = clipToolResult(turn.content, max)
    if (content === turn.content) return turn
    changed = true
    return { ...turn, content }
  })
  return changed ? { ...state, turns } : state
}
const MAX_FACTS = 60
const MAX_FACT_TEXT = 240

export interface MemoryStorage {
  get(key: string): Promise<Record<string, unknown>>
  set(items: Record<string, unknown>): Promise<void>
  remove?(keys: string | string[]): Promise<void>
}

function isToolCall(value: unknown): value is AssistantToolCall {
  if (typeof value !== 'object' || value === null) return false
  const call = value as Record<string, unknown>
  const fn = call.function
  return typeof call.id === 'string' && call.type === 'function' &&
    typeof fn === 'object' && fn !== null &&
    typeof (fn as Record<string, unknown>).name === 'string' &&
    typeof (fn as Record<string, unknown>).arguments === 'string'
}

function clipText(value: unknown, max: number): string {
  return typeof value === 'string' ? value.trim().slice(0, max) : ''
}

function readStoredFile(value: unknown): SelectedPatentFile | null {
  if (typeof value !== 'object' || value === null) return null
  const row = value as Record<string, unknown>
  const fileId = clipText(row.fileId, 80)
  const fileName = clipText(row.fileName, 300)
  if (!fileId || !fileName) return null
  const file: SelectedPatentFile = {
    fileId,
    fileName,
    fileDescription: clipText(row.fileDescription, 300),
    customerName: clipText(row.customerName, 200)
  }
  const caseId = clipText(row.caseId, 80)
  const caseName = clipText(row.caseName, 300)
  const caseVolume = clipText(row.caseVolume, 80)
  const customerVolume = clipText(row.customerVolume, 80)
  const applicationNo = clipText(row.applicationNo, 80)
  const officialPostDate = clipText(row.officialPostDate, 40)
  if (caseId) file.caseId = caseId
  if (caseName) file.caseName = caseName
  if (caseVolume) file.caseVolume = caseVolume
  if (customerVolume) file.customerVolume = customerVolume
  if (applicationNo) file.applicationNo = applicationNo
  if (officialPostDate) file.officialPostDate = officialPostDate
  return file
}

function readStoredDeadline(value: unknown): AgentDeadlineRef | null {
  if (typeof value !== 'object' || value === null) return null
  const row = value as Record<string, unknown>
  const procId = clipText(row.procId, 80)
  const caseVolume = clipText(row.caseVolume, 80)
  if (!procId || !caseVolume) return null
  return { procId, caseId: clipText(row.caseId, 80), caseVolume }
}

function readWork(value: unknown): AgentWork | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const row = value as Record<string, unknown>
  const files = Array.isArray(row.files) ? row.files.flatMap(item => {
    const file = readStoredFile(item)
    return file ? [file] : []
  }).slice(0, AGENT_FILE_KEEP) : []
  const deadlines = Array.isArray(row.deadlines) ? row.deadlines.flatMap(item => {
    const deadline = readStoredDeadline(item)
    return deadline ? [deadline] : []
  }).slice(0, AGENT_DEADLINE_KEEP) : []
  const fileQuery = clipText(row.fileQuery, 500)
  const deadlineQuery = clipText(row.deadlineQuery, 500)
  if (files.length === 0 && deadlines.length === 0 && !fileQuery && !deadlineQuery) return undefined
  return {
    files,
    deadlines,
    ...(fileQuery ? { fileQuery } : {}),
    ...(deadlineQuery ? { deadlineQuery } : {})
  }
}

function isTurn(value: unknown): value is MemoryTurn {
  if (typeof value !== 'object' || value === null) return false
  const turn = value as Record<string, unknown>
  if (turn.role !== 'user' && turn.role !== 'assistant' && turn.role !== 'tool') return false
  if (typeof turn.content !== 'string' || turn.content.length > AGENT_TURN_CHARS) return false
  if (turn.toolCallId !== undefined && typeof turn.toolCallId !== 'string') return false
  if (turn.toolCalls !== undefined && !(Array.isArray(turn.toolCalls) && turn.toolCalls.every(isToolCall))) return false
  if (turn.guidance !== undefined && (typeof turn.guidance !== 'string' || turn.guidance.length > 8_000)) return false
  return true
}

export function normalizeMemory(value: unknown): AgentMemoryState {
  if (typeof value !== 'object' || value === null) return { ...EMPTY_MEMORY }
  const record = value as Record<string, unknown>
  const turns = Array.isArray(record.turns) ? record.turns.flatMap((item): MemoryTurn[] => {
    if (!isTurn(item)) return []
    const hidden = item.hidden === true ? { hidden: true as const } : {}
    if (item.role !== 'user' || typeof item.guidance !== 'string' || !item.guidance.trim()) {
      return [{
        role: item.role,
        content: item.content,
        ...(item.toolCallId ? { toolCallId: item.toolCallId } : {}),
        ...(item.toolCalls ? { toolCalls: item.toolCalls } : {}),
        ...hidden
      }]
    }
    return [{ ...item, guidance: item.guidance.trim().slice(0, 4_000), ...hidden }]
  }) : []
  const facts = Array.isArray(record.facts) ? record.facts.flatMap((item): MemoryFact[] => {
    if (typeof item !== 'object' || item === null) return []
    const fact = item as Record<string, unknown>
    if (typeof fact.id !== 'string' || typeof fact.text !== 'string' || typeof fact.at !== 'string') return []
    const text = fact.text.trim().slice(0, MAX_FACT_TEXT)
    if (!text) return []
    return [{ id: fact.id.slice(0, 80), text, at: fact.at.slice(0, 40) }]
  }).slice(-MAX_FACTS) : []
  const summary = typeof record.summary === 'string' ? record.summary.slice(0, 4_000) : ''
  const misses = typeof record.digestMisses === 'number' && Number.isFinite(record.digestMisses)
    ? Math.max(0, Math.min(3, Math.floor(record.digestMisses)))
    : 0
  const work = readWork(record.work)
  return { summary, turns: capStoredTurns(turns), facts, ...(misses > 0 ? { digestMisses: misses } : {}), ...(work ? { work } : {}) }
}

/** 发给模型的助手原文。思考和步骤留在页面上，不计入这段长度。 */
export function modelAnswer(content: string): string {
  const head = '\u001ethought\u001e'
  if (!content.startsWith(head)) return content
  const rest = content.slice(head.length)
  const cut = rest.indexOf('\u001e')
  return cut >= 0 ? rest.slice(cut + 1) : ''
}

export function turnChars(turn: MemoryTurn): number {
  const calls = turn.toolCalls?.reduce((sum, call) => sum + call.function.name.length + call.function.arguments.length, 0) ?? 0
  const content = turn.role === 'assistant' ? modelAnswer(turn.content) : turn.content
  return content.length + (turn.guidance?.length ?? 0) + calls
}

/** 存在本机缓存里、会交给模型的原文有多长。关掉后台再打开，用同一份记录重算。 */
export function contextChars(state: AgentMemoryState): number {
  return state.summary.length + state.turns.reduce((sum, turn) => sum + turnChars(turn), 0)
}

/** 会话目录。每段对话一份原文，长期记忆放在目录上，各段共用。 */
export const AGENT_SESSIONS_KEY = 'patmail.agent.sessions.v1'
/** 新建对话时要不要先问名字。存在本机，和某一段对话无关。 */
export const AGENT_ASK_SESSION_NAME_KEY = 'patmail.agent.askSessionName'
const SESSION_PREFIX = 'patmail.agent.session.v1.'
export const MAX_AGENT_SESSIONS = 30
const SESSION_TITLE_LIMIT = 24

export interface AgentSessionInfo {
  id: string
  title: string
  updatedAt: string
  active: boolean
}

export interface AgentSessionSnapshot {
  memory: AgentMemoryState
  sessions: AgentSessionInfo[]
  activeId: string
}

interface SessionMeta { id: string; title: string; updatedAt: string; named?: boolean }
interface SessionIndex { activeId: string; facts: MemoryFact[]; items: SessionMeta[] }

function sessionKey(id: string): string {
  return `${SESSION_PREFIX}${id}`
}

function newSessionId(): string {
  const raw = globalThis.crypto?.randomUUID?.() ?? `s${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`
  return raw.replace(/[^A-Za-z0-9-]/g, '').slice(0, 40)
}

export function sessionTitleFrom(turns: readonly MemoryTurn[]): string {
  const first = turns.find(turn => turn.role === 'user' && !turn.hidden && turn.content.trim())
  if (!first) return '新对话'
  return clipSessionTitle(first.content)
}

/** 用户起的名字。空的表示还没起，列表里继续叫「新对话」。 */
export function clipSessionTitle(value: string): string {
  const line = value.replace(/\s+/g, ' ').trim()
  if (!line) return '新对话'
  return line.length > SESSION_TITLE_LIMIT ? `${line.slice(0, SESSION_TITLE_LIMIT)}…` : line
}

function sessionBody(state: AgentMemoryState): Pick<AgentMemoryState, 'summary' | 'turns' | 'digestMisses' | 'work'> {
  const normalized = normalizeMemory(state)
  return {
    summary: normalized.summary,
    turns: normalized.turns,
    ...(normalized.digestMisses ? { digestMisses: normalized.digestMisses } : {}),
    ...(normalized.work ? { work: normalized.work } : {})
  }
}

function transcriptEmpty(state: AgentMemoryState): boolean {
  return !state.summary && state.turns.every(turn => turn.hidden || !turn.content.trim())
}

function parseMeta(value: unknown): SessionMeta | null {
  if (typeof value !== 'object' || value === null) return null
  const row = value as Record<string, unknown>
  if (typeof row.id !== 'string' || !/^[A-Za-z0-9-]{8,40}$/.test(row.id)) return null
  const title = typeof row.title === 'string' && row.title.trim() ? row.title.trim().slice(0, 40) : '新对话'
  const updatedAt = typeof row.updatedAt === 'string' ? row.updatedAt.slice(0, 40) : ''
  return { id: row.id, title, updatedAt, ...(row.named === true ? { named: true } : {}) }
}

function parseIndex(value: unknown): SessionIndex | null {
  if (typeof value !== 'object' || value === null) return null
  const record = value as Record<string, unknown>
  if (!Array.isArray(record.items)) return null
  const items = record.items.flatMap((item): SessionMeta[] => {
    const meta = parseMeta(item)
    return meta ? [meta] : []
  }).slice(0, MAX_AGENT_SESSIONS)
  const activeId = typeof record.activeId === 'string' ? record.activeId : ''
  if (!items.some(item => item.id === activeId)) return null
  return { activeId, items, facts: normalizeMemory({ facts: record.facts }).facts }
}

function cardsOf(index: SessionIndex): AgentSessionInfo[] {
  return [...index.items]
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    .map(item => ({ ...item, active: item.id === index.activeId }))
}

async function readBody(area: MemoryStorage, id: string): Promise<AgentMemoryState> {
  try {
    return normalizeMemory((await area.get(sessionKey(id)))[sessionKey(id)])
  } catch {
    return { ...EMPTY_MEMORY, turns: [], facts: [] }
  }
}

async function ensureIndex(area: MemoryStorage): Promise<SessionIndex> {
  let stored: unknown
  try {
    stored = (await area.get(AGENT_SESSIONS_KEY))[AGENT_SESSIONS_KEY]
  } catch {
    stored = undefined
  }
  const parsed = parseIndex(stored)
  if (parsed) return parsed
  let legacy = { ...EMPTY_MEMORY, turns: [] as MemoryTurn[], facts: [] as MemoryFact[] }
  try {
    legacy = normalizeMemory((await area.get(AGENT_MEMORY_KEY))[AGENT_MEMORY_KEY])
  } catch { /* 旧记录读不到时从空对话开始 */ }
  const now = new Date().toISOString()
  const id = newSessionId()
  const index: SessionIndex = {
    activeId: id,
    facts: legacy.facts,
    items: [{ id, title: sessionTitleFrom(legacy.turns), updatedAt: now }]
  }
  try {
    await area.set({
      [AGENT_SESSIONS_KEY]: index,
      [sessionKey(id)]: sessionBody(legacy),
      [AGENT_MEMORY_KEY]: null
    })
  } catch { /* 存不下也先用这份索引顶着，回答不能丢 */ }
  return index
}

async function snapshot(area: MemoryStorage, index: SessionIndex): Promise<AgentSessionSnapshot> {
  const body = await readBody(area, index.activeId)
  return {
    memory: { ...body, facts: index.facts },
    sessions: cardsOf(index),
    activeId: index.activeId
  }
}

export async function readAgentSessions(area: MemoryStorage): Promise<AgentSessionSnapshot> {
  return snapshot(area, await ensureIndex(area))
}

export async function loadMemory(area: MemoryStorage): Promise<AgentMemoryState> {
  return (await readAgentSessions(area)).memory
}

/** 写不下时先把这段对话收短：更早的原话丢掉，只留最近一小段，工作清单也不存。 */
function shrunkBody(state: AgentMemoryState): AgentMemoryState {
  const { recent } = splitForCompression(state, 60_000)
  const tight: AgentMemoryState = { ...state, turns: recent }
  delete tight.work
  return tight
}

/** 存不下就先腾地方再试，最后宁可不存，也不能把这一轮回答丢掉。 */
export async function saveMemory(area: MemoryStorage, state: AgentMemoryState): Promise<void> {
  const index = await ensureIndex(area)
  const now = new Date().toISOString()
  const next: SessionIndex = {
    activeId: index.activeId,
    facts: normalizeMemory({ facts: state.facts }).facts,
    items: index.items.map(item => {
      if (item.id !== index.activeId) return item
      const title = item.named ? item.title : sessionTitleFrom(state.turns)
      return { id: item.id, title, updatedAt: now, ...(item.named ? { named: true as const } : {}) }
    })
  }
  const write = (body: AgentMemoryState): Promise<void> => area.set({
    [AGENT_SESSIONS_KEY]: next,
    [sessionKey(index.activeId)]: sessionBody(body)
  })
  try {
    await write(state)
    return
  } catch { /* 按缓存满处理，先收短再试 */ }
  const tight = shrunkBody(state)
  try {
    await write(tight)
    return
  } catch { /* 还是满就清掉其它对话的原文 */ }
  try {
    const ids = index.items.map(item => item.id).filter(id => id !== index.activeId)
    if (ids.length > 0 && area.remove) await area.remove(ids.map(sessionKey))
    await write(tight)
  } catch { /* 存不下就先不存 */ }
}

/** 当前这段还没有内容时不另开。满了就停，避免把更早的对话悄悄丢掉。有名字就固定下来，不再被第一句话替换。 */
export async function createAgentSession(area: MemoryStorage, title = ''): Promise<AgentSessionSnapshot & { message: string }> {
  const index = await ensureIndex(area)
  const current = await snapshot(area, index)
  if (transcriptEmpty(current.memory)) return { ...current, message: '这段对话还是空的，直接说就行。' }
  if (index.items.length >= MAX_AGENT_SESSIONS) {
    return { ...current, message: `对话已经有 ${MAX_AGENT_SESSIONS} 段，先删掉不用的再开新的。` }
  }
  const now = new Date().toISOString()
  const id = newSessionId()
  const named = title.replace(/\s+/g, ' ').trim().length > 0
  const next: SessionIndex = {
    activeId: id,
    facts: index.facts,
    items: [...index.items, { id, title: named ? clipSessionTitle(title) : '新对话', updatedAt: now, ...(named ? { named: true } : {}) }]
  }
  await area.set({
    [AGENT_SESSIONS_KEY]: next,
    [sessionKey(id)]: sessionBody(EMPTY_MEMORY)
  })
  return { ...(await snapshot(area, next)), message: '新对话已打开。之前的对话还在列表里，长期记忆是共用的。' }
}

export async function openAgentSession(area: MemoryStorage, id: string): Promise<AgentSessionSnapshot & { message: string }> {
  const index = await ensureIndex(area)
  if (!index.items.some(item => item.id === id)) {
    const current = await snapshot(area, index)
    return { ...current, message: '没有这段对话。' }
  }
  const next: SessionIndex = { ...index, activeId: id }
  await area.set({ [AGENT_SESSIONS_KEY]: next })
  return { ...(await snapshot(area, next)), message: '' }
}

/** 改列表里的名字。改过之后，第一句话不再覆盖它。 */
export async function renameAgentSession(area: MemoryStorage, id: string, title: string): Promise<AgentSessionSnapshot & { message: string }> {
  const index = await ensureIndex(area)
  if (!index.items.some(item => item.id === id)) {
    const current = await snapshot(area, index)
    return { ...current, message: '没有这段对话。' }
  }
  const named = title.replace(/\s+/g, ' ').trim().length > 0
  if (!named) {
    const current = await snapshot(area, index)
    return { ...current, message: '名字不能是空的。' }
  }
  const next: SessionIndex = {
    ...index,
    items: index.items.map(item => item.id === id ? { ...item, title: clipSessionTitle(title), named: true } : item)
  }
  await area.set({ [AGENT_SESSIONS_KEY]: next })
  return { ...(await snapshot(area, next)), message: '' }
}

/** 删的是这一段的上下文。长期记忆留在目录上。最后一段删掉后留一个空对话。 */
export async function removeAgentSession(area: MemoryStorage, id: string): Promise<AgentSessionSnapshot & { message: string }> {
  const index = await ensureIndex(area)
  if (!index.items.some(item => item.id === id)) {
    const current = await snapshot(area, index)
    return { ...current, message: '没有这段对话。' }
  }
  const rest = index.items.filter(item => item.id !== id)
  let activeId = index.activeId
  const created: SessionMeta[] = []
  if (rest.length === 0) {
    const now = new Date().toISOString()
    const fresh = { id: newSessionId(), title: '新对话', updatedAt: now }
    created.push(fresh)
    rest.push(fresh)
    activeId = fresh.id
  } else if (activeId === id) {
    activeId = [...rest].sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))[0]?.id ?? rest[0].id
  }
  const next: SessionIndex = { activeId, facts: index.facts, items: rest }
  await area.set({
    [AGENT_SESSIONS_KEY]: next,
    [sessionKey(id)]: null,
    ...(created[0] ? { [sessionKey(created[0].id)]: sessionBody(EMPTY_MEMORY) } : {})
  })
  return { ...(await snapshot(area, next)), message: '这段对话已删除。长期记忆还在。' }
}

export function needsCompression(state: AgentMemoryState): boolean {
  return contextChars(state) > COMPRESS_AT_CHARS
}

/**
 * 按缓存长度留下最近一大段原话。从末尾往前量，工具调用和它的返回必须留在同一边。
 */
export function splitForCompression(state: AgentMemoryState, keepChars = KEEP_RECENT_CHARS): { older: MemoryTurn[]; recent: MemoryTurn[] } {
  const turns = state.turns
  let size = 0
  let start = turns.length
  for (let index = turns.length - 1; index >= 0; index -= 1) {
    const cost = turnChars(turns[index])
    if (size > 0 && size + cost > keepChars) break
    size += cost
    start = index
  }
  while (start > 0 && turns[start]?.role === 'tool') start -= 1
  return { older: turns.slice(0, start), recent: turns.slice(start) }
}

function capStoredTurns(turns: MemoryTurn[]): MemoryTurn[] {
  if (contextChars({ summary: '', turns, facts: [] }) <= STORAGE_TURN_CHARS) return turns
  return splitForCompression({ summary: '', turns, facts: [] }, STORAGE_TURN_CHARS).recent
}

/** 模型嫌上下文太长时先丢更早的原话，把最近这一段留下。工具调用和它的返回留在同一边。 */
export function dropOldTurns(state: AgentMemoryState, keepChars = KEEP_RECENT_CHARS): AgentMemoryState {
  const { older, recent } = splitForCompression(state, keepChars)
  if (older.length === 0) return state
  return { ...state, turns: recent }
}

const DIGEST_NOTE = '以下是更早对话的原文摘录，不是查证结论。摘录里没有的文号、客户、日期和数量都不能当成已经查到。'
const DIGEST_LINE = /^- (用户：|工具原文：|调用了：|助手说过：)/

function oneLine(text: string, limit: number): string {
  return text.replace(/\s+/g, ' ').trim().slice(0, limit)
}

/** 旧工具摘录里的文号和长编号不留给后面的轮次照抄。 */
function redactOldEvidence(text: string): string {
  return text.replace(/ZL\d{6,}/gi, '文号已略').replace(/\b\d{10,}\b/g, '编号已略')
}

/** 从原话里摘句子。不改写，避免压缩时编出没出现过的文号或结论。 */
export function digestTurns(turns: MemoryTurn[]): string {
  const lines: string[] = []
  for (const turn of turns) {
    if (turn.hidden) continue
    if (turn.role === 'user') {
      const text = oneLine(turn.content, 160)
      if (text) lines.push(`- 用户：${text}`)
      continue
    }
    if (turn.role === 'tool') {
      const text = oneLine(redactOldEvidence(turn.content), 480)
      if (text) lines.push(`- 工具原文：${text}`)
      continue
    }
    if (turn.toolCalls?.length) {
      lines.push(`- 调用了：${turn.toolCalls.map(call => call.function.name).join('、')}`)
      continue
    }
    const answer = oneLine(turn.content.replace(/\u001ethought\u001e[\s\S]*?\u001e/g, ''), 120)
    if (answer && !answer.startsWith('**思考**')) lines.push(`- 助手说过：${answer}`)
  }
  return lines.join('\n')
}

/** 只保留上次摘录里的原文行，再接上新丢掉的原话。自由发挥的旧摘要整段丢掉。 */
export function foldDigest(previous: string, older: MemoryTurn[]): string {
  const kept = previous.split('\n').map(line => line.trim()).filter(line => DIGEST_LINE.test(line))
  const added = digestTurns(older).split('\n').filter(Boolean)
  const lines = [...kept, ...added]
  while (lines.length > 1 && lines.join('\n').length > 3_000) lines.shift()
  if (lines.length === 0) return ''
  return `${DIGEST_NOTE}\n${lines.join('\n')}`
}

export function applySummary(state: AgentMemoryState, summary: string): AgentMemoryState {
  const text = summary.trim().slice(0, 4_000)
  if (!text) return state
  const { recent } = splitForCompression(state)
  return { ...state, summary: text, turns: recent }
}

export function rememberFact(state: AgentMemoryState, text: string, now = new Date().toISOString()): AgentMemoryState {
  const cleaned = text.trim().replace(/\s+/g, ' ').slice(0, MAX_FACT_TEXT)
  if (!cleaned) return state
  if (state.facts.some(fact => fact.text === cleaned)) return state
  const id = globalThis.crypto?.randomUUID?.() ?? `fact-${state.facts.length + 1}`
  return { ...state, facts: [...state.facts, { id, text: cleaned, at: now }].slice(-MAX_FACTS) }
}

export function searchFacts(state: AgentMemoryState, query: string): MemoryFact[] {
  const needle = query.trim().toLowerCase()
  const matched = needle ? state.facts.filter(fact => fact.text.toLowerCase().includes(needle)) : state.facts
  return matched.slice(-12)
}

function factTerms(text: string): string[] {
  const terms: string[] = []
  for (const match of text.toLowerCase().matchAll(/[a-z0-9]{2,}/g)) terms.push(match[0])
  for (const run of text.matchAll(/[\u4e00-\u9fff]+/g)) {
    const chars = [...run[0]]
    for (let index = 0; index < chars.length - 1; index += 1) terms.push(`${chars[index] ?? ''}${chars[index + 1] ?? ''}`)
  }
  return terms
}

/** 和这句话对得上的长期记忆，再补上最近几条。最多 12 条。 */
export function factsForPrompt(state: AgentMemoryState, query: string): MemoryFact[] {
  const asked = new Set(factTerms(query))
  const matched = state.facts.filter(fact => factTerms(fact.text).some(term => asked.has(term))).slice(-8)
  const picked: MemoryFact[] = []
  const seen = new Set<string>()
  for (const fact of [...matched, ...state.facts.slice(-4)]) {
    if (seen.has(fact.id)) continue
    seen.add(fact.id)
    picked.push(fact)
    if (picked.length >= 12) break
  }
  return picked
}

/** 页面上只展示人和助手的原话，工具来回留在后台。 */
export function visibleHistory(state: AgentMemoryState): Array<{ role: 'user' | 'assistant'; content: string }> {
  return state.turns.flatMap(turn => {
    if (turn.hidden) return []
    if ((turn.role !== 'user' && turn.role !== 'assistant') || !turn.content.trim()) return []
    if (turn.role === 'assistant' && turn.toolCalls && turn.toolCalls.length > 0 && !turn.content.trim()) return []
    return [{ role: turn.role, content: turn.content.length > AGENT_TURN_CHARS ? turn.content.slice(0, AGENT_TURN_CHARS) : turn.content }]
  }).slice(-AGENT_HISTORY_LIMIT)
}

import initSqlJs, { type SqlStatic } from 'sql.js'
import wasmAsset from 'sql.js/dist/sql-wasm.wasm?url'
import type { RagIndexSnapshot, RagPassageRecord } from './rag-graph'

let engine: Promise<SqlStatic> | null = null
let binaryOverride: ArrayBuffer | null = null

/** 测试里直接交给已读出的 wasm，避免再去拉文件。 */
export function useWasmBinary(bytes: ArrayBuffer): void {
  binaryOverride = bytes
  engine = null
}

async function wasmBinary(): Promise<ArrayBuffer> {
  if (binaryOverride) return binaryOverride
  const response = await fetch(wasmAsset)
  if (!response.ok) throw new Error('向量库组件没有载入。')
  return response.arrayBuffer()
}

function sqlEngine(): Promise<SqlStatic> {
  engine ??= wasmBinary().then(binary => initSqlJs({ wasmBinary: binary }))
  return engine
}

function vectorBytes(vector: Float32Array): Uint8Array {
  return new Uint8Array(vector.buffer.slice(vector.byteOffset, vector.byteOffset + vector.byteLength))
}

function vectorFrom(value: unknown): Float32Array | null {
  if (!(value instanceof Uint8Array) || value.byteLength === 0 || value.byteLength % 4 !== 0) return null
  const copy = value.slice()
  return new Float32Array(copy.buffer)
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : ''
}

function pairs(value: unknown): Array<[string, number]> | null {
  if (!Array.isArray(value)) return null
  const rows: Array<[string, number]> = []
  for (const item of value) {
    if (!Array.isArray(item) || typeof item[0] !== 'string' || typeof item[1] !== 'number') return null
    rows.push([item[0], item[1]])
  }
  return rows
}

function words(value: unknown): string[] | null {
  if (!Array.isArray(value) || value.some(item => typeof item !== 'string')) return null
  return value
}

function cell(row: unknown[], columns: string[], name: string): unknown {
  return row[columns.indexOf(name)]
}

/** 把算好的索引写成 SQLite 文件字节。 */
export async function encodeRagIndex(snapshot: RagIndexSnapshot): Promise<Uint8Array> {
  const SQL = await sqlEngine()
  const db = new SQL.Database()
  try {
    db.run(`CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE term_df (term TEXT PRIMARY KEY, df INTEGER NOT NULL);
      CREATE TABLE gram_df (gram TEXT PRIMARY KEY, df INTEGER NOT NULL);
      CREATE TABLE passage (
        id INTEGER PRIMARY KEY,
        file TEXT NOT NULL,
        heading TEXT NOT NULL,
        body TEXT NOT NULL,
        length INTEGER NOT NULL,
        tf TEXT NOT NULL,
        heading_terms TEXT NOT NULL,
        file_terms TEXT NOT NULL,
        vector BLOB NOT NULL
      )`)
    const meta = db.prepare('INSERT INTO meta (key, value) VALUES (?, ?)')
    meta.run(['version', String(snapshot.version)])
    meta.run(['fingerprint', snapshot.fingerprint])
    meta.run(['avg', String(snapshot.avg)])
    meta.free()
    const terms = db.prepare('INSERT INTO term_df (term, df) VALUES (?, ?)')
    for (const [term, df] of snapshot.df) terms.run([term, df])
    terms.free()
    const grams = db.prepare('INSERT INTO gram_df (gram, df) VALUES (?, ?)')
    for (const [gram, df] of snapshot.gramDf) grams.run([gram, df])
    grams.free()
    const passages = db.prepare(`INSERT INTO passage
      (file, heading, body, length, tf, heading_terms, file_terms, vector)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)`)
    for (const passage of snapshot.passages) {
      passages.run([
        passage.file,
        passage.heading,
        passage.body,
        passage.length,
        JSON.stringify(passage.tf),
        JSON.stringify(passage.headingTerms),
        JSON.stringify(passage.fileTerms),
        vectorBytes(passage.vector)
      ])
    }
    passages.free()
    return db.export()
  } finally {
    db.close()
  }
}

function metaValue(rows: Array<{ columns: string[]; values: unknown[][] }>, key: string): string {
  const table = rows[0]
  if (!table) return ''
  const keyIndex = table.columns.indexOf('key')
  const valueIndex = table.columns.indexOf('value')
  const found = table.values.find(row => row[keyIndex] === key)
  return found ? text(found[valueIndex]) : ''
}

function countRows(rows: Array<{ columns: string[]; values: unknown[][] }>): Array<[string, number]> {
  const table = rows[0]
  if (!table) return []
  const name = table.columns[0]
  const count = table.columns.indexOf('df')
  if (!name || count < 0) return []
  return table.values.flatMap(row => {
    const term = text(row[0])
    const df = row[count]
    return term && typeof df === 'number' ? [[term, df] as [string, number]] : []
  })
}

/** 从 SQLite 文件字节读回索引。文件坏了就返回空，调用方再重算。 */
export async function decodeRagIndex(bytes: Uint8Array): Promise<RagIndexSnapshot | null> {
  if (bytes.byteLength < 16) return null
  const SQL = await sqlEngine()
  const db = new SQL.Database(bytes)
  try {
    const meta = db.exec('SELECT key, value FROM meta')
    const version = Number(metaValue(meta, 'version'))
    const fingerprint = metaValue(meta, 'fingerprint')
    const avg = Number(metaValue(meta, 'avg'))
    if (!fingerprint || !Number.isFinite(version) || !Number.isFinite(avg)) return null
    const passages = db.exec('SELECT file, heading, body, length, tf, heading_terms, file_terms, vector FROM passage ORDER BY id')
    const table = passages[0]
    if (!table) return null
    const records: RagPassageRecord[] = []
    for (const row of table.values) {
      const vector = vectorFrom(cell(row, table.columns, 'vector'))
      const tf = pairs(JSON.parse(text(cell(row, table.columns, 'tf'))))
      const headingTerms = words(JSON.parse(text(cell(row, table.columns, 'heading_terms'))))
      const fileTerms = words(JSON.parse(text(cell(row, table.columns, 'file_terms'))))
      const length = cell(row, table.columns, 'length')
      if (!vector || !tf || !headingTerms || !fileTerms || typeof length !== 'number') return null
      records.push({
        file: text(cell(row, table.columns, 'file')),
        heading: text(cell(row, table.columns, 'heading')),
        body: text(cell(row, table.columns, 'body')),
        length,
        tf,
        headingTerms,
        fileTerms,
        vector
      })
    }
    if (records.length === 0) return null
    return {
      version,
      fingerprint,
      avg,
      df: countRows(db.exec('SELECT term, df FROM term_df')),
      gramDf: countRows(db.exec('SELECT gram, df FROM gram_df')),
      passages: records
    }
  } catch {
    return null
  } finally {
    db.close()
  }
}

