/** 给页面一行回执，确认哪些下拉已经换成原网站返回的数量。 */
export function describePickerReceipt(dictionaries: Record<string, NormalizedDictionary>, warnings: string[] = []): string {
  const got = Object.entries(PICKER_RECEIPT).flatMap(([key, label]) => {
    const count = dictionaries[key]?.options.length ?? 0
    return count > 0 ? [`${label} ${count}`] : []
  })
  const head = got.length ? `已用原网站下拉：${got.join('、')}` : '原网站下拉没有可用选项，请查看各字段状态'
  return warnings.length ? `${head}。${warnings[0]}` : head
}

export function choicesFromDictionary(dictionary: NormalizedDictionary | undefined, caseTypeId = '', countryIds = ''): TreeOptionChoice[] {
  if (!dictionary) return []
  let options: DictionaryOption[] = dictionary.options.filter(item => !item.disabled)
  // 源站只渲染当前案件类型。把专利、商标、版权的同名状态叠在一起，就会出现两个「未递交」。
  if (dictionary.key === 'limitCaseStatus') {
    if (!caseTypeId) return []
    return caseStatusChoices(options.filter(item => item.metadata?.caseTypeId === caseTypeId))
  } else if (caseTypeId && options.some(item => item.metadata?.caseTypeId)) {
    const matched = options.filter(item => item.metadata?.caseTypeId === caseTypeId)
    if (matched.length) options = matched
  }
  if (options.some(item => item.metadata?.countryId)) {
    const selected = new Set(countryIds.split(',').map(item => item.trim()).filter(Boolean))
    options = options.filter(item => {
      const country = item.metadata?.countryId ?? ''
      return !country || country === 'ALL' || selected.has(country)
    })
  }
  return options.map(item => ({
    value: item.value,
    label: item.label,
    ...(item.parentValue ? { parent: item.parentValue } : {})
  }))
}

import { isLiveWriteCall } from '../automation/live-readonly-policy'

const readmeFiles = import.meta.glob('../../../API/README.md', {
  query: '?raw',
  import: 'default',
  eager: true
}) as Record<string, string>

let catalogCalls: Set<string> | null = null

/** 索引表里出现过的 Call。没写进文档的名字不能带着登录态发出。 */
export function documentedCallNames(): ReadonlySet<string> {
  if (catalogCalls) return catalogCalls
  const names = new Set<string>()
  for (const text of Object.values(readmeFiles)) {
    for (const match of text.matchAll(/`([A-Za-z][A-Za-z0-9_]{1,80})`/g)) names.add(match[1])
  }
  catalogCalls = names
  return names
}
import { caseInfoParams } from '../case-contact/query'
import { caseBusFlowParams } from '../customer/pct-flow-status'
import { caseDemandParams } from '../mail/easy/case-demand'

const HANDLER = /^[A-Za-z][A-Za-z0-9]{0,40}\.ashx$/
const CALL = /^[A-Za-z][A-Za-z0-9_]{1,80}$/
const FIELD = /^[A-Za-z_][A-Za-z0-9_]{0,40}$/
const WRITE = /save|delete|submit|update|insert|remove|create|destroy|drop|mailcustomer|flowsubmit|endemail/i

export function documentedCallAllowed(handler: string, call: string): { ok: true } | { ok: false; reason: string } {
  if (!HANDLER.test(handler)) return { ok: false, reason: '入口名无效，没有发出。' }
  if (!CALL.test(call)) return { ok: false, reason: 'Call 名无效，没有发出。' }
  if (!documentedCallNames().has(call)) return { ok: false, reason: '文档索引里没有这个 Call，没有发出。' }
  if (isLiveWriteCall(call) || WRITE.test(call)) return { ok: false, reason: '这个 Call 会改数据，没有发出。创建和提交仍用现成工具。' }
  return { ok: true }
}

export function documentedFields(value: unknown): Record<string, string> | null {
  if (value === undefined) return {}
  let record: unknown = value
  if (typeof record === 'string') {
    try { record = JSON.parse(record) as unknown } catch { return null }
  }
  if (typeof record !== 'object' || record === null || Array.isArray(record)) return null
  const entries = Object.entries(record)
  if (entries.length > 12) return null
  const fields: Record<string, string> = {}
  for (const [key, item] of entries) {
    if (key === 'Call' || !FIELD.test(key) || /cookie|authorization|password|token/i.test(key)) return null
    if (typeof item !== 'string' && typeof item !== 'number' && typeof item !== 'boolean') return null
    const text = String(item)
    if (text.length > 200) return null
    fields[key] = text
  }
  return fields
}

export function documentedParams(call: string, fields: Record<string, string>): URLSearchParams {
  const params = new URLSearchParams()
  params.set('Call', call)
  for (const [key, value] of Object.entries(fields)) params.set(key, value)
  if (!params.get('log_pagename')) params.set('log_pagename', 'CaseManage.aspx')
  return params
}

export interface EasyStep {
  handler: string
  call: string
  fields: Record<string, string>
}

const STEP_REF = /^@\{(\d+)\.([A-Za-z0-9_.]+)\}$/

const RECIPE_NAMES = ['biology', 'case-info', 'case-flow', 'case-demand'] as const

function paramsToFields(params: URLSearchParams): Record<string, string> {
  const fields: Record<string, string> = {}
  params.forEach((value, key) => {
    if (key !== 'Call' && value.length <= 200) fields[key] = value
  })
  return fields
}

/** 固定组合只收案件编号，字段用页面上已经写好的那一套。 */
export function explainEasyArgs(args: Record<string, unknown>): string | null {
  const recipe = typeof args.recipe === 'string' ? args.recipe.trim() : ''
  if (!recipe) return null
  if (!RECIPE_NAMES.includes(recipe as typeof RECIPE_NAMES[number])) {
    return `没有这个固定组合：${recipe}。可以用 ${RECIPE_NAMES.join('、')}。`
  }
  const caseId = typeof args.case_id === 'string' ? args.case_id.trim() : ''
  if (!caseId) return '这个固定组合要填查到的案件编号。'
  if (recipe === 'case-demand' && !caseDemandParams(caseId, 1)) return '案件编号格式不对，没有发出。'
  return null
}

function recipeStep(recipe: string, caseId: string): EasyStep | null {
  if (recipe === 'biology') {
    return {
      handler: 'CFInvoice.ashx',
      call: 'GetBiologyList',
      fields: { case_id: caseId, pageSize: '10', pageIndex: '1', _PK: 'biomaterial_id', searchKey: '', colsel: '' }
    }
  }
  if (recipe === 'case-info') return { handler: 'AgencyAction.ashx', call: 'GetCaseInfo', fields: paramsToFields(caseInfoParams(caseId)) }
  if (recipe === 'case-flow') return { handler: 'CaseInfo.ashx', call: 'GetCaseBusFlow', fields: paramsToFields(caseBusFlowParams(caseId)) }
  if (recipe === 'case-demand') {
    const params = caseDemandParams(caseId, 1)
    if (!params) return null
    return { handler: 'PatentAction.ashx', call: 'GetDemandBuCaseid', fields: paramsToFields(params) }
  }
  return null
}

/** 单步用 handler 和 call。多步用 steps。固定组合用 recipe 加 case_id。后面的字段可以用 @{1.路径} 取前面响应里的值。 */
export function readEasySteps(args: Record<string, unknown>): EasyStep[] | null {
  const recipe = typeof args.recipe === 'string' ? args.recipe.trim() : ''
  if (recipe) {
    const caseId = typeof args.case_id === 'string' ? args.case_id.trim() : ''
    const step = recipeStep(recipe, caseId)
    return step ? [step] : null
  }
  if (Array.isArray(args.steps)) {
    if (args.steps.length === 0 || args.steps.length > 4) return null
    const steps: EasyStep[] = []
    for (const item of args.steps) {
      if (typeof item !== 'object' || item === null || Array.isArray(item)) return null
      const row = item as Record<string, unknown>
      const handler = typeof row.handler === 'string' ? row.handler.trim() : ''
      const call = typeof row.call === 'string' ? row.call.trim() : ''
      const fields = documentedFields(row.fields)
      if (!handler || !call || !fields) return null
      steps.push({ handler, call, fields })
    }
    return steps
  }
  const handler = typeof args.handler === 'string' ? args.handler.trim() : ''
  const call = typeof args.call === 'string' ? args.call.trim() : ''
  if (!handler || !call) return null
  const fields = documentedFields(args.fields)
  if (!fields) return null
  return [{ handler, call, fields }]
}

function pickPath(data: unknown, path: string): unknown {
  let current = data
  for (const part of path.split('.')) {
    if (typeof current !== 'object' || current === null) return undefined
    if (Array.isArray(current)) {
      const index = Number(part)
      if (!Number.isInteger(index) || part !== String(index)) return undefined
      current = current[index]
      continue
    }
    if (!Object.prototype.hasOwnProperty.call(current, part)) return undefined
    current = (current as Record<string, unknown>)[part]
  }
  return current
}

/** 把 @{步骤.路径} 换成前面某一步响应里的字符串。对不上就停，不发这一步。 */
export function applyEasyRefs(fields: Record<string, string>, earlier: readonly unknown[]): { ok: true; fields: Record<string, string> } | { ok: false; reason: string } {
  const next: Record<string, string> = {}
  for (const [key, value] of Object.entries(fields)) {
    const ref = STEP_REF.exec(value.trim())
    if (!ref) {
      next[key] = value
      continue
    }
    const index = Number(ref[1]) - 1
    if (index < 0 || index >= earlier.length) return { ok: false, reason: `${key} 引用了还没有的第 ${ref[1]} 步，这一步没有发出。` }
    const found = pickPath(earlier[index], ref[2] ?? '')
    if (typeof found !== 'string' && typeof found !== 'number' && typeof found !== 'boolean') {
      return { ok: false, reason: `${key} 没有从第 ${ref[1]} 步对上 ${ref[2]}，这一步没有发出。` }
    }
    next[key] = String(found)
  }
  return { ok: true, fields: next }
}

export function payloadFromSummary(text: string): unknown | null {
  const marker = '已用当前登录会话调用，没有改数据。\n'
  if (!text.startsWith(marker)) return null
  const body = text.slice(marker.length)
  if (!body || body.endsWith('…')) return null
  try { return JSON.parse(body) as unknown } catch { return null }
}

/** 把实时响应收成助手能读的一段。不包含登录凭据。 */
export function summarizeEasyPayload(data: unknown): string {
  let json = ''
  try { json = JSON.stringify(data) ?? '' } catch { json = '' }
  const body = json.length > 1800 ? `${json.slice(0, 1800)}…` : json
  return `已用当前登录会话调用，没有改数据。\n${body || '接口返回了空内容。'}`
}

type Kind = 'naming' | 'download'
interface Waiter { kind: Kind; signal: AbortSignal; abort: () => void; resolve: (release: () => void) => void }

/** 六个可归还的在途额度；优先级在派发时读取，正文读完或取消才归还。 */
export class DownloadTokens {
  private active = 0
  private waiters: Waiter[] = []
  constructor(private readonly preferred: () => Kind) {}

  acquire(kind: Kind, signal: AbortSignal): Promise<() => void> {
    if (signal.aborted) return Promise.reject(signal.reason)
    return new Promise((resolve, reject) => {
      const waiter: Waiter = { kind, signal, resolve, abort: () => {
        this.waiters = this.waiters.filter(item => item !== waiter)
        reject(signal.reason)
        this.drain()
      } }
      this.waiters.push(waiter)
      signal.addEventListener('abort', waiter.abort, { once: true })
      this.drain()
    })
  }

  private drain(): void {
    while (this.active < 6 && this.waiters.length) {
      const preferred = this.waiters.findIndex(item => item.kind === this.preferred())
      const [waiter] = this.waiters.splice(preferred < 0 ? 0 : preferred, 1)
      waiter.signal.removeEventListener('abort', waiter.abort)
      this.active++
      let released = false
      waiter.resolve(() => {
        if (released) return
        released = true
        this.active--
        this.drain()
      })
    }
  }
}

import { businessMessage, isRecord, readClientInfo } from './response-guards'
import { apiError, type ApiResult } from './types'

/** 一次打包的文件数护栏（不是产品上限，下载数量不设限）：file_no 和 file_name 一一对应。 */
export const DOWNLOAD_MAX_ITEMS = 10_000

/** 待下载文件：GetFileName 认 file_id，DownLoad 认 file_no，原名在没有下载名称时兜底。 */
export interface DownloadFileItem {
  fileId: string
  fileNo: string
  fileName: string
}

export interface DownloadHandle {
  fileGuid: string
  fileSize: number | null
  /** 原站报的打包失败提示（例如「您共1个文件下载失败」）。没有失败就不带。 */
  notice: string
}

export interface DownloadedArchive {
  /** 取包地址（FileHandler.ashx?guid=），交给浏览器下载，压缩包条目名已经改好。 */
  downloadUrl: string
  fileName: string
  fileCount: number
  notice: string
}

/** 照抄原站文件查询的 DownLoad 请求：zip_name 留空，包名由插件自己起。 */
export function buildDownloadParams(fileNos: string[], names: string[]): URLSearchParams | null {
  if (!fileNos.length || fileNos.length !== names.length || fileNos.length > DOWNLOAD_MAX_ITEMS) return null
  if (fileNos.some(no => !no || no.length > 40 || no.includes(';'))) return null
  if (names.some(name => !name || name.length > 180 || name.includes(';'))) return null
  const params = new URLSearchParams()
  params.set('Call', 'DownLoad')
  params.set('file_no', fileNos.join(';'))
  params.set('file_name', names.join(';'))
  params.set('zip_name', '')
  params.set('zip_pwd', '')
  params.set('down_type', '')
  params.set('model', 'FILE')
  params.set('childpath', '')
  params.set('log_pagename', 'FileSearch.aspx')
  return params
}

/** 原站成功时 ClientInfo.Result 也可能还是 false，认 file_guid；error_message 只在真有文件失败时带出。 */
export function readDownloadHandle(data: unknown): ApiResult<DownloadHandle> {
  if (!isRecord(data)) return apiError('INVALID_RESPONSE', '下载打包响应不是对象。')
  const client = readClientInfo(data.ClientInfo)
  if (!client.ok) return client
  if (client.data.IsLogin === false) return apiError('SESSION_EXPIRED', 'EASY 登录状态已失效。')
  const fileGuid = typeof data.file_guid === 'string' ? data.file_guid.trim() : ''
  if (!fileGuid) {
    return apiError('BUSINESS_ERROR', client.data.Status === false || client.data.Result === false
      ? businessMessage(client.data)
      : '下载打包没有返回文件编号，没有下载。')
  }
  const size = data.file_size
  const fileSize = typeof size === 'number' && Number.isFinite(size) && size >= 0 ? size
    : typeof size === 'string' && /^\d+$/.test(size) ? Number(size)
    : null
  return { ok: true, data: { fileGuid, fileSize, notice: failureNotice(data) } }
}

function failureNotice(data: Record<string, unknown>): string {
  const message = typeof data.error_message === 'string' ? data.error_message.trim() : ''
  if (!message) return ''
  const failed = /共(\d+)个文件下载失败/.exec(message)
  if (failed) return Number(failed[1]) > 0 ? message.slice(0, 200) : ''
  return message.slice(0, 200)
}

function pad(value: number): string {
  return String(value).padStart(2, '0')
}

/** 原站的包名是时间戳（1793001423.zip）。插件另存时用看得懂的名字。 */
export function downloadArchiveName(now: Date = new Date()): string {
  const stamp = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`
  return `下载文件-${stamp}.zip`
}

/** 包名来自查询时的搜索模板；不把路径、设备名或重复.zip后缀带给浏览器。 */
export function templateArchiveName(templateName = ''): string {
  let name = templateName.trim().replace(/\.zip$/i, '').replace(/[<>:"/\\|?*\x00-\x1f]/g, '_').replace(/^[. ]+|[. ]+$/g, '')
  name = Array.from(name).slice(0, 100).join('')
  while (name.length > 115) name = Array.from(name).slice(0, -1).join('')
  if (!name) name = '下载文件'
  if (/^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)/i.test(name)) name = `_${name}`
  return `${name}.zip`
}

import { isQueryGuid } from '../query/query-validator'
import { isRecord } from '../shared/guards'
import { fileSearchTimeoutMs, fileSearchValueLimit, isFileSearchBusinessField, type FileSearchQuery } from './file-search-params'
import type { DictionarySnapshot } from './dictionaries'
import type { HistoryQueryDetail, HistoryQueryOption } from './query-history'
import type { FileSearchResult, PatentFile } from './file-search-types'
import { isLimitMonitorInputField, isLimitMonitorType, type LimitMonitorQuery } from './limit-monitor-params'
import type { LimitMonitorResult, LimitMonitorRow } from './limit-monitor-types'
import { filingSearchValueLimit, isFilingSearchInputField, type FilingSearchQuery } from './filing-search-params'
import type { FilingSearchResult, FilingSearchRow } from './filing-search-types'
import type { FilingFlowRow, FilingUser } from './filing-export'
import { isProcessKind, isProcessOpenTarget, PROCESS_SPECS, type ProcessListQuery, type ProcessListResult, type ProcessListRow } from './mail-process'
import type { SessionSummary } from './session'
import type { CaseContactExport } from '../case-contact/query'
import type { ApiError, ApiResult } from './types'

const QUERY_KEYS = new Set([
  'caseVolume', 'applicationNo', 'customerName', 'fileName', 'fileDescriptionId',
  'resolvedFields', 'pageIndex', 'pageSize'
])
const ERROR_CODES = new Set([
  'INVALID_ORIGIN', 'INVALID_QUERY', 'NETWORK_ERROR', 'REQUEST_TIMEOUT',
  'HTTP_ERROR', 'SESSION_EXPIRED', 'AUTH_UNKNOWN', 'BUSINESS_ERROR',
  'INVALID_RESPONSE', 'UNEXPECTED_HTML', 'REQUEST_ABORTED'
])

function optionalString(value: unknown): boolean {
  return value === undefined || typeof value === 'string'
}

function isResolvedFields(value: unknown): value is Record<string, string> {
  if (!isRecord(value) || Object.keys(value).length > 120) return false
  return Object.keys(value).every(key => isFileSearchBusinessField(key) &&
    typeof value[key] === 'string' && value[key].length <= fileSearchValueLimit(key))
}

export function isFileSearchQuery(value: unknown): value is FileSearchQuery {
  if (!isRecord(value) || Object.keys(value).some(key => !QUERY_KEYS.has(key))) return false
  if (value.resolvedFields !== undefined && !isResolvedFields(value.resolvedFields)) return false
  return Number.isSafeInteger(value.pageIndex) && Number(value.pageIndex) >= 1 &&
    Number.isSafeInteger(value.pageSize) && Number(value.pageSize) >= 1 &&
    Number(value.pageSize) <= 100 &&
    ['caseVolume', 'applicationNo', 'customerName', 'fileName', 'fileDescriptionId']
      .every(key => optionalString(value[key]))
}

function pageNumber(value: unknown, fallback: number, max: number): number {
  const parsed = typeof value === 'number' ? value : typeof value === 'string' && /^\d+$/.test(value) ? Number(value) : fallback
  if (!Number.isSafeInteger(parsed) || parsed < 1 || parsed > max) return fallback
  return parsed
}

/** 丢掉未登记字段、超长值和非法页码，避免一条坏字段让整次查询被后台拒绝。 */
export function coerceFileSearchQuery(value: unknown): FileSearchQuery | null {
  if (!isRecord(value)) return null
  const resolved: Record<string, string> = {}
  const source = isRecord(value.resolvedFields) ? value.resolvedFields : {}
  const entries = Object.entries(source).filter((entry): entry is [string, string] =>
    isFileSearchBusinessField(entry[0]) && typeof entry[1] === 'string' && entry[1].length <= fileSearchValueLimit(entry[0]))
  const ranked = [...entries.filter(([, text]) => text.trim()), ...entries.filter(([, text]) => !text.trim())]
  for (const [key, text] of ranked) {
    if (Object.keys(resolved).length >= 120) break
    resolved[key] = text
  }
  const query: FileSearchQuery = {
    resolvedFields: resolved,
    pageIndex: pageNumber(value.pageIndex, 1, 1_000_000),
    pageSize: pageNumber(value.pageSize, 20, 100)
  }
  for (const key of ['caseVolume', 'applicationNo', 'customerName', 'fileName', 'fileDescriptionId'] as const) {
    const raw = value[key]
    if (typeof raw === 'string' && raw.length <= fileSearchValueLimit(key)) query[key] = raw
  }
  return query
}

const CONTINUATION_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

/** 转发到后台之前先收成校验能通过的查询。校验本身仍然拒绝脏消息。 */
export function prepareForwardedSearch(message: unknown): void {
  if (!isRecord(message) || message.type !== 'WORKSPACE' || !isRecord(message.payload)) return
  if (message.payload.action !== 'forward' || !isRecord(message.payload.message)) return
  const inner = message.payload.message
  if (inner.type !== 'SEARCH_FILES' || !isRecord(inner.payload)) return
  const query = coerceFileSearchQuery(inner.payload.query)
  if (!query) return
  const continuation = inner.payload.continuation
  const keep = isRecord(continuation) && Object.keys(continuation).length === 1 &&
    typeof continuation.querySessionId === 'string' && CONTINUATION_ID.test(continuation.querySessionId)
  const chosen = fileSearchTimeoutMs(inner.payload.timeoutMs)
  const timeoutMs = inner.payload.timeoutMs !== undefined && chosen === Number(inner.payload.timeoutMs) ? chosen : undefined
  // batch 是批量拉页的标记，得跟着查询一起过去：收消息时把它一并留好，别在这层收丢。
  const batch = inner.payload.batch === true ? { batch: true as const } : {}
  inner.payload = keep
    ? { query, continuation, ...batch, ...(timeoutMs === undefined ? {} : { timeoutMs }) }
    : { query, ...batch, ...(timeoutMs === undefined ? {} : { timeoutMs }) }
}

function isApiError(value: unknown): value is ApiError {
  return isRecord(value) && typeof value.code === 'string' && ERROR_CODES.has(value.code) &&
    typeof value.message === 'string' &&
    (value.status === undefined || Number.isSafeInteger(value.status)) &&
    (value.responseKeys === undefined ||
      (Array.isArray(value.responseKeys) && value.responseKeys.every(key => typeof key === 'string')))
}

function isApiResult<T>(value: unknown, isData: (data: unknown) => data is T): value is ApiResult<T> {
  if (!isRecord(value)) return false
  if (value.ok === false) return isApiError(value.error)
  return value.ok === true && isData(value.data)
}

function isSessionSummary(value: unknown): value is SessionSummary {
  return isRecord(value) &&
    ['unknown', 'checking', 'authenticated', 'unauthenticated', 'expired', 'error'].includes(String(value.status)) &&
    typeof value.checkedAt === 'string' && optionalString(value.displayName) &&
    optionalString(value.userId) && optionalString(value.message)
}

const OPTIONAL_FILE_KEYS = [
  'fileNo', 'fileDescription', 'fileStatus', 'fileType', 'caseId', 'caseName',
  'caseVolume', 'customerVolume', 'applicationNo', 'applicationType', 'customerName',
  'ctrlProc', 'uploadTime', 'officialPostDate'
] as const

function isPatentFile(value: unknown): value is PatentFile {
  return isRecord(value) && typeof value.fileId === 'string' &&
    typeof value.fileName === 'string' && OPTIONAL_FILE_KEYS.every(key => optionalString(value[key]))
}

function isFileSearchResult(value: unknown): value is FileSearchResult {
  return isRecord(value) && Array.isArray(value.items) && value.items.every(isPatentFile) &&
    Number.isSafeInteger(value.total) && Number(value.total) >= 0 &&
    Number.isSafeInteger(value.pageIndex) && Number(value.pageIndex) >= 1 &&
    Number.isSafeInteger(value.pageSize) && Number(value.pageSize) >= 1 &&
    Number.isSafeInteger(value.totalPages) && Number(value.totalPages) >= 0
}

export function isSessionResult(value: unknown): value is ApiResult<SessionSummary> {
  return isApiResult(value, isSessionSummary)
