import { businessMessage, isRecord, readClientInfo, safeResponseKeys } from '../response-guards'
import { apiError, type ApiResult } from '../types'
import { isHistoryOption } from './guards'
import type { HistoryQueryOption } from './types'

function authFailure(data: Record<string, unknown>): ApiResult<never> | null {
  const client = readClientInfo(data.ClientInfo)
  if (!client.ok) return client
  if (client.data.IsLogin === false) return apiError('SESSION_EXPIRED', 'EASY 登录状态已失效，请在原网站重新登录。')
  if (client.data.Status === false) return apiError('BUSINESS_ERROR', businessMessage(client.data))
  return null
}

export function normalizeHistoryOptions(data: unknown): ApiResult<HistoryQueryOption[]> {
  if (!isRecord(data)) return apiError('INVALID_RESPONSE', '历史模板响应不是对象。', undefined)
  const auth = authFailure(data)
  if (auth) return auth
  if (data.Options === null) return { ok: true, data: [] }
  if (data.Options === undefined) {
    return { ok: false, error: {
      code: 'INVALID_RESPONSE', message: '历史模板响应缺少 Options。', responseKeys: safeResponseKeys(data)
    } }
  }
  if (!Array.isArray(data.Options)) {
    return apiError('INVALID_RESPONSE', '历史模板 Options 结构无效。')
  }
  const options: HistoryQueryOption[] = []
  for (const item of data.Options) {
    if (!isHistoryOption(item)) return apiError('INVALID_RESPONSE', '历史模板选项缺少 query_id 或 title。')
    options.push({ id: item.query_id, name: item.title.trim(), source: 'easy' })
  }
  return { ok: true, data: options }
}

/**
 * 这套原网站写入和删除成功时，ClientInfo.Result 经常仍是 false、Message 为空。
 * 真正的成败在顶层 Ret。没有 Ret 时，只有带文字的 Message 或 Status=false 才算没写上。
 * 响应里没有新模板 ID，调用方保存后要重新读列表。
 */
export function normalizeHistorySave(data: unknown): ApiResult<{ saved: true }> {
  if (!isRecord(data)) return apiError('INVALID_RESPONSE', '保存查询模板的响应不是对象。')
  const client = readClientInfo(data.ClientInfo)
  if (!client.ok) return client
  if (client.data.IsLogin === false) return apiError('SESSION_EXPIRED', 'EASY 登录状态已失效，请在原网站重新登录。')
  if (data.Ret === false || client.data.Status === false) return apiError('BUSINESS_ERROR', businessMessage(client.data))
  if (data.Ret === true) return { ok: true, data: { saved: true } }
  if (client.data.Result === false && typeof client.data.Message === 'string' && client.data.Message.trim()) {
    return apiError('BUSINESS_ERROR', businessMessage(client.data))
  }
  if (client.data.Result === true || client.data.Status === true) return { ok: true, data: { saved: true } }
  return apiError('INVALID_RESPONSE', '保存查询模板的响应没有成功标记。', undefined)
}

export function normalizeHistoryDetail(data: unknown, queryId: string): ApiResult<{ id: string; queryXml: string; name?: string }> {
  if (!isRecord(data)) return apiError('INVALID_RESPONSE', '历史模板详情不是对象。')
  const auth = authFailure(data)
  if (auth) return auth
  let name: string | undefined
  if (data.Options !== undefined && data.Options !== null) {
    const listed = normalizeHistoryOptions(data)
    if (!listed.ok) return listed
    name = listed.data.find(item => item.id === queryId)?.name
  }
  if (!Array.isArray(data.QueryXml) || data.QueryXml.length === 0) {
    return apiError('INVALID_QUERY', '未找到该历史模板。')
  }
  const row = data.QueryXml[0]
  if (!isRecord(row) || typeof row.query_xml !== 'string' || !row.query_xml.trim()) {
    return apiError('INVALID_QUERY', '未找到该历史模板。')
  }
  return { ok: true, data: { id: queryId, ...(name ? { name } : {}), queryXml: row.query_xml } }
}

import { apiError, type ApiResult } from './types'

export function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
}

export interface EasyClientInfo {
  IsLogin?: boolean
  Status?: boolean
  Result?: boolean
  Message?: string | null
  Url?: string | null
}

/** 只验证已经记录的公共字段；缺失与 true 是不同状态。 */
export function readClientInfo(value: unknown): ApiResult<EasyClientInfo> {
  if (!isRecord(value)) return apiError('INVALID_RESPONSE', 'EASY 响应缺少 ClientInfo。')
  for (const key of ['IsLogin', 'Status', 'Result'] as const) {
    if (value[key] !== undefined && typeof value[key] !== 'boolean') {
      return apiError('INVALID_RESPONSE', `ClientInfo.${key} 类型无效。`)
    }
  }
  for (const key of ['Message', 'Url'] as const) {
    if (value[key] !== undefined && value[key] !== null && typeof value[key] !== 'string') {
      return apiError('INVALID_RESPONSE', `ClientInfo.${key} 类型无效。`)
    }
  }
  return { ok: true, data: value as EasyClientInfo }
}

export function safeResponseKeys(value: Record<string, unknown>): string[] {
  return Object.keys(value).slice(0, 20).map(key => {
    if (/token|password|secret|cookie|credential|authorization/i.test(key)) return '[REDACTED]'
    return key.replace(/[^A-Za-z0-9_]/g, '_').slice(0, 40)
  })
}

export function businessMessage(info: EasyClientInfo): string {
  return typeof info.Message === 'string' && info.Message.trim()
    ? info.Message.trim().slice(0, 200) : 'EASY 返回业务失败。'
}

export interface CachedFileInfo {
  receivedBytes: number
  complete: boolean
  totalBytes?: number | null
  etag?: string
  lastModified?: string
}
export interface DownloadCache {
  names: Record<string, string[]>
  saveNames(offset: number, names: string[]): Promise<void>
  info(index: number): Promise<CachedFileInfo>
  reset(index: number, metadata: Partial<CachedFileInfo>): Promise<void>
  write(index: number, offset: number, bytes: Uint8Array): Promise<void>
  complete(index: number, metadata: Partial<CachedFileInfo>): Promise<void>
  read(index: number, offset: number): Promise<Uint8Array>
}

/** 全部回放都保持未知长度ReadableStream模式，确保ZIP本地头与首轮一致。 */
export async function cachedFileResponse(
  url: string, index: number, cache: DownloadCache, signal: AbortSignal,
  fetcher: (url: string, init?: RequestInit) => Promise<Response>
): Promise<Response> {
  let info = await cache.info(index)
  if (!info.complete && info.totalBytes != null && info.receivedBytes === info.totalBytes) {
    await cache.complete(index, info)
    info = { ...info, complete: true }
  }
  let prefix = info.complete ? info.receivedBytes : 0
  let source: Response | undefined
  if (!info.complete) {
    const validator = info.etag && !info.etag.startsWith('W/') ? info.etag : info.lastModified
    const headers = new Headers()
    if (info.receivedBytes && validator) {
      prefix = info.receivedBytes
      headers.set('Range', `bytes=${prefix}-`); headers.set('If-Range', validator)
    }
    source = await fetcher(url, { credentials: 'include', signal, headers })
    const range = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(source.headers.get('content-range') ?? '')
    const etag = source.headers.get('etag') ?? ''
    const modified = source.headers.get('last-modified') ?? ''
    const accepted = prefix > 0 && source.status === 206 && range && Number(range[1]) === prefix &&
      Number(range[2]) >= prefix && Number(range[2]) + 1 === Number(range[3]) &&
      (!info.etag || etag === info.etag) && (!info.lastModified || modified === info.lastModified)
    if (prefix && !accepted && source.status !== 200) {
      await source.body?.cancel()
      source = await fetcher(url, { credentials: 'include', signal })
    }
    if (!source.ok || !source.body) return source
    if (!accepted) {
      prefix = 0
      const size = source.headers.get('content-length')
      info = { receivedBytes: 0, complete: false, etag: source.headers.get('content-encoding') ? '' : source.headers.get('etag') ?? '', lastModified: source.headers.get('content-encoding') ? '' : source.headers.get('last-modified') ?? '',
        totalBytes: !source.headers.get('content-encoding') && size !== null ? Number(size) : null }
      await cache.reset(index, info)
    } else info = { ...info, totalBytes: Number(range![3]) }
  }
  const reader = source?.body?.getReader()
  let replayed = 0, received = prefix
  let pending = new Uint8Array(), pendingOffset = 0, sourceEnded = false
  const body = new ReadableStream<Uint8Array>({
    async pull(target) {
      try {
        signal.throwIfAborted()
        if (replayed < prefix) {
          const chunk = await cache.read(index, replayed)
          if (!chunk.length || replayed + chunk.length > prefix) throw new Error('本机附件缓存不完整，不能续传。')
          replayed += chunk.length; target.enqueue(chunk); return
        }
        if (!reader) { target.close(); return }
        if (sourceEnded) {
          if (info.totalBytes != null && received !== info.totalBytes) throw new Error('文件传输不完整，没有完成压缩包。')
          await cache.complete(index, { ...info, totalBytes: received })
          reader.releaseLock(); target.close(); return
        }
        const block = new Uint8Array(256 * 1024)
        let filled = 0
        while (filled < block.length) {
          signal.throwIfAborted()
          if (pendingOffset === pending.length) {
            const chunk = await reader.read()
            if (chunk.done) { sourceEnded = true; break }
            pending = chunk.value; pendingOffset = 0
          }
          const count = Math.min(block.length - filled, pending.length - pendingOffset)
          block.set(pending.subarray(pendingOffset, pendingOffset + count), filled)
          filled += count; pendingOffset += count
        }
        if (!filled) {
          if (info.totalBytes != null && received !== info.totalBytes) throw new Error('文件传输不完整，没有完成压缩包。')
          await cache.complete(index, { ...info, totalBytes: received })
          reader.releaseLock(); target.close(); return
        }
        const part = filled === block.length ? block : block.slice(0, filled)
        await cache.write(index, received, part)
        received += part.length
        target.enqueue(part)
      } catch (error) { target.error(error); await reader?.cancel(error).catch(() => {}) }
    },
    async cancel(reason) { await reader?.cancel(reason).catch(() => {}) }
  }, { highWaterMark: 0 })
  const responseHeaders = new Headers()
  if (info.totalBytes != null) responseHeaders.set('Content-Length', String(info.totalBytes))
  const contentType = source?.headers.get('content-type')
  if (contentType) responseHeaders.set('Content-Type', contentType)
  return new Response(body, { headers: responseHeaders })
}

import { ZipWriter } from '@zip.js/zip.js'
import type { EasyTransport } from './transport'
import { buildDownloadParams, readDownloadHandle, type DownloadFileItem } from './file-download'
import { resolveDownloadFileNames, stripApplicationNoDot, type FileDownloadSelection } from '../mail/download-name'
import type { FileDownloadProgress } from '../shared/download-progress'
import { DownloadTokens } from './download-tokens'
import { prefetchFile } from './stream-file'
import { cachedFileResponse, type DownloadCache } from './stream-cache'

export interface StreamDownloadOptions {
  sink: WritableStream<Uint8Array>
  signal?: AbortSignal
  fetchFile?: (url: string, init?: RequestInit) => Promise<Response>
  onProgress?: (progress: FileDownloadProgress) => void
  cache?: DownloadCache
  zipCreatedAt?: string
}

function safeEntryName(value: string, used: Set<string>): string {
  const clean = value.replace(/[\\/<>:"|?*\x00-\x1f]+/g, '_').replace(/^[. ]+|[. ]+$/g, '') || '文件'
  const dot = clean.lastIndexOf('.')
  const stem = dot > 0 ? clean.slice(0, dot) : clean
  const extension = dot > 0 ? clean.slice(dot) : ''
  let name = clean
  for (let index = 2; used.has(name.toLowerCase()); index++) name = stem + ' (' + index + ')' + extension
  used.add(name.toLowerCase())
  return name
}

/** 六个业务令牌；持久缓存与ZIP消费分别背压，ZIP仍按输入顺序写入。 */
export async function streamDownloadFiles(
  transport: EasyTransport, items: DownloadFileItem[], selection: FileDownloadSelection | null,
  stripAppNoDot: boolean, options: StreamDownloadOptions
): Promise<void> {
  const controller = new AbortController()
  const signal = controller.signal
  let failure: unknown
  const waiters = new Set<() => void>()
  const wake = () => { for (const resolve of waiters) resolve(); waiters.clear() }
  const wait = () => new Promise<void>(resolve => { waiters.add(resolve) })
  const fail = (error: unknown) => {
    failure ??= error
    controller.abort(error)
    wake()
  }
  const cancel = () => fail(options.signal?.reason ?? new Error('下载已取消。'))
  const untilAbort = <T>(operation: Promise<T>): Promise<T> => new Promise((resolve, reject) => {
    const aborted = () => { signal.removeEventListener('abort', aborted); reject(signal.reason) }
    if (signal.aborted) aborted()
    else signal.addEventListener('abort', aborted, { once: true })
    operation.then(value => { signal.removeEventListener('abort', aborted); resolve(value) }, error => {
      signal.removeEventListener('abort', aborted); reject(error)
    })
  })
  if (options.signal?.aborted) cancel()
  options.signal?.addEventListener('abort', cancel, { once: true })

  let nextOffset = 0, scheduled = 0, done = 0
  const budget = new DownloadTokens(() => nextOffset - scheduled < 6 ? 'naming' : 'download')
  const scoped = { post: async (...args: Parameters<EasyTransport['post']>) => {
    const release = await budget.acquire(args[0] === 'getFileName' ? 'naming' : 'download', signal)
    try { return await transport.post(...args) } finally { release() }
  } } as EasyTransport
  const queue: { offset: number; names: string[] }[] = []
  const accept = async (offset: number, names: string[]) => {
    while (!signal.aborted && (offset !== nextOffset || queue.length >= 2)) await wait()
    signal.throwIfAborted()
    queue.push({ offset, names }); nextOffset += names.length; wake()
  }
  const producer = (async () => {
    if (selection) {
      const named = await resolveDownloadFileNames(scoped, items.map(item => item.fileId), selection, {
        signal, concurrency: 6, resolvedBatches: options.cache?.names,
        onBatch: async (offset, names) => {
          await options.cache?.saveNames(offset, names)
          await accept(offset, names)
        },
        onFailure: result => { if (!result.ok) fail(new Error(result.error.message)) },
        onProgress: (count, total) => options.onProgress?.({ phase: 'naming', done: count, total })
      })
      if (!named.ok) throw new Error(named.error.message)
    } else {
      for (let offset = 0; offset < items.length; offset += 40) await accept(offset, items.slice(offset, offset + 40).map(item => item.fileName))
    }
  })().catch(fail)

  const used = new Set<string>()
  type Prepared = { content: () => Promise<Awaited<ReturnType<typeof prefetchFile>>>; name: string; networkFinished: Promise<void> }
  const jobs = new Map<number, Promise<Prepared | null>>()
  const pumps = new Set<Promise<void>>()
  const open = async (index: number, generated: string): Promise<Prepared> => {
    const item = items[index]
    const name = stripAppNoDot ? stripApplicationNoDot(generated) : generated
    const params = buildDownloadParams([item.fileNo], [name])
    if (!params) throw new Error('文件编号或生成名称无效，没有完成压缩包。')
    const cached = await options.cache?.info(index)
    if (cached && !cached.complete && cached.totalBytes != null && cached.receivedBytes === cached.totalBytes) {
      await options.cache!.complete(index, cached)
      cached.complete = true
    }
    if (cached?.complete && options.cache) {
      // 完整磁盘缓存无需占用网络窗口，也无需提前分配正文缓冲。
      return { name, networkFinished: Promise.resolve(), content: async () => {
        signal.throwIfAborted()
        const file = await prefetchFile('local-cache', item.fileName, cached.receivedBytes === 0, '', null, signal,
          () => cachedFileResponse('local-cache', index, options.cache!, signal, options.fetchFile ?? globalThis.fetch.bind(globalThis)), fail)
        pumps.add(file.finished); void file.finished.then(() => pumps.delete(file.finished))
        return file
      } }
    }
    let prepared = await scoped.post('fileDownload', params, signal)
    // This producer prepares one attachment at a time, never a server-side bulk ZIP.
    // A gateway failure can retry its handle without repeating any mail/write operation.
    for (let attempt = 1; !prepared.ok && [502, 503, 504].includes(prepared.error.status ?? 0) && attempt < 3; attempt++) {
      await untilAbort(new Promise<void>(resolve => setTimeout(resolve, attempt * 200)))
      signal.throwIfAborted()
      prepared = await scoped.post('fileDownload', params, signal)
    }
    if (!prepared.ok) throw new Error(prepared.error.message)
    const handle = readDownloadHandle(prepared.data)
    if (!handle.ok) throw new Error(handle.error.message)
    const url = transport.fileDownloadUrl(handle.data.fileGuid, handle.data.fileSize)
    if (!url) throw new Error('取文件句柄无效。')
    const fetcher = options.fetchFile ?? globalThis.fetch.bind(globalThis)
    const file = await prefetchFile(url, item.fileName, handle.data.fileSize === 0, handle.data.notice,
      budget, signal, options.cache ? target => cachedFileResponse(target, index, options.cache!, signal, fetcher) : fetcher, fail,
      options.cache ? offset => options.cache!.read(index, offset) : undefined)
    pumps.add(file.finished)
    void file.finished.then(() => pumps.delete(file.finished))
    return { content: async () => file, name, networkFinished: file.finished }
  }
  let preparing = 0
  // 持久模式仅保留每个附件的小描述符，正文留在磁盘；完成的附件不能
  // 继续占住网络窗口。内存模式仍限制六个256KiB正文缓冲。
  const lookahead = options.cache ? items.length : 6
  const dispatch = (async () => {
    while (scheduled < items.length) {
      while (!queue.length && !signal.aborted) await wait()
      signal.throwIfAborted()
      const batch = queue.shift()!
      wake()
      for (const [offset, generated] of batch.names.entries()) {
        while ((scheduled - done >= lookahead || preparing >= 6) && !signal.aborted) await wait()
        signal.throwIfAborted()
        const index = batch.offset + offset
        // 名称在派发顺序里分配，避免响应顺序改变重名后缀。
        const name = safeEntryName(stripAppNoDot ? stripApplicationNoDot(generated) : generated, used)
        preparing++
        jobs.set(index, open(index, generated).then(file => {
          void file.networkFinished.then(() => { preparing--; wake() })
          return { ...file, name }
        }).catch(error => { preparing--; fail(error); return null }))
        scheduled++; wake()
      }
    }
  })().catch(fail)

  const output = options.sink.getWriter()
  const archive = new ZipWriter(new WritableStream<Uint8Array>({ write: chunk => {
    signal.throwIfAborted()
    return output.write(chunk)
  } }), {
    level: 0, zip64: true, useWebWorkers: false, bufferedWrite: false,
    ...(options.zipCreatedAt ? { lastModDate: new Date(options.zipCreatedAt), extendedTimestamp: false, ntfs: false } : {})
  })
  try {
    while (done < items.length) {
      while (!jobs.has(done) && !signal.aborted) await wait()
      signal.throwIfAborted()
      const file = await jobs.get(done)!
      signal.throwIfAborted()
      if (!file) throw failure
      const content = await file.content()
      await untilAbort(archive.add(file.name, content.body, { signal }))
      await content.finished
      jobs.delete(done)
      done++; wake()
      options.onProgress?.({ phase: 'packing', done, total: items.length })
    }
    await producer; await dispatch
    signal.throwIfAborted()
    await untilAbort(archive.close())
    await untilAbort(output.close())
  } catch (error) {
    fail(error)
    // 底层写入若卡住，abort()也会等那笔写入；不能因此扣住整个任务。
    void output.abort(failure).catch(() => {})
    throw failure
  } finally {
    if (failure) controller.abort(failure)
    await Promise.all([producer, dispatch, ...jobs.values()])
    await Promise.all(pumps)
    output.releaseLock()
    options.signal?.removeEventListener('abort', cancel)
  }
}

import type { DownloadTokens } from './download-tokens'

export const FILE_BUFFER_BYTES = 256 * 1024
const BLOCK_BYTES = 64 * 1024

/** 应用队列按字节背压；网络读取与按序ZIP消费独立进行。 */
export async function prefetchFile(
  url: string, filename: string, emptyAllowed: boolean, notice: string,
  budget: DownloadTokens | null, signal: AbortSignal, fetchFile: (url: string, init?: RequestInit) => Promise<Response>,
  fail: (error: unknown) => void,
  replay?: (offset: number) => Promise<Uint8Array>
): Promise<{ body: ReadableStream<Uint8Array>; finished: Promise<void>; readonly bufferedBytes: number }> {
  const release = budget ? await budget.acquire('download', signal) : () => {}
  let reader: ReadableStreamDefaultReader<Uint8Array>
  let length: string | null, encoded: string | null
  try {
    const response = await fetchFile(url, { credentials: 'include', signal })
    if (!response.ok || !response.body) throw new Error('读取文件失败，没有完成压缩包。')
    if (!/\.x?html?$/i.test(filename) && /text\/html/i.test(response.headers.get('content-type') ?? '')) {
      await response.body.cancel()
      throw new Error('取文件返回了网页，没有完成压缩包。')
    }
    length = response.headers.get('content-length')
    encoded = response.headers.get('content-encoding')
    reader = response.body.getReader()
  } catch (error) { release(); throw error }

  const queue: Uint8Array[] = []
  let bufferedBytes = 0, ended = false, failure: unknown
  let available = 0, consumed = 0
  let bodyController!: ReadableStreamDefaultController<Uint8Array>
  const waiters = new Set<() => void>()
  const wake = () => { for (const resolve of waiters) resolve(); waiters.clear() }
  const wait = () => new Promise<void>(resolve => { waiters.add(resolve) })
  const stop = () => {
    failure ??= signal.reason ?? new Error('下载已取消。')
    queue.length = 0; bufferedBytes = 0
    try { bodyController.error(failure) } catch { /* 已结束 */ }
    void reader.cancel(failure).catch(() => {})
    wake()
  }
  // ZIP按序消费时才创建回放流，提前完成的磁盘附件只保留水位与描述符。
  let body: ReadableStream<Uint8Array> | undefined
  const createBody = () => new ReadableStream<Uint8Array>({
    start(controller) { bodyController = controller },
    async pull(controller) {
      if (replay) {
        while (consumed === available && !ended && !failure) await wait()
        signal.throwIfAborted()
        if (failure) throw failure
        if (consumed === available) { controller.close(); return }
        const stored = await replay(consumed)
        const chunk = stored.subarray(0, Math.min(stored.length, available - consumed))
        if (!chunk.length) throw new Error('本机附件缓存不完整，不能继续写入压缩包。')
        consumed += chunk.length; controller.enqueue(chunk); return
      }
      while (!queue.length && !ended && !failure) await wait()
      if (failure) throw failure
      const chunk = queue.shift()
      if (chunk) { bufferedBytes -= chunk.byteLength; controller.enqueue(chunk); wake() }
      else controller.close()
    },
    cancel(reason) { fail(reason ?? new Error('ZIP读取已取消。')); stop() }
  }, { highWaterMark: 0 })
  signal.addEventListener('abort', stop, { once: true })
  if (signal.aborted) stop()
  const push = async (chunk: Uint8Array) => {
    // cachedFileResponse确认落盘后才交付字节。磁盘模式只推进水位，ZIP自行回读，
    // 不能因ZIP的256KiB内存队列填满而扣住网络额度。
    if (replay) { available += chunk.length; wake(); return }
    for (let offset = 0; offset < chunk.byteLength; offset += BLOCK_BYTES) {
      const count = Math.min(BLOCK_BYTES, chunk.byteLength - offset)
      while (bufferedBytes + count > FILE_BUFFER_BYTES && !signal.aborted) await wait()
      signal.throwIfAborted()
      queue.push(chunk.slice(offset, offset + count)); bufferedBytes += count; wake()
    }
  }
  const pump = async () => {
    const first: Uint8Array[] = []
    let firstBytes = 0, eof = false
    while (firstBytes < 1024) {
      signal.throwIfAborted()
      const chunk = await reader.read()
      if (chunk.done) { eof = true; break }
      first.push(chunk.value); firstBytes += chunk.value.byteLength
    }
    const prefix = new Uint8Array(Math.min(1024, firstBytes))
    let offset = 0
    for (const chunk of first) {
      const count = Math.min(chunk.byteLength, prefix.byteLength - offset)
      prefix.set(chunk.subarray(0, count), offset); offset += count
      if (offset === prefix.byteLength) break
    }
    const header = new TextDecoder().decode(prefix)
    if ((!firstBytes && !emptyAllowed) || (/\.pdf$/i.test(filename) && !header.includes('%PDF'))) {
      throw new Error(notice || '源文件正文为空或PDF格式不符，没有完成压缩包。')
    }
    if (!/\.x?html?$/i.test(filename) && /^\s*(?:<!doctype\s+html|<html|<script)/i.test(header)) {
      throw new Error('文件响应是网页，没有完成压缩包。')
    }
    let bytes = firstBytes
    for (const chunk of first) await push(chunk)
    while (!eof) {
      signal.throwIfAborted()
      const chunk = await reader.read()
      if (chunk.done) { eof = true; break }
      bytes += chunk.value.byteLength
      await push(chunk.value)
    }
    if (!encoded && length !== null && Number(length) !== bytes) throw new Error('文件传输不完整，没有完成压缩包。')
    ended = true; wake()
  }
  const finished = pump().catch(error => {
    failure ??= error
    fail(error)
    stop()
  }).finally(async () => {
    // EOF时即归还网络额度，已缓冲的字节可以稍后再写进ZIP。
    release()
    signal.removeEventListener('abort', stop)
    await reader.cancel().catch(() => {})
    reader.releaseLock()
  })
  return { get body() { return body ??= createBody() }, finished, get bufferedBytes() { return bufferedBytes } }
}

import { reactive } from 'vue'

export type TaskCheckStatus = 'idle' | 'run' | 'hold' | 'done' | 'fail'

/** 登录掉线或会话还没接上。这种失败先停住整表，等同一位接回再继续，不要把这一批记成没查成。 */
export function sessionInterrupted(message: string): boolean {
  return /登录|会话已变化|尚未确认|尚未连接|标签页已失效/.test(message)
}

export const taskCheckProgress = reactive({
  visible: false,
  done: 0,
  total: 0,
  percent: 0,
  eta: '',
  status: 'idle' as TaskCheckStatus,
  detail: '',
  /** 进度条文案里的动词：核对（PCT 表格）、翻页（全选所有拉页）、取数（递交导出）。 */
  label: '核对'
})

export function resetTaskCheckProgress(): void {
  taskCheckProgress.visible = false
  taskCheckProgress.done = 0
  taskCheckProgress.total = 0
  taskCheckProgress.percent = 0
  taskCheckProgress.eta = ''
  taskCheckProgress.status = 'idle'
  taskCheckProgress.detail = ''
  taskCheckProgress.label = '核对'
}

function clock(at: number): string {
  const date = new Date(at)
  const pad = (value: number) => String(value).padStart(2, '0')
  const time = `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
  const today = new Date()
  if (date.toDateString() === today.toDateString()) return time
  return `${date.getMonth() + 1}月${date.getDate()}日 ${time}`
}

/** 用已经对过的件数和开始时间，算出百分比和预计结束时刻。还没对上一件时不估时间；对上一件就给，翻页这种几秒就完的事才看得见预计完成。 */
export function taskCheckSnapshot(done: number, total: number, startedAt: number, now: number, status: TaskCheckStatus): { done: number; total: number; percent: number; eta: string } {
  const safeTotal = Math.max(0, Math.floor(total))
  const safeDone = Math.min(Math.max(0, Math.floor(done)), safeTotal)
  const percent = safeTotal ? Math.min(100, Math.round(safeDone / safeTotal * 1000) / 10) : 0
  if (status !== 'run' || safeDone <= 0 || safeDone >= safeTotal) return { done: safeDone, total: safeTotal, percent, eta: '' }
  const elapsed = now - startedAt
  return { done: safeDone, total: safeTotal, percent, eta: clock(now + elapsed / safeDone * (safeTotal - safeDone)) }
}

export function paintTaskCheckProgress(done: number, total: number, startedAt: number, status: TaskCheckStatus, label = '核对', now = Date.now(), detail = ''): void {
  const view = taskCheckSnapshot(done, total, startedAt, now, status)
  const visible = view.total > 0
  const bar = taskCheckProgress
  if (bar.visible === visible && bar.done === view.done && bar.total === view.total && bar.percent === view.percent && bar.eta === view.eta && bar.status === status && bar.label === label && bar.detail === detail) return
  bar.visible = visible
  bar.done = view.done
  bar.total = view.total
  bar.percent = view.percent
  bar.eta = view.eta
  bar.status = status
  bar.label = label
  bar.detail = detail
}

import { reactive } from 'vue'
import { downloadXlsxSheets } from '../customer/xlsx-table'

export interface DialogOptions {
  title: string
  message: string
  confirmLabel?: string
  cancelLabel?: string
  /** 警示框：标题居中标红，用来在提交前拦一下。 */
  warn?: boolean
  /** 逐行清单画成表格。短表整表展开，长表在框内滚动。 */
  table?: DialogTable
}

export interface DialogTable {
  headers?: string[]
  rows: string[][]
}

const state = reactive({
  open: false,
  title: '',
  message: '',
  confirmLabel: '确定',
  cancelLabel: '取消',
  warn: false,
  table: null as DialogTable | null
})

let settle: ((confirmed: boolean) => void) | null = null

export interface ProgressLine {
  time: string
  text: string
}

export interface ProgressCounts {
  success: number
  failed: number
  abnormal: number
  skipped: number
}

export interface ProgressNote {
  kind: 'failed' | 'abnormal' | 'skipped'
  label: string
  reason: string
}

export const progressDialog = reactive({
  open: false,
  title: '',
  lines: [] as ProgressLine[],
  done: 0,
  total: 1,
  finished: false,
  counts: { success: 0, failed: 0, abnormal: 0, skipped: 0 } as ProgressCounts,
  notes: [] as ProgressNote[]
})

function progressClock(date = new Date()): string {
  const pad = (value: number) => String(value).padStart(2, '0')
  return `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
}

export function beginProgress(title: string, total: number): void {
  progressDialog.title = title
  progressDialog.lines = []
  progressDialog.done = 0
  progressDialog.total = Math.max(total, 1)
  progressDialog.finished = false
  progressDialog.counts.success = 0
  progressDialog.counts.failed = 0
  progressDialog.counts.abnormal = 0
  progressDialog.counts.skipped = 0
  progressDialog.notes = []
  progressDialog.open = true
}

/** 一封提交结果归到成功、失败、异常或跳过。对不上邮箱算异常，不用发是仲裁结论算跳过。 */
export function classifySubmitText(text: string): keyof ProgressCounts {
  if (text.startsWith('已提交')) return 'success'
  if (/对上邮箱|没有商务邮箱|没有客户联系人|没有案件联系人|对上了多个邮箱|没有可用的.+邮箱/.test(text)) return 'abnormal'
  if (/还在审核里|已经提交过|没有要提交|不用发，没有创建发文/.test(text)) return 'skipped'
  return 'failed'
}

export function tallyProgress(kind: keyof ProgressCounts, count = 1): void {
  if (count <= 0) return
  progressDialog.counts[kind] += count
}

/** 失败、异常、跳过记下文号和原因，结束时跟在件数后面。 */
export function noteProgress(kind: ProgressNote['kind'], label: string, reason: string): void {
  const text = reason.replace(/^没有提交到审核人。/, '').split('\n').map(item => item.trim()).filter(Boolean)[0] ?? ''
  progressDialog.notes.push({ kind, label: label.trim() || '这一件', reason: text.slice(0, 180) || '没有写明原因。' })
}

export function progressSummaryLine(): string {
  const counts = progressDialog.counts
  const parts = [`成功 ${counts.success} 件`, `失败 ${counts.failed} 件`, `异常 ${counts.abnormal} 件`]
  if (counts.skipped) parts.push(`跳过 ${counts.skipped} 件`)
  const head = `统计：${parts.join('，')}。`
  const names = { failed: '失败', abnormal: '异常', skipped: '跳过' } as const
  const details = progressDialog.notes.map(note => `${names[note.kind]} ${note.label}：${note.reason}`)
  return details.length ? `${head}${details.join('')}` : head
}

export function logProgress(line: string, done?: number): void {
  progressDialog.lines.push({ time: progressClock(), text: line })
  if (done === undefined) return
  const next = Math.min(progressDialog.total, Math.max(0, Math.round(done)))
  if (next > progressDialog.done) progressDialog.done = next
}

export function endProgress(): void {
  progressDialog.finished = true
  progressDialog.done = progressDialog.total
}

export function closeProgress(): void {
  if (!progressDialog.finished) return
  progressDialog.open = false
}

export function dialogState() {
  return state
}

/** 全站确认框。同一时间只开一个，后来的会关掉前一个。 */
export function confirmDialog(options: DialogOptions): Promise<boolean> {
  if (settle) settle(false)
  state.title = options.title
  state.message = options.message
  state.confirmLabel = options.confirmLabel?.trim() || '确定'
  state.cancelLabel = options.cancelLabel === undefined ? '取消' : options.cancelLabel.trim()
  state.warn = options.warn === true
  state.table = options.table?.rows.length ? options.table : null
  state.open = true
  return new Promise(resolve => {
    settle = resolve
  })
}

/** 只读说明。遮罩、Esc 和「知道了」都是关掉。 */
export function infoDialog(options: Pick<DialogOptions, 'title' | 'message'>): Promise<boolean> {
  return confirmDialog({ ...options, confirmLabel: '知道了', cancelLabel: '' })
}

/** 全选时没有客户收件人，已先把业务邮箱写入收件人。提交结束后让用户核对。 */
export async function warnBusinessRecipients(rows: string[][]): Promise<void> {
  if (!rows.length) return
  await confirmDialog({
    title: `警示：${rows.length} 封已先写入业务邮箱`,
    message: '这些信的表格没有指定收件人，客户要求也没有指定发给谁。全选时发文规则里没有可勾选的客户联系人邮箱，已先把业务邮箱写入收件人。请在审核前认真核对，不该发给业务人员的要改掉。',
    table: { headers: ['案号', '收件人'], rows },
    confirmLabel: '知道了',
    cancelLabel: '',
    warn: true
  })
}

export function closeDialog(confirmed: boolean): void {
  if (!state.open) return
  state.open = false
  const done = settle
  settle = null
  done?.(confirmed)
}

/** 提交完成后整批结果的总结表。可滚动核对，可导出成 xlsx。 */
export const summaryDialog = reactive({
  open: false,
  title: '',
  headers: [] as string[],
  rows: [] as string[][],
  exportName: ''
})

/** 总结表里的公司名最多 15 个字，再长就省略。 */
export function clipCompany(name: string | undefined): string {
  const text = name?.trim() || '表格里没有'
  return text.length > 15 ? `${text.slice(0, 15)}…` : text
}

export function openSummary(title: string, headers: string[], rows: string[][], exportName: string): void {
  summaryDialog.title = title
  summaryDialog.headers = [...headers]
  summaryDialog.rows = rows.map(row => [...row])
  summaryDialog.exportName = exportName
  summaryDialog.open = true
}

export function closeSummary(): void {
  summaryDialog.open = false
}

export function exportSummary(): void {
  if (!summaryDialog.rows.length) return
  const name = summaryDialog.exportName || '提交总结.xlsx'
  downloadXlsxSheets([{ name: '提交总结', rows: [summaryDialog.headers, ...summaryDialog.rows] }], name)
}

import { apiDocFiles, apiDocRawText } from '../../agent/api-docs'

export interface DocEntry {
  /** 树里的显示名。 */
  title: string
  file?: string
  /** 点开这一篇时才加载 Markdown 原文。没有 load 的是目录节点。 */
  load?: () => Promise<string>
  /** 有 children 时是二级目录节点，点开收起。 */
  children?: DocEntry[]
}

export interface DocGroup {
  name: string
  entries: DocEntry[]
}

/** 使用文档成篇落在 docs/usage 目录，构建时按文件名排序，点开才加载。 */
const usageFiles = import.meta.glob('../../../docs/usage/*.md', {
  query: '?raw',
  import: 'default'
}) as Record<string, () => Promise<string>>

function usageTitle(path: string): string {
  const name = path.split(/[/\\]/).pop() ?? path
  return name.replace(/\.md$/i, '').replace(/^(\d+)-/, '$1 ')
}

const usageEntries: DocEntry[] = Object.keys(usageFiles)
  .sort((a, b) => a.localeCompare(b, 'zh-Hans-CN'))
  .map(path => ({ title: usageTitle(path), load: usageFiles[path] }))

/** 三个内置工作流各一篇；索引固定排第一，源文件随扩展离线打包。 */
const workflowFiles = import.meta.glob('../../../docs/workflows/*.md', {
  query: '?raw',
  import: 'default'
}) as Record<string, () => Promise<string>>

const workflowEntries: DocEntry[] = Object.keys(workflowFiles)
  .sort((a, b) => {
    const aIndex = a.endsWith('/README.md')
    const bIndex = b.endsWith('/README.md')
    return aIndex !== bIndex ? (aIndex ? -1 : 1) : a.localeCompare(b, 'zh-Hans-CN')
  })
  .map(path => ({
    title: path.endsWith('/README.md') ? 'README（工作流索引）' : usageTitle(path),
    file: path.split('/').pop(),
    load: workflowFiles[path]
  }))

/** 接口文档直接用仓库 API 目录里的原文，不另抄一份。README 当目录排最前。 */
function apiTitle(file: string): string {
  return /^readme\.md$/i.test(file) ? 'README（目录）' : file.replace(/\.md$/i, '')
}

const apiSorted = [...apiDocFiles()].sort((a, b) => {
  const aReadme = /^readme\.md$/i.test(a)
  const bReadme = /^readme\.md$/i.test(b)
  if (aReadme !== bReadme) return aReadme ? -1 : 1
  return a.localeCompare(b, 'zh-Hans-CN')
})

const apiEntries: DocEntry[] = apiSorted.map(file => ({
  title: apiTitle(file),
  load: async () => apiDocRawText(file)
}))

/** agent 学习文档在仓库根的 docs 目录，一层子目录按二级树展开，点开才加载。 */
const agentFiles = import.meta.glob('../../../../docs/**/*.md', {
  query: '?raw',
  import: 'default'
}) as Record<string, () => Promise<string>>

interface AgentFile {
  dir: string
  name: string
  path: string
}

const agentList: AgentFile[] = Object.keys(agentFiles).map(path => {
  const rel = path.replace(/^(\.\.\/)+/, '')
  const parts = rel.split('/')
  const file = parts[parts.length - 1] ?? ''
  const dir = parts.length > 2 ? parts[parts.length - 2] : ''
  return { dir, name: file, path }
})

const agentRoots: DocEntry[] = agentList
  .filter(item => !item.dir)
  .sort((a, b) => /^readme\.md$/i.test(b.name) ? 1 : a.name.localeCompare(b.name, 'zh-Hans-CN'))
  .map(item => ({
    title: /^readme\.md$/i.test(item.name) ? 'README（总目录）' : item.name.replace(/\.md$/i, ''),
    load: agentFiles[item.path]
  }))

const agentSectionNames = [...new Set(agentList.filter(item => item.dir).map(item => item.dir))]
  .sort((a, b) => a.localeCompare(b, 'zh-Hans-CN'))

const agentSections: DocEntry[] = agentSectionNames.map(dir => ({
  title: dir,
  children: agentList
    .filter(item => item.dir === dir)
    .sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN'))
    .map(item => ({ title: item.name.replace(/\.md$/i, ''), load: agentFiles[item.path] }))
}))

const agentEntries: DocEntry[] = [...agentRoots, ...agentSections]

/** 文档浮窗左侧的文件树。前两组是平铺文章，agent学习按子目录展开二级树。 */
export const DOC_GROUPS: DocGroup[] = [
  { name: '使用文档', entries: usageEntries },
  { name: '工作流', entries: workflowEntries },
  { name: '接口文档', entries: apiEntries },
  { name: 'agent学习', entries: agentEntries }
]

import { marked, Marked } from 'marked'
import DOMPurify from 'dompurify'

const escape = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const parser = new Marked({
  gfm: true,
  breaks: true,
  renderer: {
    html: ({ text }) => escape(text),
    image: ({ text }) => escape(text),
    link(token) {
      const label = this.parser.parseInline(token.tokens)
      if (/^(?:\.\/)?[^/#:]+\.md$/i.test(token.href)) {
        return `<a href="#" data-doc-file="${escape(token.href.replace(/^\.\//, ''))}">${label}</a>`
      }
      if (/^https?:|^mailto:/i.test(token.href)) {
        return `<a href="${escape(token.href)}" target="_blank" rel="noopener noreferrer">${label}</a>`
      }
      return label
    }
  }
})

function renderText(source: string): string {
  return DOMPurify.sanitize(parser.parse(source, { async: false }), {
    ALLOWED_TAGS: ['a', 'blockquote', 'br', 'code', 'del', 'em', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'hr', 'input', 'li', 'ol', 'p', 'pre', 'strong', 'table', 'tbody', 'td', 'th', 'thead', 'tr', 'ul'],
    ALLOWED_ATTR: ['href', 'target', 'rel', 'data-doc-file', 'colspan', 'rowspan', 'align', 'type', 'checked', 'disabled']
  })
}

export type DocBlock =
  | { kind: 'html'; html: string }
  | { kind: 'mermaid'; source: string; title: string }

/** Let the Markdown lexer identify real fences; examples inside other fences stay code. */
export function documentBlocks(source: string): DocBlock[] {
  const blocks: DocBlock[] = []
  let pending = ''
  let heading = '流程图'
  const flush = () => {
    if (pending.trim()) blocks.push({ kind: 'html', html: renderText(pending) })
    pending = ''
  }
  for (const token of marked.lexer(source)) {
    if (token.type === 'heading') heading = token.text
    if (token.type === 'code' && token.lang?.trim().toLowerCase() === 'mermaid') {
      flush()
      blocks.push({ kind: 'mermaid', source: token.text, title: heading })
    } else pending += token.raw
  }
  flush()
  return blocks
}

import { isWriteSwitchOpen } from '../settings/write-switch'
import type { EvidenceLevel } from './types'

export interface ContractSample {
  handler: string
  call: string
  method: string
  contentType: string
  statusCode: number
  requestFieldNames: string[]
  responseShape: string
  businessSuccess: boolean
  redirected: boolean
  followupReadEndpoint: string
  readbackMatched: boolean
  source: 'live' | 'mock' | 'page-script'
  observedAt: string
}

const SECRET = /cookie|authorization|password|token|mail_body|mail_subject|mail_to|mail_cc|email/i
const EMAIL = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi

export function redactText(value: string): string {
  return value.replace(EMAIL, '[redacted-email]').replace(/Bearer\s+\S+/gi, '[redacted-token]')
}

export function redactRecord(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(redactRecord)
  if (!value || typeof value !== 'object') return typeof value === 'string' ? redactText(value) : value
  const output: Record<string, unknown> = {}
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    output[key] = SECRET.test(key) ? '[redacted]' : redactRecord(item)
  }
  return output
}

function shapeOf(value: unknown): string {
  if (value == null || value === '') return 'empty'
  if (Array.isArray(value)) return `array(${value.length})`
  if (typeof value === 'object') return `object(${Object.keys(value as object).sort().join(',')})`
  return typeof value
}

/** 从脱敏后的交换记录判断证据等级。Mock 和 502、空响应都不能升到回读核验。 */
export function analyzeExchange(input: {
  handler: string
  call: string
  method?: string
  contentType?: string
  statusCode: number
  request: Record<string, unknown>
  response: unknown
  redirected?: boolean
  followupReadEndpoint?: string
  readbackMatched?: boolean
  source: ContractSample['source']
  observedAt?: string
}): ContractSample {
  const request = redactRecord(input.request) as Record<string, unknown>
  const response = redactRecord(input.response)
  const statusCode = input.statusCode
  const responseShape = shapeOf(response)
  const businessSuccess = statusCode >= 200 && statusCode < 300 && responseShape !== 'empty' && input.source !== 'mock'
  return {
    handler: input.handler,
    call: input.call,
    method: input.method ?? 'POST',
    contentType: input.contentType ?? 'application/x-www-form-urlencoded; charset=UTF-8',
    statusCode,
    requestFieldNames: Object.keys(request).sort(),
    responseShape,
    businessSuccess,
    redirected: input.redirected === true,
    followupReadEndpoint: input.followupReadEndpoint ?? '',
    readbackMatched: input.readbackMatched === true && businessSuccess,
    source: input.source,
    observedAt: input.observedAt ?? new Date().toISOString()
  }
}

export function evidenceLevel(samples: ContractSample[], call: string): EvidenceLevel {
  const rows = samples.filter(item => item.call === call && item.source !== 'mock')
  if (rows.some(item => item.readbackMatched && item.businessSuccess)) return 'READBACK_VERIFIED'
  if (rows.some(item => item.businessSuccess)) return 'RESPONSE_OBSERVED'
  if (rows.some(item => item.requestFieldNames.length > 0)) return 'REQUEST_OBSERVED'
  return 'UNKNOWN'
}

/** 静态目录上的 responseCaptured 不参与判断。是否允许生产写入只看前端写开关，默认打开。 */
export function productionWriteAllowed(): boolean {
  return isWriteSwitchOpen()
}

import { redactRecord, redactText } from './contract-capture'
import type { EvidenceLevel } from './types'
import { sha256Hex } from './sha256'

export type EvidenceSource = 'LIVE' | 'CAPTURED_HAR' | 'PAGE_SCRIPT' | 'MOCK'

export interface StoredEvidence {
  evidenceId: string
  handler: string
  call: string
  origin: string
  operatorIdHash: string
  requestShape: string
  responseShape: string
  httpStatus: number
  businessSuccess: boolean
  readbackCall: string
  readbackMatched: boolean
  source: EvidenceSource
  level: EvidenceLevel
  capturedAt: string
  verifiedAt: string
  sampleHash: string
}

const SECRET = /cookie|authorization|password|token|mail_body|mail_subject|mail_to|mail_cc|set-cookie|email/i

export function hashOperator(operatorId: string): string {
  return sha256Hex(operatorId)
}

export function evidenceLevelOf(input: Pick<StoredEvidence, 'source' | 'businessSuccess' | 'readbackMatched' | 'requestShape'>): EvidenceLevel {
  if (input.source === 'MOCK') return 'UNKNOWN'
  if (input.readbackMatched && input.businessSuccess) return 'READBACK_VERIFIED'
  if (input.businessSuccess) return 'RESPONSE_OBSERVED'
  if (input.requestShape && input.requestShape !== 'empty') return 'REQUEST_OBSERVED'
  return 'UNKNOWN'
}

export function sealEvidence(input: Omit<StoredEvidence, 'evidenceId' | 'level' | 'sampleHash' | 'operatorIdHash'> & { operatorId: string; evidenceId?: string }): StoredEvidence {
  const requestShape = redactText(input.requestShape)
  const responseShape = redactText(input.responseShape)
  const row: StoredEvidence = {
    evidenceId: input.evidenceId ?? globalThis.crypto.randomUUID(),
    handler: input.handler,
    call: input.call,
    origin: input.origin,
    operatorIdHash: hashOperator(input.operatorId),
    requestShape,
    responseShape,
    httpStatus: input.httpStatus,
    businessSuccess: input.source === 'MOCK' ? false : input.businessSuccess,
    readbackCall: input.readbackCall,
    readbackMatched: input.source === 'MOCK' ? false : input.readbackMatched,
    source: input.source,
    level: 'UNKNOWN',
    capturedAt: input.capturedAt,
    verifiedAt: input.verifiedAt,
    sampleHash: ''
  }
  row.level = evidenceLevelOf(row)
  row.sampleHash = sha256Hex(JSON.stringify(redactRecord({
    call: row.call, requestShape, responseShape, httpStatus: row.httpStatus, source: row.source, level: row.level
  })))
  return row
}

export interface EvidenceRepository {
  saveEvidence(row: StoredEvidence): Promise<void>
  listEvidence(origin: string, call?: string): Promise<StoredEvidence[]>
  saveAcceptance(row: import('./acceptance-runner').LiveAcceptanceRecord): Promise<void>
  listAcceptance(origin: string, operatorId: string): Promise<import('./acceptance-runner').LiveAcceptanceRecord[]>
}

export class MemoryEvidenceStore implements EvidenceRepository {
  readonly evidence: StoredEvidence[] = []
  readonly acceptance: import('./acceptance-runner').LiveAcceptanceRecord[] = []

  saveEvidence(row: StoredEvidence): Promise<void> {
    if (SECRET.test(JSON.stringify(row))) return Promise.reject(new Error('证据包含敏感字段。'))
    const index = this.evidence.findIndex(item => item.evidenceId === row.evidenceId)
    if (index >= 0) this.evidence[index] = row
    else this.evidence.push(row)
    return Promise.resolve()
  }

  listEvidence(origin: string, call = ''): Promise<StoredEvidence[]> {
    return Promise.resolve(this.evidence.filter(item => item.origin === origin && (call === '' || item.call === call)))
  }

  saveAcceptance(row: import('./acceptance-runner').LiveAcceptanceRecord): Promise<void> {
    const text = JSON.stringify(row)
    if (SECRET.test(text) || /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(text)) {
      return Promise.reject(new Error('验收记录包含敏感字段。'))
    }
    this.acceptance.push(row)
    return Promise.resolve()
  }

  listAcceptance(origin: string, operatorId: string): Promise<import('./acceptance-runner').LiveAcceptanceRecord[]> {
    return Promise.resolve(this.acceptance.filter(item => item.origin === origin && item.operatorId === operatorId))
  }
}

interface EvidenceBundle {
  evidence: StoredEvidence[]
  acceptance: import('./acceptance-runner').LiveAcceptanceRecord[]
}

/** 证据放在扩展自己的 IndexedDB。一次事务里读取并写回。 */
export class IndexedEvidenceStore implements EvidenceRepository {
  private database: Promise<IDBDatabase> | null = null
  constructor(private readonly factory: IDBFactory) {}

  private open(): Promise<IDBDatabase> {
    this.database ??= new Promise((resolve, reject) => {
      const request = this.factory.open('patmail-evidence', 1)
      request.onupgradeneeded = () => request.result.createObjectStore('rows')
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error)
    })
    return this.database
  }

  private async update(work: (bundle: EvidenceBundle) => void): Promise<EvidenceBundle> {
    const database = await this.open()
    return await new Promise((resolve, reject) => {
      const tx = database.transaction('rows', 'readwrite')
      const store = tx.objectStore('rows')
      const current = store.get('bundle')
      let bundle: EvidenceBundle = { evidence: [], acceptance: [] }
      current.onsuccess = () => {
        bundle = current.result ?? { evidence: [], acceptance: [] }
        work(bundle)
        store.put(bundle, 'bundle')
      }
      current.onerror = () => reject(current.error)
      tx.oncomplete = () => resolve(bundle)
      tx.onerror = () => reject(tx.error)
    })
  }

  async saveEvidence(row: StoredEvidence): Promise<void> {
    await this.update(bundle => {
      const index = bundle.evidence.findIndex(item => item.evidenceId === row.evidenceId)
      if (index >= 0) bundle.evidence[index] = row
      else bundle.evidence.push(row)
    })
  }

  async listEvidence(origin: string, call = ''): Promise<StoredEvidence[]> {
    const bundle = await this.update(() => undefined)
    return bundle.evidence.filter(item => item.origin === origin && (call === '' || item.call === call))
  }

  async saveAcceptance(row: import('./acceptance-runner').LiveAcceptanceRecord): Promise<void> {
    await this.update(bundle => { bundle.acceptance.push(row) })
  }

  async listAcceptance(origin: string, operatorId: string): Promise<import('./acceptance-runner').LiveAcceptanceRecord[]> {
    const bundle = await this.update(() => undefined)
    return bundle.acceptance.filter(item => item.origin === origin && item.operatorId === operatorId)
  }
}

import type { FileTypeNode } from '../api/dictionaries/types'
