interface HarHeader { name?: string; value?: string }
interface HarEntry {
  startedDateTime?: string
  request?: { method?: string; url?: string; headers?: HarHeader[]; postData?: { mimeType?: string; text?: string } }
  response?: { status?: number; headers?: HarHeader[]; redirectURL?: string; content?: { mimeType?: string; text?: string } }
}

function paramsOf(text: string): Record<string, string> {
  const output: Record<string, string> = {}
  for (const [key, value] of new URLSearchParams(text)) output[key] = value
  return output
}

function fieldNames(record: Record<string, string>): string {
  return Object.keys(record).filter(key => !/cookie|authorization|password|token|mail_body|mail_subject|mail_to|mail_cc|email/i.test(key)).sort().join(',')
}

function shapeOf(text: string | undefined): string {
  if (!text || !text.trim()) return 'empty'
  try {
    const parsed = JSON.parse(text) as unknown
    if (!parsed || typeof parsed !== 'object') return typeof parsed
    return `object(${Object.keys(parsed as object).sort().join(',')})`
  } catch {
    return 'text'
  }
}

/** 只保留目标 Origin 的白名单 Call，并去掉凭据、正文和邮箱。 */
export function importHar(raw: unknown, origin: string, operatorId: string): StoredEvidence[] {
  if (!raw || typeof raw !== 'object') return []
  const entries = (raw as { log?: { entries?: HarEntry[] } }).log?.entries
  if (!Array.isArray(entries)) return []
  const rows: StoredEvidence[] = []
  let pending: StoredEvidence | null = null
  for (const entry of entries) {
    let url: URL
    try { url = new URL(entry.request?.url ?? '') } catch { continue }
    if (url.origin !== origin) continue
    const headerText = [...(entry.request?.headers ?? []), ...(entry.response?.headers ?? [])]
      .map(item => `${item.name ?? ''}:${item.value ?? ''}`).join('\n')
    if (/set-cookie|authorization|cookie/i.test(headerText)) {
      // 头只用于丢弃，不进入证据。
    }
    const body = paramsOf(entry.request?.postData?.text ?? '')
    const call = body.Call || url.searchParams.get('Call') || ''
    if (!ALLOWED.has(call)) continue
    const responseText = entry.response?.content?.text
    const readback = READBACK[call]
    const row = sealEvidence({
      handler: url.pathname,
      call,
      origin,
      operatorId,
      requestShape: fieldNames(body) || 'empty',
      responseShape: shapeOf(responseText),
      httpStatus: entry.response?.status ?? 0,
      businessSuccess: false,
      readbackCall: readback ?? '',
      readbackMatched: false,
      source: 'CAPTURED_HAR',
      capturedAt: entry.startedDateTime ?? new Date().toISOString(),
      verifiedAt: ''
    })
    if (pending && pending.readbackCall === call && !pending.readbackMatched) {
      pending.readbackMatched = false
      pending = null
    }
    rows.push(row)
    if (readback) pending = row
    if (responseText && /@/.test(responseText)) row.responseShape = redactText(row.responseShape)
  }
  return rows.filter(item => !/cookie|authorization|set-cookie|@[a-z0-9.-]+\.[a-z]{2,}/i.test(JSON.stringify(item)))
}

import { applyAtomicTaskUpdate, commitTasks, decideTaskSave, isProtectedTask, readStoredTasks } from './repository'
import type { TaskSaveResult } from './repository'
import type { TaskStore } from './task-service'
import type { AutomationTask } from './types'

const DB_NAME = 'patmail-automation-tasks'
const STORE = 'bundles'

/** Background 或页面 IndexedDB。迁移、冲突判断和写入都在同一次 readwrite 事务里完成，事务内不发网络请求。 */
export class IndexedTaskStore implements TaskStore {
  private database: Promise<IDBDatabase> | null = null

  constructor(private readonly factory: IDBFactory) {}

  private open(): Promise<IDBDatabase> {
    this.database ??= new Promise((resolve, reject) => {
      const request = this.factory.open(DB_NAME, 1)
      request.onupgradeneeded = () => request.result.createObjectStore(STORE)
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error)
    })
    return this.database
  }

  async list(origin: string, operatorId: string, includeArchived = false): Promise<AutomationTask[]> {
    const key = `${origin}\u0000${operatorId}`
    const database = await this.open()
    return await new Promise((resolve, reject) => {
      const tx = database.transaction(STORE, 'readwrite')
      const store = tx.objectStore(STORE)
      const current = store.get(key)
      let tasks: AutomationTask[] = []
      current.onsuccess = () => {
        const stored = readStoredTasks(current.result, origin, operatorId)
        tasks = stored.tasks.filter(item => includeArchived || !item.archived)
        if (stored.changed) store.put({ version: 2, tasks: [...stored.opaque, ...stored.tasks], migrations: stored.migrations }, key)
      }
      current.onerror = () => reject(current.error)
      tx.oncomplete = () => resolve(tasks)
      tx.onerror = () => reject(tx.error)
    })
  }

  async save(task: AutomationTask): Promise<TaskSaveResult> {
    const key = `${task.origin}\u0000${task.operatorId}`
    const database = await this.open()
    return await new Promise((resolve, reject) => {
      const tx = database.transaction(STORE, 'readwrite')
      const store = tx.objectStore(STORE)
      const current = store.get(key)
      let outcome: TaskSaveResult = { ok: false, code: 'INVALID_TRANSITION', message: '任务没有写入存储。' }
      current.onsuccess = () => {
        const stored = readStoredTasks(current.result, task.origin, task.operatorId)
        const prior = stored.tasks.find(item => item.taskId === task.taskId)
        const decided = decideTaskSave(prior, task)
        outcome = decided.result
        if (!decided.write) return
        const tasks = commitTasks(stored.tasks, decided.write)
        store.put({ version: 2, tasks: [...stored.opaque, ...tasks], migrations: stored.migrations }, key)
      }
      current.onerror = () => reject(current.error)
      tx.oncomplete = () => resolve(outcome)
      tx.onerror = () => reject(tx.error)
    })
  }

  async updateTaskAtomically(origin: string, operatorId: string, taskId: string, expectedVersion: number, transition: (current: AutomationTask) => { ok: true; task: AutomationTask } | { ok: false; message: string }): Promise<TaskSaveResult> {
    const key = `${origin}\u0000${operatorId}`
    const database = await this.open()
    return await new Promise((resolve, reject) => {
      const tx = database.transaction(STORE, 'readwrite')
      const store = tx.objectStore(STORE)
      const current = store.get(key)
      let outcome: TaskSaveResult = { ok: false, code: 'INVALID_TRANSITION', message: '没有这个任务。' }
      current.onsuccess = () => {
        const stored = readStoredTasks(current.result, origin, operatorId)
        const result = applyAtomicTaskUpdate(stored.tasks, taskId, expectedVersion, transition)
        outcome = result.ok && result.task
          ? { ok: true, task: result.task, recordVersion: result.task.recordVersion ?? 1 }
          : { ok: false, code: result.code ?? 'INVALID_TRANSITION', message: result.message, current: result.task ?? undefined }
        if (result.ok) store.put({ version: 2, tasks: [...stored.opaque, ...result.tasks], migrations: stored.migrations }, key)
      }
      current.onerror = () => reject(current.error)
      tx.oncomplete = () => resolve(outcome)
      tx.onerror = () => reject(tx.error)
    })
  }

  async archive(origin: string, operatorId: string, taskId: string): Promise<{ ok: boolean; message: string }> {
    const key = `${origin}\u0000${operatorId}`
    const database = await this.open()
    return await new Promise((resolve, reject) => {
      const tx = database.transaction(STORE, 'readwrite')
      const store = tx.objectStore(STORE)
      const current = store.get(key)
      let outcome: { ok: boolean; message: string } = { ok: false, message: '没有这个任务。' }
      current.onsuccess = () => {
        const stored = readStoredTasks(current.result, origin, operatorId)
        const task = stored.tasks.find(item => item.taskId === taskId)
        if (!task) return
        if (isProtectedTask(task)) {
          outcome = { ok: false, message: '结果未知或尚未结束的任务不能归档。' }
          return
        }
        const tasks = commitTasks(stored.tasks, { ...task, archived: true })
        store.put({ version: 2, tasks: [...stored.opaque, ...tasks], migrations: stored.migrations }, key)
        outcome = { ok: true, message: '' }
      }
      current.onerror = () => reject(current.error)
      tx.oncomplete = () => resolve(outcome)
      tx.onerror = () => reject(tx.error)
    })
  }

}

/** 测试用的串行存储。每次读取、迁移和写入都在同一次回调里完成。 */
export class SerialTaskStore implements TaskStore {
  private chain: Promise<void> = Promise.resolve()
  constructor(private raw: unknown) {}

  list(origin: string, operatorId: string, includeArchived = false): Promise<AutomationTask[]> {
    return this.run(() => {
      const stored = readStoredTasks(this.raw, origin, operatorId)
      if (stored.changed) this.raw = { version: 2, tasks: [...stored.opaque, ...stored.tasks], migrations: stored.migrations }
      return stored.tasks.filter(item => includeArchived || !item.archived)
    })
  }

  save(task: AutomationTask): Promise<TaskSaveResult> {
    return this.run(() => {
      const stored = readStoredTasks(this.raw, task.origin, task.operatorId)
      const prior = stored.tasks.find(item => item.taskId === task.taskId)
      const decided = decideTaskSave(prior, task)
      if (decided.write) {
        const tasks = commitTasks(stored.tasks, decided.write)
        this.raw = { version: 2, tasks: [...stored.opaque, ...tasks], migrations: stored.migrations }
      }
      return decided.result
    })
  }

  updateTaskAtomically(origin: string, operatorId: string, taskId: string, expectedVersion: number, transition: (current: AutomationTask) => { ok: true; task: AutomationTask } | { ok: false; message: string }): Promise<TaskSaveResult> {
    return this.run(() => {
      const stored = readStoredTasks(this.raw, origin, operatorId)
      const result = applyAtomicTaskUpdate(stored.tasks, taskId, expectedVersion, transition)
      if (result.ok) this.raw = { version: 2, tasks: [...stored.opaque, ...result.tasks], migrations: stored.migrations }
      if (result.ok && result.task) return { ok: true as const, task: result.task, recordVersion: result.task.recordVersion ?? 1 }
      return { ok: false as const, code: result.code ?? 'INVALID_TRANSITION', message: result.message, current: result.task ?? undefined }
    })
  }

  archive(origin: string, operatorId: string, taskId: string): Promise<{ ok: boolean; message: string }> {
    return this.run(() => {
      const stored = readStoredTasks(this.raw, origin, operatorId)
      const task = stored.tasks.find(item => item.taskId === taskId)
      if (!task) return { ok: false, message: '没有这个任务。' }
      if (isProtectedTask(task)) return { ok: false, message: '结果未知或尚未结束的任务不能归档。' }
      const tasks = commitTasks(stored.tasks, { ...task, archived: true })
      this.raw = { version: 2, tasks: [...stored.opaque, ...tasks], migrations: stored.migrations }
      return { ok: true, message: '' }
    })
  }

  private run<T>(work: () => T): Promise<T> {
    const job = this.chain.then(() => work())
    this.chain = job.then(() => undefined, () => undefined)
    return job
  }
}

export function createBrowserTaskStore(): TaskStore {
  const factory = globalThis.indexedDB
  if (!factory) return emptyStore()
  return new IndexedTaskStore(factory)
}

function emptyStore(): TaskStore {
  return {
    list: async () => [],
    save: async () => { throw new Error('当前环境没有任务存储。') },
    updateTaskAtomically: async () => ({ ok: false as const, code: 'INVALID_TRANSITION' as const, message: '当前环境没有任务存储。' }),
    archive: async () => ({ ok: false, message: '当前环境没有任务存储。' })
  }
}

import type { ExecutionLease } from './types'

export interface LedgerState {
  leases: ExecutionLease[]
}

export interface TransactionStore {
  /** 回调必须同步完成，不能在里面等待网络。 */
  run<T>(work: (state: LedgerState) => T): Promise<T>
}

export function memoryTransactionStore(): TransactionStore {
  let state: LedgerState = { leases: [] }
  let chain: Promise<void> = Promise.resolve()
  return {
    run(work) {
      const job = chain.then(() => {
        const draft: LedgerState = { leases: state.leases.map(item => ({ ...item })) }
        const result = work(draft)
        state = draft
        return result
      })
      chain = job.then(() => undefined, () => undefined)
      return job
    }
  }
}

function retain(leases: ExecutionLease[]): ExecutionLease[] {
  const active = leases.filter(item => item.status !== 'RELEASED' || item.requestSent)
  const released = leases.filter(item => item.status === 'RELEASED' && !item.requestSent)
  return [...active, ...released]
}

/** 在同一个存储事务里领取执行权。本地互斥不等于 EASY 服务端只执行一次。 */
export class ExecutionLedger {
  constructor(private readonly store: TransactionStore, private readonly ownerId: string) {}

  claim(origin: string, operatorId: string, taskFingerprint: string): Promise<{ ok: true; lease: ExecutionLease } | { ok: false; lease: ExecutionLease | null; reason: string }> {
    return this.store.run(state => {
      const blocking = state.leases.find(item => item.origin === origin && item.operatorId === operatorId && item.taskFingerprint === taskFingerprint && item.status !== 'RELEASED' && item.status !== 'COMPLETED')
      if (blocking) return { ok: false as const, lease: blocking, reason: blocking.requestSent ? '请求已经发出，不能再次执行。' : '已有活动执行所有者。' }
      const now = new Date().toISOString()
      const lease: ExecutionLease = {
        executionId: globalThis.crypto.randomUUID(), taskFingerprint, owner: this.ownerId, status: 'CLAIMED',
        requestSent: false, easyMailId: '', startedAt: now, updatedAt: now, lastCheckpoint: 'claimed', leaseVersion: 1, origin, operatorId
      }
      state.leases = retain([...state.leases, lease])
      return { ok: true as const, lease }
    })
  }

  markPrepared(executionId: string, leaseVersion: number): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (item.requestSent || (item.status !== 'CLAIMED' && item.status !== 'RUNNING')) return '当前租约不能标记为已准备。'
      item.status = 'PREPARED'
      item.lastCheckpoint = 'prepared'
      return ''
    })
  }

  markSent(executionId: string, leaseVersion: number, checkpoint: string): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (item.requestSent || (item.status !== 'CLAIMED' && item.status !== 'PREPARED' && item.status !== 'RUNNING')) return '当前租约不能标记为已发送。'
      item.requestSent = true
      item.status = 'REQUEST_SENT'
      item.lastCheckpoint = checkpoint
      return ''
    })
  }

  markResponse(executionId: string, leaseVersion: number): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (!item.requestSent || item.status !== 'REQUEST_SENT') return '还没有已发送的请求。'
      item.status = 'RESPONSE_RECEIVED'
      item.lastCheckpoint = 'response'
      return ''
    })
  }

  markVerified(executionId: string, leaseVersion: number, easyMailId = ''): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (!item.requestSent || (item.status !== 'RESPONSE_RECEIVED' && item.status !== 'UNKNOWN')) return '没有可核验的响应。'
      item.status = 'VERIFIED'
      item.easyMailId = easyMailId || item.easyMailId
      item.lastCheckpoint = 'verified'
      return ''
    })
  }

  complete(executionId: string, leaseVersion: number): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (item.status !== 'VERIFIED') return '只有核验通过的租约可以完成。'
      item.status = 'COMPLETED'
      item.lastCheckpoint = 'completed'
      return ''
    })
  }

  releaseBeforeSend(executionId: string, leaseVersion: number): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (item.requestSent) return '请求已经发出，不能释放。'
      item.status = 'RELEASED'
      item.lastCheckpoint = 'released-before-send'
      return ''
    })
  }

  markUnknown(executionId: string, leaseVersion: number): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.transition(executionId, leaseVersion, item => {
      if (!item.requestSent) return '请求尚未发出，应释放而不是标成未知。'
      item.status = 'UNKNOWN'
      item.lastCheckpoint = 'unknown'
      return ''
    })
  }

  recover(origin: string, operatorId: string): Promise<ExecutionLease[]> {
    return this.store.run(state => {
      const now = new Date().toISOString()
      state.leases = state.leases.map(item => {
        if (item.origin !== origin || item.operatorId !== operatorId) return item
        if (item.status === 'RELEASED' || item.status === 'COMPLETED' || item.status === 'VERIFIED') return item
        if (item.requestSent) return { ...item, status: 'UNKNOWN' as const, lastCheckpoint: 'recovered', leaseVersion: item.leaseVersion + 1, updatedAt: now }
        return { ...item, status: 'RELEASED' as const, lastCheckpoint: 'abandoned-before-send', leaseVersion: item.leaseVersion + 1, updatedAt: now }
      })
      return state.leases.filter(item => item.origin === origin && item.operatorId === operatorId)
    })
  }

  private transition(executionId: string, leaseVersion: number, apply: (lease: ExecutionLease) => string): Promise<{ ok: boolean; lease: ExecutionLease | null; reason: string }> {
    return this.store.run(state => {
      const lease = state.leases.find(item => item.executionId === executionId)
      if (!lease || lease.owner !== this.ownerId || lease.leaseVersion !== leaseVersion) {
        return { ok: false, lease: lease ?? null, reason: '执行所有权已经变化，不能发出请求。' }
      }
      const reason = apply(lease)
      if (reason) return { ok: false, lease, reason }
      lease.leaseVersion += 1
      lease.updatedAt = new Date().toISOString()
      return { ok: true, lease, reason: '' }
    })
  }
}

export function indexedTransactionStore(): TransactionStore | null {
  const factory = globalThis.indexedDB
  if (!factory) return null
  let database: IDBDatabase | null = null
  const open = new Promise<IDBDatabase>((resolve, reject) => {
    const request = factory.open('patmail-execution-ledger', 1)
    request.onupgradeneeded = () => request.result.createObjectStore('state')
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error)
  })
  return {
    async run(work) {
      database ??= await open
      return await new Promise((resolve, reject) => {
        const tx = database!.transaction('state', 'readwrite')
        const store = tx.objectStore('state')
        const current = store.get('leases')
        current.onsuccess = () => {
          const draft: LedgerState = { leases: Array.isArray(current.result) ? current.result.map((item: ExecutionLease) => ({ ...item })) : [] }
          try {
            const result = work(draft)
            store.put(draft.leases, 'leases')
            tx.oncomplete = () => resolve(result)
          } catch (error) {
            tx.abort()
            reject(error)
          }
        }
        current.onerror = () => reject(current.error)
        tx.onerror = () => reject(tx.error)
      })
    }
  }
}

import { emptyIdentity } from './snapshot'
import { preservedEvidence } from './task-transition'
import type { AutomationTask, AutomationTaskState, Checkpoint } from './types'

export interface TaskArea {
  get(key: string): Promise<Record<string, unknown>>
  set(items: Record<string, unknown>): Promise<void>
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const PROTECTED: AutomationTaskState[] = ['RUNNING', 'UNKNOWN', 'PARTIAL_FAILURE']

function keyFor(origin: string, operatorId: string): string {
  return `patmail.automation.task.v2:${origin}:${operatorId}`
}

function isCheckpoint(value: unknown): value is Checkpoint {
  if (!value || typeof value !== 'object') return false
  const item = value as Checkpoint
  return typeof item.stage === 'string' && typeof item.requestSent === 'boolean'
}

export function isProtectedTask(task: AutomationTask): boolean {
  return PROTECTED.includes(task.status) || task.checkpoints.some(item => item.requestSent && !item.verified) ||
    task.items.some(item => item.status === 'UNKNOWN' || item.status === 'RUNNING' || item.status === 'PARTIAL_FAILURE' || item.status === 'BINDING_BLOCKED')
}

export function migrateTask(task: AutomationTask): { task: AutomationTask; migration: { from: string; to: string; at: string } | null } {
  const sent = task.status === 'UNKNOWN' || task.checkpoints.some(item => item.requestSent && item.verified !== true) || task.items.some(item => item.status === 'UNKNOWN')
  const normalized: AutomationTask = {
    ...task,
    customers: task.customers ?? [],
    identitySnapshot: task.identitySnapshot ?? [],
    legacyTaskId: task.legacyTaskId ?? '',
    archived: task.archived === true,
    readonly: task.readonly === true || sent,
    verifiedAt: task.verifiedAt ?? '',
    checkpoints: task.checkpoints.map(item => ({
      stage: item.stage, itemId: item.itemId ?? '', requestSent: item.requestSent,
      responseReceived: item.responseReceived === true, verified: item.verified === true,
      easyMailId: item.easyMailId ?? '', at: item.at ?? '', note: item.note ?? ''
    })),
    status: sent ? 'UNKNOWN' : task.status,
    items: task.items.map(item => ({ ...item, customerIdentity: item.customerIdentity ?? emptyIdentity(), easyMailId: item.easyMailId ?? '' }))
  }
  if (UUID.test(task.taskId)) return { task: normalized, migration: null }
  if (!task.taskId || !Array.isArray(task.items)) {
    return { task: { ...normalized, readonly: true, status: sent ? 'UNKNOWN' : 'BLOCKED' }, migration: null }
  }
  const nextId = globalThis.crypto.randomUUID()
  const at = new Date().toISOString()
  return {
    task: {
      ...normalized,
      taskId: nextId,
      legacyTaskId: task.taskId,
      readonly: sent || normalized.readonly,
      items: task.items.map(item => ({ ...item, taskId: nextId, easyMailId: item.easyMailId ?? '', customerIdentity: item.customerIdentity ?? emptyIdentity() }))
    },
    migration: { from: task.taskId, to: nextId, at }
  }
}

function isTask(value: unknown): value is AutomationTask {
  if (!value || typeof value !== 'object') return false
  const item = value as AutomationTask
  return typeof item.taskId === 'string' && typeof item.operatorId === 'string' && typeof item.origin === 'string' &&
    typeof item.taskFingerprint === 'string' && Array.isArray(item.items) && Array.isArray(item.checkpoints) &&
    item.checkpoints.every(isCheckpoint)
}

export interface StoredTasks {
  tasks: AutomationTask[]
  opaque: unknown[]
  migrations: { from: string; to: string; at: string }[]
  changed: boolean
}

export function readStoredTasks(value: unknown, origin: string, operatorId: string): StoredTasks {
  if (!value || typeof value !== 'object') return { tasks: [], opaque: [], migrations: [], changed: false }
  const record = value as { version?: unknown; tasks?: unknown; migrations?: unknown; cookie?: unknown; authorization?: unknown; password?: unknown }
  if ((record.version !== 1 && record.version !== 2) || !Array.isArray(record.tasks)) return { tasks: [], opaque: [value], migrations: [], changed: false }
  if ('cookie' in record || 'authorization' in record || 'password' in record) return { tasks: [], opaque: [], migrations: [], changed: false }
  const tasks: AutomationTask[] = []
  const opaque: unknown[] = []
  const migrations = Array.isArray(record.migrations) ? record.migrations.filter(item => item && typeof item === 'object') as StoredTasks['migrations'] : []
  let changed = false
  for (const item of record.tasks) {
    if (!isTask(item) || item.origin !== origin || item.operatorId !== operatorId) {
      opaque.push(item)
      continue
    }
    const migrated = migrateTask(item)
    tasks.push(migrated.task)
    if (migrated.migration) {
      changed = true
      migrations.push(migrated.migration)
    }
  }
  return { tasks, opaque, migrations, changed }
}

export function commitTasks(existing: AutomationTask[], incoming: AutomationTask): AutomationTask[] {
  const migrated = existing.map(item => migrateTask(item).task).filter(item => item.taskId !== incoming.taskId &&
    (incoming.legacyTaskId === '' || item.taskId !== incoming.legacyTaskId && item.legacyTaskId !== incoming.legacyTaskId))
  return migrated.concat(migrateTask(incoming).task)
}

export type TaskSaveCode = 'VERSION_CONFLICT' | 'PROTECTED_EVIDENCE' | 'INVALID_TRANSITION'

export type TaskSaveResult =
  | { ok: true; task: AutomationTask; recordVersion: number }
  | { ok: false; code: TaskSaveCode; message: string; current?: AutomationTask }

export interface AtomicTaskResult {
  ok: boolean
  code?: TaskSaveCode
  message: string
  task: AutomationTask | null
  tasks: AutomationTask[]
}

/** 插入可以走 save。已有记录如果会抹掉执行证据，必须返回失败，不能当成保存成功。 */
export function decideTaskSave(prior: AutomationTask | undefined, task: AutomationTask): { write: AutomationTask | null; result: TaskSaveResult } {
  if (!prior) {
    const next = { ...task, recordVersion: task.recordVersion ?? 1 }
    return { write: next, result: { ok: true, task: next, recordVersion: next.recordVersion ?? 1 } }
  }
  const blocked = preservedEvidence(prior, task)
  if (blocked) return { write: null, result: { ok: false, code: 'PROTECTED_EVIDENCE', message: blocked, current: prior } }
  const next: AutomationTask = {
    ...task,
    taskId: prior.taskId,
    origin: prior.origin,
    operatorId: prior.operatorId,
    recordVersion: (prior.recordVersion ?? 1) + 1
  }
  return { write: next, result: { ok: true, task: next, recordVersion: next.recordVersion ?? 1 } }
}

/** 版本检查、执行证据和写入决定在同一次计算里完成，调用方把它放进同一个存储事务。 */
export function applyAtomicTaskUpdate(
  existing: AutomationTask[],
  taskId: string,
  expectedVersion: number,
  transition: (current: AutomationTask) => { ok: true; task: AutomationTask } | { ok: false; message: string }
): AtomicTaskResult {
  const current = existing.find(item => item.taskId === taskId)
  if (!current) return { ok: false, code: 'INVALID_TRANSITION', message: '没有这个任务。', task: null, tasks: existing }
  const version = current.recordVersion ?? 1
  if (version !== expectedVersion) return { ok: false, code: 'VERSION_CONFLICT', message: '任务版本已变化。', task: current, tasks: existing }
  const proposed = transition(current)
  if (!proposed.ok) return { ok: false, code: 'INVALID_TRANSITION', message: proposed.message, task: current, tasks: existing }
  const blocked = preservedEvidence(current, proposed.task)
  if (blocked) return { ok: false, code: 'PROTECTED_EVIDENCE', message: blocked, task: current, tasks: existing }
  const next: AutomationTask = {
    ...proposed.task,
    taskId: current.taskId,
    origin: current.origin,
    operatorId: current.operatorId,
    recordVersion: version + 1
  }
  return { ok: true, message: '', task: next, tasks: commitTasks(existing, next) }
}

export class TaskRepository {
  constructor(private readonly area: TaskArea | null) {}

  async list(origin: string, operatorId: string, includeArchived = false): Promise<AutomationTask[]> {
    const stored = await this.read(origin, operatorId)
    if (stored.changed && this.area) {
      await this.area.set({ [keyFor(origin, operatorId)]: { version: 2, tasks: [...stored.opaque, ...stored.tasks], migrations: stored.migrations } })
    }
    return stored.tasks.filter(item => includeArchived || !item.archived)
  }

  async save(task: AutomationTask): Promise<TaskSaveResult> {
    if (!this.area) return { ok: false, code: 'INVALID_TRANSITION', message: '当前环境没有任务存储。' }
    return enqueueTaskStore(task.origin, task.operatorId, async () => {
      const key = keyFor(task.origin, task.operatorId)
      const stored = await this.read(task.origin, task.operatorId)
      const prior = stored.tasks.find(item => item.taskId === task.taskId)
      const decided = decideTaskSave(prior, task)
      if (decided.write) {
        const tasks = commitTasks(stored.tasks, decided.write)
        await this.area?.set({ [key]: { version: 2, tasks: [...stored.opaque, ...tasks], migrations: stored.migrations } })
      }
      return decided.result
    })
  }

  async updateTaskAtomically(origin: string, operatorId: string, taskId: string, expectedVersion: number, transition: (current: AutomationTask) => { ok: true; task: AutomationTask } | { ok: false; message: string }): Promise<TaskSaveResult> {
    return enqueueTaskStore(origin, operatorId, async () => {
      const stored = await this.read(origin, operatorId)
      const result = applyAtomicTaskUpdate(stored.tasks, taskId, expectedVersion, transition)
      if (result.ok && result.task && this.area) {
        await this.area.set({ [keyFor(origin, operatorId)]: { version: 2, tasks: [...stored.opaque, ...result.tasks], migrations: stored.migrations } })
        return { ok: true as const, task: result.task, recordVersion: result.task.recordVersion ?? 1 }
      }
      return { ok: false as const, code: result.code ?? 'INVALID_TRANSITION', message: result.message, current: result.task ?? undefined }
    })
  }

  async archive(origin: string, operatorId: string, taskId: string): Promise<{ ok: boolean; message: string }> {
    const stored = await this.read(origin, operatorId)
    const task = stored.tasks.find(item => item.taskId === taskId)
    if (!task) return { ok: false, message: '没有这个任务。' }
    if (isProtectedTask(task)) return { ok: false, message: '结果未知或尚未结束的任务不能归档。' }
    await this.save({ ...task, archived: true })
    return { ok: true, message: '' }
  }

  private async read(origin: string, operatorId: string): Promise<StoredTasks> {
    if (!this.area) return { tasks: [], opaque: [], migrations: [], changed: false }
    const key = keyFor(origin, operatorId)
    const legacy = `patmail.automation.task.v1:${origin}:${operatorId}`
    const stored = await this.area.get(key)
    const current = readStoredTasks(stored[key], origin, operatorId)
    if (current.tasks.length > 0 || current.opaque.length > 0) return current
    const old = await this.area.get(legacy)
    return readStoredTasks(old[legacy], origin, operatorId)
  }
}

export class MemoryTaskRepository extends TaskRepository {
  readonly tasks: AutomationTask[] = []
  readonly opaque: unknown[] = []
  constructor() { super(null) }
  override async list(origin: string, operatorId: string, includeArchived = false): Promise<AutomationTask[]> {
    return this.tasks.filter(item => item.origin === origin && item.operatorId === operatorId && (includeArchived || !item.archived))
  }
  override async save(task: AutomationTask): Promise<TaskSaveResult> {
    const scoped = this.tasks.filter(item => item.origin === task.origin && item.operatorId === task.operatorId)
    const prior = scoped.find(item => item.taskId === task.taskId)
    const decided = decideTaskSave(prior, task)
    if (decided.write) {
      const next = commitTasks(scoped, decided.write)
      const others = this.tasks.filter(item => item.origin !== task.origin || item.operatorId !== task.operatorId)
      this.tasks.splice(0, this.tasks.length, ...others, ...next)
    }
    return decided.result
  }
  override async updateTaskAtomically(origin: string, operatorId: string, taskId: string, expectedVersion: number, transition: (current: AutomationTask) => { ok: true; task: AutomationTask } | { ok: false; message: string }): Promise<TaskSaveResult> {
    const scoped = this.tasks.filter(item => item.origin === origin && item.operatorId === operatorId)
    const result = applyAtomicTaskUpdate(scoped, taskId, expectedVersion, transition)
    if (result.ok && result.task) {
      const others = this.tasks.filter(item => item.origin !== origin || item.operatorId !== operatorId)
      this.tasks.splice(0, this.tasks.length, ...others, ...result.tasks)
      return { ok: true, task: result.task, recordVersion: result.task.recordVersion ?? 1 }
    }
    return { ok: false, code: result.code ?? 'INVALID_TRANSITION', message: result.message, current: result.task ?? undefined }
  }
  override async archive(origin: string, operatorId: string, taskId: string): Promise<{ ok: boolean; message: string }> {
    const task = this.tasks.find(item => item.origin === origin && item.operatorId === operatorId && item.taskId === taskId)
    if (!task) return { ok: false, message: '没有这个任务。' }
    if (isProtectedTask(task)) return { ok: false, message: '结果未知或尚未结束的任务不能归档。' }
    task.archived = true
    return { ok: true, message: '' }
  }
}

const taskQueues = new Map<string, Promise<unknown>>()

/** 同一进程内串行化 chrome.storage 任务写入。这不是跨进程事务。 */
function enqueueTaskStore<T>(origin: string, operatorId: string, work: () => Promise<T>): Promise<T> {
  const key = keyFor(origin, operatorId)
  const previous = taskQueues.get(key) ?? Promise.resolve()
  const run = previous.then(work, work)
  taskQueues.set(key, run.then(() => undefined, () => undefined))
  return run
}

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
])

function rotr(value: number, bits: number): number {
  return (value >>> bits) | (value << (32 - bits))
}

/** 同步 SHA-256。扩展页面和测试都能用，不把异步 Web Crypto 放进任务构建。 */
export function sha256Hex(text: string): string {
  const data = new TextEncoder().encode(text)
  const bitLength = data.length * 8
  const withPad = new Uint8Array(((data.length + 9 + 63) >> 6) << 6)
  withPad.set(data)
  withPad[data.length] = 0x80
  const view = new DataView(withPad.buffer)
  view.setUint32(withPad.length - 4, bitLength, false)
  const words = new Uint32Array(64)
  let a0 = 0x6a09e667, b0 = 0xbb67ae85, c0 = 0x3c6ef372, d0 = 0xa54ff53a
  let e0 = 0x510e527f, f0 = 0x9b05688c, g0 = 0x1f83d9ab, h0 = 0x5be0cd19
  for (let offset = 0; offset < withPad.length; offset += 64) {
    for (let index = 0; index < 16; index += 1) words[index] = view.getUint32(offset + index * 4, false)
    for (let index = 16; index < 64; index += 1) {
      const s0 = rotr(words[index - 15]!, 7) ^ rotr(words[index - 15]!, 18) ^ (words[index - 15]! >>> 3)
      const s1 = rotr(words[index - 2]!, 17) ^ rotr(words[index - 2]!, 19) ^ (words[index - 2]! >>> 10)
      words[index] = (words[index - 16]! + s0 + words[index - 7]! + s1) >>> 0
    }
    let a = a0, b = b0, c = c0, d = d0, e = e0, f = f0, g = g0, h = h0
    for (let index = 0; index < 64; index += 1) {
      const s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)
      const choice = (e & f) ^ (~e & g)
      const temp1 = (h + s1 + choice + K[index]! + words[index]!) >>> 0
      const s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)
      const majority = (a & b) ^ (a & c) ^ (b & c)
      const temp2 = (s0 + majority) >>> 0
      h = g; g = f; f = e; e = (d + temp1) >>> 0; d = c; c = b; b = a; a = (temp1 + temp2) >>> 0
    }
    a0 = (a0 + a) >>> 0; b0 = (b0 + b) >>> 0; c0 = (c0 + c) >>> 0; d0 = (d0 + d) >>> 0
    e0 = (e0 + e) >>> 0; f0 = (f0 + f) >>> 0; g0 = (g0 + g) >>> 0; h0 = (h0 + h) >>> 0
  }
  return [a0, b0, c0, d0, e0, f0, g0, h0].map(word => word.toString(16).padStart(8, '0')).join('')
}

