const streamDownloads = new LocalStreamDownloads(chrome.downloads)
let legacyStreamsUsed = false
const nativeTarget = createNativeDownloadTarget({ openNavigation: (url, request) => new Promise<void>((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error('下载工作台没有响应，缓存仍保留。')), 15_000)
  chrome.runtime.sendMessage({ channel: NATIVE_NAVIGATION_CHANNEL, url, taskId: request.taskId, targetId: request.targetId, owner: request.owner }, (response: BrowserFileReply | undefined) => {
    clearTimeout(timer)
    const error = chrome.runtime.lastError?.message
    if (error || !response || !response.ok) reject(new Error(response && !response.ok ? response.error : '请保持下载工作台打开，再继续下载。'))
    else resolve()
  })
}) })
const workerScope = globalThis as unknown as {
  clients: { claim(): Promise<void> }
  addEventListener(type: 'fetch', listener: (event: NativeFetchEvent) => void): void
  addEventListener(type: 'activate', listener: (event: { waitUntil(promise: Promise<void>): void }) => void): void
}
workerScope.addEventListener('fetch', event => { nativeTarget.handleFetch(event) })
workerScope.addEventListener('activate', event => { event.waitUntil(workerScope.clients.claim()) })
const browserDownloads = new BrowserStreamDownloads(createBrowserDownloadStore(), nativeTarget.host, nativeTarget.status)

watchWriteSwitch()
// 扩展 Service Worker 不能用顶层 await，否则 Chrome 直接拒绝启动，工具栏点击没有监听。
void hydrateWriteSwitch()
void hydrateCustomerMode()
void prepareApiDocs()

const CALL_CHANNEL = 'patmail-call'
const RESULT_CHANNEL = 'patmail-result'

const ownerId = globalThis.crypto.randomUUID()
const transactions = indexedTransactionStore()
const ledger = transactions ? new ExecutionLedger(transactions, ownerId) : null
const tasks = globalThis.indexedDB ? new IndexedTaskStore(globalThis.indexedDB) : null
const evidence = globalThis.indexedDB ? new IndexedEvidenceStore(globalThis.indexedDB) : new MemoryEvidenceStore()
const connection = new EasyConnectionController()
const CONNECTION_SNAPSHOT = 'patmail.connection.snapshot.v1'
let persistedSnapshot: ConnectionSnapshot | null = null

function persistConnection(): void {
  const next = connection.snapshot()
  if (sameConnectionSnapshot(persistedSnapshot, next)) return
  persistedSnapshot = next
  void chrome.storage.local.set({ [CONNECTION_SNAPSHOT]: next })
  if (connection.context.sessionStatus === 'authenticated' && connection.context.operatorId) {
    const owner = JSON.stringify([connection.context.easyOrigin, connection.context.operatorId])
    browserDownloads.revokeOtherOwners(owner)
    if (legacyStreamsUsed) streamDownloads.revokeOtherOwners(owner)
  } else if (['expired', 'unauthenticated'].includes(connection.context.sessionStatus)) {
    browserDownloads.revokeOtherOwners('')
    if (legacyStreamsUsed) streamDownloads.revokeOtherOwners('')
  }
}

let warming: Promise<void> | null = null
let warmedAt = 0

const reinjected = new Set<number>()

async function sendToTab(tabId: number, message: AppMessage): Promise<unknown> {
  try {
    return await chrome.tabs.sendMessage(tabId, message)
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    if (reinjected.has(tabId) || !/Receiving end does not exist|Could not establish connection/i.test(text) || !chrome.scripting?.executeScript) throw error
    reinjected.add(tabId)
    await chrome.scripting.executeScript({ target: { tabId }, files: ['content.js'] })
    return chrome.tabs.sendMessage(tabId, message)
  }
}

const host: WorkspaceHost = {
  connection,
  area: chrome.storage.local as unknown as WorkspaceHost['area'],
  tasks,
  evidence,
  queryTabs: () => chrome.tabs.query({}),
  getTab: (tabId) => chrome.tabs.get(tabId),
  createTab: async (url) => { await chrome.tabs.create({ url, active: true }) },
  focusTab: async (tabId, windowId) => {
    await chrome.tabs.update(tabId, { active: true })
    if (windowId != null) await chrome.windows.update(windowId, { focused: true })
  },
  openApp: async () => {
    const appUrl = chrome.runtime.getURL('app.html')
    const tabs = await chrome.tabs.query({})
    return openWorkspaceTab(tabs, appUrl, host.focusTab, async () => {
      const created = await chrome.tabs.create({ url: appUrl, active: true })
      if (created.id == null) throw new Error('没有打开工作台。')
      return created.id
    })
  },
  sendToTab,
  persist: persistConnection
}

function alignToMode(): void {
  connection.retarget(modeOrigin(customerMode()))
  const tabId = connection.context.easyTabId
  if (tabId != null && !originMatchesMode(connection.context.easyOrigin)) connection.detach(tabId)
}

function warmEasySession(): Promise<void> {
  if (warming) return warming
  if (connection.context.sessionStatus === 'authenticated' && Date.now() - warmedAt < 1500) return Promise.resolve()
  warming = resumeEasySession(host).finally(() => {
    warming = null
    warmedAt = Date.now()
  })
  return warming
}

/** 先把上次的标签页捡回来，再向页面重读登录。这条完成前不回答工作台，避免把空连接当成没登录。 */
const connectionReady = (async () => {
  try {
    await hydrateCustomerMode()
    const stored = await chrome.storage.local.get(CONNECTION_SNAPSHOT)
    connection.restoreCandidate(stored[CONNECTION_SNAPSHOT])
    alignToMode()
    persistedSnapshot = connection.snapshot()
  } catch { /* 没有存过连接 */ }
  await warmEasySession()
})()

chrome.tabs.onRemoved.addListener((tabId) => {
  streamDownloads.cancelTab(tabId)
  browserDownloads.cancelTab(tabId)
  reinjected.delete(tabId)
  connection.detach(tabId)
  persistConnection()
})
// tabs.loading也会因EASY内部mframe加载而出现；只有真正顶层导航才销毁来源文档。
chrome.webNavigation?.onBeforeNavigate.addListener(({ tabId, frameId }) => {
  if (frameId === 0) { streamDownloads.cancelTab(tabId); browserDownloads.cancelTab(tabId) }
})
let sessionReadTimer: ReturnType<typeof setTimeout> | undefined

function scheduleSessionRead(tabId: number): void {
  if (sessionReadTimer != null) clearTimeout(sessionReadTimer)
  sessionReadTimer = setTimeout(() => {
    sessionReadTimer = undefined
    if (connection.context.easyTabId !== tabId || connection.context.sessionStatus === 'authenticated') return
    void recheckBoundSession(host).finally(() => persistConnection())
  }, 400)
}

chrome.tabs.onUpdated.addListener((tabId, info, tab) => {
  if (info.url || info.status === 'loading') {
    connection.observeNavigation(tabId, info.url ?? tab.url)
    if (connection.context.easyTabId === tabId && !originMatchesMode(connection.context.easyOrigin)) {
      connection.detach(tabId)
      connection.context = { ...connection.context, message: '这个页面不属于当前客户系统。' }
    }
    persistConnection()
  }
  if (connection.context.easyTabId === tabId && connection.context.sessionStatus === 'pending') {
    scheduleSessionRead(tabId)
  }
  const opened = tabOrigin(info.url ?? tab.url)
  if (opened && originMatchesMode(opened) && connection.context.sessionStatus !== 'authenticated') {
    void warmEasySession()
  }
})
watchCustomerMode(() => {
  alignToMode()
  persistConnection()
  void warmEasySession()
})
chrome.action.onClicked.addListener(() => { void host.openApp() })

function fromExtensionPage(sender: chrome.runtime.MessageSender): boolean {
  return typeof sender.url === 'string' && sender.url.startsWith(chrome.runtime.getURL(''))
}

const WRITES = new Set<string>([
  MessageType.SaveTask, MessageType.ClaimExecution, MessageType.MarkExecutionPrepared,
  MessageType.MarkExecutionSent, MessageType.MarkExecutionResponse, MessageType.MarkExecutionVerified,
  MessageType.CompleteExecution, MessageType.ReleaseExecution, MessageType.MarkExecutionUnknown,
  MessageType.ArchiveTask
])
const READS = new Set<string>([
  MessageType.ListTasks, MessageType.GetTask, MessageType.ListAcceptance,
  MessageType.ValidateTaskMetadata, MessageType.RecoverExecution
])

/** 页面和后台用长连接。查询过程中还会调用 EASY 页面，不能占用一次性消息口。 */
async function dispatchExtensionMessage(message: unknown, sender: chrome.runtime.MessageSender): Promise<BackgroundResponse> {
  await connectionReady
  prepareForwardedSearch(message)
  if (!isMessage(message)) {
    const type = message && typeof message === 'object' && 'type' in message ? String((message as { type?: unknown }).type) : '未知'
    const inner = message && typeof message === 'object' && 'payload' in message
      && (message as { payload?: { action?: unknown; message?: { type?: unknown } } }).payload?.action === 'forward'
      ? String((message as { payload?: { message?: { type?: unknown } } }).payload?.message?.type ?? '')
      : ''
    const envelope = isRecord(message) && isRecord(message.payload) ? message.payload : undefined
    const downloadPayload = type === MessageType.DownloadFiles ? envelope
      : inner === MessageType.DownloadFiles && isRecord(envelope?.message) ? envelope.message.payload : undefined
    if (type === MessageType.DownloadFiles || inner === MessageType.DownloadFiles) {
      const issue = downloadFilesRequestIssue(downloadPayload)
      if (issue) return { type: MessageType.Error, payload: { message: `下载尚未启动：${issue}` } }
    }
    return { type: MessageType.Error, payload: { message: `后台没有接住${inner ? `转发 ${inner}` : type}。请在扩展管理页重新加载后再试。` } }
  }
  if (message.type === MessageType.Ping) {
    if (connection.context.sessionStatus !== 'authenticated') void warmEasySession()
    return { type: MessageType.Pong, payload: { ok: true } }
  }
  if (message.type === MessageType.AgentChat) {
    const pageUrl = sender.url ?? sender.tab?.url ?? ''
    if (!pageUrl.startsWith(chrome.runtime.getURL(''))) {
      return { type: MessageType.Error, payload: { message: '只有工作台页面可以调用 AI 助手。' } }
    }
    return { type: MessageType.AgentChatResult, payload: await handleAgentChat(message.payload, host) }
  }
  if (message.type === MessageType.RunReadonlyAcceptance) {
    return { type: MessageType.Error, payload: { message: '后台没有处理这条消息。' } }
  }
  if (message.type === MessageType.Workspace) {
    try {
      return await handleWorkspaceMessage(message, host)
    } catch (error: unknown) {
      return { type: MessageType.Error, payload: { message: error instanceof Error ? error.message : '后台没有完成转发。' } }
    }
  }
  /** 打包下载的压缩包由浏览器直接落盘：走 chrome.downloads 才会在下载记录里留下条目，文件名也听插件的。 */
  if (message.type === MessageType.SaveDownload) {
    const downloads = chrome.downloads
    if (!downloads?.download) {
      return { type: MessageType.Error, payload: { message: '扩展缺「下载」权限：到 chrome://extensions 给 PatMail 点一次「重新加载」后再试。' } }
    }
    try {
      const downloadId = await downloads.download({ url: message.payload.url, filename: message.payload.fileName, saveAs: false })
      return { type: MessageType.SaveDownloadResult, payload: { ok: true, fileName: message.payload.fileName, downloadId } }
    } catch (error: unknown) {
      return { type: MessageType.Error, payload: { message: error instanceof Error ? error.message : '浏览器没有接住这次下载。' } }
    }
  }
  if (message.type === MessageType.StreamDownload || message.type === MessageType.BrowserStreamDownload) {
    const tabId = sender.tab?.id
    if (tabId === undefined || !trustedOrigin(sender.url ?? sender.tab?.url ?? '')) {
      return { type: MessageType.Error, payload: { message: '只有已连接的EASY来源页可以写入下载流。' } }
    }
    try {
      if (message.payload.action === 'start') {
        await connectionReady
        await recheckBoundSession(host)
        if (connection.context.easyTabId !== tabId || connection.context.sessionStatus !== 'authenticated' || !connection.context.operatorId) {
          return { type: MessageType.Error, payload: { message: '请先重新确认同一EASY账号，再继续下载。' } }
        }
      }
      if (message.type === MessageType.StreamDownload) legacyStreamsUsed = true
      const downloads = message.type === MessageType.BrowserStreamDownload ? browserDownloads : streamDownloads
      return { type: MessageType.StreamDownloadResult, payload: await downloads.command(message.payload, tabId,
        JSON.stringify([connection.context.easyOrigin, connection.context.operatorId])) }
    } catch (error) {
      return { type: MessageType.Error, payload: { message: error instanceof Error ? error.message : '下载流桥接失败。' } }
    }
  }
  if (message.type === MessageType.DiscardDownload) {
    await connectionReady
    const contentOwner = sender.tab?.id === connection.context.easyTabId && trustedOrigin(sender.url ?? '') === connection.context.easyOrigin
    if ((!fromExtensionPage(sender) && !contentOwner) || connection.context.sessionStatus !== 'authenticated' || !connection.context.operatorId) {
      return { type: MessageType.Error, payload: { message: '请先连接原任务的EASY账号，再丢弃下载。' } }
    }
    const downloads = message.payload.backend === 'browser' ? browserDownloads : streamDownloads
    await downloads.discardTask(message.payload.taskId, JSON.stringify([connection.context.easyOrigin, connection.context.operatorId]))
    return { type: MessageType.DiscardDownloadResult, payload: { ok: true } }
  }
  if (message.type === MessageType.PauseDownload) {
    await connectionReady
    const context = connection.context
    const contentOwner = sender.tab?.id === context.easyTabId && trustedOrigin(sender.url ?? '') === context.easyOrigin
    const owner = context.operatorId || context.lastOperatorId
    if ((!fromExtensionPage(sender) && !contentOwner) || !owner) return { type: MessageType.Error, payload: { message: '下载任务账号范围无法确认。' } }
    const downloads = message.payload.backend === 'browser' ? browserDownloads : streamDownloads
    const tabs = await downloads.pauseTask(message.payload.taskId, JSON.stringify([context.easyOrigin, owner]))
    if (context.easyTabId != null) tabs.push(context.easyTabId)
    await Promise.all([...new Set(tabs)].map(id => chrome.tabs.sendMessage(id, message).catch(() => {})))
    return { type: MessageType.PauseDownloadResult, payload: { ok: true } }
  }
  /** 浏览器下载进度由内容脚本回读：后台只做一次状态查询，下载再多分钟也不占后台定时器。 */
  if (message.type === MessageType.DownloadState) {
    const downloads = chrome.downloads
    if (!downloads?.search) {
      return { type: MessageType.Error, payload: { message: '扩展缺「下载」权限，读不到下载状态。' } }
    }
    try {
      const items = await downloads.search({ id: message.payload.downloadId })
      const item = items[0]
      // 任务已经不在下载记录里（被清掉或还没建出来）：明确报错，让调用方按读不到处理，不能假装还在传。
      if (!item) return { type: MessageType.Error, payload: { message: '没有在浏览器下载记录里找到这个任务。' } }
      const receivedBytes = Number.isSafeInteger(item.bytesReceived) && item.bytesReceived >= 0 ? item.bytesReceived : 0
      const totalBytes = Number.isSafeInteger(item.totalBytes) && item.totalBytes > 0 ? item.totalBytes : null
      const state = item.state === 'complete' ? 'complete' : item.state === 'interrupted' ? 'interrupted' : 'inProgress'
      return {
        type: MessageType.DownloadStateResult,
        payload: { ok: true, state, receivedBytes, totalBytes, ...(item.error ? { error: String(item.error).slice(0, 200) } : {}) }
      }
    } catch (error: unknown) {
      return { type: MessageType.Error, payload: { message: error instanceof Error ? error.message : '浏览器没有回报下载状态。' } }
    }
  }
  let scoped: AppMessage = message
  const accountScoped = WRITES.has(message.type) || READS.has(message.type)
  if (accountScoped || fromExtensionPage(sender)) {
    if (accountScoped) {
      const gate = await recheckBoundSession(host)
      if (WRITES.has(message.type) && gate !== 'same') {
        return { type: MessageType.Error, payload: { message: '会话已变化，请重新读取后再保存。' } }
      }
    }
    const next = scopeExtensionPageMessage(message, connection.context)
    if ('error' in next) return { type: MessageType.Error, payload: { message: next.error } }
    scoped = next
  }
  const response = await handleAuthorityMessage(scoped, {
    ledger,
    tasks,
    evidence,
    account: {
      easyOrigin: connection.context.easyOrigin,
      operatorId: connection.context.operatorId,
      ...(connection.context.easyTabId == null ? {} : { easyTabId: connection.context.easyTabId, connectionVersion: connection.context.connectionVersion })
    }
  })
  return response ?? { type: MessageType.Error, payload: { message: '后台没有处理这条消息。' } }
}

function publish(response: BackgroundResponse, requestId: string | null, sendResponse: (value: BackgroundResponse) => void): void {
  try { sendResponse(response) } catch { /* 原来的消息口已经关掉 */ }
  if (!requestId) return
  try {
    chrome.runtime.sendMessage({ channel: RESULT_CHANNEL, id: requestId, body: response }, () => {
      void chrome.runtime.lastError
    })
  } catch { /* 页面已经离开 */ }
}

/** 每 20 秒碰一次扩展接口，空闲计时就不会到 30 秒。知易通或工作台还开着时，后台不会被睡过去。 */
const HEARTBEAT_MS = 20_000
function beat(): void {
  void chrome.runtime.getPlatformInfo()
}
beat()
setInterval(beat, HEARTBEAT_MS)
if (chrome.alarms) {
  chrome.alarms.onAlarm.addListener(alarm => {
    if (alarm.name !== 'patmail-keepalive') return
    beat()
    if (connection.context.sessionStatus === 'authenticated') void recheckBoundSession(host).finally(() => persistConnection())
    else void warmEasySession()
  })
  const created = chrome.alarms.create('patmail-keepalive', { periodInMinutes: 0.5 })
  void Promise.resolve(created).catch(() => {
    void chrome.alarms.create('patmail-keepalive', { periodInMinutes: 1 })
  })
}

/** 工作台停靠栏连着这条端口时，服务工作线程不会在等模型的空档里被回收。 */
let agentPorts = 0
chrome.runtime.onConnect.addListener(port => {
  if (port.sender?.id !== chrome.runtime.id) {
    port.disconnect()
    return
  }
  if (port.name === 'patmail-page') {
    port.onMessage.addListener(() => { /* 页面心跳，重置空闲计时 */ })
    void connectionReady.then(() => warmEasySession())
    port.onDisconnect.addListener(() => { void chrome.runtime.lastError })
    return
  }
  if (port.name !== 'patmail-agent') {
    port.disconnect()
    return
  }
  agentPorts += 1
  port.onMessage.addListener(() => { /* 停靠栏心跳 */ })
  port.onDisconnect.addListener(() => {
    agentPorts = Math.max(0, agentPorts - 1)
    if (agentPorts === 0) deliverAgentAnswer('跳过')
    void chrome.runtime.lastError
  })
})

/** MV3 Service Worker 是租约、任务和证据的唯一写入方。 */
chrome.runtime.onMessage.addListener((message: unknown, sender, sendResponse) => {
  if (isRecord(message) && (message.channel === BROWSER_FILE_CHANNEL || message.channel === NATIVE_NAVIGATION_CHANNEL)) return
  if (handleRecoveryMessage(message, sender, sendResponse, connection.context)) return true
  if (sender.id !== chrome.runtime.id) return
  if (isRecord(message) && message.channel === RESULT_CHANNEL) return
  if (isRecord(message) && message.channel === DOWNLOAD_PROGRESS_CHANNEL) return
  if (isRecord(message) && message.channel === DOWNLOAD_RESULT_CHANNEL) return
  const requestId = isRecord(message) && message.channel === CALL_CHANNEL && typeof message.id === 'string' && message.id.length > 0 && message.id.length <= 80
    ? message.id : null
  const payload = requestId && isRecord(message) ? message.message : message
  void dispatchExtensionMessage(payload, sender).then(
    response => publish(response, requestId, sendResponse),
    (error: unknown) => publish({
      type: MessageType.Error,
      payload: { message: error instanceof Error ? error.message : '后台没有完成。' }
    }, requestId, sendResponse)
  )
  return true
})

import { BROWSER_FILE_CHANNEL, type BrowserFileReply, type BrowserFileRequest } from '../browser-download/types'

export interface NativeDownloadItem { id: number; url: string; state: string; paused?: boolean; error?: string; bytesReceived?: number; totalBytes?: number }
export interface NativeDownloadChange { id: number; state?: { current?: string }; paused?: { current?: boolean }; error?: { current?: string } }
interface DownloadApi {
  search(query: { url: string }): Promise<NativeDownloadItem[]>
  cancel(id: number): Promise<void>
  onChanged: { addListener(listener: (change: NativeDownloadChange) => void): void; removeListener(listener: (change: NativeDownloadChange) => void): void }
}
export interface NativeDownloadTargetOptions {
  openNavigation(url: string, request: BrowserFileRequest): Promise<void>
  resolveFileName?(request: BrowserFileRequest): string | Promise<string>
  getURL?(path: string): string
  downloads?: DownloadApi
  attachTimeoutMs?: number
  finishTimeoutMs?: number
  pollIntervalMs?: number
}
export interface NativeFetchEvent { request: Request; respondWith(response: Response | Promise<Response>): void }
function deferred<T>() {
  let resolve!: (value: T) => void, reject!: (error: Error) => void
  const promise = new Promise<T>((yes, no) => { resolve = yes; reject = no })
  // Attach/complete may fail before their corresponding host request starts waiting.
  void promise.catch(() => {})
  return { promise, resolve, reject }
}
type Deferred = ReturnType<typeof deferred<void>>
interface Session {
  request: BrowserFileRequest; url: string; fileName: string; cursor: number
  stream: ReadableStream<Uint8Array>; controller: ReadableStreamDefaultController<Uint8Array>
  attached: Deferred; completed: Deferred; demand?: Deferred
  pending?: { bytes: Uint8Array; ack: Deferred }
  error?: Error; closing: boolean; done: boolean; claimed: boolean; downloadId?: number
  timer?: ReturnType<typeof setInterval>; attachTimer?: ReturnType<typeof setTimeout>
  listener: (change: NativeDownloadChange) => void
  cancellation?: Promise<void>
}

/** A navigation, unlike downloads.download(extensionURL), passes through the MV3 fetch handler. */
export function createNativeDownloadTarget(options: NativeDownloadTargetOptions) {
  const getURL = options.getURL ?? (path => chrome.runtime.getURL(path))
  const downloads = options.downloads ?? chrome.downloads
  const prefix = getURL('_patmail_native_download/')
  const sessions = new Map<string, Session>(), capabilities = new Map<string, Session>()
  const errorOf = (value: unknown) => value instanceof Error ? value : new Error(String(value))
  function cleanup(s: Session) {
    clearInterval(s.timer); clearTimeout(s.attachTimer)
    downloads.onChanged.removeListener(s.listener); capabilities.delete(s.url)
  }
  function cancelNative(s: Session): Promise<void> {
    return s.cancellation ??= (async () => {
      if (s.downloadId === undefined) {
        const item = (await downloads.search({ url: s.url })).find(item => item.url === s.url)
        if (item) s.downloadId = item.id
      }
      if (s.downloadId !== undefined) await downloads.cancel(s.downloadId)
    })()
  }
  function fail(s: Session, reason: unknown, cancel = true) {
    if (s.done || s.error) return
    s.error = errorOf(reason); cleanup(s)
    s.attached.reject(s.error); s.completed.reject(s.error)
    s.pending?.ack.reject(s.error); s.pending = undefined
    s.demand?.reject(s.error); s.demand = undefined
    try { s.controller.error(s.error) } catch { /* consumer may have already cancelled */ }
    if (cancel) void cancelNative(s).catch(() => {})
  }
  function status(s: Session, item: Pick<NativeDownloadItem, 'state' | 'paused' | 'error'>) {
    if (s.error || s.done) return
    if (item.paused || item.state === 'interrupted' || item.error) {
      fail(s, new Error('Chrome 下载已暂停或取消，缓存已保留，请在插件中继续。')); return
    }
    if (item.state === 'complete') {
      if (!s.closing) { fail(s, new Error('Chrome 下载提前结束，缓存仍保留。')); return }
      s.done = true; cleanup(s); s.completed.resolve()
    }
  }
  function watch(s: Session) {
    let polling = false
    const poll = async () => {
      if (polling || s.done || s.error) return
      polling = true
      try {
        const item = (await downloads.search({ url: s.url })).find(item => item.url === s.url)
        if (item) { s.downloadId = item.id; status(s, item) }
      } catch (error) { fail(s, error) }
      finally { polling = false }
    }
    downloads.onChanged.addListener(s.listener)
    s.timer = setInterval(() => { void poll() }, options.pollIntervalMs ?? 250)
    void poll()
  }
  function pump(s: Session) {
    if (!s.pending || !s.demand || s.error) return
    const pending = s.pending, demand = s.demand
    s.pending = undefined; s.demand = undefined
    s.controller.enqueue(pending.bytes); s.cursor += pending.bytes.byteLength
    pending.ack.resolve(); demand.resolve()
  }
  async function open(request: BrowserFileRequest) {
    const previous = sessions.get(request.targetId)
    if (previous) {
      if (previous.request.taskId !== request.taskId || previous.request.owner !== request.owner) throw new Error('下载目标不属于当前任务或账号。')
      if (!previous.done) { fail(previous, new Error('下载目标已重新打开。')); await cancelNative(previous) }
    }
    const fileName = options.resolveFileName ? await options.resolveFileName(request) : request.fileName ?? 'PatMail.zip'
    const url = prefix + crypto.randomUUID() + '/' + crypto.randomUUID() + '.zip'
    const s = { request: { ...request }, url, fileName, cursor: 0, attached: deferred<void>(), completed: deferred<void>(),
      closing: false, done: false, claimed: false, listener: (_change: NativeDownloadChange) => {} } as Session
    s.stream = new ReadableStream<Uint8Array>({
      start(controller) { s.controller = controller },
      pull() { s.demand = deferred<void>(); const waiting = s.demand.promise; pump(s); return waiting },
      cancel(reason) { fail(s, new Error('Chrome 下载接收端已关闭，缓存仍保留：' + String(reason ?? '取消'))); return cancelNative(s) }
    }, { highWaterMark: 0 })
    s.listener = change => {
      if (change.id !== s.downloadId) return
      if (change.paused?.current || change.state?.current === 'interrupted' || change.error?.current) status(s, { state: 'interrupted', paused: change.paused?.current })
      else if (change.state?.current === 'complete') status(s, { state: 'complete' })
    }
    sessions.set(request.targetId, s); capabilities.set(url, s)
    s.attachTimer = setTimeout(() => fail(s, new Error('Chrome 下载导航未连接，请保持工作台打开后重试。')), options.attachTimeoutMs ?? 15000)
    // The workbench may disappear without answering its runtime message. The attach
    // deadline must still release the producer in that case.
    void Promise.resolve().then(() => options.openNavigation(url, request)).catch(error => fail(s, error))
    try { await s.attached.promise }
    catch (error) { fail(s, error); throw error }
  }
  async function operate(request: BrowserFileRequest): Promise<void> {
    if (request.channel !== BROWSER_FILE_CHANNEL || !request.taskId || !request.targetId || !request.owner) throw new Error('下载目标请求无效。')
    if (request.action === 'open') return open(request)
    const s = sessions.get(request.targetId)
    if (!s) {
      if (request.action === 'pause') return
      throw new Error('原生下载目标已离开，请在插件中继续。')
    }
    if (s.request.taskId !== request.taskId || s.request.owner !== request.owner) throw new Error('下载目标不属于当前任务或账号。')
    if (request.action === 'pause') {
      if (s.done) return
      fail(s, new Error('插件下载已暂停，缓存已保留。')); await cancelNative(s); return
    }
    if (s.error) throw s.error
    if (request.action === 'finish') {
      if (!s.closing && !s.done) {
        if (s.pending) throw new Error('ZIP 片段仍在写入，不能完成下载。')
        s.closing = true; s.controller.close(); s.demand?.resolve(); s.demand = undefined
      }
      const timer = setTimeout(() => fail(s, new Error('Chrome 尚未确认文件保存完成，缓存已保留。')), options.finishTimeoutMs ?? 120000)
      try { await s.completed.promise } finally { clearTimeout(timer) }
      return
    }
    if (request.action !== 'write' || s.closing || s.done || s.pending || request.offset !== s.cursor || typeof request.data !== 'string' ||
      request.data.length > 349528 || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(request.data)) throw new Error('原生下载片段的顺序或编码无效。')
    const bytes = Uint8Array.from(atob(request.data), char => char.charCodeAt(0))
    if (bytes.length > 256 * 1024) throw new Error('原生下载片段超过256KiB。')
    if (!bytes.length) return
    s.pending = { bytes, ack: deferred<void>() }; const ack = s.pending.ack.promise
    pump(s); await ack
  }
  return {
    async status(targetId: string): Promise<{ state: 'inProgress' | 'complete'; receivedBytes: number; totalBytes?: number } | undefined> {
      const s = sessions.get(targetId)
      if (!s) return undefined
      if (s.error) throw s.error
      const item = (await downloads.search({ url: s.url })).find(item => item.url === s.url)
      if (item) { s.downloadId = item.id; status(s, item) }
      if (s.error) throw s.error
      return { state: s.done ? 'complete' : 'inProgress', receivedBytes: item?.bytesReceived ?? 0, ...(item?.totalBytes && item.totalBytes > 0 ? { totalBytes: item.totalBytes } : {}) }
    },
    async host(request: BrowserFileRequest): Promise<BrowserFileReply> {
      try { await operate(request); return { ok: true } }
      catch (error) { return { ok: false, error: errorOf(error).message } }
    },
    handleFetch(event: NativeFetchEvent): boolean {
      // Match the full extension URL rather than URL.origin (extension schemes can serialize it as null).
      if (!event.request.url.startsWith(prefix)) return false
      const s = capabilities.get(event.request.url)
      if (!s || s.claimed || s.error || event.request.method !== 'GET' || event.request.mode !== 'navigate') {
        event.respondWith(new Response('Download not found', { status: 404 })); return true
      }
      s.claimed = true; capabilities.delete(s.url); clearTimeout(s.attachTimer)
      const name = s.fileName.replace(/[\r\n\\/\u0000]/g, '_')
      const encoded = encodeURIComponent(name).replace(/['()*]/g, char => '%' + char.charCodeAt(0).toString(16).toUpperCase())
      event.respondWith(new Response(s.stream, { headers: { 'Content-Type': 'application/zip', 'Content-Disposition': `attachment; filename="PatMail.zip"; filename*=UTF-8''${encoded}`, 'Cache-Control': 'no-store' } }))
      watch(s); s.attached.resolve(); return true
    }
  }
}

import type { StreamDownloadCommand } from '../shared/message'
const BASE = 'http://127.0.0.1:42843'
type Downloads = Pick<typeof chrome.downloads, 'download' | 'cancel'> & Partial<Pick<typeof chrome.downloads, 'search' | 'resume'>>
interface Job {
  tabId: number; owner: string; taskId?: string; id?: number; flight: Promise<number | null>
  failure?: string; cancelled: boolean; touched: number; durable: boolean
}
const binaryBytes = (data: string) => Uint8Array.from(atob(data), char => char.charCodeAt(0))
const encodedBytes = (bytes: Uint8Array) => {
  let result = ''
  for (let i = 0; i < bytes.length; i += 8192) result += String.fromCharCode(...bytes.subarray(i, i + 8192))
  return btoa(result)
}
/** 任务URL稳定，写入令牌可轮换；下载中断只暂停，明确丢弃才删除。 */
export class LocalStreamDownloads {
  private readonly jobs = new Map<string, Job>()
  constructor(private readonly downloads: Downloads, private readonly fetcher: typeof fetch = globalThis.fetch.bind(globalThis)) {}
  private async relay(path: string, init?: RequestInit): Promise<Response> {
    const response = await this.fetcher(BASE + path, { ...init, signal: AbortSignal.timeout(init?.method === 'PUT' ? 120_000 : 10_000) })
    if (!response.ok) throw new Error(response.status === 409
      ? '缓存或任务版本不一致，没有继续写入。已保留原任务，请检查后重试。'
      : '本机下载流未就绪或未接收完整（HTTP ' + response.status + '），任务缓存仍保留。')
    return response
  }
  private json(path: string, body: unknown = {}): Promise<Response> {
    return this.relay(path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  }
  private async resume(job: Job): Promise<void> {
    if (job.id === undefined || !this.downloads.search) return
    const item = (await this.downloads.search({ id: job.id }))[0]
    if (!item) throw new Error('原下载记录已被清除。本机缓存仍保留，请从缓存另存为新文件。')
    if (item.state === 'interrupted' || item.paused) {
      if (!item.canResume || !this.downloads.resume) throw new Error('浏览器不支持原记录续传，本机缓存仍保留，请从缓存另存为新文件。')
      await this.downloads.resume(job.id)
    }
  }
  async command(command: StreamDownloadCommand, tabId: number, owner = 'legacy:' + tabId): Promise<{
    ok: true; token?: string; taskId?: string; downloadId?: number; info?: Record<string, unknown>; data?: string
  }> {
    if (command.action === 'start') {
      let data: Record<string, unknown>
      try {
        if (command.manifest || command.taskId) await this.json('/authority', { owner })
        const response = await this.json('/sessions', { fileName: command.fileName, owner,
          ...(command.taskId ? { taskId: command.taskId } : {}), ...(command.manifest ? { manifest: command.manifest } : {}) })
        data = await response.json()
        if (data.protocol !== 'patmail-stream-v1' || typeof data.token !== 'string' || !/^[0-9a-f]{64}$/.test(data.token)) throw new Error('Invalid bridge')
        if ((command.manifest || command.taskId) && data.version !== 2) throw new Error('需要新版续传桥接，请重启 start.py。')
      } catch (error) {
        const detail = error instanceof Error ? error.message : ''
        throw new Error(detail.includes('版本') || detail.includes('缓存') || detail.includes('新版') ? detail
          : '本机流式下载桥接未就绪。请运行仓库 start.py，或 scripts/start-stream-download.ps1 后重试。')
      }
      const token = data.token as string
      const durable = data.version === 2 && typeof data.taskId === 'string'
      const taskId = durable ? data.taskId as string : undefined
      if (data.completed === true) {
        if (command.newCopy) throw new Error('该任务已完成且缓存已清理，请按当前文件新建下载任务。')
        return { ok: true, token, taskId, info: data }
      }
      const url = BASE + (taskId ? '/download/' + taskId : '/stream/' + token)
      let existing: chrome.downloads.DownloadItem | undefined
      if (taskId && this.downloads.search && !command.newCopy) {
        const items = await this.downloads.search({ urlRegex: '^' + url.replace(/[.*+?^$()|[\]\\]/g, '\\$&') + '$' })
        existing = items.sort((a, b) => b.id - a.id)[0]
      }
      for (const [key, prior] of this.jobs) if (taskId && prior.taskId === taskId) this.jobs.delete(key)
      const job: Job = { tabId, owner, taskId, durable, flight: Promise.resolve(existing?.id ?? null),
        id: existing?.id, cancelled: false, touched: Date.now() }
      this.jobs.set(token, job)
      if (!existing) {
        job.flight = this.downloads.download({ url, filename: command.fileName, saveAs: false, conflictAction: 'uniquify' })
          .then(async id => { job.id = id; if (job.cancelled) await this.downloads.cancel(id).catch(() => {}); return id })
          .catch(() => { job.failure = '浏览器未接住下载。本机任务仍保留，请继续下载。'; return null })
      }
      return { ok: true, token, ...(taskId ? { taskId, info: data } : {}), ...(job.id === undefined ? {} : { downloadId: job.id }) }
    }
    const job = this.jobs.get(command.token)
    if (!job || job.tabId !== tabId) throw new Error('下载流不属于当前来源页面。')
    const token = command.token
    if (command.action === 'abort' || command.action === 'complete') {
      if (command.action === 'abort') {
        job.cancelled = true
        if (job.id !== undefined) await this.downloads.cancel(job.id).catch(() => {})
      }
      if (command.action === 'complete' && job.durable) {
        const item = job.id === undefined ? null : (await this.downloads.search?.({ id: job.id }))?.[0]
        if (!item || item.state !== 'complete') throw new Error('浏览器尚未确认完成，缓存没有清理。')
        await this.json('/complete/' + token, { downloadId: job.id })
      } else await this.relay('/stream/' + token, { method: 'DELETE' })
      this.jobs.delete(token)
      return { ok: true }
    }
    if (command.action === 'pause') {
      if (job.durable) await this.json('/pause/' + token)
      else await this.relay('/stream/' + token, { method: 'DELETE' })
      return { ok: true }
    }
    if (command.action === 'cache') {
      const path = '/cache/' + token + '/' + command.index
      if (command.command === 'info') return { ok: true, info: await (await this.json('/cache-info/' + token + '/' + command.index)).json() }
      if (command.command === 'read') {
        const response = await this.json(path, { read: true, offset: command.offset ?? 0, limit: 65536 })
        return { ok: true, data: encodedBytes(new Uint8Array(await response.arrayBuffer())) }
      }
      if (command.command === 'write') {
        await this.relay(path, { method: 'PUT', headers: { 'X-Patmail-Offset': String(command.offset) }, body: binaryBytes(command.data!) })
      } else await this.json(path, { ...command.metadata, [command.command === 'reset' ? 'reset' : 'complete']: true })
      return { ok: true }
    }
    if (command.action === 'checkpoint') {
      await this.json('/manifest/' + token, { offset: command.offset, names: command.names })
      return { ok: true }
    }
    if (command.action === 'write') {
      const bytes = binaryBytes(command.data)
      if (bytes.length > 256 * 1024) throw new Error('下载流块过大。')
      await this.relay('/stream/' + token, { method: 'PUT', headers: {
        'X-Patmail-Sequence': String(command.sequence),
        ...(command.offset === undefined ? {} : { 'X-Patmail-Offset': String(command.offset) })
      }, body: bytes })
    } else if (command.action === 'finish') {
      await this.json('/finish/' + token)
      const id = await job.flight
      if (id === null) throw new Error(job.failure || '浏览器没有返回下载编号；本机缓存已保留。')
      await this.resume(job)
      return { ok: true, downloadId: id }
    } else if (command.action === 'resume') {
      const info = await (await this.json('/status/' + token)).json()
      if (!info.sealed) throw new Error('正在恢复本机压缩包，封存后才能续传到浏览器。')
      await this.resume(job)
    } else if (Date.now() - job.touched > 15_000) {
      await this.json('/touch/' + token); job.touched = Date.now()
    }
    return { ok: true, ...(job.id === undefined ? {} : { downloadId: job.id }) }
  }
  async discardTask(taskId: string, owner: string): Promise<void> {
    const response = await this.fetcher(BASE + '/discard-task/' + taskId, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ owner }), signal: AbortSignal.timeout(10000) })
    if (!response.ok && response.status !== 404) throw new Error('本机下载任务尚未丢弃，请检查连接后重试。')
    for (const [token, job] of this.jobs) if (job.taskId === taskId) {
      if (job.id !== undefined) await this.downloads.cancel(job.id).catch(() => {})
      this.jobs.delete(token)
    }
  }
  async pauseTask(taskId: string, owner: string): Promise<number[]> {
    const tabs: number[] = []
    const response = await this.fetcher(BASE + '/pause-task/' + taskId, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ owner }), signal: AbortSignal.timeout(10000) })
    if (!response.ok && response.status !== 404) throw new Error('下载任务尚未暂停，请重试。')
    for (const [token, job] of this.jobs) if (job.taskId === taskId) { tabs.push(job.tabId); this.jobs.delete(token) }
    return tabs
  }
  cancelTab(tabId: number): void {
    for (const [token, job] of this.jobs) if (job.tabId === tabId) void this.command({ action: 'pause', token }, tabId).catch(() => {})
  }
  revokeOtherOwners(owner: string): void {
    // Python持久任务不随Service Worker的Map重启而消失，撤销必须覆盖整个同源任务登记表。
    void this.json('/authority', { owner }).catch(() => {})
    for (const [token, job] of this.jobs) if (job.owner !== owner) {
      void this.json('/revoke/' + token).catch(() => {})
      this.jobs.delete(token)
    }
  }
}

