export interface WorkspacePayload {
  ok: boolean
  message: string
  connection: EasyConnectionContext
  tabs: EasyTabCandidate[]
  customers: CustomerQueryProfile[]
  templates: QueryTemplate[]
  rules: MailRuleBundle | null
  tasks: { taskId: string; createdAt: string; customerName: string; fileCount: number; mailCount: number; status: string; verifiedAt: string; updatedAt: string }[]
  fileManageRuns: FileManageRun[]
  forwarded: AppMessage | null
  appTab: { tabId: number; created: boolean } | null
  createdTask: CreatedTaskResult | null
  contextError?: 'STALE_CONTEXT'
  rulesSaved?: boolean
  tasksRevalidated?: boolean
  pendingRevalidation?: boolean
}

export function workspaceResult(partial: Partial<WorkspacePayload> & { connection: EasyConnectionContext }): BackgroundResponse {
  const payload: WorkspacePayload = {
    ok: partial.ok ?? false,
    message: partial.message ?? partial.connection.message,
    connection: partial.connection,
    tabs: partial.tabs ?? [],
    customers: partial.customers ?? [],
    templates: partial.templates ?? [],
    rules: partial.rules ?? null,
    tasks: partial.tasks ?? [],
    fileManageRuns: partial.fileManageRuns ?? [],
    forwarded: partial.forwarded ?? null,
    appTab: partial.appTab ?? null,
    createdTask: partial.createdTask ?? null,
    ...(partial.contextError ? { contextError: partial.contextError } : {}),
    ...(partial.rulesSaved !== undefined ? { rulesSaved: partial.rulesSaved, tasksRevalidated: partial.tasksRevalidated, pendingRevalidation: partial.pendingRevalidation } : {})
  }
  return { type: MessageType.WorkspaceResult, payload }
}

export interface WorkspaceHost {
  connection: EasyConnectionController
  area: LocalArea
  tasks: TaskStore | null
  evidence: EvidenceRepository
  queryTabs(): Promise<BrowserTabRef[]>
  getTab(tabId: number): Promise<BrowserTabRef>
  createTab(url: string): Promise<void>
  focusTab(tabId: number, windowId?: number): Promise<void>
  openApp(): Promise<{ tabId: number; created: boolean }>
  sendToTab(tabId: number, message: AppMessage): Promise<unknown>
  persist?(context: EasyConnectionContext): void
}

class StaleContextError extends Error {
  constructor() { super('STALE_CONTEXT') }
}

async function accountPayload(host: WorkspaceHost, frozen?: AccountContextSnapshot): Promise<Pick<WorkspacePayload, 'customers' | 'templates' | 'rules' | 'tasks' | 'fileManageRuns'>> {
  const start = frozen ?? freezeAccount(host.connection.context)
  if (!start) return { customers: [], templates: [], rules: null, tasks: [], fileManageRuns: [] }
  if (!sameAccountContext(host.connection.context, start)) throw new StaleContextError()
  const account = await loadAccount(host.area, start.easyOrigin, start.operatorId)
  const tasks = host.tasks ? await host.tasks.list(start.easyOrigin, start.operatorId) : []
  const key = fileManageRunKey(start.easyOrigin, start.operatorId)
  const stored = await host.area.get(key)
  if (!sameAccountContext(host.connection.context, start)) throw new StaleContextError()
  return {
    customers: account.customers,
    templates: account.templates,
    rules: account.rules,
    tasks: tasks.map(task => ({
      taskId: task.taskId, createdAt: task.createdAt, customerName: task.customerName,
      fileCount: task.selectedFiles.length, mailCount: task.items.length, status: task.status,
      verifiedAt: task.verifiedAt, updatedAt: task.updatedAt
    })),
    fileManageRuns: parseFileManageRuns(stored[key])
  }
}

async function readAccount(host: WorkspaceHost, frozen?: AccountContextSnapshot): Promise<Pick<WorkspacePayload, 'customers' | 'templates' | 'rules' | 'tasks' | 'fileManageRuns'> | null> {
  try {
    return await accountPayload(host, frozen)
  } catch (error) {
    if (error instanceof StaleContextError) return null
    throw error
  }
}

function staleResult(host: WorkspaceHost): BackgroundResponse {
  return workspaceResult({
    ok: false,
    message: 'STALE_CONTEXT',
    contextError: 'STALE_CONTEXT',
    connection: host.connection.context
  })
}

function rememberObservedSearch(frozen: AccountContextSnapshot, request: AppMessage, response: AppMessage): Promise<QueryObservationResult | null> {
  if (request.type !== MessageType.SearchFiles || response.type !== MessageType.SearchFilesResult || !response.payload.ok || !response.payload.data) return Promise.resolve(null)
  const continuation = request.payload.continuation
  return observeSearchPage({
    scope: frozen,
    query: request.payload.query,
    result: response.payload.data,
    ...(continuation ? { run: { mode: 'continue' as const, querySessionId: continuation.querySessionId } } : { run: { mode: 'start' as const } })
  }).then(toQueryObservation)
}

function sourceMessageFor(recorded: QueryObservationResult): string {
  if (!recorded.ok) return recorded.code === 'QUERY_SESSION_INVALID' ? '这次翻页的查询运行已失效，请重新查询。' : recorded.code === 'QUERY_SESSION_REVALIDATION_REQUIRED' ? recorded.message : recorded.message
  if (recorded.revocationDiagnostic) return recorded.revocationDiagnostic
  if (recorded.status === 'CONFLICT') return '查询运行冲突。'
  if (recorded.persistence === 'PERSISTED') return '已保存查询来源。'
  if (recorded.persistence === 'MEMORY_ONLY') return '仅内存保存。'
  return '查询来源保存失败。'
}

function annotateSearch<T extends AppMessage>(response: T, recorded: QueryObservationResult): T {
  if (response.type !== MessageType.SearchFilesResult || !response.payload.ok || !response.payload.data) return response
  const data = { ...response.payload.data }
  delete data.querySessionId
  if (recorded.ok) {
    data.querySessionId = recorded.querySessionId
    data.sourcePersistence = recorded.persistence
    data.sourceCode = recorded.status === 'CONFLICT' ? 'FILE_DATA_CONFLICT' : recorded.persistence
    data.sourceMessage = sourceMessageFor(recorded)
  } else {
    data.sourceCode = recorded.code
    data.sourceMessage = sourceMessageFor(recorded)
  }
  return { ...response, payload: { ...response.payload, data } }
}

function stripSearchContinuation(message: AppMessage): AppMessage {
  if (message.type !== MessageType.SearchFiles) return message
  const timeoutMs = message.payload.timeoutMs
  return {
    type: MessageType.SearchFiles,
    payload: {
      query: message.payload.query,
      // batch 是批量拉页的标记（不占「新查询取消旧查询」的槽），continuation 留在后台记账，batch 要跟着过去。
      ...(message.payload.batch === true ? { batch: true as const } : {}),
      ...(timeoutMs === undefined ? {} : { timeoutMs })
    }
  }
}

function createdOf(task: AutomationTask): CreatedTaskResult {
  return {
    taskId: task.taskId,
    taskFingerprint: task.taskFingerprint,
    status: task.status,
    createdAt: task.createdAt,
    itemCount: task.items.length,
    persisted: true,
    fileSource: task.fileSource === 'SEARCH_RESPONSE_OBSERVED' ? 'SEARCH_RESPONSE_OBSERVED' : 'FILE_SOURCE_UNVERIFIED'
  }
}

async function boundTab(host: WorkspaceHost): Promise<{ ok: true; tabId: number } | { ok: false; message: string }> {
  const tabId = host.connection.context.easyTabId
  if (tabId == null) return { ok: false, message: '尚未连接 EASY。' }
  try {
    const tab = await host.getTab(tabId)
    if (typeof tab.id !== 'number' || !tabOrigin(tab.url)) {
      host.connection.context = {
        ...emptyConnection(host.connection.homeOrigin),
        lastOperatorId: host.connection.context.lastOperatorId,
        connectionVersion: host.connection.context.connectionVersion + 1,
        sessionStatus: 'error',
        message: '绑定页面已经离开 EASY 站点。'
      }
      remember(host)
      return { ok: false, message: host.connection.context.message }
    }
    return { ok: true, tabId }
  } catch {
    host.connection.detach(tabId)
    remember(host)
    return { ok: false, message: '绑定的 EASY 标签页已关闭。' }
  }
}

/** 写操作前重新读取登录身份，并返回冻结后的账号。 */
async function mutationGuard(host: WorkspaceHost, scope: ExpectedAccountScope): Promise<{ ok: true; account: AccountContextSnapshot } | { ok: false; response: BackgroundResponse }> {
  const gate = await recheckBoundSession(host)
  if (gate !== 'same') {
    const account = await readAccount(host)
    return { ok: false, response: workspaceResult({ ok: false, message: gate === 'changed' ? '会话已变化，请重新读取后再保存。' : (host.connection.context.message || '尚未确认 EASY 用户。'), connection: host.connection.context, ...(account ?? {}) }) }
  }
  if (!accountScopeMatches(host.connection.context, scope)) {
    const account = await readAccount(host)
    return { ok: false, response: workspaceResult({ ok: false, message: '保存时的账号与当前会话不一致，已拒绝。', connection: host.connection.context, ...(account ?? {}) }) }
  }
  const frozen = freezeAccount(host.connection.context)
  if (!frozen) {
    return { ok: false, response: workspaceResult({ ok: false, message: host.connection.context.message || '尚未确认 EASY 用户。', connection: host.connection.context }) }
  }
  return { ok: true, account: frozen }
}

async function recheckTasks(host: WorkspaceHost, frozen: AccountContextSnapshot): Promise<void> {
  if (!host.tasks || !sameAccountContext(host.connection.context, frozen)) return
  const account = await loadAccount(host.area, frozen.easyOrigin, frozen.operatorId)
  if (!account.rules || !sameAccountContext(host.connection.context, frozen)) return
  await refreshStaleTasks(host.tasks, frozen.easyOrigin, frozen.operatorId, account.rules, account.customers, account.templates)
}
export async function recheckBoundSession(host: WorkspaceHost): Promise<'same' | 'changed' | 'invalid'> {
  if (host.connection.context.easyTabId == null) return 'invalid'
  const version = host.connection.context.connectionVersion
  const operator = host.connection.context.operatorId
  await readBoundSession(host)
  if (host.connection.context.accountOffer) return 'changed'
  if (host.connection.context.connectionVersion !== version) return 'changed'
  if (operator && !sameOperatorId(operator, host.connection.context.operatorId)) return 'changed'
  if (host.connection.context.sessionStatus !== 'authenticated') return 'invalid'
  return 'same'
}

export async function handleWorkspaceMessage(message: AppMessage, host: WorkspaceHost): Promise<BackgroundResponse> {
  if (message.type !== MessageType.Workspace) {
    return workspaceResult({ ok: false, message: '后台没有处理这条消息。', connection: host.connection.context })
  }
  const action = message.payload
  if (action.action === 'focus') {
    const appTab = await host.openApp()
    return workspaceResult({ ok: true, message: appTab.created ? '已打开工作台。' : '已回到已打开的工作台。', connection: host.connection.context, appTab })
  }
  if (action.action === 'openLogin') {
    const origin = modeOrigin(customerMode())
    host.connection.retarget(origin)
    await host.createTab(`${origin}/`)
    return workspaceResult({ ok: true, message: `已打开${modeLabel(customerMode())}登录页面。登录后回到工作台即可读取该账号。`, connection: host.connection.context })
  }
  if (action.action === 'setCustomerMode') {
    await saveCustomerMode(action.mode)
    host.connection.retarget(modeOrigin(action.mode))
    const boundId = host.connection.context.easyTabId
    if (boundId != null && !originMatchesMode(host.connection.context.easyOrigin, action.mode)) {
      host.connection.detach(boundId)
      remember(host)
    }
    const tabs = await ensureEasySession(host)
    const account = await readAccount(host)
    if (!account) return staleResult(host)
    const connected = host.connection.context.sessionStatus === 'authenticated'
    const label = modeLabel(action.mode)
    const name = host.connection.context.displayName
    return workspaceResult({
      ok: true,
      message: connected ? `已切换到${label}${name ? `，当前是 ${name}` : '。'}` : (host.connection.context.message || `已切换到${label}。`),
      connection: host.connection.context,
      tabs,
      ...account
    })
  }
  if (action.action === 'listTabs' || action.action === 'load' || action.action === 'refreshSession') {
    const tabs = await ensureEasySession(host)
    const account = await readAccount(host)
    if (!account) return staleResult(host)
    const connected = host.connection.context.sessionStatus === 'authenticated'
    const name = host.connection.context.displayName
    const idle = tabs.length === 0 ? '尚未连接 EASY。' : '已找到 EASY 页面，但还没有读到登录。请刷新该 EASY 页面。'
    return workspaceResult({
      ok: action.action === 'refreshSession' ? connected : true,
      message: host.connection.context.message || (connected ? (name ? `已连接 ${name}` : '已连接到当前登录账号。') : action.action === 'refreshSession' ? '已重新检测会话。' : idle),
      connection: host.connection.context,
      tabs,
      ...account
    })
  }
  if (action.action === 'declineAccountSwitch') {
    const offered = host.connection.context.accountOffer?.operatorId ?? ''
    if (offered) host.connection.declinedOperatorId = offered
    host.connection.context = {
      ...host.connection.context,
      operatorId: '',
      displayName: '',
      accountOffer: null,
      sessionStatus: host.connection.context.sessionStatus === 'authenticated' ? 'unauthenticated' : host.connection.context.sessionStatus,
      message: '仍留在上一位登录人的现场。换回原来的账号即可继续。'
    }
    remember(host)
    return workspaceResult({ ok: true, message: host.connection.context.message, connection: host.connection.context })
  }
  if (action.action === 'bind') {
    const tabs = await modeTabs(host)
    const chosen = tabs.find(tab => tab.id === action.tabId)
    if (!chosen) {
      return workspaceResult({ ok: false, message: '请选择一个 EASY 标签页。', connection: host.connection.context, tabs })
    }
    const begun = host.connection.beginBind(chosen)
    if (!begun.ok) return workspaceResult({ ok: false, message: begun.message, connection: host.connection.context, tabs })
    await readBoundSession(host, 0, true)
    if (host.connection.context.sessionStatus === 'authenticated') host.connection.declinedOperatorId = ''
    const account = await readAccount(host)
    if (!account) return staleResult(host)
    return workspaceResult({ ok: host.connection.context.sessionStatus === 'authenticated', message: host.connection.context.message, connection: host.connection.context, tabs, ...account })
  }
  let frozenAccount: AccountContextSnapshot | null = null
  if (action.action === 'saveCustomer' || action.action === 'deleteCustomer' || action.action === 'saveQueryTemplate' || action.action === 'deleteQueryTemplate' || action.action === 'saveRules' || action.action === 'createTaskPlan' || action.action === 'recordFileManageRun') {
    const gate = await mutationGuard(host, action.expectedScope)
    if (!gate.ok) return gate.response
    frozenAccount = gate.account
  }
  const frozenNow = (): AccountContextSnapshot => {
    if (!frozenAccount || !sameAccountContext(host.connection.context, frozenAccount)) throw new StaleContextError()
    return frozenAccount
  }
  const failWrite = async (message: string): Promise<BackgroundResponse> => {
    if (!frozenAccount || !sameAccountContext(host.connection.context, frozenAccount)) return staleResult(host)
    const account = await readAccount(host, frozenAccount)
    if (!account) return staleResult(host)
    return workspaceResult({ ok: false, message, connection: host.connection.context, ...account })
  }
  const finishWrite = async (message: string, createdTask: CreatedTaskResult | null = null): Promise<BackgroundResponse> => {
    if (!frozenAccount || !sameAccountContext(host.connection.context, frozenAccount)) return staleResult(host)
    const account = await readAccount(host, frozenAccount)
    if (!account) return staleResult(host)
    return workspaceResult({ ok: true, message, connection: host.connection.context, createdTask, ...account })
  }
  if (action.action === 'recordFileManageRun') {
    try {
      const frozen = frozenNow()
      const key = fileManageRunKey(frozen.easyOrigin, frozen.operatorId)
      await enqueueFileManageWrite(key, async () => {
        if (!sameAccountContext(host.connection.context, frozen)) throw new StaleContextError()
        const stored = await host.area.get(key)
        const next = appendFileManageRun(parseFileManageRuns(stored[key]), {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          customerName: action.run.customerName.trim(),
          subject: action.run.subject,
          fileCount: action.run.fileCount,
          status: action.run.status,
          note: action.run.note
        })
        if (!sameAccountContext(host.connection.context, frozen)) throw new StaleContextError()
        await host.area.set({ [key]: next })
      })
      return await finishWrite('文件管理发文已记入本地记录。')
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return await failWrite(error instanceof Error ? error.message : '本地记录没有写入。')
    }
  }
  if (action.action === 'saveCustomer') {
    try {
      const frozen = frozenNow()
      await saveCustomerAccount(host.area, frozen.easyOrigin, frozen.operatorId, action.profile, action.expectedRevision)
      await recheckTasks(host, frozen)
      return await finishWrite('客户配置已保存。名称或 EASY GUID 变化的任务会重新核验。')
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return failWrite(error instanceof Error ? error.message : '客户没有保存。')
    }
  }
  if (action.action === 'deleteCustomer') {
    try {
      const frozen = frozenNow()
      await deleteCustomerAccount(host.area, frozen.easyOrigin, frozen.operatorId, action.id, action.expectedRevision)
      await recheckTasks(host, frozen)
      return await finishWrite('客户配置已删除。相关任务会重新核验。')
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return failWrite(error instanceof Error ? error.message : '客户没有删除。')
    }
  }
  if (action.action === 'saveQueryTemplate') {
    try {
      const frozen = frozenNow()
      await saveQueryTemplateAccount(host.area, frozen.easyOrigin, frozen.operatorId, action.template, action.expectedVersion)
      await recheckTasks(host, frozen)
      return await finishWrite(action.template.queryType === 'FilingSearch'
        ? '递交查询模板已保存在本机。原网站没有模板功能，不会写入。'
        : '本地模板已保存。原网站历史模板没有被写入。')
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return failWrite(error instanceof Error ? error.message : '模板没有保存。')
    }
  }
  if (action.action === 'deleteQueryTemplate') {
    try {
      const frozen = frozenNow()
      await deleteQueryTemplateAccount(host.area, frozen.easyOrigin, frozen.operatorId, action.id)
      await recheckTasks(host, frozen)
      return await finishWrite('本地模板已删除。')
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return failWrite(error instanceof Error ? error.message : '模板没有删除。')
    }
  }
  if (action.action === 'saveRules') {
    try {
      const frozen = frozenNow()
      const checked = readMailRules(action.bundle, frozen.operatorId)
      if (!checked.writable) return failWrite(checked.warning ?? '发文配置未通过校验。')
      const outcome = await saveRuleAccount(host.area, frozen.easyOrigin, frozen.operatorId, checked.bundle, host.tasks)
      const message = outcome.pendingRevalidation
        ? '发文规则已保存。旧任务重新核验没有完成，可以单独重试，不必再次保存规则。'
        : '发文规则已保存。内容变化的旧任务会标记为过期。'
      if (!frozenAccount || !sameAccountContext(host.connection.context, frozen)) return staleResult(host)
      const account = await readAccount(host, frozen)
      if (!account) return staleResult(host)
      return workspaceResult({
        ok: true,
        message,
        connection: host.connection.context,
        rulesSaved: true,
        tasksRevalidated: outcome.tasksRevalidated,
        pendingRevalidation: outcome.pendingRevalidation,
        ...account
      })
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return failWrite(error instanceof Error ? error.message : '规则没有保存。')
    }
  }
  if (action.action === 'createTaskPlan') {
    try {
      const frozen = frozenNow()
      const accountNow = await loadAccount(host.area, frozen.easyOrigin, frozen.operatorId)
      if (!sameAccountContext(host.connection.context, frozen)) return staleResult(host)
      if (!accountNow.rules || !host.tasks) {
        return workspaceResult({ ok: false, message: '没有可核验的发文规则，任务未保存。', connection: host.connection.context })
      }
      const resolved = await resolveSelectedFiles(action.files, frozen, { profiles: accountNow.customers })
      const task = planTrustedTask({
        origin: frozen.easyOrigin,
        operatorId: frozen.operatorId,
        files: resolved.files,
        rules: accountNow.rules,
        profiles: accountNow.customers,
        templates: accountNow.templates,
        verifiedSelection: resolved.selections
      })
      if (resolved.issue === 'MIXED_QUERY_SESSION') {
        task.issues.push({ code: 'MIXED_QUERY_SESSION', message: '所选文件不属于同一次查询运行。', itemId: '' })
        if (task.status !== 'UNKNOWN') task.status = 'BLOCKED'
      }
      if (resolved.issue === 'FILE_DATA_CONFLICT') {
        task.issues.push({ code: 'FILE_DATA_CONFLICT', message: '同一文件在查询响应中的业务字段不一致，不能进入可信计划。', itemId: '' })
        if (task.status !== 'UNKNOWN') task.status = 'BLOCKED'
      }
      if (resolved.requiresRevalidation) {
        task.issues.push({ code: 'EVIDENCE_REVALIDATION_REQUIRED', message: '查询证据需要重新核验后才能当作当前来源。', itemId: '' })
        if (task.status !== 'UNKNOWN') task.status = 'BLOCKED'
      }
      if (resolved.mismatches.length > 0) {
        task.issues.push({ code: 'FILE_FIELD_MISMATCH', message: '页面提交的文件字段与查询响应不一致，已按查询快照重建。', itemId: '' })
        if (task.status !== 'UNKNOWN') task.status = 'BLOCKED'
      }
      if (!sameAccountContext(host.connection.context, frozen)) return staleResult(host)
      const persisted = await host.tasks.save(task)
      if (!persisted.ok) {
        return workspaceResult({ ok: false, message: persisted.message, connection: host.connection.context })
      }
      if (!sameAccountContext(host.connection.context, frozen)) return staleResult(host)
      return await finishWrite(`已保存 · 任务 ${persisted.task.taskId}`, createdOf(persisted.task))
    } catch (error) {
      if (error instanceof StaleContextError) return staleResult(host)
      return workspaceResult({ ok: false, message: error instanceof Error ? error.message : '任务没有保存。', connection: host.connection.context })
    }
  }
  if (action.action === 'forward') {
    if (action.message.type === MessageType.LoadDictionary && action.message.payload.kind === 'customerList') {
      const local = await readSmeCustomerList(action.message.payload.force)
      if (local) {
        return workspaceResult({
          ok: true,
          message: '',
          connection: host.connection.context,
          forwarded: { type: MessageType.DictionaryResult, payload: local }
        })
      }
    }
    const readBurst = (action.message.type === MessageType.LookupIcFlow
      || action.message.type === MessageType.SearchLimitMonitor
      || action.message.type === MessageType.ReadCaseBusFlow)
      && host.connection.context.sessionStatus === 'authenticated'
      && host.connection.context.easyTabId != null
    if (!readBurst && action.message.type !== MessageType.CheckSession && action.message.type !== MessageType.CancelSessionCheck) {
      const gate = await recheckBoundSession(host)
      if (gate !== 'same') {
        return workspaceResult({ ok: false, message: gate === 'changed' ? '会话已变化，请重新检测后再继续。' : (host.connection.context.message || '尚未确认 EASY 用户。'), connection: host.connection.context })
      }
    }
    const target = await boundTab(host)
    if (!target.ok) return workspaceResult({ ok: false, message: target.message, connection: host.connection.context })
    const forwardBlock = workspaceForwardBlock(action.message)
    if (forwardBlock) {
      return workspaceResult({ ok: false, message: forwardBlock, connection: host.connection.context })
    }
    let outbound = action.message
    if (outbound.type === MessageType.SubmitLimitMail || outbound.type === MessageType.SubmitFileManage) {
      const operatorId = host.connection.context.operatorId
      if (!isConfirmedOperator(operatorId)) {
        return workspaceResult({ ok: false, message: '当前登录人还没确认，没有提交。', connection: host.connection.context })
      }
      if (outbound.type === MessageType.SubmitLimitMail) {
        const account = await readAccount(host)
        if (!account) return staleResult(host)
        const reviewerId = account.rules?.defaultReviewer?.userId ?? ''
        if (!isConfirmedOperator(reviewerId)) {
          return workspaceResult({ ok: false, message: '还没有默认审核人。请到发文映射里设置。', connection: host.connection.context })
        }
        outbound = { ...outbound, payload: { ...outbound.payload, userId: operatorId, items: outbound.payload.items.map(item => ({ ...item, reviewerId })) } }
      } else {
        outbound = { ...outbound, payload: { ...outbound.payload, userId: operatorId } }
      }
    }
    if (action.message.type === MessageType.ExportCaseContacts) {
      const frozen = freezeAccount(host.connection.context)
      const account = frozen ? await readAccount(host, frozen) : null
      const contactBlock = caseContactExportBlock(host.connection.context.easyOrigin, account?.customers ?? [])
      if (contactBlock) return workspaceResult({ ok: false, message: contactBlock, connection: host.connection.context })
    }
    const frozen = freezeAccount(host.connection.context)
    const version = host.connection.context.connectionVersion
    try {
      const response = await host.sendToTab(target.tabId, stripSearchContinuation(outbound))
      if (frozen && !sameAccountContext(host.connection.context, frozen)) {
        return workspaceResult({ ok: false, message: '账号已经变化，这次查询结果已丢弃。', connection: host.connection.context })
      }
      if (!frozen && host.connection.context.connectionVersion !== version) {
        return workspaceResult({ ok: false, message: '连接已经变化，这次结果已丢弃。', connection: host.connection.context })
      }
      if (!isMessage(response) || response.type === MessageType.Workspace || response.type === MessageType.WorkspaceResult) {
        return workspaceResult({ ok: false, message: 'EASY 页面没有返回可识别的结果。请刷新这个 EASY 标签页后再试。', connection: host.connection.context })
      }
      let forwarded = response
      if (frozen && action.message.type === MessageType.SearchFiles) {
        const recorded = await rememberObservedSearch(frozen, action.message, response)
        if (!sameAccountContext(host.connection.context, frozen)) {
          return workspaceResult({ ok: false, message: '账号已经变化，这次查询结果已丢弃。', connection: host.connection.context })
        }
        if (recorded) forwarded = annotateSearch(response, recorded)
      }
      if (frozen && action.message.type === MessageType.LoadDictionary && response.type === MessageType.DictionaryResult && response.payload.ok && response.payload.data.kind === 'fileType') {
        rememberFileTypeTree(frozen, response.payload.data.caseTypeId, response.payload.data.nodes)
      }
      return workspaceResult({ ok: true, message: '', connection: host.connection.context, forwarded })
    } catch (error) {
      const text = error instanceof Error ? error.message : ''
      const gone = /no tab with id|tab was closed|receiving end does not exist|could not establish connection/i.test(text)
      if (gone) {
        host.connection.detach(target.tabId)
        remember(host)
        return workspaceResult({ ok: false, message: '绑定的 EASY 标签页已失效。', connection: host.connection.context })
      }
      return workspaceResult({ ok: false, message: text || 'EASY 页面没有执行这次查询。', connection: host.connection.context })
    }
  }
  if (action.action === 'runAcceptance') {
    const gate = await recheckBoundSession(host)
    if (gate !== 'same') {
      return workspaceResult({ ok: false, message: gate === 'changed' ? '会话已变化，请重新检测后再验收。' : (host.connection.context.message || '尚未确认 EASY 用户。'), connection: host.connection.context })
    }
    const target = await boundTab(host)
    if (!target.ok) return workspaceResult({ ok: false, message: target.message, connection: host.connection.context })
    const acceptanceContext = { caseTypeId: action.caseTypeId, mailId: action.mailId, flowType: action.flowType, expectedFields: action.expectedFields }
    const blocked = acceptanceBlockReason(action.call, acceptanceContext)
    if (blocked) {
      const row = blockedAcceptance({ origin: host.connection.context.easyOrigin, operatorId: host.connection.context.operatorId, call: action.call, reason: blocked })
      await host.evidence.saveAcceptance(row)
      return workspaceResult({
        ok: true,
        message: `${row.call} ${row.result}`,
        connection: host.connection.context,
        forwarded: { type: MessageType.AcceptanceResult, payload: { records: [row as unknown as Record<string, unknown>] } }
      })
    }
    const version = host.connection.context.connectionVersion
    let response: unknown
    try {
      response = await host.sendToTab(target.tabId, {
        type: MessageType.RunReadonlyAcceptance,
        payload: { call: action.call, expected: action.expectedFields ?? {}, caseTypeId: action.caseTypeId, mailId: action.mailId, flowType: action.flowType }
      })
      if (host.connection.context.connectionVersion !== version) {
        return workspaceResult({ ok: false, message: '连接已经变化，这次验收结果已丢弃。', connection: host.connection.context })
      }
    } catch {
      host.connection.detach(target.tabId)
      return workspaceResult({ ok: false, message: '绑定的 EASY 标签页已失效。', connection: host.connection.context })
    }
    const probe = isMessage(response) && response.type === MessageType.AcceptanceResult ? response.payload.probe : undefined
    if (!isReadonlyProbe(probe)) {
      return workspaceResult({ ok: false, message: '只读验收没有带回可复核的响应。', connection: host.connection.context })
    }
    const runner = new LiveEasyAcceptanceRunner({ kind: 'live', call: async () => probe })
    const row = await runner.run({
      origin: host.connection.context.easyOrigin,
      operatorId: host.connection.context.operatorId,
      call: action.call,
      expected: action.expectedFields ?? {}
    })
    await host.evidence.saveAcceptance(row)
    return workspaceResult({
      ok: true,
      message: `${row.call} ${row.result}`,
      connection: host.connection.context,
      forwarded: { type: MessageType.AcceptanceResult, payload: { records: [row as unknown as Record<string, unknown>], probe } }
    })
  }
  return workspaceResult({ ok: false, message: '后台没有处理这条消息。', connection: host.connection.context })
}

function remember(host: WorkspaceHost): void {
  host.persist?.(host.connection.context)
}

function stillUnbound(host: WorkspaceHost, version: number): boolean {
  return host.connection.context.easyTabId == null && host.connection.context.connectionVersion === version
}

const SESSION_READ_MS = 12_000

/** 内容脚本没回话时不能一直等，否则后面的登录检测全部排在这一次后面。 */
function readTabSession(host: WorkspaceHost, tabId: number): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('登录检测超时。')), SESSION_READ_MS)
    host.sendToTab(tabId, { type: MessageType.CheckSession }).then(
      value => { clearTimeout(timer); resolve(value) },
      error => { clearTimeout(timer); reject(error) }
    )
  })
}

/**
 * 登录人和现场主人不是同一位时先挂起，不写入新身份。
 * 返回 true 表示这一次没有接上，调用方不要再 beginBind。
 */
function holdForeignLogin(host: WorkspaceHost, tabId: number, userId: string, displayName: string): boolean {
  const previous = host.connection.context.operatorId || host.connection.context.lastOperatorId
  if (resumeLoginChoice(previous, userId) !== 'ask') return false
  if (sameOperatorId(host.connection.declinedOperatorId, userId)) {
    if (host.connection.context.sessionStatus === 'authenticated' || host.connection.context.accountOffer) {
      host.connection.context = {
        ...host.connection.context,
        operatorId: '',
        displayName: '',
        accountOffer: null,
        sessionStatus: 'unauthenticated',
        message: '仍留在上一位登录人的现场。换回原来的账号即可继续。'
      }
      remember(host)
    }
    return true
  }
  const offer = host.connection.context.accountOffer
  if (offer && sameOperatorId(offer.operatorId, userId) && offer.tabId === tabId) return true
  host.connection.context = {
    ...host.connection.context,
    operatorId: '',
    displayName: '',
    accountOffer: {
      operatorId: userId,
      displayName: displayName.trim().slice(0, 80),
      tabId
    },
    sessionStatus: 'unauthenticated',
    lastCheckedAt: new Date().toISOString(),
    message: '登录人和现场不是同一位。'
  }
  remember(host)
  return true
}

async function observeTab(host: WorkspaceHost, tabId: number): Promise<SessionObservation | null> {
  try {
    const response = await readTabSession(host, tabId)
    console.log('[patmail-bg] observeTab response', tabId, response)
    if (!isMessage(response) || response.type !== MessageType.SessionResult) {
      return { ok: false, message: '无法读取该标签页的登录状态。' }
    }
    if (!response.payload.ok) {
      if (response.payload.error.code === 'REQUEST_ABORTED') return null
      return {
        ok: false,
        status: response.payload.error.code === 'SESSION_EXPIRED' ? 'expired' : 'error',
        message: response.payload.error.message
      }
    }
    return {
      ok: true,
      status: response.payload.data.status,
      userId: response.payload.data.userId,
      displayName: response.payload.data.displayName,
      checkedAt: response.payload.data.checkedAt,
      message: response.payload.data.message
    }
  } catch (error) {
    console.log('[patmail-bg] observeTab error', tabId, error)
    return null
  }
}

async function modeTabs(host: WorkspaceHost): Promise<EasyTabCandidate[]> {
  const tabs = host.connection.list(await host.queryTabs())
  return tabs.filter(tab => originMatchesMode(tab.origin))
}

/** 工作台打开时跟随已经登录的 EASY 标签页。多个不同账号时不代为选择。 */
async function ensureEasySession(host: WorkspaceHost): Promise<EasyTabCandidate[]> {
  const tabs = await modeTabs(host)
  console.log('[patmail-bg] ensureEasySession tabs', tabs.length, tabs.map(t => ({ id: t.id, url: t.url })))
  const boundId = host.connection.context.easyTabId
  if (boundId != null) {
    if (tabs.some(tab => tab.id === boundId)) {
      console.log('[patmail-bg] bound tab found, reading session', boundId)
      await readBoundSession(host)
      console.log('[patmail-bg] after readBoundSession', host.connection.context.sessionStatus, host.connection.context.operatorId)
      if (host.connection.context.sessionStatus === 'authenticated' || host.connection.context.accountOffer) return tabs
      // 超时、失效、读失败都不要停在旧绑定上。接着看现在到底是谁登录。
      host.connection.detach(boundId)
      remember(host)
    } else {
      console.log('[patmail-bg] bound tab missing, detach', boundId)
      host.connection.detach(boundId)
      remember(host)
    }
  }
  const version = host.connection.context.connectionVersion
  const seen: { tab: EasyTabCandidate; observation: SessionObservation }[] = []
  for (const tab of tabs) {
    if (!stillUnbound(host, version)) return modeTabs(host)
    const observation = await observeTab(host, tab.id)
    console.log('[patmail-bg] observeTab', tab.id, observation)
    if (!stillUnbound(host, version)) return modeTabs(host)
    if (observation) seen.push({ tab, observation })
  }
  const loggedIn = seen.filter(item => item.observation.ok && item.observation.status === 'authenticated' && item.observation.userId && isConfirmedOperator(item.observation.userId))
  console.log('[patmail-bg] loggedIn count', loggedIn.length)
  const operators = new Set(loggedIn.map(item => item.observation.userId))
  if (operators.size === 1 && loggedIn[0]) {
    const found = loggedIn[0]
    const userId = found.observation.userId ?? ''
    if (holdForeignLogin(host, found.tab.id, userId, found.observation.displayName ?? '')) return tabs
    const begun = host.connection.beginBind(found.tab)
    if (begun.ok) {
      host.connection.applySession(found.observation, host.connection.context.connectionVersion)
      host.connection.declinedOperatorId = ''
      if (loggedIn.length > 1) host.connection.context = { ...host.connection.context, message: '已连接到当前登录账号。' }
      remember(host)
    }
    return tabs
  }
  if (operators.size > 1) {
    host.connection.context = { ...host.connection.context, message: '发现多个已登录账号，请选择要连接的标签页。' }
    remember(host)
    return tabs
  }
  if (tabs.length === 1 && seen[0]) {
    const begun = host.connection.beginBind(seen[0].tab)
    if (begun.ok) {
      host.connection.applySession(seen[0].observation, host.connection.context.connectionVersion)
      remember(host)
    }
    return tabs
  }
  if (tabs.length > 0) {
    host.connection.context = {
      ...host.connection.context,
      message: seen.length === 0 ? '找到 EASY 页面，但还读不到登录状态。请刷新该页面后再检测。' : '这些 EASY 页面都没有已登录账号。'
    }
    remember(host)
  } else if (host.connection.context.easyTabId == null) {
    const label = modeLabel(customerMode())
    const origin = modeOrigin(customerMode())
    host.connection.context = {
      ...host.connection.context,
      easyOrigin: origin,
      message: `尚未连接${label}。请先打开并登录 ${origin}/ 。`
    }
    remember(host)
  }
  return tabs
}

/** 服务工作线程被浏览器停掉后重新醒来时调用。候选标签还在就重读登录，不在就再找已打开的 EASY 页。 */
export async function resumeEasySession(host: WorkspaceHost): Promise<void> {
  await ensureEasySession(host)
  host.persist?.(host.connection.context)
}

async function readBoundSession(host: WorkspaceHost, attempt = 0, adoptForeign = false): Promise<void> {
  const target = await boundTab(host)
  if (!target.ok) return
  const version = host.connection.context.connectionVersion
  const tabId = target.tabId
  const previous = host.connection.context.operatorId || host.connection.context.lastOperatorId
  const retry = async (): Promise<void> => {
    if (attempt >= 2 || host.connection.context.easyTabId !== tabId) return
    await new Promise(resolve => setTimeout(resolve, 250))
    if (host.connection.context.easyTabId !== tabId) return
    await readBoundSession(host, attempt + 1, adoptForeign)
  }
  try {
    const response = await readTabSession(host, tabId)
    console.log('[patmail-bg] readBoundSession response', tabId, response)
    if (host.connection.context.easyTabId !== tabId) return
    if (host.connection.context.connectionVersion !== version) {
      await retry()
      return
    }
    if (!isMessage(response) || response.type !== MessageType.SessionResult) {
      host.connection.applySession({ ok: false, message: '无法读取该标签页的登录状态。' }, version)
      remember(host)
      return
    }
    if (!response.payload.ok) {
      if (response.payload.error.code === 'REQUEST_ABORTED') return
      // 瞬时失败（超时、网络、网关）不是掉登录：已连接就保持现状，只把这次检测当成没读到。明确的登录失效才改状态。
      if (response.payload.error.code !== 'SESSION_EXPIRED' && host.connection.context.sessionStatus === 'authenticated') return
      host.connection.applySession({
        ok: false,
        status: response.payload.error.code === 'SESSION_EXPIRED' ? 'expired' : 'error',
        message: response.payload.error.message
      }, version)
      remember(host)
      return
    }
    const data = response.payload.data
    if (!adoptForeign && data.status === 'authenticated' && data.userId && holdForeignLogin(host, tabId, data.userId, data.displayName ?? '')) return
    host.connection.applySession({
      ok: true,
      status: data.status,
      userId: data.userId,
      displayName: data.displayName,
      checkedAt: data.checkedAt,
      message: data.message
    }, version)
    if (host.connection.context.sessionStatus === 'authenticated') host.connection.declinedOperatorId = ''
    if (previous && host.connection.context.operatorId && !sameOperatorId(previous, host.connection.context.operatorId)) {
      host.connection.context = { ...host.connection.context, message: '已切换到当前标签页的登录用户。' }
    }
    remember(host)
  } catch (error) {
    console.log('[patmail-bg] readBoundSession error', tabId, error)
    if (host.connection.context.easyTabId !== tabId) return
    if (attempt < 2) {
      await retry()
      return
    }
    if (host.connection.context.connectionVersion !== version) return
    host.connection.context = {
      ...host.connection.context,
      operatorId: '',
      displayName: '',
      sessionStatus: 'pending',
      message: '已找到 EASY 页面，但还没有读到登录。请刷新该页面。'
    }
    remember(host)
  }
}

export async function openWorkspaceTab(tabs: BrowserTabRef[], appUrl: string, focus: (id: number, windowId?: number) => Promise<void>, create: () => Promise<number>): Promise<{ tabId: number; created: boolean }> {
  const choice = chooseAppTab(tabs, appUrl)
  if (choice.action === 'focus') {
    const tab = tabs.find(item => item.id === choice.id)
    await focus(choice.id, tab?.windowId)
    return { tabId: choice.id, created: false }
  }
  return { tabId: await create(), created: true }
}

import { newUuid } from '../utils/uuid'

export const NATIVE_NAVIGATION_CHANNEL = 'PATMAIL_NATIVE_NAVIGATE'
interface Target { taskId: string; owner: string; frame?: HTMLIFrameElement }
const targets = new Map<string, Target>()
let listeningRuntime: unknown

export async function registerNativeDownloadTarget(taskId: string, owner: string): Promise<string> {
  releaseNativeDownloadTarget(taskId)
  const runtime = globalThis.chrome?.runtime
  if (!runtime?.onMessage) throw new Error('浏览器扩展后台不可用，请重新加载扩展后打开工作台。')
  const targetId = newUuid()
  targets.set(targetId, { taskId, owner })
  if (listeningRuntime !== runtime) {
    runtime.onMessage.addListener(handleNativeNavigation)
    listeningRuntime = runtime
  }
  return targetId
}

export function handleNativeNavigation(message: unknown, sender: chrome.runtime.MessageSender, reply: (value: { ok: boolean; error?: string }) => void): boolean {
  if (!message || typeof message !== 'object') return false
  const request = message as Record<string, unknown>
  const runtime = globalThis.chrome?.runtime
  if (request.channel !== NATIVE_NAVIGATION_CHANNEL || !runtime || sender.id !== runtime.id || sender.tab ||
    sender.url !== runtime.getURL('background.js') || typeof request.targetId !== 'string') return false
  const target = targets.get(request.targetId)
  if (!target || request.taskId !== target.taskId || request.owner !== target.owner || typeof request.url !== 'string' ||
    !request.url.startsWith(runtime.getURL('_patmail_native_download/'))) return false
  void (async () => {
    const workers = navigator.serviceWorker
    if (!workers) throw new Error('当前浏览器未提供扩展流式下载能力。')
    await workers.ready
    if (!workers.controller) await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => { workers.removeEventListener('controllerchange', ready); reject(new Error('下载后台尚未接管工作台，请重新打开工作台。')) }, 10_000)
      const ready = () => { if (workers.controller) { clearTimeout(timer); workers.removeEventListener('controllerchange', ready); resolve() } }
      workers.addEventListener('controllerchange', ready)
      ready()
    })
    if (targets.get(request.targetId as string) !== target) throw new Error('下载目标已离开。')
    target.frame?.remove()
    const frame = document.createElement('iframe')
    frame.hidden = true
    frame.title = '浏览器流式下载'
    frame.src = request.url as string
    target.frame = frame
    document.body.append(frame)
  })().then(() => reply({ ok: true }), error => reply({ ok: false, error: error instanceof Error ? error.message : '原生下载没有启动。' }))
  return true
}

export function releaseNativeDownloadTarget(taskId: string): void {
  for (const [id, target] of targets) if (target.taskId === taskId) { target.frame?.remove(); targets.delete(id) }
}

import type { CachedFileInfo } from '../api/stream-cache'
import type { BrowserBlob, BrowserDownloadStore, BrowserDownloadTask } from './types'

const DB = 'patmail-browser-downloads'
const STORES = ['tasks', 'manifests', 'blobs', 'chunks', 'names']
const BLOCK = 256 * 1024
const TTL = 7 * 86400000
type TaskRecord = Omit<BrowserDownloadTask, 'manifest'> & { generation: string }
interface BlobRecord extends CachedFileInfo { taskId: string; blob: string; revision: string; epoch: string }
interface ChunkRecord { taskId: string; blob: string; offset: number; bytes: Uint8Array<ArrayBuffer>; digest: string }
const emptyInfo = (): CachedFileInfo => ({ receivedBytes: 0, complete: false })
const integer = (value: number) => { if (!Number.isSafeInteger(value) || value < 0) throw new Error('Invalid cache offset or size') }
function blobKey(blob: BrowserBlob): string {
  if (blob === 'archive') return blob
  integer(blob)
  return String(blob)
}
function request<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => { req.onsuccess = () => resolve(req.result); req.onerror = () => reject(req.error) })
}
async function digest(bytes: Uint8Array<ArrayBuffer>): Promise<string> {
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)), b => b.toString(16).padStart(2, '0')).join('')
}
function metadata(value: Partial<CachedFileInfo>): Partial<CachedFileInfo> {
  if (value.totalBytes != null) integer(value.totalBytes)
  return { ...(value.totalBytes !== undefined ? { totalBytes: value.totalBytes } : {}),
    ...(value.etag !== undefined ? { etag: value.etag } : {}),
    ...(value.lastModified !== undefined ? { lastModified: value.lastModified } : {}) }
}

/** ACKs resolve only after a strict-durability transaction commits. Crypto is always outside transactions. */
export function createBrowserDownloadStore(factory: IDBFactory = indexedDB): BrowserDownloadStore {
  let database: Promise<IDBDatabase> | undefined
  function open(): Promise<IDBDatabase> {
    database ??= new Promise((resolve, reject) => {
      const req = factory.open(DB, 1)
      req.onupgradeneeded = () => {
        const db = req.result
        db.createObjectStore('tasks', { keyPath: 'taskId' })
        db.createObjectStore('manifests')
        for (const name of ['blobs', 'chunks', 'names']) {
          const store = db.createObjectStore(name, { keyPath: name === 'chunks' ? ['taskId', 'blob', 'offset'] : name === 'blobs' ? ['taskId', 'blob'] : ['taskId', 'offset'] })
          store.createIndex('taskId', 'taskId')
        }
      }
      req.onsuccess = () => { req.result.onversionchange = () => req.result.close(); resolve(req.result) }
      req.onerror = () => reject(req.error)
      req.onblocked = () => reject(new Error('Download cache database upgrade blocked'))
    })
    return database
  }
  async function transaction<T>(mode: IDBTransactionMode, run: (tx: IDBTransaction) => Promise<T>): Promise<T> {
    const db = await open()
    const tx = db.transaction(STORES, mode, mode === 'readwrite' ? { durability: 'strict' } : undefined)
    let failure: unknown
    const done = new Promise<void>((resolve, reject) => {
      tx.oncomplete = () => resolve()
      tx.onabort = () => reject(failure ?? tx.error ?? new Error('Cache transaction aborted'))
      tx.onerror = () => { /* onabort is the authoritative failure event */ }
    })
    // Attach immediately, including when the body itself rejects before awaiting completion.
    void done.catch(() => {})
    try { const value = await run(tx); await done; return value }
    catch (error) { failure = error; try { tx.abort() } catch { /* already aborted */ } await done.catch(() => {}); throw error }
  }
  async function task(tx: IDBTransaction, taskId: string): Promise<TaskRecord> {
    const value = await request<TaskRecord | undefined>(tx.objectStore('tasks').get(taskId))
    if (!value) throw new Error('Download task does not exist')
    return value
  }
  function writable(value: TaskRecord): void { if (value.state === 'done') throw new Error('Download task already completed') }
  async function touch(tx: IDBTransaction, value: TaskRecord): Promise<void> {
    await request(tx.objectStore('tasks').put({ ...value, updatedAt: Date.now() }))
  }
  async function erase(tx: IDBTransaction, taskId: string, keepReceipt = false): Promise<void> {
    for (const name of ['blobs', 'chunks', 'names']) {
      await new Promise<void>((resolve, reject) => {
        const cursor = tx.objectStore(name).index('taskId').openCursor(IDBKeyRange.only(taskId))
        cursor.onerror = () => reject(cursor.error)
        cursor.onsuccess = () => { const row = cursor.result; if (!row) return resolve(); row.delete(); row.continue() }
      })
    }
    if (!keepReceipt) {
      await request(tx.objectStore('manifests').delete(taskId))
      await request(tx.objectStore('tasks').delete(taskId))
    }
  }
  async function collect(tx: IDBTransaction): Promise<void> {
    const all = await request<TaskRecord[]>(tx.objectStore('tasks').getAll())
    for (const value of all) if ((value.state === 'paused' || value.state === 'done') && value.updatedAt < Date.now() - TTL) await erase(tx, value.taskId)
  }
  async function blobInfo(tx: IDBTransaction, taskId: string, blob: string): Promise<BlobRecord | undefined> {
    return request(tx.objectStore('blobs').get([taskId, blob]))
  }
  async function rows(tx: IDBTransaction, taskId: string, blob: string, offset: number, end: number): Promise<ChunkRecord[]> {
    // Include the block containing offset; chunks can have arbitrary start offsets.
    const store = tx.objectStore('chunks')
    const before = await request(store.openCursor(IDBKeyRange.bound([taskId, blob, 0], [taskId, blob, offset]), 'prev'))
    const start = before ? (before.value as ChunkRecord).offset : offset
    return request(store.getAll(IDBKeyRange.bound([taskId, blob, start], [taskId, blob, end], false, true)))
  }
  async function verified(rows: ChunkRecord[], offset: number, length: number): Promise<Uint8Array<ArrayBuffer>> {
    const result = new Uint8Array(length)
    let next = offset
    for (const row of rows) {
      if (await digest(row.bytes) !== row.digest) throw new Error('Download cache checksum mismatch')
      const start = Math.max(next, row.offset), end = Math.min(offset + length, row.offset + row.bytes.length)
      if (start > next) throw new Error('Download cache has a gap')
      if (end > start) { result.set(row.bytes.subarray(start - row.offset, end - row.offset), start - offset); next = end }
    }
    if (next !== offset + length) throw new Error('Download cache is incomplete')
    return result
  }
  const store: BrowserDownloadStore = {
    async create(value) {
      if (!value.taskId || !value.owner) throw new Error('Missing task identity')
      const frozen = structuredClone(value)
      await transaction('readwrite', async tx => {
        await collect(tx)
        if (await request(tx.objectStore('tasks').get(frozen.taskId))) throw new Error('Download task already exists')
        const { manifest, ...record } = frozen
        await request(tx.objectStore('manifests').add(manifest, frozen.taskId))
        await request(tx.objectStore('tasks').add({ ...record, generation: crypto.randomUUID() }))
      })
    },
    async get(taskId) {
      return transaction('readwrite', async tx => {
        await collect(tx)
        const value = await request<TaskRecord | undefined>(tx.objectStore('tasks').get(taskId))
        if (!value) return null
        const { generation: _generation, ...record } = value
        return { ...record, manifest: await request(tx.objectStore('manifests').get(taskId)) }
      })
    },
    async update(taskId, patch) {
      const targetChanged = Object.prototype.hasOwnProperty.call(patch, 'activeTargetId')
      const targetId = patch.activeTargetId
      if (targetChanged && targetId !== undefined && (typeof targetId !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(targetId))) throw new Error('Invalid active target UUID')
      await transaction('readwrite', async tx => {
        const current = await task(tx, taskId)
        writable(current)
        if (patch.state === 'done') throw new Error('Use complete to commit a done receipt')
        const next = { ...current, updatedAt: patch.updatedAt ?? Date.now(),
          ...(patch.state !== undefined ? { state: patch.state } : {}),
          ...(patch.completedBytes !== undefined ? { completedBytes: patch.completedBytes } : {}),
          ...(targetChanged ? { activeTargetId: targetId } : {}) }
        if (next.completedBytes !== undefined) integer(next.completedBytes)
        await request(tx.objectStore('tasks').put(next))
      })
    },
    async info(taskId, blob) {
      const key = blobKey(blob)
      return transaction('readonly', async tx => {
        await task(tx, taskId)
        const value = await blobInfo(tx, taskId, key)
        return value ? { receivedBytes: value.receivedBytes, complete: value.complete, ...metadata(value) } : emptyInfo()
      })
    },
    async reset(taskId, blob, extra) {
      const key = blobKey(blob), meta = metadata(extra)
      await transaction('readwrite', async tx => {
        const current = await task(tx, taskId); writable(current)
        if (current.state === 'sealed') throw new Error('Archive is sealed')
        const chunks = tx.objectStore('chunks')
        await request(chunks.delete(IDBKeyRange.bound([taskId, key, 0], [taskId, key, Number.MAX_SAFE_INTEGER])))
        await request(tx.objectStore('blobs').put({ taskId, blob: key, ...meta, ...emptyInfo(), revision: crypto.randomUUID(), epoch: crypto.randomUUID() }))
        await touch(tx, current)
      })
    },
    async append(taskId, blob, offset, input) {
      integer(offset)
      const key = blobKey(blob), bytes = new Uint8Array(input)
      integer(offset + bytes.length)
      let generation: string | undefined, epoch: string | undefined
      for (;;) {
        const snapshot = await transaction('readonly', async tx => {
          const current = await task(tx, taskId); writable(current)
          const info = await blobInfo(tx, taskId, key)
          const currentEpoch = info?.epoch ?? `initial-${current.generation}`
          generation ??= current.generation; epoch ??= currentEpoch
          if (generation !== current.generation || epoch !== currentEpoch) throw new Error('Cache task or blob was replaced during write')
          const received = info?.receivedBytes ?? 0
          if (offset > received) throw new Error('Non-contiguous cache write')
          if ((info?.complete || current.state === 'sealed') && offset + bytes.length > received) throw new Error('Blob is complete')
          const overlap = Math.min(bytes.length, received - offset)
          return { info, received, overlap, rows: overlap ? await rows(tx, taskId, key, offset, offset + overlap) : [] }
        })
        const prefix = await verified(snapshot.rows, offset, snapshot.overlap)
        if (prefix.some((byte, index) => byte !== bytes[index])) throw new Error('Download cache overlap conflict')
        const additions: ChunkRecord[] = []
        for (let index = snapshot.overlap; index < bytes.length; index += BLOCK) {
          const part = bytes.slice(index, index + BLOCK)
          additions.push({ taskId, blob: key, offset: offset + index, bytes: part, digest: await digest(part) })
        }
        const committed = await transaction('readwrite', async tx => {
          const current = await task(tx, taskId); writable(current)
          const latest = await blobInfo(tx, taskId, key)
          if (current.generation !== generation || (latest?.epoch ?? `initial-${current.generation}`) !== epoch) throw new Error('Cache task or blob was replaced during write')
          if (latest?.revision !== snapshot.info?.revision) return false
          if (current.state === 'sealed' && additions.length) throw new Error('Archive is sealed')
          const receivedBytes = Math.max(snapshot.received, offset + bytes.length)
          if (latest?.totalBytes != null && receivedBytes > latest.totalBytes) throw new Error('Blob exceeds expected size')
          for (const part of additions) await request(tx.objectStore('chunks').add(part))
          await request(tx.objectStore('blobs').put({ ...emptyInfo(), ...latest, taskId, blob: key, receivedBytes, revision: crypto.randomUUID(), epoch }))
          await touch(tx, current)
          return true
        })
        if (committed) return
      }
    },
    async finishBlob(taskId, blob, extra = {}) {
      const key = blobKey(blob), meta = metadata(extra)
      await transaction('readwrite', async tx => {
        const current = await task(tx, taskId); writable(current)
        const value = { ...emptyInfo(), epoch: `initial-${current.generation}`, ...await blobInfo(tx, taskId, key), ...meta }
        if (value.totalBytes != null && value.totalBytes !== value.receivedBytes) throw new Error('Blob size does not match expected total')
        await request(tx.objectStore('blobs').put({ ...value, totalBytes: value.receivedBytes, complete: true, taskId, blob: key, revision: crypto.randomUUID() }))
        await touch(tx, current)
      })
    },
    async read(taskId, blob, offset, limit = BLOCK) {
      integer(offset); integer(limit)
      const key = blobKey(blob)
      const snapshot = await transaction('readonly', async tx => {
        await task(tx, taskId)
        const info = await blobInfo(tx, taskId, key)
        const length = Math.min(limit, Math.max(0, (info?.receivedBytes ?? 0) - offset))
        return { length, chunks: length ? await rows(tx, taskId, key, offset, offset + length) : [] }
      })
      return verified(snapshot.chunks, offset, snapshot.length)
    },
    async saveNames(taskId, offset, names) {
      integer(offset)
      const values = [...names]
      await transaction('readwrite', async tx => {
        const current = await task(tx, taskId); writable(current)
        const records = tx.objectStore('names')
        const existing = await request(records.get([taskId, offset]))
        if (existing && JSON.stringify(existing.names) !== JSON.stringify(values)) throw new Error('Download names batch conflict')
        const batches = await request(records.index('taskId').getAll(taskId))
        for (const batch of batches) {
          const start = Math.max(offset, batch.offset), end = Math.min(offset + values.length, batch.offset + batch.names.length)
          for (let index = start; index < end; index++) if (values[index - offset] !== batch.names[index - batch.offset]) throw new Error('Download names overlap conflict')
        }
        await request(records.put({ taskId, offset, names: values }))
        await touch(tx, current)
      })
    },
    async names(taskId) {
      return transaction('readonly', async tx => {
        await task(tx, taskId)
        const values = await request(tx.objectStore('names').index('taskId').getAll(taskId))
        return Object.fromEntries(values.map(value => [String(value.offset), value.names]))
      })
    },
    async complete(taskId, bytes) {
      integer(bytes)
      await transaction('readwrite', async tx => {
        const current = await task(tx, taskId)
        if (current.state === 'done') { if (current.completedBytes !== bytes) throw new Error('Completion receipt conflict'); return }
        const archive = await blobInfo(tx, taskId, 'archive')
        if (!archive?.complete || archive.receivedBytes !== bytes) throw new Error('Archive is not fully sealed')
        await request(tx.objectStore('tasks').put({ ...current, state: 'done', completedBytes: bytes, updatedAt: Date.now() }))
        await erase(tx, taskId, true)
      })
    },
    async discard(taskId) { await transaction('readwrite', tx => erase(tx, taskId)) },
  }
  return store
}

