const SEARCH_FIELDS = [
  'case_volume_customer', 'app_no', 'case_name', 'case_type', 'apply_type', 'case_status',
  'country', 'business_type', 'apply_name'
] as const

function xmlText(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

function tag(name: string, value = ''): string {
  return `&lt;${name}&gt;${xmlText(value)}&lt;/${name}&gt;`
}

/** 案件查询的 Element。客户案号写入 case_volume_customer。值本身是转义后的 XML，交给表单编码再转一次。 */
export function agencySearchElement(volumes: string[]): string {
  const customerVolumes = volumes.join('\n')
  return tag('case_volume') +
    SEARCH_FIELDS.map(name => tag(name, name === 'case_volume_customer' ? customerVolumes : '')).join('') +
    tag('is_proc', '1') +
    tag('is_finish')
}

export function agencySearchParams(volumes: string[], pageUserId: string, pageIndex: number, pageSize: number): URLSearchParams {
  return new URLSearchParams({
    Call: 'AgencySearchCase',
    Element: agencySearchElement(volumes),
    is_proc: 'false',
    pageSize: String(pageSize),
    pageIndex: String(pageIndex),
    _PK: 'case_id',
    searchKey: '',
    log_pagename: 'CaseList.aspx',
    page_user_id: pageUserId
  })
}

export function patentDataParams(caseId: string): URLSearchParams {
  return new URLSearchParams({
    Call: 'GetPatentData',
    KeyColumn: 'case_id',
    Element: `&lt;p_case_info&gt;${tag('case_id', caseId)}${tag('tech_user_id')}${tag('case_volume')}&lt;/p_case_info&gt;`
  })
}

export function caseInfoParams(caseId: string): URLSearchParams {
  return new URLSearchParams({
    Call: 'GetCaseInfo',
    case_id: caseId,
    log_pagename: 'CaseInfo.aspx'
  })
}

function textOf(row: Record<string, unknown>, key: string, limit: number): string {
  const value = row[key]
  return typeof value === 'string' ? value.trim().slice(0, limit) : ''
}

export function searchHits(data: unknown): { hits: CaseHit[]; total: number } | null {
  if (!isRecord(data)) return null
  if (data.TableRows == null) return { hits: [], total: 0 }
  if (!Array.isArray(data.TableRows)) return null
  const hits: CaseHit[] = []
  for (const row of data.TableRows) {
    if (!isRecord(row)) continue
    const volume = textOf(row, 'case_volume_customer', 80)
    const caseId = textOf(row, 'case_id', 40)
    if (!volume || !isQueryGuid(caseId)) continue
    hits.push({ volume, caseId })
  }
  const first = data.TableRows[0]
  const raw = isRecord(first) ? first.tablerowscount : hits.length
  const total = typeof raw === 'number' || typeof raw === 'string' ? Number(raw) : hits.length
  return { hits, total: Number.isFinite(total) ? total : hits.length }
}

/** 著录项目第一位发明人的邮箱。不读取身份证、手机和地址。 */
export function firstInventorEmail(data: unknown): string {
  if (!isRecord(data) || !Array.isArray(data.Inventors) || !isRecord(data.Inventors[0])) return ''
  return textOf(data.Inventors[0], 'email', 200)
}

export function techUserText(data: unknown): string {
  if (!isRecord(data) || !Array.isArray(data.p_case_info) || !isRecord(data.p_case_info[0])) return ''
  return textOf(data.p_case_info[0], 'tech_user_id_text', 80)
}

/** 导出列是客户案号。著录里没有客户文号时，保留用户贴进来的那一串，不用我方文号替换。 */
export function shownVolume(data: unknown, fallback: string): string {
  if (!isRecord(data) || !Array.isArray(data.p_case_info) || !isRecord(data.p_case_info[0])) return fallback
  return textOf(data.p_case_info[0], 'case_volume_customer', 80) || fallback
}

const REDACTED = '[REDACTED]'
const SENSITIVE_NAME = /token|authorization|password|secret|cookie|credential|session|csrf|xsrf|api[-_]?key/i
const SAFE_ATTRIBUTE = /^(id|name|type|class|role|title|placeholder|autocomplete|maxlength|minlength|min|max|step|pattern|tabindex|hidden|disabled|readonly|required|checked|selected|multiple|aria-[\w-]+|data-[\w-]+)$/i

export { REDACTED }

export function isSensitiveName(value: string): boolean {
  return SENSITIVE_NAME.test(value)
}

/** 仅保留表单语义相关属性；值属性单独处理，避免密码、文件路径泄漏。 */
export function readAttributes(element: Element): {
  attributes: Record<string, string>
  dataset: Record<string, string>
} {
  const attributes: Record<string, string> = Object.create(null)
  const dataset: Record<string, string> = Object.create(null)
  for (const attribute of Array.from(element.attributes)) {
    const name = attribute.name.toLowerCase()
    if (!SAFE_ATTRIBUTE.test(name)) continue
    const value = isSensitiveName(name) ? REDACTED : attribute.value.slice(0, 512)
    attributes[name] = value
    if (name.startsWith('data-')) {
      const key = name.slice(5).replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase())
      Object.defineProperty(dataset, key, { value, enumerable: true, configurable: true })
    }
  }
  return { attributes, dataset }
}

/** URL 的用户名、密码、hash 和敏感查询参数不进入快照。 */
export function sanitizeUrl(raw: string, base?: string): string {
  try {
    const url = new URL(raw, base)
    if (url.protocol === 'data:' || url.protocol === 'javascript:') return `${url.protocol}[REDACTED]`
    url.username = ''
    url.password = ''
    url.hash = ''
    for (const key of Array.from(url.searchParams.keys())) {
      if (isSensitiveName(key) || /^(code|auth|access_key)$/i.test(key)) url.searchParams.set(key, REDACTED)
    }
    return base && raw.startsWith('/') && !raw.startsWith('//') ? `${url.pathname}${url.search}` : url.href
  } catch {
    return '[INVALID URL]'
  }
}

import type { FormControlKind, FormControlSnapshot, SelectOptionSnapshot } from '../shared/types'
import { isSensitiveName, readAttributes, REDACTED } from './attribute-reader'
import { explicitLabel, nearbyLabel } from './label-resolver'
import { resolveSemantic } from './semantic-resolver'

type NativeControl = HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement | HTMLButtonElement

type DomConstructors = {
  HTMLInputElement: typeof HTMLInputElement
  HTMLTextAreaElement: typeof HTMLTextAreaElement
  HTMLSelectElement: typeof HTMLSelectElement
  HTMLButtonElement: typeof HTMLButtonElement
}

/** iframe 里的控件属于子文档的构造函数。Window 类型本身不声明这些构造函数。 */
function realm(element: Element): DomConstructors {
  return (element.ownerDocument.defaultView ?? window) as unknown as DomConstructors
}

export function isInputElement(element: Element): element is HTMLInputElement {
  return element instanceof realm(element).HTMLInputElement
}

function isTextAreaElement(element: Element): element is HTMLTextAreaElement {
  return element instanceof realm(element).HTMLTextAreaElement
}

function isSelectElement(element: Element): element is HTMLSelectElement {
  return element instanceof realm(element).HTMLSelectElement
}

function isButtonElement(element: Element): element is HTMLButtonElement {
  return element instanceof realm(element).HTMLButtonElement
}

function controlKind(element: NativeControl): FormControlKind {
  if (isTextAreaElement(element)) return 'textarea'
  if (isSelectElement(element)) return 'select'
  if (isButtonElement(element)) return 'button'
  return 'input'
}

function sensitiveControl(element: NativeControl): boolean {
  return (isInputElement(element) && ['password', 'file', 'hidden'].includes(element.type)) ||
    [element.id, element.getAttribute('name') ?? '', element.getAttribute('autocomplete') ?? ''].some(isSensitiveName)
}

function optionsOf(element: HTMLSelectElement, redact: boolean): SelectOptionSnapshot[] {
  return Array.from(element.options).map(option => ({
    value: redact ? REDACTED : option.value,
    text: redact ? REDACTED : option.text.trim(),
    selected: option.selected,
    disabled: option.disabled || Boolean(option.closest('optgroup[disabled]'))
  }))
}

/** 不长期保存 DOM 引用；key 用同次扫描中的序号消除重复 id/name 冲突。 */
export function scanControl(element: NativeControl, index: number, visible: boolean): FormControlSnapshot {
  const kind = controlKind(element)
  const redact = sensitiveControl(element)
  const label = explicitLabel(element)
  const nearby = label ? undefined : nearbyLabel(element)
  const id = element.id || undefined
  const name = element.getAttribute('name') || undefined
  const placeholder = isInputElement(element) || isTextAreaElement(element)
    ? element.placeholder || undefined : undefined
  const ariaLabel = element.getAttribute('aria-label') || undefined
  const title = element.title || undefined
  const options = isSelectElement(element) ? optionsOf(element, redact) : undefined
  const rawValue = redact ? REDACTED : isButtonElement(element)
    ? element.value || element.textContent?.trim() || '' : element.value
  const displayValue = redact ? REDACTED : isSelectElement(element)
    ? Array.from(element.selectedOptions).map(option => option.text.trim()).join(', ') :
      isButtonElement(element) ? element.textContent?.trim() || element.value :
        isInputElement(element) && element.type === 'image' ? element.alt || element.value : rawValue
  const { attributes, dataset } = readAttributes(element)
  const semantic = resolveSemantic([
    { value: label, source: 'label', confidence: 1 },
    { value: ariaLabel, source: 'aria', confidence: 0.9 },
    { value: title, source: 'title', confidence: 0.8 },
    { value: placeholder, source: 'placeholder', confidence: 0.7 },
    { value: nearby, source: 'nearby', confidence: 0.6 },
    { value: name, source: 'name', confidence: 0.4 },
    { value: id, source: 'id', confidence: 0.3 }
  ])
  return {
    key: `${kind}:${id ?? name ?? 'anonymous'}:${index}`,
    tagName: element.tagName.toLowerCase(), kind,
    ...(isInputElement(element) ? { inputType: element.type } : {}),
    id, name, value: rawValue, displayValue, placeholder, title, label: label ?? nearby, ariaLabel,
    role: element.getAttribute('role') || undefined,
    classNames: Array.from(element.classList), visible,
    disabled: element.disabled || element.matches(':disabled'),
    readonly: (isInputElement(element) || isTextAreaElement(element)) && element.readOnly,
    required: !isButtonElement(element) && element.required,
    ...(isInputElement(element) && ['checkbox', 'radio'].includes(element.type) ? { checked: element.checked } : {}),
    ...(isSelectElement(element) ? { selected: element.selectedOptions.length > 0, multiple: element.multiple, options } : {}),
    attributes, dataset, ...semantic
  }
}

export function isNativeControl(element: Element): element is NativeControl {
  return isInputElement(element) || isTextAreaElement(element) || isSelectElement(element) || isButtonElement(element)
}

