const pageWorld = globalThis as typeof globalThis & { __patmailContent?: boolean }
if (!pageWorld.__patmailContent) {
  pageWorld.__patmailContent = true

  // Popup 发给当前顶层页面；返回 true 保持异步响应通道存活。
  chrome.runtime.onMessage.addListener((message: unknown, sender, sendResponse) => {
    if (sender.id !== chrome.runtime.id) return
    if (!isContentRequest(message)) {
      const type = message && typeof message === 'object' && 'type' in message ? String((message as { type?: unknown }).type) : '未知'
      sendResponse({ type: MessageType.Error, payload: { message: `当前 EASY 页面脚本不认识 ${type}。请刷新这个 EASY 标签页。` } } satisfies ContentResponse)
      return
    }
    if (message.type === MessageType.DownloadFiles && message.payload.detached && message.payload.progressId) {
      const id = message.payload.progressId
      const publish = (body: ContentResponse): void => {
        try { chrome.runtime.sendMessage({ channel: DOWNLOAD_RESULT_CHANNEL, id, body }, () => { void chrome.runtime.lastError }) } catch { /* 工作台可关闭，浏览器下载已独立交接 */ }
      }
      sendResponse({ type: MessageType.DownloadFilesAccepted, payload: { progressId: id } } satisfies ContentResponse)
      void bridge.request(message).then(publish).catch(() => publish({ type: MessageType.Error, payload: { message: '下载准备失败，请检查原站页面。' } }))
      return
    }
    void bridge.request(message).then(sendResponse).catch(() => {
      sendResponse({ type: MessageType.Error, payload: { message: '页面读取失败，请刷新后重试。' } } satisfies ContentResponse)
    })
    return true
  })

  let pagePort: chrome.runtime.Port | null = null
  let pagePulse = 0
  function holdBackground(): void {
    if (!chrome.runtime?.id || pagePort) return
    try {
      const port = chrome.runtime.connect({ name: 'patmail-page' })
      pagePort = port
      pagePulse = window.setInterval(() => {
        try { port.postMessage({ kind: 'tick' }) } catch { /* 端口已断，等 onDisconnect 重连 */ }
      }, 20_000)
      port.onDisconnect.addListener(() => {
        void chrome.runtime.lastError
        window.clearInterval(pagePulse)
        if (pagePort === port) pagePort = null
        window.setTimeout(holdBackground, 500)
      })
    } catch { /* 扩展刚重新加载，等页面再次可见 */ }
  }
  holdBackground()
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') holdBackground()
  })
}

// 正式入口是完整工作台。浮窗只在收到 SHOW_PANEL 时挂载。

import type { EasyTransport } from '../api/transport'
import { isRecord, readClientInfo } from '../api/response-guards'
import { listParams, readTableRows } from '../mail/easy/contracts'
import { isQueryGuid } from '../query/query-validator'

const DEPT_LABEL = '所属部门'
const DEPT_MARK = '研发本部'
const DESC = '文件描述'
const INVENTOR = '发明人'
const VOLUME = '我方案号'
const INVENTOR_PAGE = 10
const INVENTOR_PAGES = 20

export function departmentIncludesRnd(value: string): boolean {
  return value.includes(DEPT_MARK)
}

/** 按序号把发明人姓名拼成顿号分隔。空姓名丢掉，同名只留先出现的。 */
export function inventorNames(rows: Array<{ name: string; seq: number }>): string {
  const ordered = rows
    .map(row => ({ name: row.name.trim(), seq: row.seq }))
    .filter(row => row.name)
    .sort((left, right) => left.seq - right.seq)
  const seen = new Set<string>()
  const names: string[] = []
  for (const row of ordered) {
    if (seen.has(row.name)) continue
    seen.add(row.name)
    names.push(row.name)
  }
  return names.join('、')
}

function decode(value: string): string {
  return value
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#(\d+);/g, (_, code: string) => String.fromCodePoint(Number(code)))
    .replace(/&amp;/gi, '&')
}

function cellPlain(cell: string): string {
  return decode(cell.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim()
}

function escapeCell(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

function openTag(cell: string): string {
  return cell.match(/^<td\b[^>]*>/i)?.[0] ?? '<td>'
}

function withText(cell: string, text: string): string {
  return `${openTag(cell)}${escapeCell(text)}</td>`
}

function cellsOf(row: string): string[] {
  return [...row.matchAll(/<td\b[^>]*>[\s\S]*?<\/td>/gi)].map(item => item[0])
}

function rebuildRow(row: string, cells: string[]): string {
  const open = row.match(/^<tr\b[^>]*>/i)?.[0] ?? '<tr>'
  return `${open}${cells.join('')}</tr>`
}

/**
 * 在发文类型带出的表格上，于「文件描述」右侧放入「发明人」。
 * 已有这一列时只填格子。没有「我方案号」或「文件描述」时原样返回。
 */
export function insertInventorColumn(html: string, namesByVolume: ReadonlyMap<string, string>): string {
  if (!namesByVolume.size || !/<table\b/i.test(html)) return html
  const tables = [...html.matchAll(/<table\b[^>]*>[\s\S]*?<\/table>/gi)]
  for (const table of tables) {
    const source = table[0]
    const rows = [...source.matchAll(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi)].map(item => item[0])
    const parsed = rows.map(row => ({ row, cells: cellsOf(row) }))
    const header = parsed.find(item => item.cells.some(cell => cellPlain(cell) === DESC))
    if (!header) continue
    const descIndex = header.cells.findIndex(cell => cellPlain(cell) === DESC)
    const volumeIndex = header.cells.findIndex(cell => cellPlain(cell) === VOLUME)
    if (descIndex < 0 || volumeIndex < 0) continue
    const already = cellPlain(header.cells[descIndex + 1] ?? '') === INVENTOR
    const nextRows = parsed.map(item => {
      const cells = item.cells.slice()
      if (!cells.length) return item.row
      const volume = cellPlain(cells[volumeIndex] ?? '')
      const names = namesByVolume.get(volume) ?? ''
      if (item === header) {
        if (!already) cells.splice(descIndex + 1, 0, withText(cells[descIndex] ?? '<td>', INVENTOR))
        return rebuildRow(item.row, cells)
      }
      const styleFrom = cells[descIndex] ?? '<td>'
      if (!already) cells.splice(descIndex + 1, 0, withText(styleFrom, names))
      else if (names) cells[descIndex + 1] = withText(cells[descIndex + 1] ?? styleFrom, names)
      return rebuildRow(item.row, cells)
    })
    let cursor = 0
    const rebuilt = source.replace(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi, () => nextRows[cursor++] ?? '')
    return html.replace(source, rebuilt)
  }
  return html
}

function textField(row: Record<string, unknown>, key: string): string {
  const value = row[key]
  return typeof value === 'string' ? value.trim() : ''
}

async function departmentColumn(transport: EasyTransport): Promise<{ ok: true; columnId: string } | { ok: false; message: string }> {
  const params = new URLSearchParams()
  params.set('Call', 'GetCustomField')
  params.set('table_name', 'p_case_info')
  params.set('log_pagename', 'CaseManage.aspx')
  const loaded = await transport.post('caseCustomField', params)
  if (!loaded.ok) return { ok: false, message: '所属部门没有读到，发明人列没有加。' }
  if (!isRecord(loaded.data)) return { ok: false, message: '所属部门没有读到，发明人列没有加。' }
  const client = readClientInfo(loaded.data.ClientInfo)
  if (!client.ok || client.data.IsLogin === false) return { ok: false, message: '读取所属部门时登录已失效。' }
  if (!Array.isArray(loaded.data.column_field_list)) return { ok: false, message: '所属部门没有读到，发明人列没有加。' }
  const hit = loaded.data.column_field_list.find(row => isRecord(row) && textField(row, 'column_name') === DEPT_LABEL && /^column_\d+$/.test(textField(row, 'column_id')))
  if (!isRecord(hit)) return { ok: false, message: '案件上没有名为所属部门的栏位，发明人列没有加。' }
  return { ok: true, columnId: textField(hit, 'column_id') }
}

async function caseDepartment(transport: EasyTransport, caseId: string, columnId: string): Promise<{ ok: true; value: string } | { ok: false; message: string }> {
  const params = new URLSearchParams()
  params.set('Call', 'GetCaseInfo')
  params.set('case_id', caseId)
  params.set('log_pagename', 'CaseManage.aspx')
  const loaded = await transport.post('caseManageInfo', params)
  if (!loaded.ok) return { ok: false, message: '所属部门没有读到，发明人列没有加。' }
  if (!isRecord(loaded.data)) return { ok: false, message: '所属部门没有读到，发明人列没有加。' }
  const client = readClientInfo(loaded.data.ClientInfo)
  if (!client.ok || client.data.IsLogin === false) return { ok: false, message: '读取所属部门时登录已失效。' }
  const row = Array.isArray(loaded.data.CaseInfo) ? loaded.data.CaseInfo.find(isRecord) : undefined
  if (!row) return { ok: false, message: '所属部门没有读到，发明人列没有加。' }
  return { ok: true, value: textField(row, columnId) }
}

async function caseInventors(transport: EasyTransport, caseId: string): Promise<{ ok: true; names: string } | { ok: false; message: string }> {
  const rows: Array<{ name: string; seq: number }> = []
  const seen = new Set<string>()
  for (let page = 1; page <= INVENTOR_PAGES; page += 1) {
    const params = new URLSearchParams()
    params.set('Call', 'GetCaseInventor')
    params.set('apply_id', caseId)
    params.set('pageSize', String(INVENTOR_PAGE))
    params.set('pageIndex', String(page))
    params.set('_PK', 'inventor_id')
    params.set('searchKey', '')
    params.set('colsel', ';code;inventor_name_cn;seq;inventor_id;')
    params.set('log_pagename', 'CaseManage.aspx')
    const loaded = await transport.post('caseInventor', params)
    if (!loaded.ok) return { ok: false, message: '发明人没有读到，没有提交。' }
    if (!isRecord(loaded.data)) return { ok: false, message: '发明人没有读到，没有提交。' }
    const client = readClientInfo(loaded.data.ClientInfo)
    if (!client.ok || client.data.IsLogin === false) return { ok: false, message: '读取发明人时登录已失效。' }
    if (loaded.data.TableRows === null) break
    if (!Array.isArray(loaded.data.TableRows)) return { ok: false, message: '发明人没有读到，没有提交。' }
    for (const row of loaded.data.TableRows) {
      if (!isRecord(row)) continue
      const id = textField(row, 'inventor_id').toLowerCase()
      if (id && seen.has(id)) continue
      if (id) seen.add(id)
      const seq = Number(textField(row, 'seq'))
      rows.push({ name: textField(row, 'inventor_name_cn'), seq: Number.isFinite(seq) ? seq : Number.MAX_SAFE_INTEGER })
    }
    if (loaded.data.TableRows.length < INVENTOR_PAGE) break
  }
  return { ok: true, names: inventorNames(rows) }
}

async function mailCases(transport: EasyTransport, mailId: string): Promise<{ ok: true; cases: Array<{ id: string; volume: string }> } | { ok: false; message: string }> {
  const cases: Array<{ id: string; volume: string }> = []
  for (let page = 1; page <= 5; page += 1) {
    const loaded = await transport.post('getMailCase', listParams('GetMailCase', mailId, page))
    if (!loaded.ok) return { ok: false, message: '发文上的案件没有读到，发明人列没有加。' }
    const parsed = readTableRows(loaded.data, 'case_id', 'case_volume')
    if (parsed.state === 'invalid') return { ok: false, message: '发文上的案件没有读到，发明人列没有加。' }
    if (parsed.state !== 'known') break
    for (const row of parsed.rows) {
      if (!isQueryGuid(row.id) || !row.name.trim()) continue
      cases.push({ id: row.id, volume: row.name.trim() })
    }
    const reached = parsed.total !== null && cases.length >= parsed.total
    if (reached || parsed.rows.length < 100) break
  }
  return { ok: true, cases }
}

/** 所属部门包含研发本部的案件，把全部发明人写进正文表格。读不到时不改正文，登录失效才停住。 */
export async function bodyWithRndInventors(transport: EasyTransport, mailId: string, html: string): Promise<{ ok: true; html: string; note: string } | { ok: false; message: string }> {
  if (!html.includes(DESC)) return { ok: true, html, note: '' }
  const cases = await mailCases(transport, mailId)
  if (!cases.ok) return cases.message.includes('登录') ? { ok: false, message: cases.message } : { ok: true, html, note: cases.message }
  if (!cases.cases.length) return { ok: true, html, note: '' }
  const column = await departmentColumn(transport)
  if (!column.ok) return column.message.includes('登录') ? { ok: false, message: column.message } : { ok: true, html, note: column.message }
  const names = new Map<string, string>()
  for (const item of cases.cases) {
    const dept = await caseDepartment(transport, item.id, column.columnId)
    if (!dept.ok) return dept.message.includes('登录') ? { ok: false, message: dept.message } : { ok: true, html, note: dept.message }
    if (!departmentIncludesRnd(dept.value)) continue
    const inventors = await caseInventors(transport, item.id)
    if (!inventors.ok) return { ok: false, message: `文号 ${item.volume} 的${inventors.message}` }
    names.set(item.volume, inventors.names)
  }
  if (!names.size) return { ok: true, html, note: '' }
  return { ok: true, html: insertInventorColumn(html, names), note: '所属部门包含研发本部的案件，已在文件描述右侧写入全部发明人。' }
}

import { pctRowsFromTable, type CarryMode } from './pct-sheet'
import { sheetDisplayName } from './pct-recipients'
import type { PctRuntimeConfig } from '../workflow/pct-config'
import type { PctTaskRow } from './types'
import type { XlsxSheet } from './xlsx-table'

export interface PctWorkbookRead {
  rows: PctTaskRow[]
  notice: string
  /** 补完上一行之后 IPR 仍是空的。交给助手仲裁。 */
  gaps: PctTaskRow[]
}

function isDetailSheet(name: string): boolean {
  return name.includes('处理细节')
}

function isNationalSheet(name: string): boolean {
  return name.includes('进国家')
}

function isRemindSheet(name: string): boolean {
  return name.includes('提醒申请PCT') && !isDetailSheet(name)
}

/** 导入时只解开这几张。期限监控和图片不读，避免大表把页面卡住。对不上名字时仍读第一张。 */
export function isPctWorkbookSheet(name: string): boolean {
  return isRemindSheet(name) || isNationalSheet(name) || isDetailSheet(name)
}

function shortCustomer(name: string): string {
  let text = name.trim()
  const suffixes = ['股份有限公司', '有限责任公司', '有限公司', '股份', '集团']
  let changed = true
  while (changed) {
    changed = false
    for (const suffix of suffixes) {
      if (text.endsWith(suffix) && text.length - suffix.length >= 2) {
        text = text.slice(0, -suffix.length)
        changed = true
      }
    }
  }
  return text
}

/** 处理细节表里的原话。图片公式和纯数字不拿来对客户。 */
export function detailLines(table: string[][]): string[] {
  const lines: string[] = []
  for (const row of table) {
    const text = row
      .map(cell => cell.trim())
      .filter(cell => cell && !cell.startsWith('=DISPIMG') && !/^\d+(\.\d+)?$/.test(cell))
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim()
    if (text) lines.push(text.slice(0, 500))
  }
  return lines
}

function nameHits(token: string, key: string): boolean {
  const cleaned = token.replace(/不用发/g, '').replace(/[（(].*$/, '').trim()
  return cleaned.split(/[-—]/).map(shortCustomer).some(name => name.length >= 2 && (name === key || key.startsWith(name) || name.startsWith(key)))
}

function headMention(text: string, head: string): boolean {
  let from = 0
  while (from <= text.length - head.length) {
    const at = text.indexOf(head, from)
    if (at < 0) return false
    const before = at === 0 ? '' : text[at - 1] ?? ''
    const rest = text.slice(at + head.length)
    const boundaryBefore = at === 0 || /[\s，,、。；;：:（(]/.test(before)
    const boundaryAfter = rest === '' || /^[\s，,、。；;：:（()）]/.test(rest) || /^(?:提醒|收件|主送|不用)/.test(rest)
    if (boundaryBefore && boundaryAfter) return true
    from = at + head.length
  }
  return false
}

function mentionsCustomer(text: string, key: string): boolean {
  if (key.length < 2) return false
  if (text.includes(key)) return true
  if (text.split(/[、,，]/).some(piece => nameHits(piece, key))) return true
  const longest = Math.min(key.length - 1, 4)
  for (let size = longest; size >= 2; size -= 1) {
    if (headMention(text, key.slice(0, size))) return true
  }
  return false
}

function ownBits(line: string, key: string): string[] {
  return line.split(/[。；;\n]/).flatMap(sentence => sentence.split(/[，,]/)).map(bit => bit.trim()).filter(bit => mentionsCustomer(bit, key))
}

function cleanPerson(raw: string): string {
  const text = sheetDisplayName(raw.replace(/<[^>]*>/g, '').replace(/@[^\s]+/g, '')).replace(/\s*[（(][^）)]{1,12}[）)]\s*$/, '').trim()
  if (!text || text.length > 12) return ''
  if (/不用发|处理细节|每个月|统一|IPR|商务|主送|抄送|提醒/.test(text)) return ''
  return text
}

function personIn(bit: string): string {
  const match = bit.match(/(?:收件人|主送)\s*[:：]\s*([^\s<,，;；、]{1,20})/)
  return match ? cleanPerson(match[1]) : ''
}

function inventorFor(line: string, key: string): boolean {
  return line.split(/[。；;\n]/).some(sentence => {
    if (!sentence.includes('发明人') || !mentionsCustomer(sentence, key)) return false
    const bits = sentence.split(/[，,]/).map(bit => bit.trim())
    return bits.some((bit, index) => {
      if (!bit.includes('发明人')) return false
      const near = bits.slice(Math.max(0, index - 1), index + 1).join('')
      return mentionsCustomer(bit, key) || mentionsCustomer(near, key)
    })
  })
}

function skipped(line: string, key: string): boolean {
  return line.split(/[。；;\n]/).some(sentence => {
    if (!sentence.includes('不用发')) return false
    const bit = sentence.split(/[，,]/).find(item => item.includes('不用发')) ?? ''
    return mentionsCustomer(bit, key)
  })
}

/** 从处理细节里只取出裁决：人名、不用发，或发明人。拿不准就留空，不把原话塞进收件人。 */
export function arbitrateDetail(customerName: string, lines: readonly string[]): string {
  const key = shortCustomer(customerName)
  if (key.length < 2) return ''
  const hits = lines.filter(line => mentionsCustomer(line, key))
  for (const line of hits) {
    for (const bit of ownBits(line, key)) {
      const person = personIn(bit)
      if (person) return person
    }
  }
  if (hits.some(line => skipped(line, key))) return '不用发'
  if (hits.some(line => inventorFor(line, key))) return '发明人'
  return ''
}

export function noteForBlankIpr(customerName: string, lines: readonly string[]): string {
  const key = shortCustomer(customerName)
  const hits = key.length >= 2 ? lines.filter(line => line.includes(key)).slice(0, 2) : []
  if (!hits.length) return '上一行也没有 IPR。要到案件要求里核对，拿不准交给助手仲裁。'
  const text = hits.join(' ')
  const clip = text.length > 600 ? `${text.slice(0, 600)}…` : text
  if (text.includes('发明人')) return `处理细节要看发明人。表格里没有，到案件页发明人里核对。${clip}`.slice(0, 800)
  return `处理细节：${clip}`.slice(0, 800)
}

function withDetailNotes(rows: PctTaskRow[], lines: readonly string[]): PctTaskRow[] {
  return rows.map(row => {
    if (row.iprName.trim()) return row
    const decided = arbitrateDetail(row.customerName, lines)
    if (decided) return { ...row, iprName: decided, iprArbitrated: true as const }
    return { ...row, iprNote: noteForBlankIpr(row.customerName, lines) }
  })
}

/**
 * 一次读提醒申请 PCT 和进国家两张表。
 * 没有这两张名字时，仍只读第一张，跟以前的单表一样。
 * 处理细节不进发文行，只用来给空着的 IPR 摘一句。
 */
export function pctRowsFromWorkbook(
  sheets: XlsxSheet[],
  mailTypes: Array<{ id: string; name: string }> = [],
  config?: PctRuntimeConfig,
  carry: CarryMode = 'block'
): PctWorkbookRead {
  const detail = sheets.find(sheet => isDetailSheet(sheet.name))
  const namedRemind = sheets.filter(sheet => isRemindSheet(sheet.name))
  const namedNational = sheets.filter(sheet => isNationalSheet(sheet.name))
  const named = namedRemind.length + namedNational.length > 0
  const remindSheets = named ? namedRemind : sheets.filter(sheet => !isDetailSheet(sheet.name)).slice(0, 1)
  const nationalSheets = named ? namedNational : []
  const parts = [
    ...remindSheets.map(sheet => pctRowsFromTable(sheet.rows, mailTypes, config, 'remind', carry)),
    ...nationalSheets.map(sheet => pctRowsFromTable(sheet.rows, mailTypes, config, 'national', carry))
  ]
  const merged = parts.flatMap(part => part.rows).slice(0, 5000)
  const noted = withDetailNotes(merged, detail ? detailLines(detail.rows) : [])
  const gaps = noted.filter(row => !row.iprName.trim())
  const decided = noted.filter(row => row.iprArbitrated).length
  const remindCount = noted.filter(row => row.letterKind !== 'national' && row.letterKind !== 'design').length
  const nationalCount = noted.filter(row => row.letterKind === 'national' || row.letterKind === 'design').length
  const hiddenRows = [...remindSheets, ...nationalSheets].reduce((sum, sheet) => sum + (sheet.hiddenRows ?? 0), 0)
  const notice = [
    named ? `提醒申请 PCT ${remindCount} 行，进国家 ${nationalCount} 行。` : '',
    hiddenRows ? `表格有筛选，隐藏的 ${hiddenRows} 行没有导入，导出也只含可见行。` : '',
    parts.map(part => part.notice).filter(Boolean).join(''),
    gaps.length ? `${gaps.length} 行 IPR 仍是空的，可以交给助手。` : '',
    decided ? `处理细节裁了 ${decided} 行，收件人后面标（仲）。` : ''
  ].filter(Boolean).join('')
  return { rows: noted, notice, gaps }
}

/** 本地模型一轮能扛住的仲裁条数。原文越长、剩下越多，一次越少。 */
export function arbitrationBatchSize(notes: readonly string[]): number {
  const count = notes.length
  if (count <= 1) return count
  const longest = notes.reduce((max, note) => Math.max(max, note.trim().length), 0)
  let size = longest >= 120 ? 1 : longest >= 40 ? 2 : 3
  if (count >= 40) size = Math.min(size, 2)
  if (count >= 80) size = 1
  return Math.min(size, count)
}

interface ArbitrationUnit {
  customer: string
  rows: PctTaskRow[]
  note: string
}

function sheetFieldLine(row: PctTaskRow): string {
  const fields = [
    `我方文号 ${row.ourVolume.trim() || '空'}`,
    `客户文号 ${row.customerVolume.trim() || '空'}`,
    `客户名称 ${row.customerName.trim() || '空'}`,
    `第一客户联系人 ${row.contactName.trim() || '空'}`,
    `IPR ${row.iprName.trim() || '空'}`,
    ...(row.leadName?.trim() ? [`技术负责人 ${row.leadName.trim()}`] : []),
    `处理事项 ${row.procLabel.trim() || '空'}`,
    `发文类型 ${row.mailTypeLabel.trim() || '空'}`,
    `处理细节 ${row.iprNote?.trim() || '没有'}`
  ]
  return fields.join('，')
}

function clipDemand(text: string | undefined): string {
  const clean = text?.trim() ?? ''
  if (!clean) return '插件没有读到这位客户的客户信息。'
  return clean.length > 4000 ? `${clean.slice(0, 3999)}…` : clean
}

function clipCase(text: string | undefined): string {
  const clean = text?.trim() ?? ''
  if (!clean) return '著录项目：这一文号没有读到。'
  const body = clean.length > 1500 ? `${clean.slice(0, 1500)}…` : clean
  return `著录项目：\n${body}`
}

function arbitrationUnits(rows: readonly PctTaskRow[]): ArbitrationUnit[] {
  const order: string[] = []
  const grouped = new Map<string, ArbitrationUnit>()
  for (const row of rows) {
    if (row.iprName.trim()) continue
    const customer = row.customerName.trim()
    const key = customer || `行:${row.ourVolume}`
    const found = grouped.get(key)
    if (found) {
      found.rows.push(row)
      if (!found.note && row.iprNote?.trim()) found.note = row.iprNote.trim()
      continue
    }
    order.push(key)
    grouped.set(key, { customer: customer || '未写', rows: [row], note: row.iprNote?.trim() || '' })
  }
  return order.flatMap(key => {
    const unit = grouped.get(key)
    return unit ? [unit] : []
  })
}

function unitBlock(unit: ArbitrationUnit, demands: Readonly<Record<string, string>>, cases: Readonly<Record<string, string>>): string {
  const lines = unit.rows.map(row => {
    const volume = row.ourVolume.trim() || row.customerVolume.trim()
    return `- ${sheetFieldLine(row)}\n${clipCase(cases[volume])}`
  })
  return [`客户 ${unit.customer}`, `客户信息：\n${clipDemand(demands[unit.customer])}`, '表格字段：', ...lines].join('\n')
}

function splitOversized(unit: ArbitrationUnit, demands: Readonly<Record<string, string>>, cases: Readonly<Record<string, string>>): ArbitrationUnit[] {
  if (unitBlock(unit, demands, cases).length <= 9000) return [unit]
  const pieces: ArbitrationUnit[] = []
  let bucket: PctTaskRow[] = []
  for (const row of unit.rows) {
    const next = unitBlock({ ...unit, rows: [...bucket, row] }, demands, cases)
    if (bucket.length && next.length > 9000) {
      pieces.push({ ...unit, rows: bucket })
      bucket = [row]
    } else {
      bucket.push(row)
    }
  }
  if (bucket.length) pieces.push({ ...unit, rows: bucket })
  return pieces
}

export interface ArbitrationOptions {
  /** 客户要求没写发给谁时，允许仲裁把著录项目或表格里的技术联系人写成收件人。默认关：这类行拿不准留空，交给「全选联系人」。 */
  iprOnly?: boolean
}

function mailKindLine(): string {
  return '这批是提醒申请 PCT 或 PCT 进国家。先看有没有单独点名这封提醒的句子，没有再用「所有邮件」「官文转达」「流程事务」「提醒」。初稿、检索、看稿、年费、办登、撰稿时限、总委和地址都不是这封信的收件人。下面几条都只看客户要求原文，著录项目里列出的人名本身不是要求。要求写了不发 PCT 提醒、不用发这种提醒、不用发涉外提醒的，整行写成：客户文号 我方文号｜不用发｜依据 一句。这条优先于同客户的主送技术联系人和所有邮件。要求单独写了 PCT 提醒、提醒 PCT、进国家提醒或国家提醒发给谁，就用那一条的人，身份按这一行著录项目写，不要改成只发业务。要求原文写了所有邮件只发业务或商务、不要发给客户、无需再发送给客户，或者原文点名的人在这一行里只是业务人员，整行写成：客户文号 我方文号｜只发业务｜依据 一句。著录项目里只有业务人员、客户要求又没指定发给谁，不是只发业务。所有邮件只发某个技术联系人、IPR 或客户联系人时，写这个人，不要写成只发业务。不要把业务员姓名写成收件人或抄送。要求说按案件备注发文时，用这一行著录项目里的案件备注；备注没有人名、又写了改主送负责人的，用这一行的公司负责人，身份写客户联系人；都对不上就拿不准。要求说主送第一申请人的 IPR 时，用著录项目里对上该申请人的联系人，身份写 IPR，对不上就拿不准。只有客户要求原文写了主送技术联系人时，才用这一行著录项目里的技术联系人，同客户别的案子的人不能拿来用。著录项目里有技术联系人，不等于客户要求主送技术联系人。不用发和只发业务不要写成拿不准，也不要写身份。'
}

function priorityLine(iprOnly: boolean): string {
  if (iprOnly) {
    return '优先级：1. 上面已经判成不用发或只发业务的，保持那种写法。其余客户要求里明确写了发给谁、抄送谁，就按要求。收件人和抄送都可以是 IPR、发明人、客户联系人的任意组合。2. 客户要求没有指定收件人时，收件人只写著录项目或表格里的技术联系人，身份写 IPR。著录项目里仅仅列出来的发明人、客户联系人，不是发信要求。3. 没有明确要求，也没有技术联系人时，这一行写成拿不准，收件人留空。不要用客户联系人名单、技术负责人或商务去顶。'
  }
  return '优先级：1. 上面已经判成不用发或只发业务的，保持那种写法，不要改成拿不准。其余客户要求里明确写了发给谁、抄送谁，就按要求写全，不要因为本批的兜底规则而漏写。收件人和抄送都可以是 IPR、发明人、客户联系人的任意组合，客户要求点名了技术联系人也照样写。2. 只有客户要求没有指定收件人时，这一行直接写成拿不准，收件人留空，提交时用「全选联系人」兜底。依据只写「客户要求没有指定发给谁」一句。著录项目或表格里即使有技术联系人，也不要写成收件人，不要写「按著录项目主送技术联系人」，不要把著录项目里有没有联系人写进依据，也不要用发明人、客户联系人名单、技术负责人或商务来顶。'
}

function waveMessage(units: readonly ArbitrationUnit[], index: number, total: number, demands: Readonly<Record<string, string>>, cases: Readonly<Record<string, string>>, options: Readonly<ArbitrationOptions> = {}): string {
  const blocks = units.map(unit => unitBlock(unit, demands, cases))
  const text = [
    `请仲裁收件人和抄送。这是第 ${index}/${total} 批。材料只有下面这些文字：每一行的表格字段，以及核对时已经暂存的客户要求和著录项目。`,
    '每一行单独裁。第一客户联系人不同的，不能收成同一个人，也不能用一条结论盖住同客户的全部文号。',
    'IPR 就是技术联系人。身份只能是：发明人、客户联系人、IPR。多人用顿号，身份与人名一一对应。',
    '不要写商务、登录人、登陆人、密送、技术负责人。抄送商务、抄送登录人、密送登录人由系统在提交时默认追加。仲裁写了也会被丢掉，写抄送无也不会取消这些默认项。',
    mailKindLine(),
    priorityLine(options.iprOnly === true) + '抄送只写第 1 条里额外要点名的人，没有就写无。',
    '每一行只写一行，用竖线分开，文号原样照抄。没有客户文号就写空。不要加尖括号，不要解释，不要写英文：',
    '客户文号 我方文号｜事项 表格处理事项原样照抄｜收件人 人名｜身份 身份｜抄送 人名或无｜抄送身份 身份或无｜依据 一句简体中文',
    '拿不准的行写成：客户文号 我方文号｜事项 表格处理事项原样照抄｜拿不准｜依据 一句简体中文。依据写完立刻换行。不要把身份写进人名括号。',
    '同一文号在表里出现两行时，两行各写一条，事项列写各自的处理事项，不要合并成一条。',
    '不要调用工具，不要构造接口，不要自己去查，不要创建任务，不要让用户挑选。裁完这一批就停，不要写思考过程。',
    ...blocks
  ].join('\n\n')
  return text.length > 18000 ? `${text.slice(0, 18000)}\n（后面的原文被截断了。）` : text
}

/** 空 IPR 按客户合并后再分批。一批一次交给本地模型。客户信息和著录项目用核对时暂存的文字，写进原文。 */
export function iprArbitrationWaves(
  rows: readonly PctTaskRow[],
  demands: Readonly<Record<string, string>> = {},
  cases: Readonly<Record<string, string>> = {},
  options: Readonly<ArbitrationOptions> = {}
): string[] {
  const units = arbitrationUnits(rows).flatMap(unit => splitOversized(unit, demands, cases))
  const waves: ArbitrationUnit[][] = []
  let rest = units
  while (rest.length) {
    const size = arbitrationBatchSize(rest.map(unit => unit.note))
    waves.push(rest.slice(0, size))
    rest = rest.slice(size)
  }
  return waves.map((wave, index) => waveMessage(wave, index + 1, waves.length, demands, cases, options))
}

/** 核对整表结束之后才能仲裁。材料是核对顺带带回来的，没结束就点会用到不完整的原文。 */
export function arbitrationAllowed(phase: 'idle' | 'run' | 'done' | 'fail'): boolean {
  return phase === 'done'
}

/** 整表核对结束、开关开着、还有空着的收件人，并且当前没有在交仲裁。没查成的补查在进入仲裁时先做一轮，补查结束不会从这里再开。 */
export function shouldAutoArbitrate(input: { fullCheck: boolean; phase: 'idle' | 'run' | 'done' | 'fail'; enabled: boolean; gaps: number; asking: boolean }): boolean {
  return input.fullCheck && arbitrationAllowed(input.phase) && input.enabled && input.gaps > 0 && !input.asking
}

/** 上传给助手的仲裁说明。只带 IPR 仍空着、并且核对时已经暂存了材料的行。 */
export function iprArbitrationBrief(
  rows: readonly PctTaskRow[],
  demands: Readonly<Record<string, string>> = {},
  cases: Readonly<Record<string, string>> = {},
  options: Readonly<ArbitrationOptions> = {}
): string {
  return iprArbitrationWaves(rows, demands, cases, options)[0] ?? ''
}

function volumeKey(value: string): string {
  return value.replace(/\s/g, '').toUpperCase()
}

export interface ArbitrationDecision {
  volume: string
  /** 裁决行对应的那一事项。同文号出现两行时靠它区分，模型没写就留空。 */
  procLabel?: string
  recipient: string
  role: string
  cc: string
  ccRole: string
  reason: string
  unsure: boolean
}

const ROLE_WORDS = ['发明人', '客户联系人', 'IPR', '技术联系人', '技术负责人', '商务', '登录人', '登陆人', '密送', '不用发']

function blankParty(value: string): boolean {
  return !value || /^(无|空|没有|不抄送|拿不准|不用发|只发业务)/.test(value)
}

/** 不发这封提醒，或只发给业务、不发给客户。这两种是明确结论，不能当成拿不准。 */
function closedVerdict(parts: string[]): '' | '不用发' | '只发业务' {
  for (const part of parts) {
    if (/^(依据|抄送|身份|抄送身份|事项)/.test(part)) continue
    const text = unwrapToken(part).replace(/^收件人\s*[：:]?\s*/, '').trim()
    if (text === '不用发') return '不用发'
    if (text === '只发业务') return '只发业务'
  }
  return ''
}

function partyText(value: string): string {
  const names = value.split(/[、,，]/).map(part => unwrapToken(part).replace(/[（(][^）)]{1,12}[）)]/g, '').trim()).filter(part => part && !blankParty(part))
  return names.join('、').slice(0, 200)
}

function unwrapToken(value: string): string {
  return value.replace(/^[<《「『"'\u201c*]+|[>》」』"'\u201d*]+$/g, '').trim()
}

function roleText(value: string, fallback: string): string {
  const picked = value.split(/[、,，]/).map(part => unwrapToken(part)).filter(part => ROLE_WORDS.includes(part))
  if (picked.length) return picked.join('、')
  const marked = fallback.match(/[（(]([^）)]+)[）)]/g)?.map(part => part.replace(/[（()）]/g, '').trim()).filter(part => ROLE_WORDS.includes(part)) ?? []
  return marked.join('、')
}

/** 商务、登录人、密送是提交时的默认项。技术负责人不是技术联系人，除非依据里写明这个人就是技术联系人。 */
function partySlots(names: string, roles: string, reason: string): { names: string; roles: string } {
  const nameList = names.split('、').map(item => item.trim()).filter(Boolean)
  const roleList = roles.split('、').map(item => item.trim()).filter(Boolean)
  const keptNames: string[] = []
  const keptRoles: string[] = []
  nameList.forEach((name, index) => {
    const role = roleList[index] || (roleList.length === 1 ? roleList[0] : '')
    if (/^(商务|登录人|登陆人|密送|发件人)$/.test(name) || /^(商务|登录人|登陆人|密送|发件人)$/.test(role)) return
    if (role === '技术负责人') {
      if (!/技术联系人|\bIPR\b/i.test(reason)) return
      keptNames.push(name)
      keptRoles.push('IPR')
      return
    }
    keptNames.push(name)
    if (role) keptRoles.push(role === '技术联系人' ? 'IPR' : role)
  })
  return { names: keptNames.join('、'), roles: keptRoles.join('、') }
}

function fieldOf(parts: string[], label: string): string {
  const found = parts.find(part => part === label || part.startsWith(`${label} `) || part.startsWith(`${label}：`) || part.startsWith(`${label}:`))
  if (!found || found === label) return ''
  return found.slice(label.length).replace(/^[：:\s]+/, '').trim()
}

/** 依据只留一句中文。模型有时会在同一行接着写英文思考，那种尾巴不能进表格。 */
function cleanReason(value: string): string {
  const text = unwrapToken(value)
  const cut = text.search(/[`']|\s+[A-Za-z]{2,}(?:\s+[A-Za-z'.,]+){2,}/)
  if (cut === 0) return ''
  const kept = (cut > 0 ? text.slice(0, cut) : text).replace(/[\s`'"“”]+$/g, '').trim()
  return kept.slice(0, 120)
}

function isCaseVolume(value: string): boolean {
  return /^[A-Za-z0-9][A-Za-z0-9\u4e00-\u9fff._/-]*\d[A-Za-z0-9\u4e00-\u9fff._/-]*$/.test(value)
}

function decisionLines(text: string): string[] {
  const clean = text.replace(/```[\w-]*\n?/g, '').replace(/<\/?think>/gi, '')
  const out: string[] = []
  for (const line of clean.split(/\n+/)) {
    const pieces = line.split(/(?=文号(?:为|是)?\s*[｜|│丨:：]?\s*[<《「『"'\u201c*`]*\s*[A-Za-z0-9][A-Za-z0-9\u4e00-\u9fff._/-]*\d)/).map(part => part.trim()).filter(Boolean)
    if (pieces.length > 1) out.push(...pieces)
    else if (line.trim()) out.push(line.trim())
  }
  return out
}

/** 正式格式是「文号 我方文号」。模型也常写成「客户文号 我方文号」或「空 我方文号」。没有数字的词不是文号。 */
function volumeOf(line: string): string {
  const classic = line.match(/文号(?:为|是)?\s*[｜|│丨:：]?\s*[<《「『"'\u201c*`]*\s*([A-Za-z0-9][A-Za-z0-9\u4e00-\u9fff._/-]{1,80})/)
  if (classic?.[1] && isCaseVolume(classic[1])) return classic[1]
  const paired = line.match(/^(?:空|[A-Za-z0-9][A-Za-z0-9\u4e00-\u9fff._/-]{1,40})\s+([A-Za-z0-9][A-Za-z0-9\u4e00-\u9fff._/-]{1,80})\s*[｜|│丨]/)
  if (paired?.[1] && isCaseVolume(paired[1])) return paired[1]
  const single = line.match(/^([A-Za-z0-9][A-Za-z0-9\u4e00-\u9fff._/-]{1,80})\s*[｜|│丨]/)
  return single?.[1] && isCaseVolume(single[1]) ? single[1] : ''
}

/** 同一份回复里，短总结常常也带「文号」二字，但裁决行在另一段。取能对上更多文号的那一段。 */
export function pickArbitrationText(parts: readonly string[]): string {
  let best = ''
  let hits = -1
  for (const part of parts) {
    const text = part.trim()
    if (!text) continue
    const found = readArbitrationDecisions(text).length
    if (found > hits) {
      best = text
      hits = found
    }
  }
  return best
}

/** 从助手回复里取出每一行的收件人、身份和抄送。拿不准的也留下，但不写进表格。 */
export function readArbitrationDecisions(text: string): ArbitrationDecision[] {
  const decisions: ArbitrationDecision[] = []
  for (const raw of decisionLines(text)) {
    const line = raw.trim().replace(/^\d+[.、)\]]\s*/, '').replace(/^[-*]\s+/, '')
    const volume = volumeOf(line)
    if (!volume) continue
    const parts = line.split(/[｜|│丨]/).map(part => part.trim())
    const unsure = parts.some(part => part === '拿不准' || part.startsWith('拿不准')) || /[：:]\s*拿不准/.test(line)
    const reason = cleanReason(fieldOf(parts, '依据'))
    const procLabel = fieldOf(parts, '事项').slice(0, 60)
    const closed = closedVerdict(parts)
    if (closed) {
      decisions.push({ volume, ...(procLabel ? { procLabel } : {}), recipient: closed, role: '', cc: '', ccRole: '', reason, unsure: false })
      continue
    }
    if (unsure) {
      decisions.push({ volume, ...(procLabel ? { procLabel } : {}), recipient: '', role: '', cc: '', ccRole: '', reason, unsure: true })
      continue
    }
    const recipientRaw = fieldOf(parts, '收件人') || line.match(/收件人\s*[：:\-]?\s*([^，,；;｜|\n]+)/)?.[1]?.trim() || ''
    const ccRaw = fieldOf(parts, '抄送') || line.match(/抄送\s*[：:\-]?\s*([^，,；;｜|\n]+)/)?.[1]?.trim() || ''
    const keptTo = partySlots(partyText(recipientRaw), roleText(fieldOf(parts, '身份'), recipientRaw), reason)
    const keptCc = partySlots(partyText(ccRaw), roleText(fieldOf(parts, '抄送身份'), ccRaw), reason)
    if (!keptTo.names) {
      if (fieldOf(parts, '收件人') || unsure) {
        decisions.push({ volume, ...(procLabel ? { procLabel } : {}), recipient: '', role: '', cc: '', ccRole: '', reason, unsure: true })
      }
      continue
    }
    decisions.push({
      volume,
      ...(procLabel ? { procLabel } : {}),
      recipient: keptTo.names,
      role: keptTo.roles,
      cc: keptCc.names,
      ccRole: keptCc.roles,
      reason,
      unsure: false
    })
  }
  return decisions
}

/** 没开「只写技术联系人」时，客户要求写了没指定发给谁，却用著录项目里的人来顶，不当成裁决。 */
function inventedRecordPick(reason: string, recipient: string, iprOnly: boolean): boolean {
  if (!/未指定|没有指定/.test(reason)) return false
  if (/不发\s*PCT|不用发涉外|所有邮件只发|不要发给客户|无需再发送/.test(reason)) return false
  if (recipient === '只发业务') return /著录项目|仅含业务/.test(reason)
  if (iprOnly || recipient === '不用发') return false
  return /著录项目|主送技术联系人|技术联系人/.test(reason)
}

/** 按文号（带事项）把收件人写回表格。拿不准的不填。同文号两行靠事项列区分；没有事项列又对上多行的，宁可不写也不串行。 */
export function applyArbitrationReply(rows: readonly PctTaskRow[], text: string, options: Readonly<ArbitrationOptions> = {}): { rows: PctTaskRow[]; written: number; unsure: number; decisions: ArbitrationDecision[] } {
  const iprOnly = options.iprOnly === true
  const decisions = readArbitrationDecisions(text).map(item => inventedRecordPick(item.reason, item.recipient, iprOnly)
    ? { ...item, recipient: '', role: '', cc: '', ccRole: '', unsure: true }
    : item)
  const byVolume = new Map<string, ArbitrationDecision[]>()
  for (const item of decisions.filter(item => !item.unsure)) {
    const key = volumeKey(item.volume)
    const list = byVolume.get(key) ?? []
    list.push(item)
    byVolume.set(key, list)
  }
  const decisionFor = (row: PctTaskRow): ArbitrationDecision | undefined => {
    const proc = row.procLabel.trim()
    for (const key of [row.ourVolume, row.customerVolume]) {
      if (!key.trim()) continue
      const list = byVolume.get(volumeKey(key))
      if (!list) continue
      const exact = proc ? list.filter(item => (item.procLabel ?? '').trim() === proc) : []
      if (exact.length) return exact[exact.length - 1]
      if (list.length === 1) return list[0]
    }
    return undefined
  }
  let written = 0
  const next = rows.map(row => {
    const write = decisionFor(row)
    if (!write) return row
    written += 1
    const { iprCarried: _carried, ...rest } = row
    return {
      ...rest,
      iprName: write.recipient,
      iprArbitrated: true as const,
      ...(write.cc ? { mailCc: write.cc } : {})
    }
  })
  return { rows: next, written, unsure: decisions.filter(item => item.unsure).length, decisions }
}

/** 查不到的行，按源表的列拆回两张表。沿用上一行或仲裁填上的称呼不写回去。 */
export function missedSourceSheets(
  rows: readonly PctTaskRow[],
  verdict: (row: PctTaskRow) => string,
  columns: PctRuntimeConfig['columns']
): Array<{ name: string; rows: string[][] }> {
  const header = [
    columns.ourVolume,
    columns.customerVolume,
    columns.customerName,
    columns.contactName,
    columns.iprName,
    ...(columns.leadName ? [columns.leadName] : []),
    columns.procLabel,
    '查询结果'
  ]
  const remind: string[][] = [header]
  const national: string[][] = [header]
  for (const row of rows) {
    const result = verdict(row)
    if (result !== '库里没有' && result !== '没查成') continue
    const line = [
      row.ourVolume,
      row.customerVolume,
      row.customerName,
      row.contactCarried ? '' : row.contactName,
      row.iprCarried || row.iprArbitrated ? '' : row.iprName,
      ...(columns.leadName ? [row.leadCarried ? '' : (row.leadName ?? '')] : []),
      row.procLabel,
      result
    ]
    const target = row.letterKind === 'national' || row.letterKind === 'design' ? national : remind
    target.push(line)
  }
  return [
    remind.length > 1 ? { name: '提醒申请PCT', rows: remind } : null,
    national.length > 1 ? { name: 'PCT进国家阶段官方绝限', rows: national } : null
  ].filter((item): item is { name: string; rows: string[][] } => item !== null)
}

/** 核对完的整张表。列跟上传的一样，末尾多一列审核状态。 */
export function checkedSourceSheets(
  rows: readonly PctTaskRow[],
  statusOf: (row: PctTaskRow) => string,
  columns: PctRuntimeConfig['columns']
): Array<{ name: string; rows: string[][] }> {
  const header = [
    columns.ourVolume,
    columns.customerVolume,
    columns.customerName,
    columns.contactName,
    columns.iprName,
    ...(columns.leadName ? [columns.leadName] : []),
    columns.procLabel,
    '审核状态'
  ]
  const remind: string[][] = [header]
  const national: string[][] = [header]
  for (const row of rows) {
    const line = [
      row.ourVolume,
      row.customerVolume,
      row.customerName,
      row.contactName,
      row.iprName,
      ...(columns.leadName ? [row.leadName ?? ''] : []),
      row.procLabel,
      statusOf(row)
    ]
    const target = row.letterKind === 'national' || row.letterKind === 'design' ? national : remind
    target.push(line)
  }
  return [
    remind.length > 1 ? { name: '提醒申请PCT', rows: remind } : null,
    national.length > 1 ? { name: 'PCT进国家阶段官方绝限', rows: national } : null
  ].filter((item): item is { name: string; rows: string[][] } => item !== null)
}

import { apiError, type ApiResult } from '../api/types'
import { isRecord, readClientInfo } from '../api/response-guards'
import type { EasyTransport } from '../api/transport'
import { DOWNLOAD_MAX_ITEMS } from '../api/file-download'
import { isQueryGuid } from '../query/query-validator'

/** 文件查询里选中的下载名称。不进 GetSearchFiles，发文前交给 GetFileName。 */
export interface FileDownloadSelection {
  templateId?: string
  column?: string
  fixedText?: string
  /** 选中时从模板行抄下的配方。发文时优先用账号上的最新模板。 */
  newFilename?: string
  fileNameType?: string
  label?: string
}

export interface DownloadNameRecipe {
  newFilename: string
  fileNameType: string
}

export interface DownloadNamePart { column: string; fixedText: string }
export class DownloadNameValidationError extends Error {}

export function downloadNameParts(selection: FileDownloadSelection | null): DownloadNamePart[] {
  const recipe = selection?.newFilename && selection.fileNameType
    ? downloadRecipe(selection.newFilename, selection.fileNameType) : null
  if (!recipe) return [{ column: selection?.column ?? '', fixedText: selection?.fixedText ?? '' }]
  const names = recipe.newFilename.split(';')
  return recipe.fileNameType.split(';').map((kind, index) => ({
    column: kind === 'txt' ? 'fixtxt' : names[index], fixedText: kind === 'txt' ? names[index] : ''
  }))
}

/** 编辑过的配方不携带模板ID，避免下载时重新加载模板覆盖本次修改。 */
export function selectionFromNameParts(parts: DownloadNamePart[], label = ''): FileDownloadSelection | null {
  const names: string[] = []
  const types: string[] = []
  for (const [index, part] of parts.entries()) {
    if (!part.column) continue
    if (part.column === 'fixtxt' && !part.fixedText.trim()) {
      throw new DownloadNameValidationError(`第${index + 1}段固定字符不能为空。`)
    }
    names.push(part.column === 'fixtxt' ? part.fixedText.trim() : part.column)
    types.push(part.column === 'fixtxt' ? 'txt' : 'colname')
  }
  if (!names.length) return null
  const recipe = downloadRecipe(names.join(';'), types.join(';'))
  // 单段固定字符含分号不能混入配方分隔符。
  if (!recipe || parts.some(part => part.column === 'fixtxt' && part.fixedText.includes(';'))) {
    throw new DownloadNameValidationError('下载名称最多31段，每段最多80字，固定字符不能包含分号。')
  }
  return { ...recipe, label: label ? `${label.slice(0, 73)}（已修改）` : '自定义下载名称' }
}

export interface DownloadNameOptions {
  /** 流水下载共享预算时可借用六路；其它调用保持默认五路。 */
  concurrency?: number
  resolvedBatches?: Record<string, string[]>
  /** 已完成的文件数；并发批次完成顺序不影响返回名称的顺序。 */
  onProgress?: (done: number, total: number) => void
  signal?: AbortSignal
  /** 流水下载消费已生成的一批；等待消费方腾出空间后才继续派发。发文调用无需提供。 */
  onBatch?: (offset: number, names: string[]) => Promise<void>
  /** 首个失败立即通知流水消费者，不能等其它onBatch等待结束后才传播。 */
  onFailure?: (failure: ApiResult<never>) => void
}

const COLUMN = /^[A-Za-z_][A-Za-z0-9_]{0,40}$/
/** 命名一批 40 个：100 个一批单批要跑几分钟，中途一断整批重来；40 个一批是单批耗时与往返次数的折中。 */
export const NAME_BATCH = 40
/** 命名最多 5 路：在常见 HTTP/1.1 同源 6 连接限制下，避免仅命名请求就占满连接；其他请求仍共享同源调度。 */
const NAME_CONCURRENCY = 5

function segments(value: string): string[] {
  return value.split(';')
}

export function downloadRecipe(newFilename: string, fileNameType: string): DownloadNameRecipe | null {
  const names = segments(newFilename.trim())
  const types = segments(fileNameType.trim())
  if (!names.length || names.length !== types.length || names.length > 31) return null
  if (names.some(name => !name || name.length > 80)) return null
  for (let index = 0; index < types.length; index += 1) {
    const kind = types[index]
    const name = names[index]
    if (kind === 'colname' && !COLUMN.test(name)) return null
    if (kind !== 'colname' && kind !== 'txt') return null
  }
  return { newFilename: names.join(';'), fileNameType: types.join(';') }
}

export function selectionFromControls(input: {
  templateId?: string
  column?: string
  fixedText?: string
  label?: string
  template?: { newFilename: string; fileNameType: string } | null
}): FileDownloadSelection | null {
  const templateId = input.templateId?.trim() ?? ''
  const column = input.column?.trim() ?? ''
  const fixedText = input.fixedText?.trim() ?? ''
  const label = input.label?.trim().slice(0, 80) ?? ''
  if (isQueryGuid(templateId)) {
    const recipe = input.template ? downloadRecipe(input.template.newFilename, input.template.fileNameType) : null
    return {
      templateId,
      ...(recipe ?? {}),
      ...(label ? { label } : {})
    }
  }
  if (!column) return null
  if (column === 'fixtxt') {
    if (!fixedText || fixedText.includes(';') || fixedText.length > 80) return null
    return { column: 'fixtxt', fixedText, newFilename: fixedText, fileNameType: 'txt', ...(label ? { label } : {}) }
  }
  if (!COLUMN.test(column)) return null
  return { column, newFilename: column, fileNameType: 'colname', ...(label ? { label } : {}) }
}

export function isFileDownloadSelection(value: unknown): value is FileDownloadSelection {
  if (!isRecord(value)) return false
  const keys = Object.keys(value)
  if (keys.some(key => !['templateId', 'column', 'fixedText', 'newFilename', 'fileNameType', 'label'].includes(key))) return false
  const templateId = value.templateId
  const column = value.column
  const fixedText = value.fixedText
  const label = value.label
  if (templateId !== undefined && (typeof templateId !== 'string' || !isQueryGuid(templateId))) return false
  if (column !== undefined && (typeof column !== 'string' || (column !== 'fixtxt' && !COLUMN.test(column)))) return false
  if (fixedText !== undefined && (typeof fixedText !== 'string' || !fixedText || fixedText.length > 80 || fixedText.includes(';'))) return false
  if (label !== undefined && (typeof label !== 'string' || !label.trim() || label.length > 80)) return false
  const named = value.newFilename
  const typed = value.fileNameType
  if ((named === undefined) !== (typed === undefined)) return false
  if (named !== undefined || typed !== undefined) {
    if (typeof named !== 'string' || typeof typed !== 'string' || !downloadRecipe(named, typed)) return false
  }
  if (!templateId && named === undefined && !column) return false
  if (column === 'fixtxt' && !fixedText && named === undefined) return false
  return true
}

export function downloadNameText(selection: FileDownloadSelection | null | undefined): string {
  const label = selection?.label?.trim()
  if (label) return label
  if (selection?.column === 'fixtxt') return selection.fixedText || '固定字符'
  if (selection?.column) return selection.column
  if (selection?.templateId) return '已选下载名称模板'
  return ''
}

/** 申请号带校验点（202610026334.9、202311613183.X）。下载文件名里把点去掉（2026100263349、202311613183X），扩展名和其他小数点不动。 */
const APPLICATION_NO_DOT = /(?<!\d)(\d{12}|\d{8})\.(?:(\d)(?!\d)|([Xx])(?![\dXx]))/g

export function stripApplicationNoDot(name: string): string {
  return name.replace(APPLICATION_NO_DOT, '$1$2$3')
}

export function recipeFromTempList(data: unknown, templateId: string): DownloadNameRecipe | null {
  if (!isRecord(data) || !Array.isArray(data.TempNameList)) return null
  for (const row of data.TempNameList) {
    if (!isRecord(row) || typeof row.id !== 'string' || row.id.toLowerCase() !== templateId.toLowerCase()) continue
    const filename = typeof row.new_filename === 'string' ? row.new_filename : ''
    const kind = typeof row.file_name_type === 'string' ? row.file_name_type : ''
    return downloadRecipe(filename, kind)
  }
  return null
}

function snapshotRecipe(selection: FileDownloadSelection): DownloadNameRecipe | null {
  if (!selection.newFilename || !selection.fileNameType) return null
  return downloadRecipe(selection.newFilename, selection.fileNameType)
}

export function buildGetFileNameParams(fileIds: string[], recipe: DownloadNameRecipe): URLSearchParams | null {
  if (!fileIds.length || fileIds.length > NAME_BATCH || fileIds.some(id => !isQueryGuid(id))) return null
  const params = new URLSearchParams()
  params.set('Call', 'GetFileName')
  params.set('file_ids', fileIds.join(';'))
  params.set('new_filename', recipe.newFilename)
  params.set('file_name_type', recipe.fileNameType)
  params.set('childpath', '')
  params.set('zip_name', '')
  params.set('zip_file_name_type', '')
  params.set('log_pagename', 'FileSearch.aspx')
  return params
}

/** 生成名与传入的文件 ID 一一对应。空段或超长名整批作废。 */
export function readGeneratedFileNames(data: unknown, count: number): string[] | null {
  if (!isRecord(data) || count < 1) return null
  const info = readClientInfo(data.ClientInfo)
  if (!info.ok || info.data.IsLogin === false || info.data.Status !== true || typeof data.file_names !== 'string') return null
  const names = data.file_names.split(';').map(name => name.trim())
  if (names.length !== count || names.some(name => !name || name.length > 180)) return null
  return names
}

async function recipeFor(transport: EasyTransport, selection: FileDownloadSelection, signal?: AbortSignal): Promise<ApiResult<DownloadNameRecipe>> {
  const saved = snapshotRecipe(selection)
  if (!selection.templateId) {
    return saved ? { ok: true, data: saved } : apiError('INVALID_QUERY', '下载名称没有配好，没有按这个名称发文。')
  }
  const params = new URLSearchParams()
  params.set('Call', 'GetFileTempNameList')
  params.set('log_pagename', 'FileSearch.aspx')
  const listed = await transport.post('fileTempList', params, signal)
  if (!listed.ok) {
    if (saved && listed.error.code !== 'SESSION_EXPIRED' && listed.error.code !== 'REQUEST_ABORTED') return { ok: true, data: saved }
    return listed
  }
  if (isRecord(listed.data)) {
    const info = readClientInfo(listed.data.ClientInfo)
    if (info.ok && info.data.IsLogin === false) return apiError('SESSION_EXPIRED', 'EASY 登录状态已失效。')
  }
  const live = recipeFromTempList(listed.data, selection.templateId)
  if (live) return { ok: true, data: live }
  if (saved) return { ok: true, data: saved }
  return apiError('BUSINESS_ERROR', '这份下载名称模板不在当前账号里，没有按原文件名发文。')
}

/** 按下载名称模板生成发文用的文件名。查询结果里的附件原名留在调用方。 */
export async function resolveDownloadFileNames(
  transport: EasyTransport,
  fileIds: string[],
  selection: FileDownloadSelection,
  options: DownloadNameOptions = {}
): Promise<ApiResult<string[]>> {
  if (!fileIds.length || fileIds.length > DOWNLOAD_MAX_ITEMS || fileIds.some(id => !isQueryGuid(id))) {
    return apiError('INVALID_QUERY', '文件编号不能用来生成下载名称。')
  }
  if (options.signal?.aborted) return apiError('REQUEST_ABORTED', '请求已取消。')
  options.onProgress?.(0, fileIds.length)
  const recipe = await recipeFor(transport, selection, options.signal)
  if (!recipe.ok) return recipe
  if (options.signal?.aborted) return apiError('REQUEST_ABORTED', '请求已取消。')
  const controller = new AbortController()
  let failure: ApiResult<never> | undefined
  const stop = (result: ApiResult<never>) => {
    const first = !failure
    failure ??= result
    controller.abort()
    if (first) options.onFailure?.(result)
  }
  const abort = () => stop(apiError('REQUEST_ABORTED', '请求已取消。'))
  options.signal?.addEventListener('abort', abort, { once: true })
  const names: string[] = new Array(fileIds.length)
  let next = 0
  let completed = 0
  const worker = async () => {
    while (!failure && next < fileIds.length) {
      const index = next
      next += NAME_BATCH
      const batch = fileIds.slice(index, index + NAME_BATCH)
      const params = buildGetFileNameParams(batch, recipe.data)
      if (!params) {
        stop(apiError('INVALID_QUERY', '下载名称参数无效，没有发文。'))
        return
      }
      const cached = options.resolvedBatches?.[String(index)]
      const response = cached?.length === batch.length
        ? { ok: true as const, data: { file_names: cached.join(';') } }
        : await transport.post('getFileName', params, controller.signal)
      if (failure) return
      if (!response.ok) {
        stop(response)
        return
      }
      const info = isRecord(response.data) ? readClientInfo(response.data.ClientInfo) : null
      if (info?.ok && info.data.IsLogin === false) {
        stop(apiError('SESSION_EXPIRED', 'EASY 登录状态已失效。'))
        return
      }
      const generated = cached?.length === batch.length
        ? cached.every(name => typeof name === 'string' && name.trim().length > 0 && name.length <= 180 && !name.includes(';')) ? cached.slice() : null
        : readGeneratedFileNames(response.data, batch.length)
      if (!generated) {
        stop(apiError('INVALID_RESPONSE', '下载名称没有生成完整的文件名，没有按原文件名发文。'))
        return
      }
      // 原站只给分号分隔的名称，没有 ID；必须按请求的原偏移落位。
      names.splice(index, generated.length, ...generated)
      await options.onBatch?.(index, generated)
      completed += batch.length
      options.onProgress?.(completed, fileIds.length)
    }
  }
  try {
    const concurrency = Math.max(1, Math.min(6, Math.floor(options.concurrency ?? NAME_CONCURRENCY)))
    await Promise.all(Array.from({ length: Math.min(concurrency, Math.ceil(fileIds.length / NAME_BATCH)) }, worker))
    return failure ?? { ok: true, data: names }
  } finally {
    options.signal?.removeEventListener('abort', abort)
  }
}

import type { ApiResult } from '../../api/types'
import { isQueryGuid } from '../../query/query-validator'
import { isRecord, readClientInfo } from '../../api/response-guards'
import type { MailDraftPreview, SendMode } from '../types'
import type { EasyMailAttachment, EasyMailCase, EasyMailSnapshot, KnownValue, WriteStatus } from './types'

const MAIL_CUSTOMER_PAGE = 'FileSearchMail.aspx'
const MAIL_PAGE = 'mail.aspx'

export function mailStyleValue(mode: SendMode): string | null {
  return mode === 'merge_by_customer_description' ? '1' : null
}

export function buildMailCustomerParams(preview: MailDraftPreview): { ok: true; params: URLSearchParams } | { ok: false; message: string } {
  const style = mailStyleValue(preview.sendMode)
  if (!style) return { ok: false, message: '单个来文的 mailstyle 尚未确认，不能创建。' }
  if (!isQueryGuid(preview.mailTypeId)) return { ok: false, message: '发文类型不是 EASY GUID。' }
  if (preview.fileIds.length === 0 || preview.fileIds.length !== preview.files.length) {
    return { ok: false, message: '文件 ID 与文件名称数量不一致。' }
  }
  const ids: string[] = []
  const names: string[] = []
  for (const file of preview.files) {
    if (!isQueryGuid(file.fileId) || !file.fileName.trim() || file.fileName.includes(';') || ids.includes(file.fileId)) {
      return { ok: false, message: '文件 ID 或名称不能按分号提交。' }
    }
    ids.push(file.fileId)
    names.push(file.fileName)
  }
  const params = new URLSearchParams()
  params.set('Call', 'MailCustomer')
  params.set('_file_ids', ids.join(';'))
  params.set('_file_names', names.join(';'))
  params.set('mailstyle', style)
  params.set('mailtype', preview.mailTypeId)
  params.set('log_pagename', MAIL_CUSTOMER_PAGE)
  return { ok: true, params }
}

/** 已经调用传输层之后，除了发出前就被拒绝的请求，都不能当成可重试的失败。 */
export function unconfirmedWrite(result: ApiResult<unknown>): WriteStatus<never> | null {
  if (result.ok) return null
  if (result.error.code === 'INVALID_ORIGIN' || result.error.code === 'INVALID_QUERY') {
    return { status: 'failed', requestSent: false, message: result.error.message }
  }
  return { status: 'unknown', requestSent: true, message: '请求已经发出，但没有确定的业务结果。不能自动重试，请到 EASY 核对。' }
}

/** 页面成功条件是 objid。正文未保存，缺 objid 时按未知处理，不能重试。 */
export function readMailCustomer(data: unknown): WriteStatus<{ mailId: string }> {
  if (!isRecord(data) || readClientInfo(data.ClientInfo).ok === false) {
    return { status: 'unknown', requestSent: true, message: '创建响应无法确认，不能再次创建。请到 EASY 核对。' }
  }
  const objid = typeof data.objid === 'string' ? data.objid.trim() : ''
  if (!isQueryGuid(objid)) {
    return { status: 'unknown', requestSent: true, message: '响应没有可确认的 objid，不能再次创建。请到 EASY 核对。' }
  }
  return { status: 'ok', data: { mailId: objid } }
}

function known(record: Record<string, unknown>, key: string): KnownValue {
  if (!Object.prototype.hasOwnProperty.call(record, key)) return { state: 'unknown', value: null }
  const value = record[key]
  if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return { state: 'known', value: value === null ? null : String(value) }
  }
  return { state: 'unknown', value: null }
}

function blank(): KnownValue {
  return { state: 'unknown', value: null }
}

export function readMailInfo(data: unknown, expectedMailId: string): { ok: true; row: Record<string, unknown> } | { ok: false; message: string } {
  const client = isRecord(data) ? readClientInfo(data.ClientInfo) : null
  if (!client?.ok) return { ok: false, message: 'GetMailInfo 缺少 ClientInfo。' }
  if (client.data.IsLogin === false) return { ok: false, message: 'EASY 登录已失效。' }
  if (client.data.Status === false) return { ok: false, message: 'GetMailInfo 被 EASY 拒绝。' }
  if (!isRecord(data) || !Array.isArray(data.MailInfo) || !isRecord(data.MailInfo[0])) {
    return { ok: false, message: 'GetMailInfo 没有邮件行。' }
  }
  const row = data.MailInfo[0]
  if (typeof row.mail_id !== 'string' || row.mail_id.trim().toLowerCase() !== expectedMailId.trim().toLowerCase()) {
    return { ok: false, message: '返回的邮件 ID 与创建结果不一致。' }
  }
  return { ok: true, row }
}

export function snapshotFromMailInfo(row: Record<string, unknown>, mailId: string): EasyMailSnapshot {
  return {
    mailId,
