/** mail.js 只把 ClientInfo.Result 当成关联成功。原文没保存，所以成功后仍应回读 GetMailFile。 */
export function readRelatedFiles(data: unknown): WriteStatus<{ accepted: true }> {
  if (!isRecord(data)) return { status: 'unknown', requestSent: true, message: '文件关联响应无法确认。' }
  const client = readClientInfo(data.ClientInfo)
  if (!client.ok || client.data.Result === undefined) {
    return { status: 'unknown', requestSent: true, message: '文件关联响应没有 ClientInfo.Result，不能重试。' }
  }
  if (client.data.Result === true) return { status: 'ok', data: { accepted: true } }
  return { status: 'failed', requestSent: true, message: 'EASY 拒绝了文件关联。请先读取邮件文件，不要直接重试。' }
}

export function filesMatch(expected: string[], actual: EasyMailAttachment[]): boolean {
  const left = [...expected].map(id => id.toLowerCase()).sort()
  const right = actual.map(file => file.fileId.toLowerCase()).sort()
  return left.length === right.length && left.every((id, index) => id === right[index])
}

export function listParams(call: 'GetMailFile' | 'GetMailCase', mailId: string, pageIndex: number): URLSearchParams {
  const params = new URLSearchParams()
  params.set('Call', call)
  params.set('mail_id', mailId)
  params.set('pageIndex', String(pageIndex))
  params.set('searchKey', '')
  params.set('log_pagename', MAIL_PAGE)
  if (call === 'GetMailFile') {
    params.set('pageSize', '5')
    params.set('_PK', 'file_id')
    params.set('colsel', ';is_ralte_mail;file_name;file_type;upload_user;undefined;upload_time;customer_id;')
  } else {
    params.set('pageSize', '100')
    params.set('_PK', 'mail_case_id')
    params.set('colsel', ';sn;case_volume;ctrl_proc;case_name;case_volume_customer;app_no;issue_no;register_type_code;legal_due_date;customer_id;')
  }
  return params
}

/** 完成事项只勾本封案件上的处理事项。同一事项只留一次，多个用逗号，和期限查询里多选的写法一样。 */
export function finishCtrlProcIds(rows: readonly unknown[]): string {
  const seen = new Set<string>()
  const ids: string[] = []
  for (const row of rows) {
    if (!isRecord(row) || typeof row.ctrl_proc_id !== 'string') continue
    const id = row.ctrl_proc_id.trim()
    if (!isQueryGuid(id)) continue
    const key = id.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    ids.push(id)
  }
  return ids.join(',')
}

/** 读本封 GetMailCase，取出要写入 finish_ctrl_proc 的处理事项。没有案件时是空字符串。 */
export async function loadFinishCtrlProc(
  mailId: string,
  post: (params: URLSearchParams) => Promise<{ ok: boolean; data?: unknown }>
): Promise<{ ok: true; value: string } | { ok: false; message: string }> {
  const rows: unknown[] = []
  let seen = 0
  for (let page = 1; page <= 5; page += 1) {
    const loaded = await post(listParams('GetMailCase', mailId, page))
    if (!loaded.ok) return { ok: false, message: '发文上的处理事项没有读到，没有提交。' }
    const parsed = readTableRows(loaded.data, 'case_id', 'case_volume')
    if (parsed.state === 'invalid') return { ok: false, message: '发文上的处理事项没有读到，没有提交。' }
    if (parsed.state !== 'known') break
    if (isRecord(loaded.data) && Array.isArray(loaded.data.TableRows)) rows.push(...loaded.data.TableRows)
    seen += parsed.rows.length
    const reached = parsed.total !== null && seen >= parsed.total
    if (reached || parsed.rows.length < 100) break
  }
  return { ok: true, value: finishCtrlProcIds(rows) }
}

export function initParams(mailId: string): URLSearchParams {
  const params = new URLSearchParams()
  params.set('Call', 'MailinfoInit')
  params.set('mail_id', mailId)
  params.set('case_id', '')
  params.set('proc_id', '')
  params.set('file_ids', '')
  params.set('customer_id', '')
  params.set('log_pagename', MAIL_PAGE)
  return params
}

import type { EasyTransport } from '../../api/transport'
import { readRelatedFiles, readSaveMailInfo, relatedFileParams, saveParams, unconfirmedWrite } from './contracts'
import type { MailWriteGate } from './gate'
import type { EasyMailDraft, WriteStatus } from './types'

export class EasyMailSaveService {
  constructor(private readonly transport: EasyTransport, private readonly gate: MailWriteGate) {}

  async save(draft: EasyMailDraft, signal?: AbortSignal): Promise<WriteStatus<{ saved: true }>> {
    if (!draft.canSave) return { status: 'failed', requestSent: false, message: draft.blockers[0] ?? '保存字段还不完整。' }
    const response = await this.transport.post('saveMailInfo', saveParams(draft.fields as Parameters<typeof saveParams>[0]), signal)
    if (!response.ok) return unconfirmedWrite(response) ?? { status: 'unknown', requestSent: true, message: '保存响应无法确认，不能重试。' }
    return readSaveMailInfo(response.data)
  }

  async bind(mailId: string, fileIds: string[], signal?: AbortSignal): Promise<WriteStatus<{ accepted: true }> | { status: 'blocked'; requestSent: false; message: string }> {
    const encoded = this.gate.relatedFileIds(fileIds)
    if (encoded === null) {
      return { status: 'blocked', requestSent: false, message: 'SaveMailRalteCaseFile 的 file_ids 格式还没有核对，没有发送关联请求。' }
    }
    const response = await this.transport.post('saveMailRelatedFiles', relatedFileParams(mailId, encoded), signal)
    if (!response.ok) return unconfirmedWrite(response) ?? { status: 'unknown', requestSent: true, message: '文件关联响应无法确认。' }
    return readRelatedFiles(response.data)
  }
}

import { isQueryGuid } from '../../query/query-validator'
import { isRecord } from '../../api/response-guards'

/** 发文页签名下拉里的一项。内容已从原站 HTML 收成可读文本。 */
export interface MailSignatureItem {
  id: string
  name: string
  content: string
}

export interface MailSignatureRead {
  reserved: MailSignatureItem | null
  items: MailSignatureItem[]
  note: string
}

const RESERVED_FLAGS = ['is_default', 'IsDefault', 'is_reserved', 'reserved']

function decodeEntities(value: string): string {
  let text = value
  for (let pass = 0; pass < 3; pass += 1) {
    const next = text
      .replace(/&amp;/gi, '&')
      .replace(/&nbsp;|&#160;|&#x0*a0;/gi, ' ')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&quot;|&#34;/gi, '"')
      .replace(/&#(\d+);/g, (_, code: string) => String.fromCodePoint(Number(code)))
      .replace(/&#x([0-9a-f]+);/gi, (_, code: string) => String.fromCodePoint(Number.parseInt(code, 16)))
    if (next === text) break
    text = next
  }
  return text.replace(/\u00a0/g, ' ')
}

/** 原站签名是 HTML，保存时还会再编码一次。操作员签名按纯文本带回，换行保留。 */
export function signaturePlainText(value: string): string {
  const text = decodeEntities(value)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
  return text.slice(0, 4000)
}

export interface SignatureListRow {
  id: string
  name: string
  enabled: boolean
}

function enabledFlag(value: unknown): boolean {
  if (value === true || value === 1) return true
  if (typeof value !== 'string') return false
  const text = value.trim().toLowerCase()
  return text === '1' || text === 'true' || text === '是'
}

/** 个人设置「邮件签名」列表。GetMailSignatureSettingList 的 TableRows，正文不在这一张表里。 */
export function readSignatureRows(data: unknown): SignatureListRow[] {
  if (!isRecord(data) || !Array.isArray(data.TableRows)) return []
  const items: SignatureListRow[] = []
  for (const row of data.TableRows) {
    if (!isRecord(row) || typeof row.signature_id !== 'string' || !isQueryGuid(row.signature_id)) continue
    const name = typeof row.signature_name === 'string' ? row.signature_name.trim() : ''
    if (!name) continue
    if (items.some(item => item.id === row.signature_id)) continue
    items.push({ id: row.signature_id, name: name.slice(0, 80), enabled: enabledFlag(row.is_enabled) })
  }
  return items
}

/** 下拉选中后写进正文的 HTML。只解码，不去标签。 */
export function signatureHtml(value: string): string {
  return decodeEntities(value).trim().slice(0, 20000)
}

/** 操作员自己写的签名没有下拉 HTML。换行写成编辑器能排版的换行。 */
export function operatorSignatureHtml(value: string): string {
  const text = value.trim()
  if (!text) return ''
  if (/<[a-z][\s\S]*>/i.test(text)) return text.slice(0, 20000)
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>')
    .slice(0, 20000)
}

/** GetSignature 里指定那一条的 signature_content。 */
export function readSignatureHtml(data: unknown, signatureId: string): string {
  if (!isRecord(data) || !Array.isArray(data.Signature) || !isQueryGuid(signatureId)) return ''
  const row = data.Signature.find(item => isRecord(item) && typeof item.signature_id === 'string' && item.signature_id.toLowerCase() === signatureId.toLowerCase())
  if (!isRecord(row) || typeof row.signature_content !== 'string') return ''
  return signatureHtml(row.signature_content)
}

/** GetSignatureset 的 SignatureInfo[0].signature_content。 */
export function readSignatureContent(data: unknown): string {
  if (!isRecord(data) || !Array.isArray(data.SignatureInfo) || !isRecord(data.SignatureInfo[0])) return ''
  const raw = data.SignatureInfo[0].signature_content
  return typeof raw === 'string' ? signaturePlainText(raw) : ''
}

function flagged(row: Record<string, unknown>): boolean {
  return RESERVED_FLAGS.some(key => row[key] === true || row[key] === 1 || row[key] === '1')
}

/** GetSignature 的 Signature 列表。下拉显示 signature_name，正文用 signature_content。 */
export function readNamedSignatures(data: unknown): Array<MailSignatureItem & { reserved: boolean }> {
  if (!isRecord(data) || !Array.isArray(data.Signature)) return []
  const items: Array<MailSignatureItem & { reserved: boolean }> = []
  for (const row of data.Signature) {
    if (!isRecord(row) || typeof row.signature_id !== 'string' || !isQueryGuid(row.signature_id)) continue
    const name = typeof row.signature_name === 'string' ? row.signature_name.trim() : ''
    const content = typeof row.signature_content === 'string' ? signaturePlainText(row.signature_content) : ''
    if (!name || !content) continue
    if (items.some(item => item.id === row.signature_id)) continue
    items.push({ id: row.signature_id, name: name.slice(0, 80), content, reserved: flagged(row) })
  }
  return items
}

/** 发文页「邮件签名」下拉。写进正文的是这里的 signature_content，不是邮件设置里的 Signature。 */
export function combineSignatures(named: Array<MailSignatureItem & { reserved: boolean }>): MailSignatureRead {
  const items = named.map(({ id, name, content }) => ({ id, name, content }))
  const marked = named.filter(item => item.reserved)
  if (marked.length === 1) {
    const one = marked[0]
    return { reserved: { id: one.id, name: one.name, content: one.content }, items, note: '' }
  }
  if (named.length === 1) {
    const one = named[0]
    return { reserved: { id: one.id, name: one.name, content: one.content }, items, note: '' }
  }
  if (!named.length) return { reserved: null, items: [], note: '当前登录账号没有有效的邮件签名。' }
  return { reserved: null, items, note: '邮件签名有多项有效的，没有标明哪一条会写进正文。' }
}

import { isQueryGuid } from '../../query/query-validator'
import type { MailExecutionRecord, MailExecutionState } from './types'

const STATES = new Set<MailExecutionState>([
  'PREVIEW_READY', 'CONFIRM_REQUIRED', 'CREATING', 'CREATED', 'LOADING_MAIL', 'MAIL_LOADED',
  'SAVE_CONFIRM_REQUIRED', 'SAVING', 'SAVED', 'BINDING_FILES', 'VERIFYING',
  'COMPLETED', 'PARTIAL_FAILURE', 'BINDING_BLOCKED', 'UNKNOWN', 'FAILED'
])

export function executionStorageKey(origin: string, userId: string): string | null {
  if (!isQueryGuid(userId)) return null
  return `patmail.mail.exec.v1:${origin}:${userId}`
}

export interface ExecutionArea {
  get(key: string): Promise<Record<string, unknown>>
  set(items: Record<string, unknown>): Promise<void>
}

function isRecord(value: unknown): value is MailExecutionRecord {
  if (!value || typeof value !== 'object') return false
  const item = value as MailExecutionRecord
  return typeof item.executionId === 'string' && typeof item.userId === 'string' && typeof item.origin === 'string' &&
    typeof item.customerProfileId === 'string' && Array.isArray(item.fileIds) && item.fileIds.every(id => typeof id === 'string') &&
    typeof item.mailTypeId === 'string' && typeof item.ruleRevision === 'number' && typeof item.fingerprint === 'string' &&
    STATES.has(item.state) && typeof item.mailId === 'string' && typeof item.stage === 'string' &&
    typeof item.lastError === 'string' && typeof item.requestSent === 'boolean' && typeof item.updatedAt === 'string' &&
    (item.diffDigest === undefined || typeof item.diffDigest === 'string')
}

export function readExecutionRecords(value: unknown, userId: string, origin: string): MailExecutionRecord[] {
  if (!value || typeof value !== 'object') return []
  const record = value as { version?: unknown; records?: unknown; cookie?: unknown; authorization?: unknown }
  if (record.version !== 1 || !Array.isArray(record.records)) return []
  if ('cookie' in record || 'authorization' in record || 'password' in record) return []
  return record.records.filter(isRecord).filter(item => item.userId === userId && item.origin === origin).slice(-40)
    .map(item => ({ ...item, diffDigest: item.diffDigest ?? '' }))
}

export class ExecutionStore {
  private readonly chains = new Map<string, Promise<unknown>>()

  constructor(private readonly area: ExecutionArea | null) {}

  /** 同一页面里的同指纹创建串行执行。chrome.storage 没有事务，跨标签页不是原子操作。 */
  async exclusive<T>(origin: string, userId: string, fingerprint: string, run: () => Promise<T>): Promise<T> {
    const key = `${origin}\u0000${userId}\u0000${fingerprint}`
    const previous = this.chains.get(key) ?? Promise.resolve()
    const current = previous.then(run, run)
    this.chains.set(key, current.then(() => undefined, () => undefined))
    return current
  }

  async load(origin: string, userId: string): Promise<MailExecutionRecord[]> {
    const key = this.area ? executionStorageKey(origin, userId) : null
    if (!key || !this.area) return []
    const stored = await this.area.get(key)
    return readExecutionRecords(stored[key], userId, origin)
  }

  async save(origin: string, userId: string, records: MailExecutionRecord[]): Promise<void> {
    const key = this.area ? executionStorageKey(origin, userId) : null
    if (!key || !this.area) return
    const kept = records.filter(item => item.userId === userId && item.origin === origin).slice(-40)
    await this.area.set({ [key]: { version: 1, records: kept } })
  }
}

export class MemoryExecutionStore extends ExecutionStore {
  readonly records: MailExecutionRecord[] = []
  constructor() {
    super(null)
  }

  override async load(origin: string, userId: string): Promise<MailExecutionRecord[]> {
    return this.records.filter(item => item.origin === origin && item.userId === userId)
  }

  override async save(origin: string, userId: string, records: MailExecutionRecord[]): Promise<void> {
    const others = this.records.filter(item => item.origin !== origin || item.userId !== userId)
    this.records.splice(0, this.records.length, ...others, ...records.filter(item => item.origin === origin && item.userId === userId))
  }
}

import { isQueryGuid } from '../../query/query-validator'
import type { DescriptionMailTypeMapping } from '../types'

export interface ImportMailType {
  id: string
  name: string
  parentId?: string
}

export interface MergeImportedMappingsOptions {
  now: string
  createId: () => string
}

type Role = 'description' | 'mailType' | 'descriptionId' | 'mailTypeId'

interface ColumnMap {
  header: number
  description: number
  mailType: number
  descriptionId: number
  mailTypeId: number
}

type TypeMatch =
  | { kind: 'ok'; id: string; name: string }
  | { kind: 'missing' }
  | { kind: 'ambiguous' }

export type MergeImportedMappingsResult =
  | { ok: true; mappings: DescriptionMailTypeMapping[]; added: number; notice: string }
  | { ok: false; message: string }

function clean(value: string): string {
  return value.normalize('NFKC').replace(/[\u200b\u200c\u200d\ufeff]/g, '').trim()
}

function normHeader(value: string): string {
  return clean(value).toLowerCase().replace(/[\s:：_\-—/\\|·.。,，()（）【】[\]"'“”‘’]/g, '')
}

function roleOf(cell: string): { role: Role; score: number } | null {
  const text = normHeader(cell)
  if (!text) return null
  if (text === '文件描述id' || text === 'filedescriptionid' || text === '描述id') return { role: 'descriptionId', score: 3 }
  if (text === '发文类型id' || text === '邮件类型id' || text === 'mailtypeid') return { role: 'mailTypeId', score: 3 }
  if (text.includes('文件描述') || text.includes('来文描述') || text.includes('来文名称') || text.includes('官文名称') || text.includes('官文描述')) {
    return { role: 'description', score: 3 }
  }
  if (text.includes('发文类型') || text.includes('邮件类型') || text.includes('官文类型')) return { role: 'mailType', score: 3 }
  if (text === '描述' || text === 'description' || text === 'filedescription') return { role: 'description', score: 2 }
  if (text === '类型' || text === 'mailtype' || text === 'mailtypename') return { role: 'mailType', score: 2 }
  return null
}

function columnsOf(row: string[]): Partial<Record<Role, number>> {
  const best: Partial<Record<Role, { index: number; score: number }>> = {}
  row.forEach((cell, index) => {
    if (index > 20) return
    const found = roleOf(cell)
    if (!found) return
    const current = best[found.role]
    if (!current || found.score > current.score) best[found.role] = { index, score: found.score }
  })
  const picked: Partial<Record<Role, number>> = {}
  for (const role of ['description', 'mailType', 'descriptionId', 'mailTypeId'] as const) {
    const column = best[role]
    if (column) picked[role] = column.index
  }
  return picked
}

function pathOf(node: ImportMailType, byId: Map<string, ImportMailType>): string {
  const names: string[] = []
  let current: ImportMailType | undefined = node
  const seen = new Set<string>()
  while (current && !seen.has(current.id)) {
    seen.add(current.id)
    names.unshift(clean(current.name))
    const nextParent: string = current.parentId?.trim() ?? ''
    current = nextParent ? byId.get(nextParent) : undefined
  }
  return names.join('/')
}

function compact(value: string): string {
  return clean(value).toLowerCase().replace(/\s+/g, '').replace(/[／\\]/g, '/')
}

function pickByName(matches: Array<{ node: ImportMailType }>, nodes: ImportMailType[]): TypeMatch | null {
  if (matches.length === 1) return { kind: 'ok', id: matches[0].node.id, name: matches[0].node.name }
  if (matches.length < 2) return null
  const parents = new Set(nodes.map(node => node.parentId?.trim()).filter((id): id is string => Boolean(id)))
  const leaves = matches.filter(item => !parents.has(item.node.id))
  if (leaves.length === 1) return { kind: 'ok', id: leaves[0].node.id, name: leaves[0].node.name }
  return { kind: 'ambiguous' }
}

function matchLabel(label: string, nodes: ImportMailType[], byId: Map<string, ImportMailType>): TypeMatch {
  const wanted = compact(label)
  if (!wanted) return { kind: 'missing' }
  if (isQueryGuid(clean(label))) {
    const hit = nodes.find(node => node.id.toLowerCase() === clean(label).toLowerCase())
    return hit ? { kind: 'ok', id: hit.id, name: hit.name } : { kind: 'missing' }
  }
  const ranked = nodes.map(node => ({ node, path: compact(pathOf(node, byId)), name: compact(node.name) }))
  const byName = ranked.filter(item => item.name === wanted)
  if (!wanted.includes('/')) {
    const named = pickByName(byName, nodes)
    if (named) return named
  }
  const byPath = ranked.filter(item => item.path === wanted)
  if (byPath.length === 1) return { kind: 'ok', id: byPath[0].node.id, name: byPath[0].node.name }
  if (byPath.length > 1) return { kind: 'ambiguous' }
  return pickByName(byName, nodes) ?? { kind: 'missing' }
}

function locate(table: string[][], nodes: ImportMailType[]): ColumnMap | { message: string } {
  let sawDescription = false
  let sawType = false
  const limit = Math.min(table.length, 12)
  for (let index = 0; index < limit; index += 1) {
    const found = columnsOf(table[index] ?? [])
    if (found.description !== undefined || found.descriptionId !== undefined) sawDescription = true
    if (found.mailType !== undefined || found.mailTypeId !== undefined) sawType = true
    const description = found.description ?? found.descriptionId
    const mailType = found.mailType ?? found.mailTypeId
    if (description === undefined || mailType === undefined) continue
    return {
      header: index,
      description: found.description ?? -1,
      mailType: found.mailType ?? -1,
      descriptionId: found.descriptionId ?? -1,
      mailTypeId: found.mailTypeId ?? -1
    }
  }
  if (sawDescription && !sawType) return { message: '认出了文件描述，还缺「发文类型」这一列。' }
  if (sawType && !sawDescription) return { message: '认出了发文类型，还缺「文件描述」这一列。' }
  const inferred = inferColumns(table, nodes)
  if (inferred) {
    return { header: -1, description: inferred.description, mailType: inferred.mailType, descriptionId: -1, mailTypeId: -1 }
  }
  if (!nodes.length) return { message: '发文类型还没读到。先重新读取发文类型，再导入。' }
  return { message: '没有认出文件描述和发文类型。表头写成「文件描述」「发文类型」，或把描述放第一列、类型放第二列。' }
}

function inferColumns(table: string[][], nodes: ImportMailType[]): { description: number; mailType: number } | null {
  if (!nodes.length || !table.length) return null
  const byId = new Map(nodes.map(node => [node.id, node]))
  const width = Math.min(12, table.reduce((max, row) => Math.max(max, row.length), 0))
  let typeBest: { index: number; hits: number } | null = null
  for (let column = 0; column < width; column += 1) {
    let nonEmpty = 0
    let hits = 0
    for (const row of table) {
      const cell = clean(row[column] ?? '')
      if (!cell || roleOf(cell)) continue
      nonEmpty += 1
      if (matchLabel(cell, nodes, byId).kind !== 'missing') hits += 1
    }
    if (nonEmpty < 1 || hits / nonEmpty < 0.5) continue
    if (!typeBest || hits > typeBest.hits) typeBest = { index: column, hits }
  }
  if (!typeBest) return null
  let description = -1
  let count = 0
  for (let column = 0; column < width; column += 1) {
    if (column === typeBest.index) continue
    const filled = table.filter(row => clean(row[column] ?? '') && !roleOf(clean(row[column] ?? ''))).length
    if (filled > count) {
      count = filled
      description = column
    }
  }
  return description < 0 ? null : { description, mailType: typeBest.index }
}

function cell(row: string[], index: number): string {
  if (index < 0) return ''
  return clean(row[index] ?? '').slice(0, 200)
}

function quoted(items: string[]): string {
  const unique = [...new Set(items.map(item => clean(item)).filter(Boolean))]
  const shown = unique.slice(0, 3).map(item => `「${item.slice(0, 40)}」`).join('、')
  return unique.length > 3 ? `${shown}等 ${unique.length} 个` : shown
}

function importKey(item: { fileDescriptionId?: string; fileDescriptionText?: string }): string | null {
  const id = clean(item.fileDescriptionId ?? '')
  if (id && isQueryGuid(id)) return `id:${id.toLowerCase()}`
  const text = clean(item.fileDescriptionText ?? '')
  return text ? `text:${text}` : null
}

function noticeOf(stats: {
  added: number
  existing: number
  duplicate: number
  fileConflict: string[]
  existingConflict: string[]
  missing: string[]
  ambiguous: string[]
  mismatch: string[]
}): string {
  const parts = [`新增 ${stats.added} 条。`]
  if (stats.existing) parts.push(`已有 ${stats.existing} 条，没有重复写入。`)
  if (stats.duplicate) parts.push(`表格里相同的 ${stats.duplicate} 条已去掉。`)
  if (stats.fileConflict.length) parts.push(`这些描述在表格里对应了多个发文类型，后出现的没有写入：${quoted(stats.fileConflict)}。`)
  if (stats.existingConflict.length) parts.push(`这些描述已经对应另一个发文类型，没有改：${quoted(stats.existingConflict)}。`)
  if (stats.missing.length) parts.push(`这些发文类型没有对上：${quoted(stats.missing)}。`)
  if (stats.ambiguous.length) parts.push(`这些发文类型对上了多项，没有选用：${quoted(stats.ambiguous)}。`)
  if (stats.mismatch.length) parts.push(`这些行的发文类型名称和编号不一致，没有写入：${quoted(stats.mismatch)}。`)
  return parts.join('')
}

/** 按导入认的两列表头写出当前映射。发文类型写成树上的路径，没有树时用保存的名称。 */
export function mappingExportRows(
  mappings: ReadonlyArray<Pick<DescriptionMailTypeMapping, 'fileDescriptionText' | 'fileDescriptionId' | 'mailTypeId' | 'mailTypeName'>>,
  mailTypes: ImportMailType[]
): string[][] {
  const nodes = mailTypes.filter(node => node.id && clean(node.name))
  const byId = new Map(nodes.map(node => [node.id, node]))
  const rows = [['文件描述', '发文类型']]
  for (const item of mappings) {
    const description = clean(item.fileDescriptionText ?? '') || clean(item.fileDescriptionId ?? '')
    const node = byId.get(item.mailTypeId)
    const typeName = node ? pathOf(node, byId) : clean(item.mailTypeName)
    if (!description && !typeName) continue
    rows.push([description, typeName])
  }
  return rows
}

/** 从表格并入文件描述映射。相同描述只保留一条，已经存在的不改、不重复添加。 */
export function mergeImportedMappings(
  mappings: DescriptionMailTypeMapping[],
  table: string[][],
  mailTypes: ImportMailType[],
  options: MergeImportedMappingsOptions
): MergeImportedMappingsResult {
  const nodes = mailTypes.filter(node => isQueryGuid(node.id) && clean(node.name))
  const located = locate(table, nodes)
  if ('message' in located) return { ok: false, message: located.message }
  const byId = new Map(nodes.map(node => [node.id, node]))
  const data = table.slice(located.header + 1, located.header + 1 + 2000)
  if (!data.length) return { ok: false, message: '表格里没有数据行。' }
  const chosen = new Map<string, string>()
  const pending: DescriptionMailTypeMapping[] = []
  const stats = {
    added: 0,
    existing: 0,
    duplicate: 0,
    fileConflict: [] as string[],
    existingConflict: [] as string[],
    missing: [] as string[],
    ambiguous: [] as string[],
    mismatch: [] as string[]
  }
  for (const row of data) {
    const text = located.description < 0 ? '' : cell(row, located.description)
    const descriptionId = cell(row, located.descriptionId)
    const fileDescriptionId = isQueryGuid(descriptionId) ? descriptionId : undefined
    const nameCell = cell(row, located.mailType)
    const idCell = cell(row, located.mailTypeId)
    const descriptionIsHeader = Boolean(text && roleOf(text)?.role === 'description' && !fileDescriptionId)
    const typeIsHeader = Boolean(nameCell && roleOf(nameCell)?.role === 'mailType' && !idCell)
    if (descriptionIsHeader && typeIsHeader) continue
    const fileDescriptionText = text
    if (!fileDescriptionId && !fileDescriptionText) continue
    const label = fileDescriptionText || fileDescriptionId || ''
    const byGuid = isQueryGuid(idCell) ? nodes.find(node => node.id.toLowerCase() === idCell.toLowerCase()) : undefined
    const byName = nameCell ? matchLabel(nameCell, nodes, byId) : null
    if (byGuid && byName?.kind === 'ok' && byGuid.id.toLowerCase() !== byName.id.toLowerCase()) {
      stats.mismatch.push(label)
      continue
    }
    const resolved = byGuid
      ? { kind: 'ok' as const, id: byGuid.id, name: byGuid.name }
      : byName
    if (!resolved || resolved.kind === 'missing') {
      stats.missing.push(nameCell || idCell || `${label}（没有发文类型）`)
      continue
    }
    if (resolved.kind === 'ambiguous') {
      stats.ambiguous.push(nameCell || label)
      continue
    }
    const key = importKey({ fileDescriptionId, fileDescriptionText })
    if (!key) continue
    const previous = chosen.get(key)
    if (previous) {
      if (previous === resolved.id.toLowerCase()) stats.duplicate += 1
      else stats.fileConflict.push(label)
      continue
    }
    const same = mappings.filter(item => importKey(item) === key)
    if (same.some(item => item.mailTypeId.toLowerCase() === resolved.id.toLowerCase())) {
      chosen.set(key, resolved.id.toLowerCase())
      stats.existing += 1
      continue
    }
    if (same.some(item => item.enabled)) {
      chosen.set(key, resolved.id.toLowerCase())
      stats.existingConflict.push(label)
      continue
    }
    chosen.set(key, resolved.id.toLowerCase())
    pending.push({
      id: options.createId(),
      ...(fileDescriptionId ? { fileDescriptionId } : {}),
      ...(fileDescriptionText ? { fileDescriptionText } : {}),
      mailTypeId: resolved.id,
      mailTypeName: resolved.name,
      enabled: true,
      version: 1,
      updatedAt: options.now
    })
  }
  stats.added = pending.length
  if (!stats.added && !stats.existing && !stats.duplicate && !stats.fileConflict.length && !stats.existingConflict.length && !stats.missing.length && !stats.ambiguous.length && !stats.mismatch.length) {
    return { ok: false, message: '表格里没有可导入的映射。' }
  }
  return {
    ok: true,
    mappings: stats.added ? mappings.concat(pending) : mappings,
    added: stats.added,
    notice: noticeOf(stats)
  }
}

import type { HistoryQueryOption } from '../api/query-history'
import type { HistorySurface } from '../api/query-history/surfaces'

const STORAGE_KEY = 'patmail.historyQueryOptions'
const memory = new Map<string, HistoryQueryOption[]>()

function cacheKey(userId: string, surface: HistorySurface): string {
  return `${userId}:${surface}`
}

function isOption(value: unknown): value is HistoryQueryOption {
  if (!value || typeof value !== 'object') return false
  const row = value as Record<string, unknown>
  return typeof row.id === 'string' && row.id.length > 0 && row.id.length <= 80 &&
    typeof row.name === 'string' && row.name.trim().length > 0 && row.name.length <= 200 &&
    row.source === 'easy'
}

function copy(options: HistoryQueryOption[]): HistoryQueryOption[] {
  return options.map(item => ({ id: item.id, name: item.name, source: 'easy' }))
}

export function peekHistoryList(userId: string, surface: HistorySurface): HistoryQueryOption[] {
  return copy(memory.get(cacheKey(userId, surface)) ?? [])
}

export async function readHistoryList(userId: string, surface: HistorySurface): Promise<HistoryQueryOption[]> {
  const key = cacheKey(userId, surface)
  const hit = memory.get(key)
  if (hit) return copy(hit)
  const area = globalThis.chrome?.storage?.local
  if (!area || !userId) return []
  const stored = await area.get(STORAGE_KEY)
  const bag = stored[STORAGE_KEY]
  if (!bag || typeof bag !== 'object') return []
  const row = (bag as Record<string, unknown>)[key]
  if (!Array.isArray(row)) return []
  const options = row.filter(isOption).slice(0, 200)
  memory.set(key, options)
  return copy(options)
}

export function saveHistoryList(userId: string, surface: HistorySurface, options: HistoryQueryOption[]): void {
  if (!userId) return
  const key = cacheKey(userId, surface)
  const next = copy(options).slice(0, 200)
  memory.set(key, next)
  const area = globalThis.chrome?.storage?.local
  if (!area) return
  void area.get(STORAGE_KEY).then(stored => {
    const previous = stored[STORAGE_KEY]
    const bag = previous && typeof previous === 'object' ? { ...(previous as Record<string, HistoryQueryOption[]>) } : {}
    bag[key] = next
    return area.set({ [STORAGE_KEY]: bag })
  }).catch(() => undefined)
}

import type { NormalizedDictionary } from '../api/dictionaries'
import type { FileSearchFormField } from '../shared/message'

/** 文件查询里走基础资料接口的下拉，表单键对应字典名。 */
export const FILE_BASIC_OPTION_FIELDS: Record<string, string> = {
  case_type: 'caseType',
  apply_type: 'applyType',
  case_status: 'caseStatus',
  business_type_id: 'bussType',
  country: 'country',
  customer_country: 'country',
  customer_status_id: 'customerStatus',
  i_ctrl_proc: 'ctrlProc',
  branch_dept_id: 'caseBranchDept'
}

/** 文件查询里走流程字典的下拉。 */
export const FILE_FLOW_OPTION_FIELDS: Record<string, string> = {
  file_status: 'fileStatus',
  flow_direction: 'caseDirection',
  proc_status: 'procStatus',
  selfilename1: 'downloadFileName'
}

export interface SavedChoice {
  value: string
  label: string
  parent?: string
  /** 案件类型归属。原站的案件状态、申请类型、业务类型都按当前案件类型收窄，缓存要带着这份归属才能照原站口径过滤。 */
  caseTypeId?: string
  /** 案件状态的分类（ALL / CASE / PROC）。原站案件状态只放 ALL 和 CASE，PROC 是年费状态，不进查询树。 */
  statusClass?: string
}

const STORAGE_KEY = 'patmail.formOptionFallback.v1'
const memory = new Map<string, Map<string, SavedChoice[]>>()
const loadedUsers = new Set<string>()
const dirtyUsers = new Set<string>()
const listeners = new Set<() => void>()
let activeUser = ''
let epoch = 0
let flushTimer = 0

export function optionFallbackEpoch(): number {
  return epoch
}

export function subscribeOptionFallback(listener: () => void): () => void {
  listeners.add(listener)
  return () => listeners.delete(listener)
}

export function activeOptionUser(): string {
  return activeUser
}

function touch(): void {
  epoch += 1
  for (const listener of listeners) listener()
}

function same(left: SavedChoice[], right: SavedChoice[]): boolean {
  if (left.length !== right.length) return false
  return left.every((item, index) => {
    const other = right[index]
    return Boolean(other) && item.value === other.value && item.label === other.label && item.parent === other.parent &&
      item.caseTypeId === other.caseTypeId && item.statusClass === other.statusClass
  })
}

function optionalId(value: unknown, limit: number): string {
  return typeof value === 'string' && value.trim().length <= limit ? value.trim() : ''
}

function cleanChoice(value: unknown): SavedChoice | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const row = value as Record<string, unknown>
  if (typeof row.value !== 'string' || typeof row.label !== 'string') return null
  const id = row.value.trim()
  const label = row.label.trim()
  if (!id || !label || id.length > 120 || label.length > 200 || label.replace(/[\s\-—_]/g, '') === '请选择') return null
  const parent = typeof row.parent === 'string' ? row.parent.trim() : ''
  if (parent.length > 120) return null
  const caseTypeId = optionalId(row.caseTypeId, 120)
  const statusClass = optionalId(row.statusClass, 40)
  return {
    value: id,
    label,
    ...(parent ? { parent } : {}),
    ...(caseTypeId ? { caseTypeId } : {}),
    ...(statusClass ? { statusClass } : {})
  }
}

function sanitize(choices: SavedChoice[]): SavedChoice[] {
  const seen = new Set<string>()
  const output: SavedChoice[] = []
  for (const item of choices) {
    const clean = cleanChoice(item)
    if (!clean || seen.has(clean.value)) continue
    seen.add(clean.value)
    output.push(clean)
    if (output.length >= 2000) break
  }
  return output
}

function parseBag(value: unknown): Map<string, SavedChoice[]> {
  const bag = new Map<string, SavedChoice[]>()
  if (!value || typeof value !== 'object' || Array.isArray(value)) return bag
  for (const [key, rows] of Object.entries(value as Record<string, unknown>)) {
    if (!key || key.length > 80 || !Array.isArray(rows)) continue
    const choices = sanitize(rows as SavedChoice[])
    if (choices.length || rows.length === 0) bag.set(key, choices)
    if (bag.size >= 400) break
  }
  return bag
}

function scheduleFlush(): void {
  if (flushTimer) return
  flushTimer = setTimeout(() => {
    flushTimer = 0
    void flushOptionFallback()
  }, 200) as unknown as number
}

export async function flushOptionFallback(): Promise<void> {
  if (flushTimer) {
    clearTimeout(flushTimer)
    flushTimer = 0
  }
  const users = [...dirtyUsers]
  dirtyUsers.clear()
  const area = globalThis.chrome?.storage?.local
  if (!area || users.length === 0) return
  try {
    const stored = await area.get(STORAGE_KEY)
    const previous = stored[STORAGE_KEY]
    const all = previous && typeof previous === 'object' && !Array.isArray(previous)
      ? { ...(previous as Record<string, unknown>) }
      : {}
    for (const userId of users) {
      const bag = memory.get(userId)
      if (!bag?.size) continue
      const row: Record<string, SavedChoice[]> = {}
      for (const [key, choices] of bag) row[key] = choices
      all[userId] = row
    }
    await area.set({ [STORAGE_KEY]: all })
  } catch {
    for (const userId of users) dirtyUsers.add(userId)
  }
}

/** 切换账号后先用这个账号上次保存的下拉，接口回来再覆盖。 */
export function activateOptionFallback(userId: string): void {
  activeUser = userId
  touch()
}

export async function hydrateOptionFallback(userId: string): Promise<void> {
  activeUser = userId
  if (!userId || loadedUsers.has(userId)) {
    touch()
    return
  }
  loadedUsers.add(userId)
  const area = globalThis.chrome?.storage?.local
  if (!area) {
    touch()
    return
  }
  try {
    const stored = await area.get(STORAGE_KEY)
    const bag = stored[STORAGE_KEY]
    const row = bag && typeof bag === 'object' && !Array.isArray(bag)
      ? (bag as Record<string, unknown>)[userId]
      : undefined
    const parsed = parseBag(row)
    if (parsed.size) {
      const current = memory.get(userId) ?? new Map<string, SavedChoice[]>()
      for (const [key, choices] of parsed) {
        if (!current.has(key)) current.set(key, choices)
      }
      memory.set(userId, current)
    }
  } catch {
    loadedUsers.delete(userId)
  }
  touch()
}

export function savedChoices(userId: string, key: string): SavedChoice[] | null {
  const rows = memory.get(userId)?.get(key)
  return rows ? rows.map(item => ({ ...item })) : null
}

/** 这个字段已经存下非空选项才算有账本。有账本的字段走静默校对：拉取不挡界面，拉不到用账本兜底。 */
export function hasSavedChoices(userId: string, key: string): boolean {
  return (memory.get(userId)?.get(key)?.length ?? 0) > 0
}

/**
 * 扫描空列表不覆盖旧值；接口确认的空列表写为墓碑，直至读到新的真实选项。
 * `nonEmptyOnly` 用于静默校对：账本上已有非空选项时，空结果一律不写回（非空才更新）。
 * 返回这次真正写进去的键有没有变化。
 */
export function rememberChoices(userId: string, key: string, choices: SavedChoice[], confirmedEmpty = false, nonEmptyOnly = false): boolean {
  if (!userId || !key || key.length > 80) return false
  const clean = sanitize(choices)
  if (!clean.length && !confirmedEmpty) return false
  const bag = memory.get(userId) ?? new Map<string, SavedChoice[]>()
  const previous = bag.get(key)
  if (nonEmptyOnly && !clean.length && (previous?.length ?? 0) > 0) return false
  if (previous && same(previous, clean)) return false
  bag.set(key, clean)
  memory.set(userId, bag)
  dirtyUsers.add(userId)
  scheduleFlush()
  touch()
  return true
}

export function choicesFromDictionary(dictionary: NormalizedDictionary | undefined): SavedChoice[] {
  if (!dictionary || dictionary.status === 'invalid') return []
  return sanitize(dictionary.options.flatMap(item => {
    if (item.disabled || !item.value || !item.label) return []
    return [{
      value: item.value,
      label: item.label,
      ...(item.parentValue ? { parent: item.parentValue } : {}),
      ...(item.metadata?.caseTypeId ? { caseTypeId: item.metadata.caseTypeId } : {}),
      ...(item.metadata?.statusClass ? { statusClass: item.metadata.statusClass } : {})
    }]
  }))
}

const CASE_STATUS_KEYS = new Set(['case_status', 'case_status_id'])

/**
 * 按当前案件类型收窄缓存里的下拉。原站 FileSearch.js / LimitMonitor.js 都是
 * 「status_class 为 ALL 或 CASE，且 case_type_id 等于当前案件类型」才放进案件状态树；
 * 没选案件类型时原站下拉框默认专利，这里同口径用调用方传入的默认值。
 * 没带案件类型归属的旧缓存原样返回，不做猜测。
 */
export function scopeSavedChoices(key: string, choices: SavedChoice[], caseTypeId: string): SavedChoice[] {
  const type = caseTypeId.trim()
  if (!type || !choices.some(item => item.caseTypeId)) return choices
  return choices.filter(item => {
    if (item.caseTypeId && item.caseTypeId !== type) return false
    if (CASE_STATUS_KEYS.has(key) && item.statusClass) return item.statusClass === 'ALL' || item.statusClass === 'CASE'
    return true
  })
}

/** 按表单键保存成功字典；明确空写墓碑，失败来源不改变已有缓存。返回这次有变化的表单键。 */
export function rememberDictionaries(
  userId: string,
  formToDictionary: Record<string, string>,
  dictionaries: Record<string, NormalizedDictionary>,
  nonEmptyOnly = false
): string[] {
  const changed: string[] = []
  for (const [formKey, name] of Object.entries(formToDictionary)) {
    const dictionary = dictionaries[name]
    if (!dictionary || dictionary.status === 'invalid') continue
    if (rememberChoices(userId, formKey, choicesFromDictionary(dictionary), dictionary.status === 'empty', nonEmptyOnly)) changed.push(formKey)
  }
  return changed
}

/** 脚本扫到的下拉只有带选项时才覆盖回退。调用方传入已经换成表单键的字段。返回这次有变化的字段键。 */
export function rememberFormFields(userId: string, fields: FileSearchFormField[]): string[] {
  const changed: string[] = []
  for (const field of fields) {
    if ((field.control !== 'select' && field.control !== 'picker') || !field.options.length) continue
    if (savedChoices(userId, field.id)?.length === 0) continue
    if (rememberChoices(userId, field.id, field.options)) changed.push(field.id)
  }
  return changed
}

/** 静默校对的回执文案：有更新点名，拉不到就说明用账本兜底，手动点开时至少给一句话。 */

export function describeOptionUpdate(changedLabels: string[]): string {
  return changedLabels.length ? `下拉选项已更新：${changedLabels.join('、')}。` : ''
}

export const OPTION_PULL_UNCHANGED = '已经和原网站对过，选项没有变化。'
export const OPTION_PULL_FALLBACK = '没有拉到最新下拉，继续用上次的选项。'

export interface OptionPullSummary {
  /** 这次真正换上的下拉对应的字段名。 */
  updatedLabels: string[]
  /** 拉取失败、部分字典没回传之类的说明；静默兜底时不会展示。 */
  failures: string[]
  /** 用户手动点「校对最新字段」时才给没变化的回执。 */
  manual: boolean
  /** 账本里已有非空选项：拉不到就用账本兜底，而不是报错。 */
  hasLedger: boolean
  /** 各界面自己的补充说明，比如自定义栏位改名。 */
  extra?: string[]
}

export function describeOptionPull(summary: OptionPullSummary): string {
  const parts: string[] = []
  const updated = describeOptionUpdate(summary.updatedLabels)
  if (updated) parts.push(updated)
  if (summary.failures.length) parts.push(summary.hasLedger ? OPTION_PULL_FALLBACK : summary.failures[0]!)
  for (const line of summary.extra ?? []) {
    if (line) parts.push(line)
  }
  if (!parts.length && summary.manual) parts.push(OPTION_PULL_UNCHANGED)
  return parts.join('')
}

import { isFileSearchBusinessField } from '../api/file-search-params'
import { isFilingSearchInputField } from '../api/filing-search-params'
import { isForbiddenFieldName } from './field-registry'
import type { QueryTemplate } from './query-types'

const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const GENERIC_KEY = /^[A-Za-z_][A-Za-z0-9_]*$/

export function isQueryGuid(value: string): boolean {
  return GUID.test(value)
}

function stringRecord(value: unknown, accept: (key: string) => boolean): Record<string, string> | null {
  if (value === undefined) return {}
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return null
  const output = Object.create(null) as Record<string, string>
  for (const key of Object.keys(value as object)) {
    const raw = (value as Record<string, unknown>)[key]
    if (isForbiddenFieldName(key) || typeof raw !== 'string' || !accept(key)) return null
    output[key] = raw
  }
  return output
}

export function isQueryTemplate(value: unknown): value is QueryTemplate {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false
  const template = value as Record<string, unknown>
  if (typeof template.id !== 'string' || !template.id.trim()) return false
  if (typeof template.name !== 'string' || !template.name.trim() || template.name.length > 80) return false
  if (template.source !== 'local' && template.source !== 'easy') return false
  if (template.queryType !== 'FileSearch' && template.queryType !== 'FilingSearch') return false
  // 递交查询的模板只存本机：原站的递交列表没有模板功能，也没有可写回的查询。
  if (template.queryType === 'FilingSearch' && template.source !== 'local') return false
  if (template.sourceQueryId !== undefined && (typeof template.sourceQueryId !== 'string' || !isQueryGuid(template.sourceQueryId))) return false
  if (!Number.isSafeInteger(template.version) || Number(template.version) < 1) return false
  if (typeof template.createdAt !== 'string' || typeof template.updatedAt !== 'string') return false
  const fieldOk = template.queryType === 'FilingSearch' ? isFilingSearchInputField : isFileSearchBusinessField
  const unknown = stringRecord(template.unknownFields, key => GENERIC_KEY.test(key))
  // 递交模板没有原站页面字段，unknownFields 只能为空。
  if (unknown === null || (template.queryType === 'FilingSearch' && Object.keys(unknown).length > 0)) return false
  return stringRecord(template.fields, fieldOk) !== null &&
    stringRecord(template.displayValues, fieldOk) !== null
}

export function cloneTemplate(template: QueryTemplate): QueryTemplate {
  return {
    ...template,
    fields: { ...template.fields },
    ...(template.displayValues ? { displayValues: { ...template.displayValues } } : {}),
    ...(template.unknownFields ? { unknownFields: { ...template.unknownFields } } : {}),
    ...(template.sourceQueryId ? { sourceQueryId: template.sourceQueryId } : {})
  }
}

import type { RecoveryHead, RecoverySlot } from './wal-ledger'
export const RECOVERY_RPC = 'PATMAIL_RECOVERY_RPC'
export type RecoveryRequest = { op: 'get' | 'put' | 'latest' | 'heads' | 'checkpoint'; slot?: RecoverySlot; scope?: string; payload?: unknown; expectedRevision?: number }
export interface RecoveryReply { payload?: unknown; revision?: number }
export type RecoveryTransport = (request: RecoveryRequest) => Promise<RecoveryReply>
export function createRecoveryClient(transport: RecoveryTransport = async request => {
  if (!globalThis.chrome?.runtime?.sendMessage) throw new Error('恢复账本不可用，当前工作尚未保护。')
  const response = await chrome.runtime.sendMessage({ type: RECOVERY_RPC, request })
  if (!response?.ok) throw new Error(response?.error || '恢复账本未提交。')
  return response.value
}) {
  const revisions = new Map<string, number>()
  let chain = Promise.resolve()
  const key = (slot: RecoverySlot, scope: string) => JSON.stringify([slot, scope])
  const ordered = <T>(work: () => Promise<T>): Promise<T> => {
    const run = chain.then(work, work)
    chain = run.then(() => undefined, () => undefined)
    return run
  }
  async function read(slot: RecoverySlot, scope: string) {
    const reply = await transport({ op: 'get', slot, scope })
    revisions.set(key(slot, scope), reply.revision ?? 0)
    return reply.payload ?? null
  }
  async function write(slot: RecoverySlot, scope: string, payload: unknown) {
    const id = key(slot, scope)
    if (!revisions.has(id)) await read(slot, scope)
    const reply = await transport({ op: 'put', slot, scope, payload, expectedRevision: revisions.get(id)! })
    revisions.set(id, reply.revision!)
  }
  return {
    get: (slot: RecoverySlot, scope: string) => ordered(() => read(slot, scope)),
    put: (slot: RecoverySlot, scope: string, payload: unknown) => ordered(() => write(slot, scope, payload)),
    forget: (slot: RecoverySlot, scope: string) => ordered(() => write(slot, scope, { forgotten: true })),
    latest: (slot: RecoverySlot) => ordered(async () => { const head = (await transport({ op: 'latest', slot })).payload as RecoveryHead | null; if (head?.revision !== undefined) revisions.set(key(slot, head.scope), head.revision); return head }),
    heads: (slot: RecoverySlot) => ordered(async () => { const heads = (await transport({ op: 'heads', slot })).payload as RecoveryHead[]; for (const head of heads) if (head.revision !== undefined) revisions.set(key(slot, head.scope), head.revision); return heads }),
    checkpoint: () => ordered(async () => { await transport({ op: 'checkpoint' }) })
  }
}

import initSqlJs, { type SqlStatic } from 'sql.js'
import { createRecoveryClient } from './client'

type SqlDatabase = InstanceType<SqlStatic['Database']>
import wasmAsset from 'sql.js/dist/sql-wasm.wasm?url'

/** 工作面、查询结果、发文账本、流程执行记录、递交导出行档。登录掉了也按这个槽位装回去。 */
export type RecoverySlot = 'workflow-desk' | 'limit-query' | 'limit-mail' | 'file-mail' | 'file-desk' | 'workflow-exec' | 'mail-exec' | 'filing-export' | 'file-query'

export interface StoredFrame {
  seq: number
  slot: RecoverySlot
  scope: string
  payload: string
  at: string
}

export interface RecoveryStore {
  readCheckpoint(): Promise<Uint8Array | null>
  writeCheckpoint(bytes: Uint8Array): Promise<void>
  commitCheckpoint?(bytes: Uint8Array, through: number): Promise<void>
  appendFrame(frame: StoredFrame): Promise<void>
  readFrames(): Promise<StoredFrame[]>
  dropFramesThrough(seq: number): Promise<void>
}

export interface RecoveryHead {
  scope: string
  payload: unknown
  at: string
  revision?: number
}

const SLOTS = new Set<RecoverySlot>(['workflow-desk', 'limit-query', 'limit-mail', 'file-mail', 'file-desk', 'workflow-exec', 'mail-exec', 'filing-export', 'file-query'])

/** 两个系统各留一份。origin 用站点地址，leaf 是页面里的槽。 */
export function systemScope(origin: string, leaf: string): string {
  const base = origin.trim().replace(/\/+$/, '').toLowerCase() || 'local'
  const scope = `${base}|${leaf}`
  return scope.length > 200 ? scope.slice(0, 200) : scope
}
const SECRET = /^(cookie|authorization|password|set-cookie)$/i

let wasmOverride: ArrayBuffer | null = null
let engine: Promise<SqlStatic> | null = null

/** 测试直接交给 wasm 字节，避免再去拉文件。 */
export function useRecoveryWasm(bytes: ArrayBuffer): void {
  wasmOverride = bytes
  engine = null
}

async function wasmBinary(): Promise<ArrayBuffer> {
  if (wasmOverride) return wasmOverride
  const response = await fetch(wasmAsset)
  if (!response.ok) throw new Error('恢复账本组件没有载入。')
  return response.arrayBuffer()
}

function sqlEngine(): Promise<SqlStatic> {
  engine ??= wasmBinary().then(binary => initSqlJs({ wasmBinary: binary }))
  return engine
}

export function isSlot(value: string): value is RecoverySlot {
  return SLOTS.has(value as RecoverySlot)
}

function hasSecret(value: unknown): boolean {
  if (!value || typeof value !== 'object') return false
  if (Array.isArray(value)) return value.some(item => hasSecret(item))
  return Object.entries(value).some(([key, item]) => SECRET.test(key) || hasSecret(item))
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : ''
}

function cell(row: unknown[], columns: string[], name: string): unknown {
  return row[columns.indexOf(name)]
}

function quote(value: string): string {
  return `'${value.replace(/'/g, "''")}'`
}

export function memoryRecoveryStore(): RecoveryStore {
  let checkpoint: Uint8Array | null = null
  const frames: StoredFrame[] = []
  return {
    async readCheckpoint() {
      return checkpoint ? checkpoint.slice() : null
    },
    async writeCheckpoint(bytes) {
      checkpoint = bytes.slice()
    },
    async appendFrame(frame) {
      frames.push({ ...frame })
    },
    async readFrames() {
      return frames.map(item => ({ ...item }))
    },
    async dropFramesThrough(seq) {
      for (let index = frames.length - 1; index >= 0; index -= 1) {
        if (frames[index].seq <= seq) frames.splice(index, 1)
      }
    }
  }
}

const DB_NAME = 'patmail-recovery'
const CHECKPOINT = 'checkpoint'
const WAL = 'wal'
const CHECKPOINT_KEY = 'db'

/** 扩展自己的 IndexedDB。页面和后台共用这一份，不放在原站页面里。 */
export function indexedRecoveryStore(factory: IDBFactory | undefined = globalThis.indexedDB): RecoveryStore | null {
  if (!factory) return null
  let opened: Promise<IDBDatabase> | null = null
  const open = (): Promise<IDBDatabase> => {
    opened ??= new Promise((resolve, reject) => {
      const request = factory.open(DB_NAME, 1)
      request.onupgradeneeded = () => {
        const database = request.result
        if (!database.objectStoreNames.contains(CHECKPOINT)) database.createObjectStore(CHECKPOINT)
        if (!database.objectStoreNames.contains(WAL)) database.createObjectStore(WAL)
      }
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error ?? new Error('恢复账本没有打开。'))
    })
    return opened
  }
  async function transaction<T>(names: string | string[], mode: IDBTransactionMode, work: (tx: IDBTransaction, result: (value: T) => void) => void): Promise<T> {
    const database = await open()
    return new Promise<T>((resolve, reject) => {
      const tx = database.transaction(names, mode)
      let value: T
      tx.oncomplete = () => resolve(value)
      tx.onerror = tx.onabort = () => reject(tx.error ?? new Error('恢复账本事务未提交。'))
      try { work(tx, next => { value = next }) } catch (error) { tx.abort(); reject(error) }
    })
  }
  function removeThrough(tx: IDBTransaction, through: number): void {
    const request = tx.objectStore(WAL).openCursor()
    request.onsuccess = () => {
      const cursor = request.result
      if (!cursor) return
      if (typeof cursor.key === 'number' && cursor.key <= through) cursor.delete()
      cursor.continue()
    }
  }
  return {
    readCheckpoint: () => transaction<Uint8Array | null>(CHECKPOINT, 'readonly', (tx, result) => {
      const request = tx.objectStore(CHECKPOINT).get(CHECKPOINT_KEY)
      request.onsuccess = () => result(request.result instanceof Uint8Array ? request.result : null)
    }),
    writeCheckpoint: bytes => transaction<void>(CHECKPOINT, 'readwrite', tx => { tx.objectStore(CHECKPOINT).put(bytes, CHECKPOINT_KEY) }),
    commitCheckpoint: (bytes, through) => transaction<void>([CHECKPOINT, WAL], 'readwrite', tx => {
      tx.objectStore(CHECKPOINT).put(bytes, CHECKPOINT_KEY)
      removeThrough(tx, through)
    }),
    appendFrame: frame => transaction<void>(WAL, 'readwrite', tx => { tx.objectStore(WAL).add(frame, frame.seq) }),
    readFrames: () => transaction<StoredFrame[]>(WAL, 'readonly', (tx, result) => {
      const request = tx.objectStore(WAL).getAll()
      request.onsuccess = () => result((request.result as StoredFrame[]).filter(frame =>
        Number.isSafeInteger(frame?.seq) && isSlot(frame.slot) && typeof frame.scope === 'string' && typeof frame.payload === 'string'))
    }),
    dropFramesThrough: seq => transaction<void>(WAL, 'readwrite', tx => removeThrough(tx, seq))
  }
}

function schema(db: SqlDatabase): string {
  db.run(`CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS wal (
      seq INTEGER PRIMARY KEY,
      slot TEXT NOT NULL,
      scope TEXT NOT NULL,
      payload TEXT NOT NULL,
      at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS head (
      slot TEXT NOT NULL,
      scope TEXT NOT NULL,
      seq INTEGER NOT NULL,
      payload TEXT NOT NULL,
      at TEXT NOT NULL,
      PRIMARY KEY (slot, scope)
    )`)
  const mode = db.exec('PRAGMA journal_mode=WAL')
  db.run('PRAGMA synchronous=NORMAL')
  const journal = text(mode[0]?.values[0]?.[0]) || 'memory'
  db.run(`INSERT INTO meta (key, value) VALUES ('journal', ${quote(journal)}) ON CONFLICT(key) DO UPDATE SET value=excluded.value`)
  return journal
}

function maxSeq(db: SqlDatabase): number {
  // 序号同时看暂存的 wal 和已折好的 head：wal 表被清掉之后序号也不能回头，不然新笔压不动旧 head。
  const rows = db.exec('SELECT COALESCE(MAX(seq), 0) AS seq FROM (SELECT seq FROM wal UNION ALL SELECT seq FROM head)')
  const value = rows[0]?.values[0]?.[0]
  return typeof value === 'number' ? value : 0
}

/** 已经折进 head 的行从 wal 表里清掉。这张表只当暂存用，不清的话每笔快照都背着全量历史，越写越大。 */
function compactWal(db: SqlDatabase, through: number): void {
  try { db.run(`DELETE FROM wal WHERE seq <= ${through}`) } catch { /* 清不掉也不影响读写 */ }
}

function applyFrame(db: SqlDatabase, frame: StoredFrame): void {
  db.run('BEGIN IMMEDIATE')
  try {
    db.run(`INSERT OR IGNORE INTO wal (seq, slot, scope, payload, at) VALUES (${frame.seq}, ${quote(frame.slot)}, ${quote(frame.scope)}, ${quote(frame.payload)}, ${quote(frame.at)})`)
    db.run(`INSERT INTO head (slot, scope, seq, payload, at) VALUES (${quote(frame.slot)}, ${quote(frame.scope)}, ${frame.seq}, ${quote(frame.payload)}, ${quote(frame.at)})
      ON CONFLICT(slot, scope) DO UPDATE SET seq=excluded.seq, payload=excluded.payload, at=excluded.at
      WHERE excluded.seq >= head.seq`)
    db.run('COMMIT')
  } catch (error) {
    try { db.run('ROLLBACK') } catch { /* 事务已经结束 */ }
    throw error
  }
}

/** 折库前把 SQLite 自己的 WAL 日志并回主库，导出才是完整的一份。 */
function foldJournal(db: SqlDatabase): void {
  try { db.run('PRAGMA wal_checkpoint(TRUNCATE)') } catch { /* 这一下没折进去，导出时仍是提交后的库 */ }
}

function readPayload(raw: string): unknown | null {
  try {
    const parsed: unknown = JSON.parse(raw)
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && (parsed as { forgotten?: unknown }).forgotten === true) return null
    return parsed
  } catch {
    return null
  }
}

/** SQLite 开着 WAL。真正掉电前先把这一笔写进 IndexedDB，再折进库文件。库文件没写完时，下次打开会把那一笔补上。
 * 折库是整库导出（O(库大小)），所以跟着写回合并攒着一把做：帧先落账本兜底，库文件按节拍/批量补上。 */
export class RecoveryLedger {
  private chain: Promise<void> = Promise.resolve()
  /** 已经折进内存库的最后一笔。 */
  private foldedSeq = 0
  /** 已经落进库文件的最后一笔。 */
  private checkpointSeq = 0
  private checkpointTimer: ReturnType<typeof setTimeout> | undefined

  constructor(private readonly store: RecoveryStore, private readonly db: SqlDatabase, readonly journalMode: string) {
    this.foldedSeq = maxSeq(db)
    this.checkpointSeq = this.foldedSeq
  }

  put(slot: RecoverySlot, scope: string, payload: unknown, expectedRevision?: number): Promise<void> {
    return this.enqueue(() => this.write(slot, scope, payload, expectedRevision))
  }

  /** 把攒着的笔一把折进库文件：整库导出只做一次，不跟着每一笔跑。 */
  checkpoint(): Promise<void> {
    return this.enqueue(() => this.fold())
  }

  forget(slot: RecoverySlot, scope: string): Promise<void> {
    return this.put(slot, scope, { forgotten: true })
  }

  async get(slot: RecoverySlot, scope: string): Promise<unknown | null> {
    await this.chain
    const rows = this.db.exec(`SELECT payload FROM head WHERE slot=${quote(slot)} AND scope=${quote(scope)}`)
    const raw = rows[0]?.values[0]?.[0]
    return typeof raw === 'string' ? readPayload(raw) : null
  }

  async latest(slot: RecoverySlot): Promise<RecoveryHead | null> {
    await this.chain
    const table = this.db.exec(`SELECT scope, payload, at, seq FROM head WHERE slot=${quote(slot)} ORDER BY seq DESC`)[0]
    if (!table) return null
    for (const row of table.values) {
      const payload = readPayload(text(cell(row, table.columns, 'payload')))
      if (payload == null) continue
      return { scope: text(cell(row, table.columns, 'scope')), payload, at: text(cell(row, table.columns, 'at')), revision: Number(cell(row, table.columns, 'seq')) }
    }
    return null
  }

  async heads(slot: RecoverySlot): Promise<RecoveryHead[]> {
    await this.chain
    const table = this.db.exec(`SELECT scope, payload, at, seq FROM head WHERE slot=${quote(slot)} ORDER BY seq`)[0]
    if (!table) return []
    return table.values.flatMap(row => {
      const payload = readPayload(text(cell(row, table.columns, 'payload')))
      if (payload == null) return []
      return [{ scope: text(cell(row, table.columns, 'scope')), payload, at: text(cell(row, table.columns, 'at')), revision: Number(cell(row, table.columns, 'seq')) }]
    })
  }

  async revision(slot: RecoverySlot, scope: string): Promise<number> {
    await this.chain
    return this.currentRevision(slot, scope)
  }

  private currentRevision(slot: RecoverySlot, scope: string): number {
    const value = this.db.exec(`SELECT seq FROM head WHERE slot=${quote(slot)} AND scope=${quote(scope)}`)[0]?.values[0]?.[0]
    return typeof value === 'number' ? value : 0
  }

  private enqueue<T>(work: () => Promise<T>): Promise<T> {
    const run = this.chain.then(work, work)
    this.chain = run.then(() => undefined, () => undefined)
    return run
  }

  private async write(slot: RecoverySlot, scope: string, payload: unknown, expectedRevision?: number): Promise<void> {
    if (expectedRevision !== undefined && this.currentRevision(slot, scope) !== expectedRevision) throw new Error('RECOVERY_CONFLICT：工作面已被其它页面更新，请重新载入后合并。')
    if (!isSlot(slot) || !scope || scope.length > 16384) throw new Error('恢复账本的范围不对。')
    if (hasSecret(payload)) throw new Error('恢复账本不保存登录凭据。')
    const frame: StoredFrame = {
      seq: maxSeq(this.db) + 1,
      slot,
      scope,
      payload: JSON.stringify(payload),
      at: new Date().toISOString()
    }
    // 帧先落 IndexedDB（掉电兜底），整库导出攒着一把做——一笔一导出是 O(库大小) 的写放大。
    await this.store.appendFrame(frame)
    applyFrame(this.db, frame)
    this.foldedSeq = frame.seq
    if (frame.seq - this.checkpointSeq >= CHECKPOINT_BATCH) {
      this.checkpoint().catch(() => { /* 折库失败不挡写入：帧已经落账本，下一笔再折 */ })
      return
    }
    this.scheduleCheckpoint()
  }

  /** 写回合并：停手一小会儿才折库；连续写就一直攒着，最多攒 CHECKPOINT_BATCH 笔。 */
  private scheduleCheckpoint(): void {
    if (this.checkpointTimer !== undefined) clearTimeout(this.checkpointTimer)
    this.checkpointTimer = setTimeout(() => {
      this.checkpointTimer = undefined
      this.checkpoint().catch(() => { /* 折库失败不挡写入：帧已经落账本，下次再折 */ })
    }, CHECKPOINT_WAIT)
  }

  private async fold(): Promise<void> {
    if (this.checkpointTimer !== undefined) {
      clearTimeout(this.checkpointTimer)
      this.checkpointTimer = undefined
    }
    const through = this.foldedSeq
    if (through <= this.checkpointSeq) return
    compactWal(this.db, through)
    foldJournal(this.db)
    await persistCheckpoint(this.store, this.db.export(), through)
    this.checkpointSeq = through
  }
}

/** 折库节拍：停手 500ms 折一次，攒够 120 笔不等节拍直接折。 */
const CHECKPOINT_WAIT = 500
const CHECKPOINT_BATCH = 120

async function persistCheckpoint(store: RecoveryStore, bytes: Uint8Array, through: number): Promise<void> {
  if (store.commitCheckpoint) await store.commitCheckpoint(bytes, through)
  else { await store.writeCheckpoint(bytes); await store.dropFramesThrough(through) }
}

async function replay(store: RecoveryStore, db: SqlDatabase): Promise<void> {
  const frames = (await store.readFrames()).sort((a, b) => a.seq - b.seq)
  let applied = 0
  for (const frame of frames) {
    if (!isSlot(frame.slot)) continue
    applyFrame(db, frame)
    applied = frame.seq
  }
  if (applied) {
    compactWal(db, applied)
    foldJournal(db)
    await persistCheckpoint(store, db.export(), applied)
  }
}

export async function openRecoveryLedger(store: RecoveryStore): Promise<RecoveryLedger> {
  const SQL = await sqlEngine()
  const bytes = await store.readCheckpoint()
  const db = bytes && bytes.byteLength > 0 ? new SQL.Database(bytes) : new SQL.Database()
  const journal = schema(db)
  await replay(store, db)
  return new RecoveryLedger(store, db, journal)
}

// Production pages never open their own SQLite copy. One service worker owns sequence allocation.
const remote = createRecoveryClient()
export async function recoveryLedger() { return remote }
export async function recoveryLedgerNow() { return remote }

export async function rememberRecovery(slot: RecoverySlot, scope: string, payload: unknown): Promise<void> {
  // 写不等空闲：这一笔要落盘，等空闲反而可能等不到（关页前的抢救写）。
  const ledger = await recoveryLedgerNow()
  if (!ledger) return
  await ledger.put(slot, scope, payload)
}

export async function forgetRecovery(slot: RecoverySlot, scope: string): Promise<void> {
  const ledger = await recoveryLedgerNow()
  if (!ledger) return
  await ledger.forget(slot, scope)
}

export async function recallRecovery(slot: RecoverySlot, scope: string): Promise<unknown | null> {
  const ledger = await recoveryLedger()
  if (!ledger) return null
  return ledger.get(slot, scope)
}

export async function recallLatest(slot: RecoverySlot): Promise<RecoveryHead | null> {
  const ledger = await recoveryLedger()
  if (!ledger) return null
  return ledger.latest(slot)
}

interface Scheduled {
  slot: RecoverySlot
  scope: string
  read: () => unknown
  timer: number
}

const scheduled = new Map<string, Scheduled>()
const held = new Map<string, unknown | null>()

function holdKey(slot: RecoverySlot, scope: string): string {
  return `${slot}\n${scope}`
}

/**
 * 切系统时先把这一侧放进内存，再异步写进恢复账本。
 * 回来时先读内存，没有再读账本，不用等原网站重查。
 */
export function holdRecovery(slot: RecoverySlot, scope: string, payload: unknown | null): void {
  const key = holdKey(slot, scope)
  held.set(key, payload)
  const previous = scheduled.get(key)
  if (previous) window.clearTimeout(previous.timer)
  scheduled.delete(key)
  void (payload == null ? forgetRecovery(slot, scope) : rememberRecovery(slot, scope, payload)).catch(() => { /* 内存里还有，下一轮再写账本 */ })
}

export function peekRecovery(slot: RecoverySlot, scope: string): unknown | null | undefined {
  const key = holdKey(slot, scope)
  return held.has(key) ? held.get(key) ?? null : undefined
}

async function commitScheduled(key: string, item: Scheduled): Promise<void> {
  scheduled.delete(key)
  try {
    const payload = item.read()
    if (payload == null) await forgetRecovery(item.slot, item.scope)
    else await rememberRecovery(item.slot, item.scope, payload)
  } catch {
    /* 这一笔没记上，页面上的工作还在。 */
  }
}

/** 连续改动合成一笔。read 返回 null 表示这一轮已经清空，账本里也抹掉。 */
export function scheduleRecovery(slot: RecoverySlot, scope: string, read: () => unknown, wait = 400): void {
  const key = `${slot}\n${scope}`
  const previous = scheduled.get(key)
  if (previous) window.clearTimeout(previous.timer)
  const timer = window.setTimeout(() => { void commitScheduled(key, scheduled.get(key) ?? { slot, scope, read, timer }) }, wait)
  scheduled.set(key, { slot, scope, read, timer })
}

export async function flushRecovery(slot: RecoverySlot, scope: string, read: () => unknown): Promise<void> {
  const key = `${slot}\n${scope}`
  const previous = scheduled.get(key)
  if (previous) window.clearTimeout(previous.timer)
  await commitScheduled(key, { slot, scope, read, timer: 0 })
}

if (typeof window !== 'undefined') {
  window.addEventListener('pagehide', () => {
    for (const [key, item] of scheduled) {
      window.clearTimeout(item.timer)
      void commitScheduled(key, item)
    }
    // 攒着还没折库的笔趁关页前折掉；折不完也没事，帧还在账本里，下次打开补上。
    void remote.checkpoint().catch(() => { /* 持久帧由后台保留 */ })
  })
}

import type { DictionaryOption } from '../api/dictionaries/types'

export interface ResolvedDisplay {
  text: string
  unresolved: boolean
}

/** 只生成展示文案，不改写已经保存的内部 ID。 */
export function resolveInternalIdDisplay(value: string, options: DictionaryOption[], multiple = false): ResolvedDisplay {
  if (!value.trim()) return { text: '未设置', unresolved: false }
  const ids = multiple ? value.split(',').map(item => item.trim()).filter(Boolean) : [value.trim()]
  const labels = ids.map(id => options.find(item => item.value === id)?.label)
  if (labels.some(label => !label)) return { text: '未识别的历史 ID', unresolved: true }
  return { text: labels.join('、'), unresolved: false }
}

export function unknownIds(value: string, options: DictionaryOption[]): string[] {
  return value.split(',').map(item => item.trim()).filter(id => id && !options.some(item => item.value === id))
}

/**
 * 多选值（逗号拼的内部 ID）逐个换显示名，再用逗号拼回去，和原站 `{控件}_text` 的写法一致。
 * 有一个换不出来就返回空串：宁可不写这节，也不把 GUID 串当名字存进模板。
 */
export function resolveMultiLabel(value: string, options: Array<{ value: string; label: string }>): string {
  const parts = value.split(',').map(item => item.trim()).filter(Boolean)
  const labels = parts.map(part => options.find(item => item.value === part)?.label?.trim() ?? '')
  return parts.length > 0 && labels.every(Boolean) ? labels.join(',') : ''
}

export interface FileDescriptionDisplay {
  ids: string[]
  labels: string[]
  resolved: boolean
  unresolvedIds: string[]
  text: string
  /** 逐项展示用：解析出来是名字；解析不出时用历史文本按逗号拆开的片段；再不行用 ID。 */
  items: string[]
  /** 以内部 ID 计的选中项数。 */
  count: number
}

/** 内部 ID 串的样子：十六进制段用短横线连起来。名字里一般有中文，不会长成这样。 */
export function looksLikeInternalIds(value: string): boolean {
  const parts = value.split(/[,，]/).map(item => item.trim()).filter(Boolean)
  return parts.length > 0 && parts.every(part => /^[0-9a-f-]{16,}$/i.test(part) && part.includes('-'))
}

/** 名字里可能带逗号（如 NOTIFICATION ...,OBTENTION ...），按树里的名字把被拆开的片段并回去。 */
function splitFileDescriptionEntries(value: string, names: Set<string>): string[] {
  const raw = value.split(/[,，]/).map(item => item.trim()).filter(Boolean)
  const merged: string[] = []
  for (const part of raw) {
    const last = merged.at(-1)
    const joined = last ? `${last},${part}` : ''
    if (last && joined.length <= 200 && !names.has(last) && names.has(joined)) {
      merged[merged.length - 1] = joined
      continue
    }
    merged.push(part)
  }
  return merged
}

/** 模板和手填都可能混进名字、空段或中文逗号：GUID 原样留，名字按描述树换回 ID，换不了的放 dropped，不蒙混进查询。 */
export function normalizeFileDescriptionValue(
  value: string,
  nodes: Array<{ id: string; name: string }>
): { value: string; dropped: string[] } {
  if (!nodes.length) {
    return { value: value.split(/[,，]/).map(item => item.trim()).filter(Boolean).join(','), dropped: [] }
  }
  const byName = new Map<string, string[]>()
  for (const node of nodes) {
    const key = node.name.trim()
    const bucket = byName.get(key) ?? []
    bucket.push(node.id)
    byName.set(key, bucket)
  }
  const ids: string[] = []
  const dropped: string[] = []
  for (const part of splitFileDescriptionEntries(value, new Set(byName.keys()))) {
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(part)) {
      ids.push(part)
      continue
    }
    const matched = byName.get(part) ?? []
    if (matched.length === 1) ids.push(matched[0]!)
    else dropped.push(part)
  }
  return { value: ids.join(','), dropped }
}

/** 手工查询和历史模板共用。历史显示文本不能把未解析 ID 标成已解析，也不能把 GUID 串当名字摆出来。 */
export function resolveFileDescriptionDisplay(input: {
  savedIds: string
  descriptions?: Array<{ id: string; name: string }>
  historyText?: string
}): FileDescriptionDisplay {
  const ids = input.savedIds.split(',').map(item => item.trim()).filter(Boolean)
  const descriptions = input.descriptions ?? []
  const labels: string[] = []
  const unresolvedIds: string[] = []
  for (const id of ids) {
    const name = descriptions.find(item => item.id.toLowerCase() === id.toLowerCase())?.name
    if (name) labels.push(name)
    else unresolvedIds.push(id)
  }
  const resolved = ids.length > 0 && unresolvedIds.length === 0
  // 历史文本如果本身就是 ID 串（模板存坏了），不能当名字显示。
  const history = input.historyText?.trim() ?? ''
  const historyText = history && !looksLikeInternalIds(history) ? history : ''
  const historyItems = historyText ? historyText.split(/[,，]/).map(item => item.trim()).filter(Boolean) : []
  let text = '未设置'
  if (ids.length === 0) text = '未设置'
  else if (resolved) text = labels.join('、')
  else if (historyText) text = `${historyText}（未识别的历史 ID）`
  else text = ids.length > 1 ? `已选 ${ids.length} 项（未识别的历史 ID）` : '未识别的历史 ID'
  const items = resolved ? labels : historyItems.length ? historyItems : ids
  return { ids, labels, resolved, unresolvedIds, text, items, count: ids.length }
}

/** 超过 max 项只摆前 max 项，尾巴标总数；全文由页面自己展开。 */
export function previewFileDescription(display: FileDescriptionDisplay, max = 10): { short: string; truncated: boolean } {
  if (display.items.length <= max) return { short: display.text, truncated: false }
  const joiner = display.resolved ? '、' : ','
  return { short: `${display.items.slice(0, max).join(joiner)}…（共 ${display.count} 项）`, truncated: true }
}

import { LARGE_CUSTOMER_DOMAIN_ORIGIN, LARGE_CUSTOMER_ORIGIN, PCL_ORIGIN, SME_CUSTOMER_DOMAIN_ORIGIN, SME_CUSTOMER_ORIGIN } from '../api/config'

/** 大客户走 66，中小客户走 44。中小客户先复用大客户的全部能力。 */
export type CustomerMode = 'large' | 'sme'

export const CUSTOMER_MODE_KEY = 'patmail.customerMode.v1'
export const CUSTOMER_MODE_DEFAULT: CustomerMode = 'large'

export function isCustomerMode(value: unknown): value is CustomerMode {
  return value === 'large' || value === 'sme'
}

export function modeOrigin(mode: CustomerMode): string {
  return mode === 'sme' ? SME_CUSTOMER_ORIGIN : LARGE_CUSTOMER_ORIGIN
}

export function modeLabel(mode: CustomerMode): string {
  return mode === 'sme' ? '中小客户' : '大客户'
}

/** 大客户认 66、d.hiseeip.com 和鹏城。中小客户认 44 和 z.hiseeip.com。 */
export function originsForMode(mode: CustomerMode): readonly string[] {
  return mode === 'sme'
    ? [SME_CUSTOMER_ORIGIN, SME_CUSTOMER_DOMAIN_ORIGIN]
    : [LARGE_CUSTOMER_ORIGIN, LARGE_CUSTOMER_DOMAIN_ORIGIN, PCL_ORIGIN]
}

export function originMatchesMode(origin: string, mode: CustomerMode = customerMode()): boolean {
  return originsForMode(mode).includes(origin)
}

function storageReady(): boolean {
  return typeof chrome !== 'undefined' && Boolean(chrome.storage?.local)
}

let mode: CustomerMode = CUSTOMER_MODE_DEFAULT
let hydrated = !storageReady()
let ticket = 0
const listeners = new Set<() => void>()
let watching = false

function publish(): void {
  for (const listener of listeners) listener()
}

export function customerMode(): CustomerMode {
  return mode
}

export function watchCustomerMode(listener?: () => void): () => void {
  if (listener) listeners.add(listener)
  if (!watching && typeof chrome !== 'undefined' && chrome.storage?.onChanged) {
    watching = true
    chrome.storage.onChanged.addListener((changes, area) => {
      if (area !== 'local' || !(CUSTOMER_MODE_KEY in changes)) return
      const next = changes[CUSTOMER_MODE_KEY]?.newValue
      mode = isCustomerMode(next) ? next : CUSTOMER_MODE_DEFAULT
      hydrated = true
      publish()
    })
  }
  return () => {
    if (listener) listeners.delete(listener)
  }
}

export async function hydrateCustomerMode(): Promise<void> {
  const mine = ++ticket
  const previous = mode
  const first = !hydrated
  if (!storageReady()) {
    if (mine !== ticket) return
    hydrated = true
    if (first) publish()
    return
  }
  try {
    const stored = await chrome.storage.local.get(CUSTOMER_MODE_KEY)
    if (mine !== ticket) return
    const next = stored[CUSTOMER_MODE_KEY]
    mode = isCustomerMode(next) ? next : CUSTOMER_MODE_DEFAULT
  } catch {
    if (mine !== ticket) return
    mode = CUSTOMER_MODE_DEFAULT
  }
  hydrated = true
  if (first || mode !== previous) publish()
}

export function isCustomerModeReady(): boolean {
  return hydrated
}

export async function setCustomerMode(next: CustomerMode): Promise<void> {
  ticket += 1
  mode = next
  hydrated = true
  publish()
  if (!storageReady()) return
  try {
    await chrome.storage.local.set({ [CUSTOMER_MODE_KEY]: mode })
  } catch {
    /* 当前页面已经按新模式生效 */
  }
}

import { centerCropRect, MAX_AVATAR_DATA_URL } from './avatar'

const ALLOWED = new Set(['image/jpeg', 'image/png', 'image/webp', 'image/gif'])
const MAX_FILE_BYTES = 8 * 1024 * 1024

const SIZES = [512, 384, 256, 192]

/** 居中裁成正方形，压成 WebP 放进浏览器缓存。透明底会留下来。 */
export async function fitAvatarBlob(file: File): Promise<Blob> {
  return fitAvatar(file, async (canvas, quality) => {
    const blob = await canvasToBlob(canvas, quality)
    return blob.size > 0 && blob.size <= 700_000 ? blob : null
  })
}

/** 缓存不可用时才把小图收成 data URL。 */
export async function fitAvatarFile(file: File): Promise<string> {
  return fitAvatar(file, async (canvas, quality) => {
    const image = canvas.toDataURL('image/webp', quality)
    return image.length <= MAX_AVATAR_DATA_URL ? image : null
  })
}

async function fitAvatar<T>(file: File, accept: (canvas: HTMLCanvasElement, quality: number) => Promise<T | null>): Promise<T> {
  if (!ALLOWED.has(file.type)) throw new Error('请选择 jpg、png、webp 或 gif 图片。')
  if (file.size <= 0 || file.size > MAX_FILE_BYTES) throw new Error('图片需要小于 8MB。')
  const bitmap = await createImageBitmap(file)
  try {
    for (const edge of SIZES) {
      const canvas = drawSquare(bitmap, edge)
      for (const quality of [0.86, 0.72, 0.6]) {
        const accepted = await accept(canvas, quality)
        if (accepted) return accepted
      }
    }
    throw new Error('这张图压完还是太大，换一张再试。')
  } finally {
    bitmap.close()
  }
}

function drawSquare(bitmap: ImageBitmap, edge: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas')
  canvas.width = edge
  canvas.height = edge
  const context = canvas.getContext('2d')
  if (!context) throw new Error('当前页面画不了头像。')
  const crop = centerCropRect(bitmap.width, bitmap.height)
  context.clearRect(0, 0, edge, edge)
  context.drawImage(bitmap, crop.sx, crop.sy, crop.side, crop.side, 0, 0, edge, edge)
  return canvas
}

function canvasToBlob(canvas: HTMLCanvasElement, quality: number): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob(blob => {
      if (blob) resolve(blob)
      else reject(new Error('当前页面压不了头像。'))
    }, 'image/webp', quality)
  })
}

/** 前端写开关。没存过时默认打开。扩展里要先读完存储，读完之前视为关闭。 */
export const WRITE_SWITCH_KEY = 'patmail.writeSwitch.v1'
export const WRITE_SWITCH_DEFAULT = true

function storageReady(): boolean {
  return typeof chrome !== 'undefined' && Boolean(chrome.storage?.local)
}

let open = WRITE_SWITCH_DEFAULT
/** 没有扩展存储时（测试）直接用默认值。扩展进程里要等 hydrate。 */
let hydrated = !storageReady()
let ticket = 0
const listeners = new Set<() => void>()
let watching = false

function publish(): void {
  for (const listener of listeners) listener()
}

export function isWriteSwitchOpen(): boolean {
  return hydrated && open
}

export function isWriteSwitchReady(): boolean {
  return hydrated
}

export function watchWriteSwitch(listener?: () => void): () => void {
  if (listener) listeners.add(listener)
  if (!watching && typeof chrome !== 'undefined' && chrome.storage?.onChanged) {
    watching = true
    chrome.storage.onChanged.addListener((changes, area) => {
      if (area !== 'local' || !(WRITE_SWITCH_KEY in changes)) return
      const next = changes[WRITE_SWITCH_KEY]?.newValue
      open = next === undefined ? WRITE_SWITCH_DEFAULT : next === true
      hydrated = true
      publish()
    })
  }
  return () => {
    if (listener) listeners.delete(listener)
  }
}

export async function hydrateWriteSwitch(): Promise<void> {
  const mine = ++ticket
  if (!storageReady()) {
    if (mine !== ticket) return
    open = WRITE_SWITCH_DEFAULT
    hydrated = true
    publish()
    return
  }
  try {
    const stored = await chrome.storage.local.get(WRITE_SWITCH_KEY)
    if (mine !== ticket) return
    open = Object.prototype.hasOwnProperty.call(stored, WRITE_SWITCH_KEY)
      ? stored[WRITE_SWITCH_KEY] === true
      : WRITE_SWITCH_DEFAULT
  } catch {
    if (mine !== ticket) return
    open = false
  }
  hydrated = true
  publish()
}

export async function setWriteSwitchOpen(next: boolean): Promise<void> {
  ticket += 1
  open = next === true
  hydrated = true
  publish()
  if (!storageReady()) return
  try {
    await chrome.storage.local.set({ [WRITE_SWITCH_KEY]: open })
  } catch {
    /* 当前页面已经按新值生效 */
  }
}

import type {
  FormControlSnapshot, IframeInfo, PageInfo, PageMetadata, PageScanStats, PageSnapshot,
  SelectOptionSnapshot
} from './types'

export function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
}

function strings(value: Record<string, unknown>, keys: string[]): boolean {
  return keys.every(key => typeof value[key] === 'string')
}

function stringMap(value: unknown): value is Record<string, string> {
  return isRecord(value) && Object.values(value).every(item => typeof item === 'string')
}

function nonnegative(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0
}

export function isPageInfo(value: unknown): value is PageInfo {
  return isRecord(value) && strings(value, ['url', 'title', 'hostname'])
}

function isPageMetadata(value: unknown): value is PageMetadata {
  return isRecord(value) &&
    strings(value, ['url', 'origin', 'hostname', 'pathname', 'search', 'title']) &&
    nonnegative(value.iframeDepth) &&
    ['loading', 'interactive', 'complete'].includes(String(value.readyState))
}

function isOption(value: unknown): value is SelectOptionSnapshot {
  return isRecord(value) && strings(value, ['value', 'text']) &&
    typeof value.selected === 'boolean' && typeof value.disabled === 'boolean'
}

function optionalString(value: unknown): boolean {
  return value === undefined || typeof value === 'string'
}

function isControl(value: unknown): value is FormControlSnapshot {
  if (!isRecord(value) || !strings(value, ['key', 'tagName', 'kind']) ||
    !['input', 'textarea', 'select', 'button'].includes(value.kind as string) ||
    !Array.isArray(value.classNames) || !value.classNames.every(name => typeof name === 'string') ||
    typeof value.visible !== 'boolean' || typeof value.disabled !== 'boolean' ||
    typeof value.readonly !== 'boolean' || typeof value.required !== 'boolean' ||
    !stringMap(value.attributes) || !stringMap(value.dataset)) return false
  if (!['inputType', 'id', 'name', 'value', 'displayValue', 'placeholder', 'title', 'label', 'ariaLabel', 'role', 'semanticName']
    .every(key => optionalString(value[key]))) return false
  if (['checked', 'selected', 'multiple'].some(key => value[key] !== undefined && typeof value[key] !== 'boolean')) return false
  if (value.options !== undefined && (!Array.isArray(value.options) || !value.options.every(isOption))) return false
  if (value.semanticConfidence !== undefined &&
    (typeof value.semanticConfidence !== 'number' || value.semanticConfidence < 0 ||
      value.semanticConfidence > 1 || !Number.isFinite(value.semanticConfidence))) return false
  if (value.semanticSource !== undefined &&
    !['label', 'aria', 'title', 'placeholder', 'nearby', 'name', 'id'].includes(String(value.semanticSource))) return false
  return true
}

function isIframe(value: unknown): value is IframeInfo {
  return isRecord(value) && typeof value.src === 'string' && typeof value.sameOrigin === 'boolean'
}

function isStats(value: unknown): value is PageScanStats {
  return isRecord(value) &&
    ['totalControls', 'inputs', 'textareas', 'selects', 'buttons', 'visible', 'hidden',
      'disabled', 'semanticResolved', 'durationMs'].every(key => nonnegative(value[key]))
}

export function isPageSnapshot(value: unknown): value is PageSnapshot {
  if (!isRecord(value) || value.version !== 2 || !isPageMetadata(value.page) ||
    !Array.isArray(value.controls) || !value.controls.every(isControl) ||
    !Array.isArray(value.iframes) || !value.iframes.every(isIframe) ||
    !isStats(value.stats) || typeof value.scannedAt !== 'string') return false
  const stats = value.stats
  return stats.totalControls === value.controls.length &&
    stats.totalControls === stats.inputs + stats.textareas + stats.selects + stats.buttons &&
    stats.totalControls === stats.visible + stats.hidden &&
    stats.disabled <= stats.totalControls && stats.semanticResolved <= stats.totalControls
}

import { isCustomerProfile } from '../customer/guards'
import type { CustomerQueryProfile } from '../customer/types'
import { isQueryTemplate } from '../query/query-validator'
import type { QueryTemplate } from '../query/query-types'

export const QUERY_BUNDLE_VERSION = 1

export interface QueryBundle {
  version: typeof QUERY_BUNDLE_VERSION
  templates: QueryTemplate[]
  customers: CustomerQueryProfile[]
}

export interface QueryBundleRepository {
  readonly queueKey: string
  load(): Promise<{ bundle: QueryBundle; warning?: string; writable: boolean }>
  save(bundle: QueryBundle): Promise<void>
}

export function emptyBundle(): QueryBundle {
  return { version: QUERY_BUNDLE_VERSION, templates: [], customers: [] }
}

export function storageKey(origin: string, userId: string | null): string {
  const scope = userId && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(userId)
    ? userId : 'unscoped'
  return `patmail.query.v${QUERY_BUNDLE_VERSION}:${origin}:${scope}`
}

export function readBundle(value: unknown): { bundle: QueryBundle; warning?: string; writable: boolean } {
  if (value === undefined || value === null) return { bundle: emptyBundle(), writable: true }
  if (typeof value !== 'object' || Array.isArray(value)) {
    return { bundle: emptyBundle(), warning: '本地配置无法识别，未自动覆盖原数据。', writable: false }
  }
  const record = value as Record<string, unknown>
  if (record.version !== undefined && record.version !== QUERY_BUNDLE_VERSION) {
    return { bundle: emptyBundle(), warning: '本地配置版本不匹配，未自动覆盖原数据。', writable: false }
  }
  const templates = Array.isArray(record.templates) ? record.templates.filter(isQueryTemplate) : []
  const customers = Array.isArray(record.customers) ? record.customers.filter(isCustomerProfile) : []
  const dropped = (Array.isArray(record.templates) && templates.length !== record.templates.length) ||
    (Array.isArray(record.customers) && customers.length !== record.customers.length)
  if (dropped) {
    return {
      bundle: { version: QUERY_BUNDLE_VERSION, templates, customers },
      warning: '部分本地配置结构无效，已停止写入以免覆盖原数据。',
      writable: false
    }
  }
  return { bundle: { version: QUERY_BUNDLE_VERSION, templates, customers }, writable: true }
}

export function isPersistableBundle(bundle: QueryBundle): boolean {
  return bundle.version === QUERY_BUNDLE_VERSION &&
    bundle.templates.every(isQueryTemplate) && bundle.customers.every(isCustomerProfile)
}

const bundleQueues = new Map<string, Promise<void>>()

/** 同一配置包的修改串行执行，避免并发 load-modify-save 互相覆盖。 */
export async function updateBundle(repository: QueryBundleRepository, mutate: (bundle: QueryBundle) => void): Promise<void> {
  const previous = bundleQueues.get(repository.queueKey) ?? Promise.resolve()
  const run = previous.then(async () => {
    const loaded = await repository.load()
    if (!loaded.writable) throw new Error(loaded.warning ?? '本地配置只读，未覆盖原数据。')
    const draft = structuredClone(loaded.bundle)
    mutate(draft)
    if (!isPersistableBundle(draft)) throw new Error('本地配置未通过校验，未保存。')
    await repository.save(draft)
  })
  bundleQueues.set(repository.queueKey, run.then(() => undefined, () => undefined))
  return run
}

let memoryBundleSequence = 0

export class MemoryBundleRepository implements QueryBundleRepository {
  readonly queueKey = `memory:${memoryBundleSequence++}`
  private raw: unknown

  constructor(initial?: unknown) {
    this.raw = initial
  }

  async load(): Promise<{ bundle: QueryBundle; warning?: string; writable: boolean }> {
    const read = readBundle(this.raw)
    return { ...read, bundle: structuredClone(read.bundle) }
  }

  async save(bundle: QueryBundle): Promise<void> {
    const current = readBundle(this.raw)
    if (!current.writable) throw new Error(current.warning ?? '本地配置只读，未覆盖原数据。')
    this.raw = structuredClone(bundle)
  }
}

export class ChromeBundleRepository implements QueryBundleRepository {
  readonly queueKey: string

  constructor(private readonly key: string, private readonly area: chrome.storage.StorageArea = chrome.storage.local) {
    this.queueKey = key
  }

  async load(): Promise<{ bundle: QueryBundle; warning?: string; writable: boolean }> {
    const stored = await this.area.get(this.key)
    return readBundle(stored[this.key])
  }

  async save(bundle: QueryBundle): Promise<void> {
    const stored = await this.area.get(this.key)
    const current = readBundle(stored[this.key])
    if (!current.writable) throw new Error(current.warning ?? '本地配置只读，未覆盖原数据。')
    await this.area.set({ [this.key]: bundle })
  }
}

import { MessageType, type StreamDownloadCommand } from '../shared/message'
import type { FileDownloadProgress } from '../shared/download-progress'
import { sendToBackground } from './runtime'
import type { DownloadCache, CachedFileInfo } from '../api/stream-cache'
import { isRecord } from '../shared/guards'

export interface NativeDownloadContext { cache?: DownloadCache; zipCreatedAt?: string; taskId?: string }
const activeProducers = new Map<string, AbortController>()
export function pauseNativeDownload(taskId: string): void {
  activeProducers.get(taskId)?.abort(new Error('下载已暂停，本机缓存和任务已保留。'))
}
const encode = (bytes: Uint8Array) => {
  let text = ''
  for (let i = 0; i < bytes.length; i += 8192) text += String.fromCharCode(...bytes.subarray(i, i + 8192))
  return btoa(text)
}
const decode = (data: string) => Uint8Array.from(atob(data), char => char.charCodeAt(0))

/** 共用有界生产者；浏览器模式直接写已选目标，旧模式保留HTTP续传兼容。 */
export async function nativeStreamArchive(
  fileName: string,
  produce: (sink: WritableStream<Uint8Array>, signal: AbortSignal, onWork: (progress: FileDownloadProgress) => void, context: NativeDownloadContext) => Promise<void>,
  report: (progress: FileDownloadProgress) => void,
  options: { taskId?: string; manifest?: Record<string, unknown>; newCopy?: true; backend?: 'browser'; targetId?: string } = {}
): Promise<number> {
  const controller = new AbortController()
  const signal = controller.signal
  const { backend, ...startOptions } = options
  const browser = backend === 'browser'
  if (options.taskId) {
    activeProducers.get(options.taskId)?.abort(new Error('任务已由新的恢复请求接管。'))
    activeProducers.set(options.taskId, controller)
  }
  const untilAbort = <T>(promise: Promise<T>): Promise<T> => new Promise((resolve, reject) => {
    const abort = () => { signal.removeEventListener('abort', abort); reject(signal.reason) }
    if (signal.aborted) abort(); else signal.addEventListener('abort', abort, { once: true })
    promise.then(value => { signal.removeEventListener('abort', abort); resolve(value) }, error => { signal.removeEventListener('abort', abort); reject(error) })
  })
  const retryDelay = (ms: number) => new Promise<void>((resolve, reject) => {
    const abort = () => { clearTimeout(timer); signal.removeEventListener('abort', abort); reject(signal.reason) }
    const timer = setTimeout(() => { signal.removeEventListener('abort', abort); resolve() }, ms)
    if (signal.aborted) abort(); else signal.addEventListener('abort', abort, { once: true })
  })
  const command = async (payload: StreamDownloadCommand) => {
    // 只重试无副作用的读取；写入/封存的应答丢失时，不能猜测后台是否已经提交。
    const retryable = payload.action === 'status' || (payload.action === 'cache' && (payload.command === 'info' || payload.command === 'read'))
    const cleanup = payload.action === 'pause' || payload.action === 'abort'
    for (let attempt = 0; ; attempt++) {
      if (!cleanup) signal.throwIfAborted()
      const request = sendToBackground({ type: browser ? MessageType.BrowserStreamDownload : MessageType.StreamDownload, payload },
        payload.action === 'write' || payload.action === 'cache' || (browser && payload.action === 'finish') ? 130_000 : 20_000)
      const response = await (cleanup ? request : untilAbort(request))
      if (response?.type === MessageType.StreamDownloadResult) return response.payload
      const reason = response?.type === MessageType.Error ? response.payload.message : '本机下载流没有应答。'
      const transient = !response || /扩展后台没有在时限内返回|扩展后台没有答上|message port closed|receiving end does not exist|service worker/i.test(reason)
      if (!transient) throw new Error(reason)
      if (!retryable || attempt >= 2) throw new Error(`${reason} 下载已暂停，缓存已保留；请点击「继续下载」恢复。`)
      await retryDelay(500 * (attempt + 1))
    }
  }
  const created = await command({ action: 'start', fileName, ...startOptions }).catch(error => {
    if (options.taskId && activeProducers.get(options.taskId) === controller) activeProducers.delete(options.taskId)
    throw error
  })
  if (created.info?.completed === true && Number.isSafeInteger(created.info.completedBytes)) {
    if (options.taskId && activeProducers.get(options.taskId) === controller) activeProducers.delete(options.taskId)
    return Number(created.info.completedBytes)
  }
  if (!created.token) throw new Error('本机下载流缺少写入凭据。')
  const token = created.token
  const manifest = isRecord(created.info?.manifest) ? created.info.manifest : {}
  const names: Record<string, string[]> = {}
  if (isRecord(manifest.cachedNames)) for (const [key, list] of Object.entries(manifest.cachedNames)) {
    if (Array.isArray(list) && list.every(name => typeof name === 'string')) names[key] = list
  }
  const metadata = (info: Partial<CachedFileInfo>): Record<string, unknown> => ({
    ...(info.totalBytes === undefined ? {} : { totalBytes: info.totalBytes }),
    ...(typeof info.etag === 'string' ? { etag: info.etag } : {}),
    ...(typeof info.lastModified === 'string' ? { lastModified: info.lastModified } : {})
  })
  const cache: DownloadCache | undefined = created.taskId ? {
    names,
    async saveNames(offset, list) {
      if (names[String(offset)]?.join(';') === list.join(';')) return
      await command({ action: 'checkpoint', token, offset, names: list })
      names[String(offset)] = list.slice()
    },
    async info(index) {
      const result = (await command({ action: 'cache', command: 'info', token, index })).info
      if (!result || !Number.isSafeInteger(result.receivedBytes) || Number(result.receivedBytes) < 0 || typeof result.complete !== 'boolean') {
        throw new Error('本机附件检查点无效，不能继续下载。')
      }
      return result as unknown as CachedFileInfo
    },
    async reset(index, info) { await command({ action: 'cache', command: 'reset', token, index, metadata: metadata(info) }) },
    async write(index, offset, bytes) { await command({ action: 'cache', command: 'write', token, index, offset, data: encode(bytes) }) },
    async complete(index, info) { await command({ action: 'cache', command: 'complete', token, index, metadata: metadata(info) }) },
    async read(index, offset) { const result = await command({ action: 'cache', command: 'read', token, index, offset }); return decode(result.data ?? '') }
  } : undefined
  const context: NativeDownloadContext = { cache, taskId: created.taskId, zipCreatedAt: typeof manifest.zipCreatedAt === 'string' ? manifest.zipCreatedAt : undefined }
  let failure: Error | null = null, productionDone = false, succeeded = false
  const pageGone = () => controller.abort(new Error('EASY来源页面已离开，下载已暂停并保留缓存。'))
  globalThis.addEventListener?.('pagehide', pageGone, { once: true })
  let sequence = 0, offset = 0, filled = 0
  const block = new Uint8Array(256 * 1024)
  const flush = async () => {
    if (!filled) return
    signal.throwIfAborted()
    await command({ action: 'write', token, sequence, offset, data: encode(block.subarray(0, filled)) })
    sequence++; offset += filled; filled = 0
  }
  const sink = new WritableStream<Uint8Array>({
    async write(chunk) {
      signal.throwIfAborted()
      for (let position = 0; position < chunk.length;) {
        const count = Math.min(block.length - filled, chunk.length - position)
        block.set(chunk.subarray(position, position + count), filled)
        filled += count; position += count
        if (filled === block.length) await flush()
      }
      if (sequence === 0 && filled) await flush()
    },
    async close() { await flush(); await command({ action: 'finish', token }); productionDone = true },
    async abort(reason) { failure ??= reason instanceof Error ? reason : new Error('输出失败，下载任务已保留。'); await command({ action: 'pause', token }).catch(() => {}) }
  })
  const track = (async () => {
    let downloadId = created.downloadId
    try {
      while (!signal.aborted) {
        if (browser) {
          const result = await untilAbort(command({ action: 'status', token }))
          const info = result.info
          if (!info || !Number.isSafeInteger(info.receivedBytes)) throw new Error('浏览器文件写入状态无效，缓存仍保留。')
          const receivedBytes = Number(info.receivedBytes)
          report({ phase: 'downloading', done: 0, total: 1, receivedBytes })
          if (info.state === 'complete' && productionDone) return receivedBytes
          await untilAbort(new Promise<void>(resolve => setTimeout(resolve, 500)))
          continue
        }
        if (downloadId === undefined) downloadId = (await untilAbort(command({ action: 'status', token }))).downloadId
        if (downloadId !== undefined) {
          const response = await untilAbort(sendToBackground({ type: MessageType.DownloadState, payload: { downloadId } }, 15_000))
          if (response?.type === MessageType.DownloadStateResult) {
            const snapshot = response.payload
            report({ phase: 'downloading', done: 0, total: 1, state: snapshot.state, receivedBytes: snapshot.receivedBytes,
              ...(snapshot.totalBytes ? { totalBytes: snapshot.totalBytes } : {}) })
            if (snapshot.state === 'complete' && productionDone) return Math.max(snapshot.receivedBytes, snapshot.totalBytes ?? 0)
            if (snapshot.state === 'interrupted' && /USER_CANCELED/.test(snapshot.error ?? '')) throw new Error('浏览器下载已取消，本机任务已保留，可在工作台继续或丢弃。')
            if (snapshot.state === 'interrupted' && productionDone) throw new Error('浏览器续传中断，本机完整缓存已保留，请继续下载。')
          } else if (productionDone) throw new Error('无法读取浏览器下载记录，本机完整缓存已保留。')
        }
        await untilAbort(new Promise<void>(resolve => setTimeout(resolve, 500)))
      }
    } catch (error) {
      if (!signal.aborted) { failure ??= error instanceof Error ? error : new Error('下载中断。'); controller.abort(failure) }
    }
    return 0
  })()
  const startedAt = Date.now()
  let lastWork: FileDownloadProgress = { phase: 'naming', done: 0, total: 1 }
  const onWork = (progress: FileDownloadProgress) => { lastWork = progress; report(progress) }
  const pulse = setInterval(() => {
    // track 独占状态轮询和重试，心跳只回报最近进度，避免重复轮询积压。
    if (!productionDone) report({ ...lastWork, elapsedMs: Date.now() - startedAt })
  }, 15000)
  try {
    if (created.info?.sealed === true) { await command({ action: 'finish', token }); productionDone = true }
    else await produce(sink, signal, onWork, context)
    const bytes = await track
    if (failure) throw failure
    signal.throwIfAborted()
    succeeded = true
    // 下载complete与ZIP封存均已确认，才清理磁盘缓存。
    await command({ action: 'complete', token }).catch(async () => { await command({ action: 'pause', token }).catch(() => {}) })
    return bytes
  } catch (error) {
    failure ??= error instanceof Error ? error : new Error('流水下载中断，任务缓存仍保留。')
    controller.abort(failure)
    await command({ action: 'pause', token }).catch(() => {})
    await track
    throw failure
  } finally {
    if (options.taskId && activeProducers.get(options.taskId) === controller) activeProducers.delete(options.taskId)
    clearInterval(pulse)
    globalThis.removeEventListener?.('pagehide', pageGone)
    if (!succeeded) await command({ action: 'pause', token }).catch(() => {})
  }
}

import type { FilingExportRow } from '../api/filing-export'
import { recallRecovery, rememberRecovery } from '../recovery/wal-ledger'
import { yieldToMain } from '../utils/idle'

/**
 * 递交导出行档：几万件的导出行不进渲染管线，先记进恢复账本，翻页才把那几行拿出来算渲染。
 * 取数是并行乱序的，行按件入档、按片（200 件）落账本。同一批件重新导出时装回旧档，
 * 取过的件不再打接口——取数中断了也是接着取没取到的，不是从头再来。
 */

/** 一片记多少件。片小写得勤、续传丢得少；片大一笔账本大。200 件在两边都够用。 */
export const FILING_ROWS_SHARD = 200

/** 行档在恢复账本里的槽位，和工作面、查询结果一个待遇：掉了按槽位装回去。 */
const SLOT = 'filing-export'
const PREFIX = 'filing-rows'
const META_SCOPE = `${PREFIX}|meta`

/** 账本里一片的形状：这一片每件的编号和行，没取到的件是 null。 */
interface FilingRowsShard {
  version: 1
  batchKey: string
  entries: { id: string; lines: FilingExportRow[] | null }[]
}

/** 账本里的片数记号：这一批件写到第几片。 */
interface FilingRowsMeta {
  version: 1
  batchKey: string
  shards: number
}

/** 行档的落账本接口。默认走恢复账本，测试可以换成内存的。 */
export interface FilingRowsStore {
  remember(scope: string, payload: unknown): Promise<void>
  recall(scope: string): Promise<unknown | null>
}

const recoveryRowsStore: FilingRowsStore = {
  remember: (scope, payload) => rememberRecovery(SLOT, scope, payload),
  recall: scope => recallRecovery(SLOT, scope)
}

function shardScope(shard: number): string {
  return `${PREFIX}|${shard}`
}

function readShard(value: unknown): FilingRowsShard | null {
  if (!value || typeof value !== 'object') return null
  const shard = value as Partial<FilingRowsShard>
  if (shard.version !== 1 || typeof shard.batchKey !== 'string' || !Array.isArray(shard.entries)) return null
  return shard as FilingRowsShard
}

function readMeta(value: unknown): FilingRowsMeta | null {
  if (!value || typeof value !== 'object') return null
  const meta = value as Partial<FilingRowsMeta>
  if (meta.version !== 1 || typeof meta.batchKey !== 'string' || !Number.isInteger(meta.shards)) return null
  return meta as FilingRowsMeta
}

function hashOf(text: string): number {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return hash >>> 0
}

/** 批次指纹：件数加逐件编号的散列。并行取数到件顺序每次不同，指纹不能跟顺序有关。 */
export function filingRowsBatchKey(rows: readonly { filingId: string; caseVolume: string }[]): string {
  if (!rows.length) return 'empty'
  let sum = 0
  for (const row of rows) sum = (sum + hashOf(row.filingId || row.caseVolume)) >>> 0
  return `${rows.length}-${sum.toString(36)}`
}

/** 一批件的导出行档：内存一份供翻页取行，账本一份供续传。 */
export class FilingRowsLedger {
  /** 按件下标放这一件的导出行；还没取到的是 undefined。普通数组，不进响应式。 */
  private readonly slots: Array<FilingExportRow[] | undefined>
  private readonly ids: string[]
  private readonly indexById = new Map<string, number>()
  /** 落账本还没写完的片号。 */
  private readonly dirty = new Set<number>()
  private total = 0
  private shards = 0
  private metaDirty = false
  private chain: Promise<void> = Promise.resolve()

  constructor(
    readonly batchKey: string,
    filings: readonly { filingId: string; caseVolume: string }[],
    private readonly store: FilingRowsStore = recoveryRowsStore
  ) {
    this.ids = filings.map(row => row.filingId || row.caseVolume)
    this.slots = filings.map(() => undefined)
    this.ids.forEach((id, index) => {
      if (!this.indexById.has(id)) this.indexById.set(id, index)
    })
  }

  /** 一件的行入档：进内存等翻页取，标脏等落账本。同一件同一批行重复入档不动。 */
  put(index: number, lines: FilingExportRow[]): void {
    if (index < 0 || index >= this.slots.length) return
    const previous = this.slots[index]
    if (previous === lines) return
    if (previous) this.total -= previous.length
    this.slots[index] = lines
    this.total += lines.length
    const shard = Math.floor(index / FILING_ROWS_SHARD)
    this.dirty.add(shard)
    if (shard >= this.shards) {
      this.shards = shard + 1
      this.metaDirty = true
    }
  }

  /** 这件取过且有行就给行。断点续传按这个跳过已取的件；没取到的（含失败的空行）会重取。 */
  filled(index: number): FilingExportRow[] | undefined {
    const lines = this.slots[index]
    return lines && lines.length ? lines : undefined
  }

  /** 总导出行数。增量维护，不摊平全量。 */
  get lineCount(): number {
    return this.total
  }

  /** 翻页才取行：按全局行序切 [from, from + size)，没翻到的页不算不渲染。 */
  page(from: number, size: number): Array<{ key: string; row: FilingExportRow }> {
    const out: Array<{ key: string; row: FilingExportRow }> = []
    if (size <= 0 || from < 0) return out
    let seen = 0
    for (let index = 0; index < this.slots.length && out.length < size; index += 1) {
      const lines = this.slots[index]
      if (!lines) continue
      for (let order = 0; order < lines.length; order += 1) {
        if (seen >= from) out.push({ key: `${index}-${order}`, row: lines[order] })
        seen += 1
        if (out.length >= size) return out
      }
    }
    return out
  }

  /** 导出那一下才摊平全量，渲染循环里不碰这个。 */
  all(): FilingExportRow[] {
    const out: FilingExportRow[] = []
    for (const lines of this.slots) {
      for (const line of lines ?? []) out.push(line)
    }
    return out
  }

  /** 脏片落账本。写一次账本要整库导出落盘，所以攒着成片写，不按件写。 */
  flush(): Promise<void> {
    this.chain = this.chain.then(() => this.drain())
    return this.chain
  }

  private async drain(): Promise<void> {
    for (;;) {
      const next = this.dirty.values().next()
      if (next.done) break
      const shard = next.value
      this.dirty.delete(shard)
      try {
        await this.store.remember(shardScope(shard), this.shardPayload(shard))
      } catch {
        this.dirty.add(shard)
        return
      }
    }
    if (!this.metaDirty) return
    this.metaDirty = false
    try {
      await this.store.remember(META_SCOPE, { version: 1, batchKey: this.batchKey, shards: this.shards } satisfies FilingRowsMeta)
    } catch {
      this.metaDirty = true
    }
  }

  private shardPayload(shard: number): FilingRowsShard {
    const from = shard * FILING_ROWS_SHARD
    const to = Math.min(from + FILING_ROWS_SHARD, this.slots.length)
    const entries: { id: string; lines: FilingExportRow[] | null }[] = []
    for (let index = from; index < to; index += 1) {
      entries.push({ id: this.ids[index], lines: this.slots[index] ?? null })
    }
    return { version: 1, batchKey: this.batchKey, entries }
  }

  /** 同一批件装回旧档：指纹对得上才认，装回的件不再打接口。返回装回多少件。 */
  async restore(): Promise<number> {
    let meta: FilingRowsMeta | null = null
    try {
      meta = readMeta(await this.store.recall(META_SCOPE))
    } catch {
      return 0
    }
    if (!meta || meta.batchKey !== this.batchKey) return 0
    let filled = 0
    for (let shard = 0; shard < meta.shards; shard += 1) {
      // 装档是一口气的活，每装完一片让一让主线程，别把启动那一瞬堵死。
      if (shard) await yieldToMain()
      let saved: FilingRowsShard | null = null
      try {
        saved = readShard(await this.store.recall(shardScope(shard)))
      } catch {
        continue
      }
      if (!saved || saved.batchKey !== this.batchKey) continue
      for (const entry of saved.entries) {
        if (!entry || typeof entry.id !== 'string' || !Array.isArray(entry.lines) || !entry.lines.length) continue
        const index = this.indexById.get(entry.id)
        if (index === undefined || this.slots[index]) continue
        this.slots[index] = entry.lines
        this.total += entry.lines.length
        filled += 1
      }
    }
    return filled
  }
}

import type { WorkflowNode } from './types'

export type NodeResolution =
  | { kind: 'none' }
  | { kind: 'one'; node: WorkflowNode }
  | { kind: 'many'; nodes: WorkflowNode[] }
  | { kind: 'missing' }

/** 只有一个下一节点时才确定。多个节点必须由调用方给出节点 ID。 */
export function resolveNextNodes(nodes: WorkflowNode[], selectedId = ''): NodeResolution {
  const usable = nodes.filter(node => node.nodeId)
  if (usable.length === 0) return { kind: 'none' }
  if (!selectedId) return usable.length === 1 ? { kind: 'one', node: usable[0]! } : { kind: 'many', nodes: usable }
  const found = usable.find(node => node.nodeId.toLowerCase() === selectedId.toLowerCase())
  return found ? { kind: 'one', node: found } : { kind: 'missing' }
}

import { isQueryGuid } from '../query/query-validator'
import type { WorkflowExecutionRecord, WorkflowExecutionState } from './types'

const STATES = new Set<WorkflowExecutionState>([
  'NOT_STARTED', 'READING', 'READY', 'SELECTING_NODE', 'SELECTING_REVIEWER', 'PREVIEW_READY',
  'CONFIRM_REQUIRED', 'CHECKING_VERSION', 'SUBMITTING', 'SUBMITTED', 'VERIFYING',
  'COMPLETED', 'STALE', 'UNKNOWN', 'FAILED', 'BLOCKED'
])

export function workflowStorageKey(origin: string, userId: string): string | null {
  if (!isQueryGuid(userId)) return null
  return `patmail.workflow.exec.v1:${origin}:${userId}`
}

export interface WorkflowArea {
  get(key: string): Promise<Record<string, unknown>>
  set(items: Record<string, unknown>): Promise<void>
}

function isStored(value: unknown): value is WorkflowExecutionRecord {
  if (!value || typeof value !== 'object') return false
  const item = value as WorkflowExecutionRecord
  return typeof item.executionId === 'string' && typeof item.mailId === 'string' &&
    (item.flowType === undefined || typeof item.flowType === 'string') && typeof item.flowId === 'string' &&
    typeof item.currentNodeId === 'string' && typeof item.nextNodeId === 'string' && typeof item.reviewerId === 'string' &&
    STATES.has(item.status) && typeof item.versionToken === 'string' && typeof item.submittedAt === 'string' &&
    typeof item.lastVerifiedAt === 'string' && typeof item.lastError === 'string' && typeof item.requestSent === 'boolean' &&
    typeof item.userId === 'string' && typeof item.origin === 'string'
}

export function readWorkflowRecords(value: unknown, userId: string, origin: string): WorkflowExecutionRecord[] {
  if (!value || typeof value !== 'object') return []
  const record = value as { version?: unknown; records?: unknown; cookie?: unknown; authorization?: unknown; password?: unknown }
  if (record.version !== 1 || !Array.isArray(record.records)) return []
  if ('cookie' in record || 'authorization' in record || 'password' in record) return []
  return record.records.filter(isStored).filter(item => item.userId === userId && item.origin === origin).slice(-40)
    .map(item => ({ ...item, flowType: item.flowType ?? '' }))
}

export class WorkflowStore {
  private readonly chains = new Map<string, Promise<unknown>>()

  constructor(private readonly area: WorkflowArea | null) {}

  async exclusive<T>(origin: string, userId: string, mailId: string, run: () => Promise<T>): Promise<T> {
    const key = `${origin}\u0000${userId}\u0000${mailId}`
    const previous = this.chains.get(key) ?? Promise.resolve()
    const current = previous.then(run, run)
    this.chains.set(key, current.then(() => undefined, () => undefined))
    return current
  }

  async load(origin: string, userId: string): Promise<WorkflowExecutionRecord[]> {
    const key = this.area ? workflowStorageKey(origin, userId) : null
    if (!key || !this.area) return []
    const stored = await this.area.get(key)
    return readWorkflowRecords(stored[key], userId, origin)
  }

  async save(origin: string, userId: string, records: WorkflowExecutionRecord[]): Promise<void> {
    const key = this.area ? workflowStorageKey(origin, userId) : null
    if (!key || !this.area) return
    await this.area.set({ [key]: { version: 1, records: records.filter(item => item.userId === userId && item.origin === origin).slice(-40) } })
  }
}

export class MemoryWorkflowStore extends WorkflowStore {
  readonly records: WorkflowExecutionRecord[] = []
  constructor() { super(null) }

  override async load(origin: string, userId: string): Promise<WorkflowExecutionRecord[]> {
    return this.records.filter(item => item.origin === origin && item.userId === userId)
  }

  override async save(origin: string, userId: string, records: WorkflowExecutionRecord[]): Promise<void> {
    const others = this.records.filter(item => item.origin !== origin || item.userId !== userId)
    this.records.splice(0, this.records.length, ...others, ...records.filter(item => item.origin === origin && item.userId === userId))
  }
}

import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import ts from 'typescript'
import { chromium } from 'playwright'

const path = new URL('../../src/browser-download/store.ts', import.meta.url)
const source = await readFile(path, 'utf8').catch(() => '')
assert.ok(source, 'persistent browser store must be implemented')
const js = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 } }).outputText
const browser = await chromium.launch({ headless: true })
try {
  const page = await browser.newPage()
  await page.route('https://cache.test/**', route => route.fulfill({ contentType: 'text/html', body: '<title>Cache fixture</title>' }))
  await page.goto('https://cache.test/')
  await page.addScriptTag({ content: js.replace('export function createBrowserDownloadStore', 'window.createBrowserDownloadStore = function createBrowserDownloadStore') })
  const result = await page.evaluate(async () => {
    const check = (condition, message) => { if (!condition) throw new Error(message) }
    const rejects = async (op, message) => { let failed = false; try { await op() } catch { failed = true } check(failed, message) }
    const store = window.createBrowserDownloadStore()
    const task = id => ({ taskId: id, owner: 'alice', fileName: 'a.zip', manifest: { frozen: ['a'] }, state: 'running', zipCreatedAt: '2026-01-01', updatedAt: Date.now() })
    await store.create(task('one'))
    await rejects(() => store.create({ ...task('one'), owner: 'bob' }), 'owner collision')
    await store.append('one', 0, 0, new Uint8Array([1, 2, 3]))
    await store.append('one', 0, 1, new Uint8Array([2, 3, 4, 5]))
    check(String(await store.read('one', 0, 0)) === '1,2,3,4,5', 'matching overlap extends prefix')
    await rejects(() => store.append('one', 0, 2, new Uint8Array([9])), 'conflicting overlap')
    await rejects(() => store.append('one', 0, 9, new Uint8Array([9])), 'gap')
    await Promise.all([store.append('one', 1, 0, new Uint8Array([7])), store.append('one', 2, 0, new Uint8Array([8]))])
