  const worker = context.serviceWorkers()[0] ?? await context.waitForEvent('serviceworker')
  const errors = []
  worker.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()) })
  const page = await context.newPage()
  page.on('pageerror', e => errors.push(e.message))
  await page.goto('http://183.36.43.66:88/fixture')
  assert.deepEqual(await page.evaluate(() => ({ secure: isSecureContext, uuid: typeof crypto.randomUUID })),
    { secure: false, uuid: 'undefined' }, '必须在真实 HTTP 非安全上下文复现，不能用 localhost 或 HTTPS 掩盖缺陷')
  const app = await context.newPage()
  await app.goto(`chrome-extension://${new URL(worker.url()).host}/app.html#/files`)
  const progressId = '11111111-1111-4111-8111-111111111111'
  await app.evaluate(id => {
    globalThis.__downloadAudit = []
    globalThis.__downloadResult = null
    chrome.runtime.onMessage.addListener(message => {
      if (message.channel === 'patmail-download-progress' && message.id === id) globalThis.__downloadAudit.push(message.progress)
      if (message.channel === 'patmail-download-result' && message.id === id) globalThis.__downloadResult = message.body
    })
  }, progressId)
  let tab
  for (let i = 0; i < 30; i++) {
    tab = (await worker.evaluate(() => chrome.tabs.query({}))).find(t => t.url?.endsWith('/fixture'))
    try {
      const result = await worker.evaluate(id => chrome.tabs.sendMessage(id, { type: 'PING' }), tab.id)
      if (result?.type === 'PONG') break
    } catch {}
    await new Promise(resolve => setTimeout(resolve, 200))
  }
  let timeout
  const accepted = await Promise.race([
    worker.evaluate(({ id, files, progressId }) => chrome.tabs.sendMessage(id, {
      type: 'DOWNLOAD_FILES', payload: {
        items: files,
        selection: { newFilename: 'file_desc', fileNameType: 'colname' }, stripAppNoDot: true, progressId, detached: true
      }
    }), { id: tab.id, files, progressId }),
    new Promise(resolve => { timeout = setTimeout(() => resolve({ diagnosticTimeout: true }), 40000) })
  ])
  clearTimeout(timeout)
  assert.equal(accepted.type, 'DOWNLOAD_FILES_ACCEPTED', '长任务必须先短暂受理，不能一直占住后台转发')
  await app.waitForFunction(() => globalThis.__downloadResult !== null, undefined, { timeout: 40000 })
  const result = await app.evaluate(() => globalThis.__downloadResult)
  let downloads = []
  for (let attempt = 0; attempt < 50; attempt++) {
    downloads = await worker.evaluate(() => chrome.downloads.search({}).then(items => items.map(({ id, state, error, bytesReceived, totalBytes, filename }) => ({ id, state, error, bytesReceived, totalBytes, filename }))))
    if (downloads.some(item => item.state === 'complete' || item.state === 'interrupted')) break
    await new Promise(resolve => setTimeout(resolve, 200))
  }
  const progress = await app.evaluate(() => globalThis.__downloadAudit)
  const report = { accepted, result, downloads, calls, errors, peakNames, progress }
  await mkdir(testResultsDir, { recursive: true })
  await writeFile(resultPath('download-e2e.json'), JSON.stringify(report, null, 2))
  console.log(JSON.stringify(report, null, 2))
  assert.equal(result.type, 'DOWNLOAD_FILES_RESULT')
  assert.equal(result.payload.ok, true)
  assert.equal(result.payload.data.fileCount, 241)
  // 最终结果要带浏览器下载终态：压缩包保存完成才算完成，不能只报「已交给浏览器」。
  assert.match(result.payload.data.notice, /浏览器下载完成/, '最终结果要回报浏览器下载完成')
  assert(!/另存走了浏览器直接下载/.test(result.payload.data.notice), '后台应直接接住下载，不能靠 iframe 假成功')
  assert.equal(calls.filter(call => call.call === 'DownLoad').length, 1)
  // 命名一批 40 个、并发 5 路：241 个文件是 7 批（40×6+1），验证补位且在途不超过 5。
  assert.equal(calls.filter(call => call.call === 'GetFileName').length, 7)
  assert.equal(peakNames, 5)
  assert.equal(downloadParams.get('file_no'), files.map(file => file.fileNo).join(';'))
  assert.equal(downloadParams.get('file_name'), files.map((_, index) => `file-${index + 1}.pdf`).join(';'))
  const naming = progress.filter(item => item.phase === 'naming')
  assert.equal(naming[0].done, 0)
  assert.equal(naming.at(-1).done, 241)
  assert.equal(naming.every((item, index) => index === 0 || item.done > naming[index - 1].done), true)
  assert(progress.some(item => item.phase === 'packing'))
  const received = progress.filter(item => item.phase === 'packing' && item.receivedBytes > 0).map(item => item.receivedBytes)
  assert(received.length >= 2 && received.at(-1) > received[0], '真实流式响应字节要逐步上报')
  assert(progress.some(item => item.phase === 'saving'))
  // 浏览器下载阶段的流式输出：至少要报出下载终态，长传输时还有 inProgress 字节进度。
  const transfer = progress.filter(item => item.phase === 'downloading')
  assert(transfer.some(item => item.state === 'complete'), '下载阶段要流式回报并给出完成终态')
  assert.equal(transfer.filter(item => item.state === 'complete' || item.state === 'interrupted').length, 1, '终态只能报一次')
  assert.equal(calls.filter(call => call.path.endsWith('FileHandler.ashx')).length, 1)
  assert.equal(downloads.length, 1)
  assert.equal(downloads[0].state, 'complete')
  assert.equal(downloads[0].bytesReceived, zip.length)
  assert.deepEqual(await readFile(downloads[0].filename), zip, '下载记录对应的磁盘文件必须完整')
  console.log('HTTP download regression passed: pack → background message → browser download → verified disk bytes')
} finally {
  await context?.close()
  server.closeAllConnections()
  await new Promise(resolve => server.close(resolve))
}

import http from 'node:http'
import assert from 'node:assert/strict'
import { mkdtemp, readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { execFile } from 'node:child_process'
import { promisify } from 'node:util'
import { chromium } from 'playwright'
import { distDir, testResultsDir, resultPath } from './support/paths.mjs'
import { waitForContentScript } from './support/browser.mjs'
import { ensureStreamBridge } from './support/stream-bridge.mjs'

const files = Array.from({ length: 6 }, (_, index) => ({ fileId: `00000000-0000-4000-8000-${String(index + 1).padStart(12, '0')}`, fileNo: `R${index}`, fileName: `old-${index}.pdf` }))
const info = { IsLogin: true, Status: true, Result: true }
const source = index => { const bytes = Buffer.alloc(512 * 1024, index); bytes.write('%PDF durable fixture'); return bytes }
let names = 0, failed = false, releaseFailure
const failureGate = new Promise(resolve => { releaseFailure = resolve })
const fetches = [], ranges = []
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://183.36.43.66:88')
  let body = ''; for await (const chunk of req) body += chunk
  const params = new URLSearchParams(body), call = params.get('Call')
  const json = data => { res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify({ ClientInfo: info, ...data })) }
  if (call === 'GetUserModel') return json({ UserModel: { user_id: '11111111-1111-4111-8111-111111111111', user_name: 'fixture', Name: 'Fixture' } })
  if (call === 'GetFileName') { names++; return json({ file_names: params.get('file_ids').split(';').map(id => `202610026334.9-${files.findIndex(file => file.fileId === id)}.pdf`).join(';') }) }
  if (call === 'DownLoad') return json({ file_guid: files.find(file => file.fileNo === params.get('file_no')).fileId, file_size: 512 * 1024 })
  if (url.pathname.endsWith('FileHandler.ashx')) {
    const index = files.findIndex(file => file.fileId === url.searchParams.get('guid'))
    fetches.push(index)
    const bytes = source(index), range = req.headers.range
    const offset = range ? Number(/^bytes=(\d+)-/.exec(range)?.[1]) : 0
    if (range) ranges.push({ index, offset })
    res.setHeader('Content-Type', 'application/pdf'); res.setHeader('ETag', `"source-${index}-v1"`)
    res.setHeader('Content-Length', bytes.length - offset)
    if (range) { res.statusCode = 206; res.setHeader('Content-Range', `bytes ${offset}-${bytes.length - 1}/${bytes.length}`) }
    if (index === 1 && !failed) {
      failed = true; res.write(bytes.subarray(0, 256 * 1024)); await failureGate; res.destroy(); return
    }
    return res.end(bytes.subarray(offset))
  }
  if (url.pathname === '/fixture') { res.setHeader('Content-Type', 'text/html'); return res.end('<!doctype html><title>durable fixture</title>') }
  json({})
})
server.on('connect', (_, socket) => socket.destroy())
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
const stopBridge = await ensureStreamBridge()
let context
try {
  const netlog = resultPath('durable-download-netlog.json')
  context = await chromium.launchPersistentContext('', { channel: 'chromium', headless: true, acceptDownloads: true,
    proxy: { server: `http://127.0.0.1:${server.address().port}`, bypass: '127.0.0.1' },
    args: [`--disable-extensions-except=${distDir}`, `--load-extension=${distDir}`, `--log-net-log=${netlog}`, '--net-log-capture-mode=IncludeSensitive'] })
  const worker = context.serviceWorkers()[0] ?? await context.waitForEvent('serviceworker')
  const easy = await context.newPage(); await easy.goto('http://183.36.43.66:88/fixture')
  const app = await context.newPage(); await app.goto(`chrome-extension://${new URL(worker.url()).host}/app.html#/files`)
  const destination = await mkdtemp(join(testResultsDir, 'durable-download-'))
  await (await context.newCDPSession(app)).send('Browser.setDownloadBehavior', { behavior: 'allow', downloadPath: destination, eventsEnabled: true })
  await app.evaluate(() => { window.__results = {}; chrome.runtime.onMessage.addListener(message => { if (message.channel === 'patmail-download-result') window.__results[message.id] = message.body }) })
  let tab
  for (let i = 0; i < 50; i++) {
    tab = (await worker.evaluate(() => chrome.tabs.query({}))).find(item => item.url?.endsWith('/fixture'))
    try { if ((await worker.evaluate(id => chrome.tabs.sendMessage(id, { type: 'PING' }), tab.id))?.type === 'PONG') break } catch {}
    await new Promise(resolve => setTimeout(resolve, 100))
  }
  const taskId = crypto.randomUUID()
  const start = async progressId => worker.evaluate(({ tabId, files, taskId, progressId }) => chrome.tabs.sendMessage(tabId, {
    type: 'DOWNLOAD_FILES', payload: { items: files, selection: { newFilename: 'file_name', fileNameType: 'colname' },
      stripAppNoDot: true, archiveName: '续传验收.zip', stream: true, detached: true, taskId, progressId }
  }), { tabId: tab.id, files, taskId, progressId })
  const first = crypto.randomUUID()
  assert.equal((await start(first)).type, 'DOWNLOAD_FILES_ACCEPTED')
  let original
  for (let i = 0; i < 500; i++) {
    original = (await worker.evaluate(() => chrome.downloads.search({})))[0]
    if (original?.bytesReceived >= 512 * 1024) { releaseFailure(); break }
    const earlyError = await app.evaluate(id => window.__results[id], first)
    if (earlyError) throw new Error(JSON.stringify(earlyError))
    await new Promise(resolve => setTimeout(resolve, 100))
  }
  releaseFailure()
  await app.waitForFunction(id => Boolean(window.__results[id]), first, { timeout: 60000 })
  const failedResult = await app.evaluate(id => window.__results[id], first)
  assert.equal(failedResult.payload.ok, false)
  assert(original?.bytesReceived > 0, '首轮必须留下非零浏览器前缀')
  await easy.reload()
  await waitForContentScript(worker, easy)
  const second = crypto.randomUUID()
  assert.equal((await start(second)).type, 'DOWNLOAD_FILES_ACCEPTED')
  await app.waitForFunction(id => Boolean(window.__results[id]), second, { timeout: 120000 })
  const resumed = await app.evaluate(id => window.__results[id], second)
  assert.equal(resumed.payload.ok, true, JSON.stringify(resumed))
  const downloads = await worker.evaluate(() => chrome.downloads.search({}))
  assert.equal(downloads.length, 1, '续传必须复用原下载记录')
  assert.equal(downloads[0].id, original.id)
  assert.equal(downloads[0].state, 'complete')
  assert.equal(names, 1, '已持久化的命名批次不能重跑')
  assert.equal(fetches.filter(index => index === 0).length, 1, '完整缓存的首个附件不能重下')
  assert(ranges.some(item => item.index === 1 && item.offset > 0), '未完成源附件必须按版本和偏移续取')
  const validation = 'import zipfile,sys\nwith zipfile.ZipFile(sys.argv[1]) as z:\n assert z.testzip() is None\n assert z.namelist()==[f"2026100263349-{i}.pdf" for i in range(6)]\n assert all(len(z.read(e))==524288 for e in z.namelist())\n print("CRC OK")'
  await promisify(execFile)('python', ['-c', validation, downloads[0].filename], { windowsHide: true })
  await context.close(); context = null
  const events = JSON.parse(await readFile(netlog, 'utf8')).events
  const headers = events.filter(event => String(event.params?.line ?? '').startsWith(`GET /download/${taskId} `))
    .flatMap(event => event.params?.headers ?? []).filter(value => typeof value === 'string')
  const nativeRanges = headers.filter(header => /^range:\s*bytes=[1-9]\d*-/i.test(header))
  assert(nativeRanges.length > 0, '真实浏览器必须发出非零Range请求')
  const report = { passed: true, sameDownloadId: original.id, originalBytes: original.bytesReceived, names, sourceFetches: fetches, sourceRanges: ranges,
    nativeRanges, finalBytes: downloads[0].bytesReceived, crc: true }
  await writeFile(resultPath('durable-download.json'), JSON.stringify(report, null, 2))
  console.log(JSON.stringify(report))
} finally {
  releaseFailure(); await context?.close()
  server.closeAllConnections(); await new Promise(resolve => server.close(resolve)); stopBridge()
}

import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import { distDir, fixturePagePath } from './support/paths.mjs'
import { startFixtureServer } from './support/fixture-server.mjs'
import { easyFixtureUrl, installEasyMock } from './support/easy-mock.mjs'
import { extensionWorker, launchExtensionContext, waitForContentScript } from './support/browser.mjs'
import { createReporter } from './support/report.mjs'
import { runPanelScan } from './scenarios/panel-scan.mjs'
import { runFileSearch } from './scenarios/file-search.mjs'
import { runPanelWindow } from './scenarios/panel-window.mjs'
import { runLargeFormScan } from './scenarios/panel-large-form.mjs'
import { runWorkspaceFlow } from './scenarios/workspace.mjs'

const dist = distDir
const fixture = await readFile(fixturePagePath)
const report = createReporter()
const fixtureServer = await startFixtureServer(fixture)
const url = fixtureServer.url
const easyUrl = easyFixtureUrl

let context
try {
  context = await launchExtensionContext(dist)
} catch (error) {
  await fixtureServer.close()
  throw error
}

// 整个 EASY Origin 由测试路由拦截；绝不触达真实服务器。
const mock = await installEasyMock(context, { fixtureHtml: fixture, profile: 'extension' })
const apiCalls = mock.apiCalls
const errors = []
const requestFailures = []
const watch = (page) => {
  page.on('pageerror', (error) => errors.push(error.message))
  page.on('console', (message) => {
    if (message.text().includes('502')) return
    if (message.type() === 'error' || message.text().includes('PatMail transport diagnostic:')) errors.push(message.text())
  })
  page.on('requestfailed', request => { if (request.url().includes('/AjaxServers/')) requestFailures.push({ url: request.url(), failure: request.failure()?.errorText }) })
}
context.on('page', watch)
for (const page of context.pages()) watch(page)

const visible = async (panel, width, height) => {
  // resize 和 Vue 响应式位置更新跨帧发生；等待最终稳定位置。
  await panel.page().waitForFunction(() => {
    const element = document.querySelector('patmail-root')?.shadowRoot?.querySelector('.panel')
    if (!element) return false
    const box = element.getBoundingClientRect()
    return box.x >= 0 && box.y >= 0 && box.x + box.width <= innerWidth + 1 && box.y + box.height <= innerHeight + 1
  }, null, { timeout: 3000 })
  const box = await panel.boundingBox()
  assert(box, 'panel bounding box missing')
  const viewport = panel.page().viewportSize()
  assert(viewport, 'viewport missing')
  assert(box.x >= 0 && box.y >= 0, `negative panel coordinates: ${JSON.stringify(box)}`)
  assert(box.x + box.width <= viewport.width + 1 && box.y + box.height <= viewport.height + 1,
    `panel beyond viewport: ${JSON.stringify(box)} / ${JSON.stringify(viewport)}`)
  if (width) assert.equal(Math.round(box.width), width)
  if (height) assert.equal(Math.round(box.height), height)
  return box
}

try {
  const worker = await extensionWorker(context)
  const extensionId = new URL(worker.url()).host
  assert.match(extensionId, /^[a-p]{32}$/)
  const tabFor = (targetPage) => waitForContentScript(worker, targetPage, { attempts: 25, intervalMs: 200 })
  async function showPanel(targetPage) {
    const tab = await tabFor(targetPage)
    const response = await worker.evaluate((tabId) => chrome.tabs.sendMessage(tabId, { type: 'SHOW_PANEL' }), tab.id)
    assert.deepEqual(response, { type: 'PANEL_SHOWN', payload: { ok: true } })
  }
  const page = await context.newPage()
  await page.setViewportSize({ width: 1200, height: 800 })
  await page.goto(url)
  await context.grantPermissions(['clipboard-read', 'clipboard-write'], { origin: new URL(url).origin })
  const host = page.locator('patmail-root')
  const panel = host.locator('.panel')
  await tabFor(page)
  assert.equal(await host.count(), 0)
  await showPanel(page)
  await panel.waitFor()

  const ctx = { report, context, worker, extensionId, page, panel, host, url, easyUrl, apiCalls, visible, tabFor, showPanel }
  await runPanelScan(ctx)
  await runFileSearch(ctx)
  await runPanelWindow(ctx)
  await runLargeFormScan(ctx)
  await runWorkspaceFlow(ctx)

  assert.deepEqual(errors, [], `browser errors: ${errors.join('\n')}`)
  await report.writeText('patmail-e2e.txt', `${report.checks} checks passed; browser errors: 0\n${report.notes.join('\n')}\n`)
  report.notes.forEach(line => console.log(line))
  console.log(`${report.checks} browser checks passed; screenshot: test-results/patmail-panel.png`)
} finally {
  context.off('page', watch)
  await mock.dispose()
  await context.close()
  await fixtureServer.close()
}

