  assert.deepEqual(errors, [], `browser errors: ${errors.join('\n')}`)
  console.log('limit-query e2e passed; all EASY requests were fixture-intercepted')
} finally {
  context.off('page', watch)
  await mock.dispose()
  await context.close()
}

