import { afterEach, describe, expect, it, vi } from 'vitest'
import { EasyTransport } from '../../../src/api/transport'
import { EasyRuntime } from '../../../src/api/client'
import type { FileDownloadProgress } from '../../../src/shared/download-progress'

afterEach(() => vi.useRealTimers())
describe('大批下载的等待预算', () => {
  it('服务器准备6分钟不回包时仍持续报告存活与耗时，最终直接返回取包URL', async () => {
    vi.useFakeTimers()
    const progress: FileDownloadProgress[] = []
    const fetcher: typeof fetch = async (_url, init) => {
      const call = new URLSearchParams(String(init?.body)).get('Call')
      if (call === 'DownLoad') await new Promise(resolve => setTimeout(resolve, 360_000))
      return new Response(JSON.stringify({ ClientInfo: { IsLogin: true, Status: true },
        UserModel: { user_id: '11111111-1111-4111-8111-111111111111', user_name: 'fixture', Name: '验收员' },
        file_guid: '85ebabc1-cf99-490e-b5f7-298a77742012' }))
    }
    const runtime = new EasyRuntime('http://183.36.43.66:88', { fetcher })
    await runtime.checkSession()
    const pending = runtime.downloadFiles([{ fileId: '11111111-1111-4111-8111-111111111111', fileNo: 'A001', fileName: '验收.pdf' }], null, false, event => progress.push(event))
    await vi.advanceTimersByTimeAsync(360_001)
    expect(await pending).toMatchObject({ ok: true, data: { downloadUrl: 'http://183.36.43.66:88/AjaxServers/FileHandler.ashx?guid=85ebabc1-cf99-490e-b5f7-298a77742012' } })
    expect(progress.some(event => event.phase === 'packing' && (event.elapsedMs ?? 0) >= 345_000 && event.receivedBytes === 0)).toBe(true)
    expect(vi.getTimerCount()).toBe(0)
  })
  it('打包响应逐步增长超过5分钟仍持续读取，按真实字节上报并最终解析GUID', async () => {
    vi.useFakeTimers()
    const bytes: number[] = []
    const encoder = new TextEncoder()
    const result = JSON.stringify({ ClientInfo: { IsLogin: true, Status: true }, file_guid: '85ebabc1-cf99-490e-b5f7-298a77742012', note: '文件已打包' })
    const encoded = encoder.encode(result)
    const split = encoded.length - 9 // 有意切在UTF8中文文本附近。
    const fetcher: typeof fetch = async (_url, init) => new Response(new ReadableStream({ start(controller) {
      init?.signal?.addEventListener('abort', () => controller.error(new DOMException('Aborted', 'AbortError')))
      setTimeout(() => controller.enqueue(encoder.encode('  ')), 240_000)
      setTimeout(() => controller.enqueue(encoded.slice(0, split)), 360_000)
      setTimeout(() => { controller.enqueue(encoded.slice(split)); controller.close() }, 420_000)
    } }))
    const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post('fileDownload', new URLSearchParams({ Call: 'DownLoad' }), undefined, undefined, received => bytes.push(received))
    await vi.advanceTimersByTimeAsync(420_001)
    expect(await pending).toMatchObject({ ok: true, data: { file_guid: '85ebabc1-cf99-490e-b5f7-298a77742012', note: '文件已打包' } })
    expect(bytes).toEqual([2, 2 + split, 2 + encoded.length])
  })
  it('取消信号仍能停止无总时限的打包，且不重发', async () => {
    const ticket = new AbortController()
    const fetcher = vi.fn<typeof fetch>(async (_url, init) => new Promise((_resolve, reject) => {
      init?.signal?.addEventListener('abort', () => reject(new DOMException('Aborted', 'AbortError')))
    }))
    const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post('fileDownload', new URLSearchParams({ Call: 'DownLoad' }), ticket.signal)
    ticket.abort()
    expect(await pending).toMatchObject({ ok: false, error: { code: 'REQUEST_ABORTED' } })
    expect(fetcher).toHaveBeenCalledTimes(1)
  })
  it('DownLoad准备超过5分钟仍等待同一次请求，不取消、不重发', async () => {
    vi.useFakeTimers()
    let calls = 0
    let aborted = false
    const fetcher: typeof fetch = async (_url, init) => {
      calls++
      await new Promise<void>((resolve, reject) => {
        const timer = setTimeout(resolve, 360_000)
        init?.signal?.addEventListener('abort', () => { aborted = true; clearTimeout(timer); reject(new DOMException('Aborted', 'AbortError')) }, { once: true })
      })
      return new Response(JSON.stringify({ ClientInfo: { IsLogin: true, Status: true }, file_guid: '85ebabc1-cf99-490e-b5f7-298a77742012' }))
    }
    const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post('fileDownload', new URLSearchParams({ Call: 'DownLoad' }))
    await vi.advanceTimersByTimeAsync(360_001)
    expect(await pending).toMatchObject({ ok: true })
    expect(aborted).toBe(false)
    expect(calls).toBe(1)
  })
  it.each(['getFileName', 'fileDownload'] as const)('%s 在服务器需要70秒时不被旧60秒超时掐断，也不重复提交', async operation => {
    vi.useFakeTimers()
    let calls = 0
    const fetcher: typeof fetch = async (_url, init) => {
      calls++
      await new Promise<void>((resolve, reject) => {
        const timer = setTimeout(resolve, 70_000)
        init?.signal?.addEventListener('abort', () => { clearTimeout(timer); reject(new DOMException('Aborted', 'AbortError')) }, { once: true })
      })
      return new Response(JSON.stringify({ ClientInfo: { IsLogin: true, Status: true } }))
    }
    const call = operation === 'getFileName' ? 'GetFileName' : 'DownLoad'
    const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post(operation, new URLSearchParams({ Call: call }))
    await vi.advanceTimersByTimeAsync(70_001)
    expect(await pending).toMatchObject({ ok: true })
    expect(calls).toBe(1)
  })
})

import { describe, expect, it } from 'vitest'
import { EasyRuntime } from '../../../src/api/client'

const authenticated = { ClientInfo: { IsLogin: true, Status: true, Result: true } }
const fileResponse = (name: string) => ({
  TableRows: [{ file_id: name, file_name: name }],
  TableRowsCount: '1',
  ClientInfo: authenticated.ClientInfo
})

describe('EASY Runtime 请求生命周期', () => {
  it('blocks file requests until a session is explicitly authenticated', async () => {
    let fileCalls = 0
    const fetcher: typeof fetch = async url => {
      if (String(url).endsWith('Login.ashx')) return new Response(JSON.stringify(authenticated))
      fileCalls++
      return new Response(JSON.stringify(fileResponse('文件 A')))
    }
    const runtime = new EasyRuntime('http://183.36.43.66:88', { fetcher })
    expect(await runtime.searchFiles({ caseVolume: 'A', pageIndex: 1, pageSize: 20 }))
      .toMatchObject({ ok: false, error: { code: 'AUTH_UNKNOWN' } })
    expect(fileCalls).toBe(0)
    expect(await runtime.checkSession()).toMatchObject({ ok: true, data: { status: 'authenticated' } })
    expect(await runtime.searchFiles({ caseVolume: 'A', pageIndex: 1, pageSize: 20 }))
      .toMatchObject({ ok: true, data: { items: [{ fileName: '文件 A' }] } })
  })

  it('deduplicates an identical in-flight search and prevents an old response overriding a newer one', async () => {
    const pending = new Map<string, (response: Response) => void>()
    let fileCalls = 0
    const fetcher: typeof fetch = async (_url, init) => {
      if (String(_url).endsWith('Login.ashx')) return new Response(JSON.stringify(authenticated))
      fileCalls++
      const key = new URLSearchParams(String(init?.body)).get('case_volume')!
      return new Promise(resolve => pending.set(key, resolve))
    }
    const runtime = new EasyRuntime('http://183.36.43.66:88', { fetcher })
    await runtime.checkSession()
    const first = runtime.searchFiles({ caseVolume: 'A', pageIndex: 1, pageSize: 20 })
    const duplicate = runtime.searchFiles({ caseVolume: 'A', pageIndex: 1, pageSize: 20 })
    expect(fileCalls).toBe(1)
    expect(duplicate).toBe(first)
    const second = runtime.searchFiles({ caseVolume: 'B', pageIndex: 1, pageSize: 20 })
    expect(fileCalls).toBe(2)
    pending.get('B')!(new Response(JSON.stringify(fileResponse('新结果'))))
    expect(await second).toMatchObject({ ok: true, data: { items: [{ fileName: '新结果' }] } })
    pending.get('A')!(new Response(JSON.stringify(fileResponse('旧结果'))))
    expect(await first).toMatchObject({ ok: false, error: { code: 'REQUEST_ABORTED' } })
  })

  it('cancels pending work and clears access after a session-expired business response', async () => {
    let resolveFile: ((response: Response) => void) | undefined
    let expired = false
    const fetcher: typeof fetch = async url => {
      if (String(url).endsWith('Login.ashx')) return new Response(JSON.stringify(authenticated))
      if (expired) return new Response(JSON.stringify({
        TableRows: null, TableRowsCount: '0', ClientInfo: { IsLogin: false, Status: false }
      }))
      return new Promise(resolve => { resolveFile = resolve })
    }
    const runtime = new EasyRuntime('http://183.36.43.66:88', { fetcher })
    await runtime.checkSession()
    const pending = runtime.searchFiles({ caseVolume: 'A', pageIndex: 1, pageSize: 20 })
    runtime.cancelFileSearch()
    resolveFile!(new Response(JSON.stringify(fileResponse('迟到结果'))))
    expect(await pending).toMatchObject({ ok: false, error: { code: 'REQUEST_ABORTED' } })
    expired = true
    expect(await runtime.searchFiles({ caseVolume: 'B', pageIndex: 1, pageSize: 20 }))
      .toMatchObject({ ok: false, error: { code: 'SESSION_EXPIRED' } })
    expect(runtime.sessionStatus).toBe('expired')
    expect(await runtime.searchFiles({ caseVolume: 'C', pageIndex: 1, pageSize: 20 }))
      .toMatchObject({ ok: false, error: { code: 'SESSION_EXPIRED' } })
  })

  it('loads saved queries after confirming the current page session', async () => {
    const calls: string[] = []
    const fetcher: typeof fetch = async (url, init) => {
      const call = new URLSearchParams(String(init?.body)).get('Call') ?? ''
      calls.push(`${String(url).split('/').pop()}:${call}`)
      if (call === 'GetUserModel') return new Response(JSON.stringify(authenticated))
      return new Response(JSON.stringify({
        ClientInfo: authenticated.ClientInfo,
        Options: [{ query_id: '31d1a147-2931-43b5-94ae-b72b1525ba8a', title: '微众新申请' }]
      }))
    }
    const runtime = new EasyRuntime('http://183.36.43.66:88', { fetcher })
    expect(await runtime.listHistoryQueries()).toMatchObject({ ok: true, data: [{ name: '微众新申请' }] })
    expect(calls).toEqual(['Login.ashx:GetUserModel', 'CaseInfo.ashx:SearchQueryHisList'])
  })

  it('returns saved queries from SearchQueryHisList when the local session flag is not authenticated', async () => {
    const calls: string[] = []
    const fetcher: typeof fetch = async (_url, init) => {
      const call = new URLSearchParams(String(init?.body)).get('Call') ?? ''
      calls.push(call)
      if (call === 'GetUserModel') {
        return new Response(JSON.stringify({ ClientInfo: { IsLogin: false, Status: true, Result: false } }))
      }
      return new Response(JSON.stringify({
        ClientInfo: { IsLogin: true, Status: true, Result: false },
        Options: [{ query_id: '31d1a147-2931-43b5-94ae-b72b1525ba8a', title: '宁德授权请款' }]
      }))
    }
    const runtime = new EasyRuntime('http://183.36.43.66:88', { fetcher })
    expect(await runtime.listHistoryQueries(true)).toMatchObject({ ok: true, data: [{ name: '宁德授权请款', source: 'easy' }] })
    expect(calls).toEqual(['GetUserModel', 'SearchQueryHisList'])
  })
})

import { describe, expect, it, vi } from 'vitest'
import { EasyTransport } from '../../../src/api/transport'

function jsonResponse(body: unknown, status = 200, url = 'http://183.36.43.66:88/AjaxServers/Login.ashx'): Response {
  const response = new Response(JSON.stringify(body), { status, headers: { 'content-type': 'text/plain; charset=utf-8' } })
  Object.defineProperty(response, 'url', { value: url })
  return response
}

const sessionParams = () => new URLSearchParams({ Call: 'GetUserModel', log_pagename: '' })

describe('EASY 受限传输', () => {
  it('binds the browser fetch receiver when using the native global function', async () => {
    const nativeLikeFetch = vi.fn(function (this: unknown) {
      if (this !== globalThis) throw new TypeError('Illegal invocation')
      return Promise.resolve(jsonResponse({ ClientInfo: { IsLogin: true } }))
    })
    vi.stubGlobal('fetch', nativeLikeFetch)
    try {
      const result = await new EasyTransport('http://183.36.43.66:88').post('session', sessionParams())
      expect(result.ok).toBe(true)
      expect(nativeLikeFetch).toHaveBeenCalledTimes(1)
    } finally {
      vi.unstubAllGlobals()
    }
  })

  it('posts form-urlencoded on the trusted same origin with browser-managed credentials', async () => {
    const calls: Array<{ url: string; init: RequestInit }> = []
    const fetcher: typeof fetch = async (url, init) => {
      calls.push({ url: String(url), init: init ?? {} })
      return jsonResponse({ ClientInfo: { IsLogin: true, Status: true } })
    }
    const transport = new EasyTransport('http://183.36.43.66:88', { fetcher })
    const result = await transport.post('session', sessionParams())
    expect(result).toMatchObject({ ok: true, data: { ClientInfo: { IsLogin: true } } })
    expect(calls).toHaveLength(1)
    expect(calls[0].url).toBe('http://183.36.43.66:88/AjaxServers/Login.ashx')
    expect(calls[0].init).toMatchObject({
      method: 'POST', credentials: 'include', redirect: 'follow',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8', 'X-Requested-With': 'XMLHttpRequest' }
    })
    expect(new URLSearchParams(String(calls[0].init.body)).get('log_pagename')).toBe('')
  })

  it('refuses unrelated origins and unapproved Call values before fetch', async () => {
    const fetcher = vi.fn<typeof fetch>()
    const outside = new EasyTransport('https://untrusted.example', { fetcher })
    expect(await outside.post('session', sessionParams())).toMatchObject({ ok: false, error: { code: 'INVALID_ORIGIN' } })
    const trusted = new EasyTransport('http://183.36.43.66:88', { fetcher })
    expect(await trusted.post('session', new URLSearchParams({ Call: 'MailCustomer' })))
      .toMatchObject({ ok: false, error: { code: 'INVALID_QUERY' } })
    expect(fetcher).not.toHaveBeenCalled()
  })

  it('does not trust an arbitrary localhost app as an EASY API origin', async () => {
    const fetcher = vi.fn<typeof fetch>()
    const local = new EasyTransport('http://127.0.0.1:7777', { fetcher })
    expect(await local.post('session', sessionParams()))
      .toMatchObject({ ok: false, error: { code: 'INVALID_ORIGIN' } })
    expect(fetcher).not.toHaveBeenCalled()
  })

  it('keeps network, HTTP, login HTML and invalid JSON failures distinct', async () => {
    const cases: Array<{ response?: Response; fail?: Error; code: string; status?: number }> = [
      { fail: new TypeError('offline'), code: 'NETWORK_ERROR' },
      { response: new Response('gateway down', { status: 502 }), code: 'HTTP_ERROR', status: 502 },
      { response: new Response('unavailable', { status: 503 }), code: 'HTTP_ERROR', status: 503 },
      { response: new Response('<html><form action="/Login.aspx"></form></html>'), code: 'SESSION_EXPIRED' },
      { response: new Response('<div style="width:100%;text-align: center;font-size:40px;">出错了!</div>'), code: 'SESSION_EXPIRED' },
      { response: new Response('<html><body>proxy error</body></html>'), code: 'UNEXPECTED_HTML' },
      { response: new Response('{not json'), code: 'INVALID_RESPONSE' }
    ]
    for (const item of cases) {
      const fetcher: typeof fetch = async () => {
        if (item.fail) throw item.fail
        return item.response!
      }
      const result = await new EasyTransport('http://183.36.43.66:88', { fetcher }).post('session', sessionParams())
      expect(result).toMatchObject({ ok: false, error: { code: item.code, ...(item.status ? { status: item.status } : {}) } })
    }
  })

  it('retries a readonly 502 and keeps a write 502 to a single request', async () => {
    let reads = 0
    const read: typeof fetch = async () => {
      reads += 1
      return reads === 1 ? new Response('gateway down', { status: 502 }) : jsonResponse({ ClientInfo: { IsLogin: true } })
    }
    const recovered = await new EasyTransport('http://183.36.43.66:88', { fetcher: read }).post('session', sessionParams())
    expect(recovered.ok).toBe(true)
    expect(reads).toBe(2)
    let writes = 0
    const write: typeof fetch = async () => {
      writes += 1
      return new Response('gateway down', { status: 502 })
    }
    const blocked = await new EasyTransport('http://183.36.43.66:88', { fetcher: write }).post('mailCustomer', new URLSearchParams({ Call: 'MailCustomer' }))
    expect(blocked).toMatchObject({ ok: false, error: { code: 'HTTP_ERROR', status: 502 } })
    expect(writes).toBe(1)
  })

  it('detects a login redirect even when the final HTTP status is 200', async () => {
    const fetcher: typeof fetch = async () => jsonResponse(
      { anything: true }, 200, 'http://183.36.43.66:88/Login.aspx'
    )
    const result = await new EasyTransport('http://183.36.43.66:88', { fetcher }).post('session', sessionParams())
    expect(result).toMatchObject({ ok: false, error: { code: 'SESSION_EXPIRED' } })
  })

  it('holds a file search for the selected timeout instead of one minute', async () => {
    vi.useFakeTimers()
