  })

  it('holds a limit search for the selected timeout instead of one minute', async () => {
    vi.useFakeTimers()
    try {
      let aborted = false
      const fetcher: typeof fetch = async (_url, init) => new Promise((_resolve, reject) => {
        init?.signal?.addEventListener('abort', () => {
          aborted = true
          reject(new DOMException('aborted', 'AbortError'))
        }, { once: true })
      })
      const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post(
        'limitMonitor',
        new URLSearchParams({ Call: 'GetLimitMonitorCaseList' }),
        undefined,
        120_000
      )
      await vi.advanceTimersByTimeAsync(60_000)
      expect(aborted).toBe(false)
      await vi.advanceTimersByTimeAsync(60_000)
      await expect(pending).resolves.toMatchObject({ ok: false, error: { code: 'REQUEST_TIMEOUT' } })
      expect(aborted).toBe(true)
    } finally {
      vi.useRealTimers()
    }
  })

  it('GetFileName 不设总时长，100个一批的长响应不被固定时限掐断', async () => {
    vi.useFakeTimers()
    try {
      let aborted = false
      const fetcher: typeof fetch = async (_url, init) => new Promise((_resolve, reject) => {
        init?.signal?.addEventListener('abort', () => {
          aborted = true
          reject(new DOMException('aborted', 'AbortError'))
        }, { once: true })
      })
      const controller = new AbortController()
      const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post(
        'getFileName',
        new URLSearchParams({ Call: 'GetFileName' }),
        controller.signal
      )
      await vi.advanceTimersByTimeAsync(600_000)
      expect(aborted).toBe(false)
      controller.abort()
      await expect(pending).resolves.toMatchObject({ ok: false, error: { code: 'REQUEST_ABORTED' } })
      expect(aborted).toBe(true)
    } finally {
      vi.useRealTimers()
    }
  })

  it('aborts on timeout and respects explicit cancellation', async () => {
    const fetcher: typeof fetch = async (_url, init) => new Promise((_resolve, reject) => {
      init?.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')), { once: true })
    })
    const timed = await new EasyTransport('http://183.36.43.66:88', { fetcher, timeoutMs: 5 }).post('session', sessionParams())
    expect(timed).toMatchObject({ ok: false, error: { code: 'REQUEST_TIMEOUT' } })
    const controller = new AbortController()
    const pending = new EasyTransport('http://183.36.43.66:88', { fetcher }).post('session', sessionParams(), controller.signal)
    controller.abort()
    expect(await pending).toMatchObject({ ok: false, error: { code: 'REQUEST_ABORTED' } })
  })
})

