    const built = buildTask({ origin, operatorId: userA, files: [file()], rules: rules(), profiles: [profile()], templates: [template()], queryTemplateVersion: 0, now: '2026-09-26T00:00:00.000Z' })
    const mailId = guid('mailmail')
