    })
    const matched = await runner.run({ call: 'GetUserModel', origin, operatorId: userA, expected: { userId: userA } })
    expect(matched.acceptanceLayer).toBe('MANUAL_COMPARED')
    expect(matched.evidenceLevel).not.toBe('UI_COMPARED')
