import { describe, expect, it } from 'vitest'
import { ZipReader, Uint8ArrayReader, Uint8ArrayWriter } from '@zip.js/zip.js'
import { streamDownloadFiles } from '../../../src/api/stream-download'
import type { EasyTransport } from '../../../src/api/transport'
import type { DownloadCache, CachedFileInfo } from '../../../src/api/stream-cache'

function memoryCache() {
  const files = new Map<number, { info: CachedFileInfo; bytes: Uint8Array }>()
  const entry = (index: number) => {
    if (!files.has(index)) files.set(index, { info: { receivedBytes: 0, complete: false }, bytes: new Uint8Array() })
    return files.get(index)!
  }
  const cache: DownloadCache = {
    names: {}, async saveNames(offset, names) { cache.names[String(offset)] = names.slice() },
    async info(index) { return { ...entry(index).info } },
    async reset(index, metadata) { files.set(index, { info: { ...metadata, receivedBytes: 0, complete: false }, bytes: new Uint8Array() }) },
    async write(index, offset, chunk) {
      const file = entry(index)
      if (offset !== file.bytes.length) throw new Error('noncontiguous cache write')
      const bytes = new Uint8Array(offset + chunk.length); bytes.set(file.bytes); bytes.set(chunk, offset)
      file.bytes = bytes; file.info.receivedBytes = bytes.length
    },
    async complete(index, metadata) { entry(index).info = { ...entry(index).info, ...metadata, complete: true } },
    async read(index, offset) { return entry(index).bytes.slice(offset, offset + 65536) }
  }
  return { cache, completed: () => [...files.values()].filter(file => file.info.complete).length }
}

describe('持久流水的空转回归', () => {
  it('恢复已完整缓存的附件时，ZIP阻塞不应预热后续正文到内存', async () => {
    const items = Array.from({ length: 60 }, (_, index) => ({ fileId: `00000000-0000-4000-8000-${String(index).padStart(12, '0')}`, fileNo: String(index), fileName: `${index}.pdf` }))
    const setup = memoryCache()
    const bytes = new Uint8Array(512 * 1024); bytes.set(new TextEncoder().encode('%PDF cached'))
    for (let index = 0; index < items.length; index++) {
      await setup.cache.write(index, 0, bytes)
      await setup.cache.complete(index, { totalBytes: bytes.length })
    }
    const read = setup.cache.read
    const readFiles = new Set<number>()
    setup.cache.read = async (index, offset) => { readFiles.add(index); return read(index, offset) }
    let release!: () => void, blocked!: () => void
    const gate = new Promise<void>(resolve => { release = resolve })
    const writing = new Promise<void>(resolve => { blocked = resolve })
    const running = streamDownloadFiles({ post: async () => { throw new Error('完整缓存不应请求源站') } } as unknown as EasyTransport, items, null, false, {
      cache: setup.cache, sink: new WritableStream({ async write() { blocked(); await gate } })
    })
    try {
      await writing
      await new Promise(resolve => setTimeout(resolve, 50))
      expect([...readFiles]).toEqual([0])
    } finally { release(); await running }
  })

  it('ZIP输出阻塞时，完整缓存应释放网络窗口并继续取后面的文件', async () => {
    const items = Array.from({ length: 60 }, (_, index) => ({ fileId: `00000000-0000-4000-8000-${String(index).padStart(12, '0')}`, fileNo: String(index), fileName: `${index}.pdf` }))
    const setup = memoryCache()
    const transport = { post: async (_operation: string, params: URLSearchParams) => ({ ok: true, data: {
      ClientInfo: { IsLogin: true, Status: true }, file_guid: items[Number(params.get('file_no'))].fileId
    } }), fileDownloadUrl: (id: string) => id } as unknown as EasyTransport
    const chunks: Uint8Array[] = []
    let release!: () => void
    const blocked = new Promise<void>(resolve => { release = resolve })
    let active = 0, peak = 0
    const bytes = new Uint8Array(512 * 1024); bytes.set(new TextEncoder().encode('%PDF disk-backed'))
    const running = streamDownloadFiles(transport, items, null, false, {
      cache: setup.cache, sink: new WritableStream({ async write(chunk) { await blocked; chunks.push(chunk.slice()) } }),
      fetchFile: async () => {
        active++; peak = Math.max(peak, active)
        let offset = 0
        return new Response(new ReadableStream({ pull(target) {
          if (offset === bytes.length) { active--; target.close(); return }
          target.enqueue(bytes.slice(offset, offset + 65536)); offset += 65536
        } }, { highWaterMark: 0 }), { headers: { 'Content-Length': String(bytes.length) } })
      }
    })
    try {
      for (let i = 0; i < 200 && setup.completed() < 60; i++) await new Promise(resolve => setTimeout(resolve, 5))
      expect(setup.completed()).toBe(60)
      expect(active).toBe(0)
      expect(peak).toBe(6)
    } finally { release(); await running }
    const reader = new ZipReader(new Uint8ArrayReader(Buffer.concat(chunks)), { useWebWorkers: false })
    try {
      const entries = await reader.getEntries()
      expect(entries.map(entry => entry.filename)).toEqual(items.map(item => item.fileName))
      for (const entry of entries) {
        if (entry.directory) throw new Error('Expected file entry')
        expect(Buffer.from(await entry.getData!(new Uint8ArrayWriter(), { checkSignature: true, useWebWorkers: false })).equals(Buffer.from(bytes))).toBe(true)
      }
    } finally { await reader.close() }
  }, 15000)
})

import { describe, expect, it } from 'vitest'
import { ZipReader, Uint8ArrayReader, Uint8ArrayWriter } from '@zip.js/zip.js'
import { streamDownloadFiles } from '../../../src/api/stream-download'
import type { EasyTransport } from '../../../src/api/transport'

const files = Array.from({ length: 241 }, (_, index) => ({
  fileId: `00000000-0000-4000-8000-${String(index).padStart(12, '0')}`, fileNo: `A${index}`, fileName: `file-${index}.pdf`
}))
const info = { ClientInfo: { IsLogin: true, Status: true } }
const selection = { newFilename: 'file_name', fileNameType: 'colname' }
function fixture() {
  const events: string[] = []
  let active = 0, peak = 0
  const transport = {
    post: async (operation: string, params: URLSearchParams) => {
      active++; peak = Math.max(peak, active)
      try {
        if (operation === 'getFileName') {
          const ids = params.get('file_ids')!.split(';')
          const first = files.findIndex(file => file.fileId === ids[0])
          await new Promise(resolve => setTimeout(resolve, first === 0 ? 1 : 40))
          events.push(`named:${first}`)
          return { ok: true, data: { ...info, file_names: ids.map(id => files.find(file => file.fileId === id)!.fileName).join(';') } }
        }
        const index = files.findIndex(file => file.fileNo === params.get('file_no'))
        events.push(`prepare:${index}`)
        return { ok: true, data: { ...info, file_guid: files[index].fileId } }
      } finally { active-- }
    },
    fileDownloadUrl: (guid: string) => guid
  } as unknown as EasyTransport
  const fetchFile = async (url: string) => {
    active++; peak = Math.max(peak, active)
    const index = files.findIndex(file => file.fileId === url)
    events.push(`read:${index}`)
    let sent = false
    return new Response(new ReadableStream({ async pull(controller) {
      await new Promise(resolve => setTimeout(resolve, 1))
      if (!sent) { sent = true; controller.enqueue(new TextEncoder().encode(`%PDF sample ${index}`)) }
      else { active--; controller.close() }
    } }, { highWaterMark: 0 }), { headers: { 'Content-Length': String(`%PDF sample ${index}`.length) } })
  }
  return { transport, fetchFile, events, peak: () => peak }
}
function output() {
  const chunks: Uint8Array[] = []
  let closed = false, aborted = false
  const sink = new WritableStream<Uint8Array>({ write: chunk => { chunks.push(chunk.slice()) }, close: () => { closed = true }, abort: () => { aborted = true } })
  return { sink, closed: () => closed, aborted: () => aborted, bytes: () => Buffer.concat(chunks) }
}

describe('流水单ZIP下载', () => {
  it('单附件准备遇到临时网关502后重新取得句柄，正文只下载一次', async () => {
    const result = output()
    let prepares = 0, bodies = 0
    const transport = { post: async () => ++prepares === 1 ? { ok: false, error: { code: 'HTTP_ERROR', message: 'EASY 网关异常。', status: 502 } }
      : { ok: true, data: { ClientInfo: { IsLogin: true, Status: true }, file_guid: files[0].fileId } }, fileDownloadUrl: () => 'https://easy.test/file' } as unknown as EasyTransport
    await streamDownloadFiles(transport, files.slice(0, 1), null, false, { sink: result.sink,
      fetchFile: async () => { bodies++; return new Response('%PDF retry') } })
    expect(prepares).toBe(2)
    expect(bodies).toBe(1)
    expect(result.closed()).toBe(true)
  })
  it.each([false, true])('慢首文件与后续大正文填满缓冲，取消=%s，保持顺序或清理全部请求', async cancelled => {
    const setup = fixture(), result = output(), controller = new AbortController()
    let release!: () => void
    const firstGate = new Promise<void>(resolve => { release = resolve })
    const reads = Array(6).fill(0)
    let active = 0, peak = 0
    const expected = (index: number) => {
      const body = new Uint8Array(512 * 1024).fill(index)
      body.set(new TextEncoder().encode('%PDF large fixture'))
      return body
    }
    const running = streamDownloadFiles(setup.transport, files.slice(0, 6), null, false, {
      signal: controller.signal, sink: result.sink, fetchFile: async url => {
        const index = files.findIndex(file => file.fileId === url), bytes = expected(index)
        active++; peak = Math.max(peak, active)
        let stopped = false
        return new Response(new ReadableStream({ async pull(target) {
          if (index === 0) await firstGate
          if (stopped) return
          if (reads[index] < 8) {
            const offset = reads[index]++ * 65536
            target.enqueue(bytes.slice(offset, offset + 65536))
          } else { stopped = true; active--; target.close() }
        }, cancel() { if (!stopped) { stopped = true; active-- }; release() } }, { highWaterMark: 0 }),
        { headers: { 'Content-Length': String(bytes.length) } })
      }
    })
    const settled = running.then(() => null, error => error)
    try {
      for (let attempt = 0; attempt < 100 && reads.slice(1).some(count => count < 5); attempt++) await new Promise(resolve => setTimeout(resolve, 5))
      expect(peak).toBe(6)
      expect(reads).toEqual([0, 5, 5, 5, 5, 5])
      if (cancelled) controller.abort(new Error('填满缓冲后取消'))
    } finally { release() }
    const error = await settled
    expect(active).toBe(0)
    if (cancelled) {
      expect(error?.message).toBe('填满缓冲后取消')
      expect(result.aborted()).toBe(true)
      return
    }
    expect(error).toBeNull()
    const reader = new ZipReader(new Uint8ArrayReader(result.bytes()), { useWebWorkers: false })
    const entries = await reader.getEntries()
    expect(entries.map(entry => entry.filename)).toEqual(files.slice(0, 6).map(file => file.fileName))
    for (const [index, entry] of entries.entries()) {
      if (entry.directory) throw new Error('Expected file')
      const data = await entry.getData!(new Uint8ArrayWriter(), { checkSignature: true, useWebWorkers: false })
      expect(Buffer.from(data).equals(Buffer.from(expected(index)))).toBe(true)
    }
    await reader.close()
  }, 15000)
  it('本机输出被背压阻塞时取消仍应及时返回', async () => {
    const setup = fixture(), controller = new AbortController()
    let unblock!: () => void, writing!: () => void
    const blocked = new Promise<void>(resolve => { unblock = resolve })
    const entered = new Promise<void>(resolve => { writing = resolve })
    const running = streamDownloadFiles(setup.transport, files.slice(0, 2), null, false, {
