    expect(dataOf(normalizeHistoryOptions({ ...client, Options: null }))).toEqual([])
    expect(dataOf(normalizeHistoryOptions({ ...client, Options: [] }))).toEqual([])
  })

  it('rejects a malformed list and a logged-out payload', () => {
