      ]
      return { type: MessageType.DictionaryResult, payload: { ok: true, data: {
        kind, dictionaries: { [kind === 'picker' ? 'fileTemp' : 'downloadFileName']: { key: 'fixture', options, status: 'ready', warnings: [] } }, warnings: [], responseKeys: []
      } } } as ContentResponse
    }
